    struct RollbackOnlineStageTraceCadence
    {
        // A successful stage record is roughly 70 KiB.  Keep two fresh
        // observations available to the runner without serializing one on
        // every game-thread service call.
        static constexpr uint64_t kSuccessTicks = 30;
        static constexpr uint64_t kProgressTicks = 90;

        static constexpr bool due(uint64_t tick,
                                  uint64_t last_tick,
                                  bool last_ok,
                                  bool ok) noexcept
        {
            if (tick == 1 || last_tick == 0 || last_ok != ok)
                return true;
            return tick - last_tick
                >= (ok ? kSuccessTicks : kProgressTicks);
        }
    };

    static_assert(RollbackOnlineStageTraceCadence::due(
        1, 0, false, false));
    static_assert(RollbackOnlineStageTraceCadence::due(
        2, 1, false, true));
    static_assert(!RollbackOnlineStageTraceCadence::due(
        30, 1, true, true));
    static_assert(RollbackOnlineStageTraceCadence::due(
        31, 1, true, true));
    static_assert(!RollbackOnlineStageTraceCadence::due(
        90, 1, false, false));
    static_assert(RollbackOnlineStageTraceCadence::due(
        91, 1, false, false));

