        void shutdown() noexcept
        {
            restore_background_idle_override();
            if (m_replay_injection_armed)
            {
                RollbackStockTransportObserveHook::instance()
                    .end_replay_input_script();
                RollbackLiveBoundaryHook::instance()
                    .end_replay_input_script();
            }
            m_replay_injection_armed = false;
            m_cfg.enabled = false;
            m_service_game_thread_in_progress = false;
            m_process_event_followup_in_progress = false;
            m_process_event_followup_pending = false;
            reset_online_navigator_caches();
            m_title_scene_stability.reset();
            s_luxor_network_check_compat_enabled.store(
                false, std::memory_order_release);
            s_peer_route_tag_fix_enabled.store(
                false, std::memory_order_release);
            reset_join_callback_state();
            auto* expected = this;
            (void)s_active_instance.compare_exchange_strong(
                expected, nullptr, std::memory_order_acq_rel);
        }

        void service_game_thread(uint64_t tick) noexcept
        {
            if (!m_cfg.enabled) return;
            if (m_service_game_thread_in_progress) return;
            m_service_game_thread_in_progress = true;
            m_last_service_tick = tick;
            const bool dispatch_callback_followup =
                m_process_event_followup_pending &&
                tick >= m_process_event_followup_last_tick;
            if (dispatch_callback_followup)
            {
                m_process_event_followup_pending = false;
                m_process_event_followup_in_progress = true;
                ReplayTraceFields f;
                f.string("request_id", m_cfg.request_id)
                 .string("client_role", m_cfg.client_role)
                 .string("function", m_process_event_followup_last_kind)
                 .uinteger("followup_count",
                           m_process_event_followup_count)
                 .uinteger("tick", tick)
                 .uinteger("followup_tick",
                           m_process_event_followup_last_tick)
                 .uinteger("last_attempt_tick",
                           m_online_stage_last_attempt_tick);
                ReplayDebugTrace::instance().event(
                    "rollback_online_stage_callback_followup_dispatch", f);
            }
            if (m_cfg.online_stage_requested)
                service_online_stage(tick);
            if (m_cfg.observe_gameflow_requested)
                service_gameflow_observe(tick);
            if (dispatch_callback_followup)
                m_process_event_followup_in_progress = false;
            if (m_cfg.direct_stage_requested
                || m_cfg.direct_connect_requested
                || m_cfg.direct_replay_input_requested
                || m_cfg.direct_correction_requested)
                service_direct_stage(tick);
            if (m_cfg.mirrored_versus_requested)
                service_mirrored_versus(tick);
            if (m_cfg.live_replay_input_requested
                || m_cfg.direct_replay_input_requested
                || m_cfg.direct_correction_requested)
                service_replay_input_script(tick);
            m_service_game_thread_in_progress = false;
        }

        bool direct_stage_ready() const noexcept
        {
            return m_direct_stage_ready;
        }

        const char* direct_stage_failure() const noexcept
        {
            return m_direct_stage_failure.c_str();
        }

        bool replay_input_complete() const noexcept
        {
            return m_replay_input_complete;
        }

        bool replay_input_metadata_ready() const noexcept
        {
            return m_replay_file_exists
                && m_replay_input_latched
                && replay_input_frame_count() > 0
                && local_replay_input_hash() != 0
                && expected_remote_replay_input_hash() != 0;
        }

        uint8_t local_replay_player() const noexcept
        {
            return m_cfg.local_replay_player;
        }

        uint8_t remote_replay_player() const noexcept
        {
            return m_cfg.remote_replay_player;
        }

        uint32_t replay_input_frame_count() const noexcept
        {
            if (m_cfg.local_replay_player == 0)
                return static_cast<uint32_t>(
                    (std::min<uint64_t>)(m_replay_input_frames_p0,
                                         0xFFFFFFFFull));
            if (m_cfg.local_replay_player == 1)
                return static_cast<uint32_t>(
                    (std::min<uint64_t>)(m_replay_input_frames_p1,
                                         0xFFFFFFFFull));
            return 0;
        }

        uint64_t local_replay_input_hash() const noexcept
        {
            if (m_cfg.local_replay_player == 0)
                return m_replay_input_hash_p0;
            if (m_cfg.local_replay_player == 1)
                return m_replay_input_hash_p1;
            return 0;
        }

        uint64_t expected_remote_replay_input_hash() const noexcept
        {
            if (m_cfg.remote_replay_player == 0)
                return m_replay_input_hash_p0;
            if (m_cfg.remote_replay_player == 1)
                return m_replay_input_hash_p1;
            return 0;
        }

        // Production rollback uses this only after it has failed closed and
        // frozen the native tick. The command is issued from the authoritative
        // game-thread service boundary, never from the socket or render thread.
        bool request_fail_closed_disconnect(
            uintptr_t world_context,
            std::string& reason)
        {
            if (!world_context)
            {
                reason = "fail-closed world context unavailable";
                return false;
            }
            auto* context = reinterpret_cast<RC::Unreal::UObject*>(
                world_context);
            if (!safe_is_real(context))
            {
                reason = "fail-closed world context is stale";
                return false;
            }
            return execute_console_command(
                context,
                L"disconnect",
                reason);
        }

        void update_stock_invite_peer(
            bool peer_alive,
            bool peer_fallback_ready,
            uint64_t remote_steam_id,
            bool offer_valid,
            const RollbackStockLobbyOffer& offer) noexcept
        {
            m_stock_peer_alive = peer_alive;
            m_stock_peer_fallback_ready = peer_fallback_ready;
            m_stock_remote_steam_id = remote_steam_id;
            m_stock_offer_valid = offer_valid;
            if (offer_valid) m_stock_remote_offer = offer;
        }

        uint64_t stock_local_steam_id() const noexcept
        {
            return m_steam_local_id;
        }

        bool stock_fallback_active() const noexcept
        {
            return m_stock_fallback_active;
        }

        RollbackStockLobbyOffer stock_local_offer(
            uint64_t generation,
            uint64_t build_id,
            uint64_t schema_id) const noexcept
        {
            RollbackStockLobbyOffer offer {};
            if (m_cfg.client_role != "host") return offer;
            offer.lobby_id = m_native_named_session_lobby_id;
            offer.host_steam_id = m_steam_local_id;
            offer.invitee_steam_id = m_stock_remote_steam_id;
            offer.owner_steam_id = m_native_named_session_lobby_owner_id;
            offer.request_generation = generation;
            offer.build_id = build_id;
            offer.schema_id = schema_id;
            return offer;
        }

