        static bool ensure_process_event_hook() noexcept
        {
            if (s_process_event_hook_installed.load(std::memory_order_acquire))
                return true;
            bool expected = false;
            if (!s_process_event_hook_attempted.compare_exchange_strong(
                    expected, true, std::memory_order_acq_rel))
            {
                return s_process_event_hook_installed.load(
                    std::memory_order_acquire);
            }

            try
            {
                RC::Unreal::Hook::RegisterProcessEventPostCallback(
                    [](RC::Unreal::UObject* context,
                       RC::Unreal::UFunction* function,
                       void* params) {
                        handle_process_event_post(context, function, params);
                    });
                s_process_event_hook_installed.store(
                    true, std::memory_order_release);
                RC::Output::send<RC::LogLevel::Default>(STR(
                    "[RollbackP2P] ProcessEvent post hook registered for "
                    "async session result capture\n"));
                return true;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] ProcessEvent hook registration threw: {}\n"),
                    RC::to_generic_string(e.what()));
            }
            catch (...)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] ProcessEvent hook registration threw\n"));
            }
            return false;
        }

