        static void sample_lux_shared_object_pair(
            void* pair,
            void*& object,
            void*& object_ref) noexcept
        {
            object = nullptr;
            object_ref = nullptr;
            if (!pair)
                return;
            const auto* const pair_bytes =
                static_cast<const uint8_t*>(pair);
            (void)SafeReadPtr(pair_bytes, &object);
            (void)SafeReadPtr(pair_bytes + 0x08, &object_ref);
        }

        static void read_u8_as_u32(
            const uint8_t* base,
            uintptr_t offset,
            uint32_t& out) noexcept
        {
            uint8_t value = 0xffu;
            if (SafeReadUInt8(base + offset, &value))
                out = value;
        }

        static bool is_known_luxor_magic(uint32_t magic) noexcept
        {
            return magic == 0xf08f37c5u || magic == 0xe7290085u ||
                   magic == 0x55b7747bu || magic == 0xd3952150u ||
                   magic == 0xd5cd3057u || magic == 0xdef00fccu ||
                   magic == 0x474e23b8u || magic == 0xbacbf2edu;
        }

        static LuxorMagicFrameSnapshot sample_luxor_magic_frame(
            void* packet_data,
            uint32_t packet_size) noexcept
        {
            LuxorMagicFrameSnapshot out {};
            out.data = reinterpret_cast<uintptr_t>(packet_data);
            out.size = packet_size;
            uint32_t bytes[12] {};
            for (uint32_t& value : bytes)
                value = 0xffu;
            if (packet_data && packet_size > 0)
            {
                const auto* const packet_bytes =
                    static_cast<const uint8_t*>(packet_data);
                const uint32_t sample_count =
                    packet_size < 12 ? packet_size : 12;
                for (uint32_t i = 0; i < sample_count; ++i)
                    read_u8_as_u32(packet_bytes, i, bytes[i]);
            }
            out.magic =
                ((bytes[0] & 0xffu) << 24) |
                ((bytes[1] & 0xffu) << 16) |
                ((bytes[2] & 0xffu) << 8) |
                (bytes[3] & 0xffu);
            out.payload_size =
                ((bytes[4] & 0xffu) << 8) | (bytes[5] & 0xffu);
            out.marker =
                ((bytes[6] & 0xffu) << 8) | (bytes[7] & 0xffu);
            out.local_user = bytes[8];
            out.payload_opcode = bytes[9];
            out.payload_byte1 = bytes[10];
            out.payload_byte2 = bytes[11];
            out.magic_match = is_known_luxor_magic(out.magic);
            return out;
        }

        static LuxorMagicFrameSnapshot sample_luxor_magic_frame_archive(
            void* frame_archive) noexcept
        {
            LuxorMagicFrameSnapshot out {};
            if (!frame_archive)
                return out;
            const auto* const archive_bytes =
                static_cast<const uint8_t*>(frame_archive);
            void* byte_array = nullptr;
            if (!SafeReadPtr(archive_bytes + 0x20, &byte_array) ||
                !byte_array)
            {
                return out;
            }
            const auto* const array_bytes =
                static_cast<const uint8_t*>(byte_array);
            void* data = nullptr;
            uint32_t size = 0xffffffffu;
            (void)SafeReadPtr(array_bytes + 0x00, &data);
            (void)SafeReadUInt32(array_bytes + 0x08, &size);
            if (!data || size == 0xffffffffu)
                return out;
            return sample_luxor_magic_frame(data, size);
        }

        static void add_luxor_magic_frame_fields(
            ReplayTraceFields& f,
            const LuxorMagicFrameSnapshot& frame) noexcept
        {
            f.hex("frame_data", frame.data)
             .uinteger("frame_size", frame.size)
             .hex("frame_magic", frame.magic)
             .uinteger("frame_payload_size", frame.payload_size)
             .hex("frame_marker", frame.marker)
             .uinteger("frame_local_user", frame.local_user)
             .uinteger("frame_payload_opcode", frame.payload_opcode)
             .uinteger("frame_payload_byte1", frame.payload_byte1)
             .uinteger("frame_payload_byte2", frame.payload_byte2)
             .boolean("frame_magic_match", frame.magic_match);
        }

        struct LuxorRouteIdentitySnapshot
        {
            void* vtable {nullptr};
            void* key_object {nullptr};
            void* destination_object {nullptr};
            uint32_t peer_flags {0xffffffffu};
        };

        static LuxorRouteIdentitySnapshot
        sample_luxor_route_identity(void* route_identity) noexcept
        {
            LuxorRouteIdentitySnapshot out {};
            if (!route_identity)
                return out;
            const auto* const identity_bytes =
                static_cast<const uint8_t*>(route_identity);
            (void)SafeReadPtr(route_identity, &out.vtable);
            (void)SafeReadPtr(identity_bytes + 0x08, &out.key_object);
            (void)SafeReadPtr(
                identity_bytes + 0x20, &out.destination_object);
            (void)SafeReadUInt32(identity_bytes + 0x28, &out.peer_flags);
            return out;
        }

        static void add_luxor_route_identity_fields(
            ReplayTraceFields& f,
            const char* prefix,
            const LuxorRouteIdentitySnapshot& identity) noexcept
        {
            char name[96] {};
            auto emit_hex = [&](const char* suffix, uintptr_t value) {
                std::snprintf(
                    name, sizeof(name), "%s_%s", prefix, suffix);
                f.hex(name, value);
            };
            auto emit_uinteger = [&](const char* suffix, uint32_t value) {
                std::snprintf(
                    name, sizeof(name), "%s_%s", prefix, suffix);
                f.uinteger(name, value);
            };
            emit_hex(
                "vtable", reinterpret_cast<uintptr_t>(identity.vtable));
            emit_hex(
                "key_object",
                reinterpret_cast<uintptr_t>(identity.key_object));
            emit_hex(
                "destination_object",
                reinterpret_cast<uintptr_t>(
                    identity.destination_object));
            emit_uinteger("peer_flags", identity.peer_flags);
        }

