        static bool maybe_store_peer_route_tag_fix_from_route_writer(
            uintptr_t route_tag,
            const LuxorRouteWriterRegistrySnapshot& registry,
            void* out_owner,
            void* out_owner_ref,
            uint32_t source) noexcept
        {
            if (!s_peer_route_tag_fix_enabled.load(
                    std::memory_order_acquire))
                return false;
            if (!session_trace_client_role_is("host"))
                return false;

            const LuxorRouteTagGlobalsSnapshot globals =
                sample_luxor_route_tag_globals();
            if (!luxor_route_tag_is_peer_fix_candidate(route_tag, globals))
                return false;
            if (!out_owner || !out_owner_ref || !registry.registry)
                return false;
            if (registry.entry_count == 0xffffffffu ||
                registry.sample_count == 0 ||
                registry.selected_index == 0xffffffffu ||
                registry.selected_index == 0 ||
                registry.selected_index >= registry.entry_count ||
                registry.selected_index >= registry.sample_count)
                return false;
            if (registry.selected.owner != out_owner ||
                registry.selected.owner_ref != out_owner_ref ||
                !registry.selected.writer ||
                !registry.selected.owner_route_key)
                return false;
            const uintptr_t packet_route_tag = reinterpret_cast<uintptr_t>(
                registry.selected.owner_route_key_routing_tag);
            if (!luxor_route_tag_is_peer_fix_candidate(
                    packet_route_tag, globals))
                return false;

            s_peer_route_tag_fix_last_peer_tag.store(
                packet_route_tag, std::memory_order_release);
            s_peer_route_tag_fix_last_peer_registry_index.store(
                registry.selected_index, std::memory_order_release);
            s_peer_route_tag_fix_last_peer_owner.store(
                reinterpret_cast<uintptr_t>(registry.selected.owner),
                std::memory_order_release);
            s_peer_route_tag_fix_last_peer_writer.store(
                reinterpret_cast<uintptr_t>(registry.selected.writer),
                std::memory_order_release);
            s_peer_route_tag_fix_last_peer_source.store(
                source, std::memory_order_release);
            return true;
        }

