        static uint64_t read_session_async_queue_count_for_trace(
            void* session_connection) noexcept
        {
            if (!session_connection)
                return 0;
            uint64_t count = 0;
            (void)SafeReadUInt64(
                static_cast<const uint8_t*>(session_connection) + 0xD8,
                &count);
            return count;
        }

        static uint8_t queued_luxor_connection_opcode_send_detour(
            void* payload)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            constexpr uint8_t outer_opcode = 0x15u;
            void* session_connection = nullptr;
            void* source_packet = nullptr;
            void* source_route_key_vtable = nullptr;
            void* source_routing_tag = nullptr;
            uint8_t inner_opcode = 0xffu;
            uint16_t channel_id = 0xffffu;
            if (payload)
            {
                const auto* const bytes =
                    static_cast<const uint8_t*>(payload);
                (void)SafeReadPtr(bytes + 0x00, &session_connection);
                source_packet = const_cast<uint8_t*>(bytes + 0x08);
                (void)SafeReadPtr(
                    bytes + 0x08, &source_route_key_vtable);
                (void)SafeReadPtr(bytes + 0x10, &source_routing_tag);
                (void)SafeReadUInt8(bytes + 0x18, &inner_opcode);
                (void)SafeReadUInt16(bytes + 0x1A, &channel_id);
            }
            const uint64_t queue_before =
                read_session_async_queue_count_for_trace(
                    session_connection);

            uint8_t result = 0;
            auto* original =
                reinterpret_cast<SendQueuedLuxorConnectionOpcodePayloadFn>(
                    s_queued_opcode_send_trampoline);
            if (original)
                result = original(payload);

            const uint64_t queue_after =
                read_session_async_queue_count_for_trace(
                    session_connection);
            s_queued_opcode_send_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_queued_opcode_send_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            s_queued_opcode_send_last_session_connection.store(
                reinterpret_cast<uintptr_t>(session_connection),
                std::memory_order_release);
            s_queued_opcode_send_last_source_packet.store(
                reinterpret_cast<uintptr_t>(source_packet),
                std::memory_order_release);
            s_queued_opcode_send_last_source_route_key_vtable.store(
                reinterpret_cast<uintptr_t>(source_route_key_vtable),
                std::memory_order_release);
            s_queued_opcode_send_last_source_routing_tag.store(
                reinterpret_cast<uintptr_t>(source_routing_tag),
                std::memory_order_release);
            s_queued_opcode_send_last_outer_opcode.store(
                outer_opcode, std::memory_order_release);
            s_queued_opcode_send_last_inner_opcode.store(
                inner_opcode, std::memory_order_release);
            s_queued_opcode_send_last_opcode.store(
                inner_opcode, std::memory_order_release);
            s_queued_opcode_send_last_channel_id.store(
                channel_id, std::memory_order_release);
            s_queued_opcode_send_last_result.store(
                result, std::memory_order_release);
            s_queued_opcode_send_last_queue_before.store(
                queue_before, std::memory_order_release);
            s_queued_opcode_send_last_queue_after.store(
                queue_after, std::memory_order_release);

            if (s_session_trace_enabled.load(std::memory_order_acquire))
            {
                const LuxorRouteTagGlobalsSnapshot globals =
                    sample_luxor_route_tag_globals();
                ReplayTraceFields f;
                add_session_trace_identity(f);
                f.hex("caller_rva", caller_rva)
                 .hex("payload", reinterpret_cast<uintptr_t>(payload))
                 .hex("session_connection",
                       reinterpret_cast<uintptr_t>(session_connection))
                 .hex("source_packet",
                      reinterpret_cast<uintptr_t>(source_packet))
                 .hex("source_route_key_vtable",
                      reinterpret_cast<uintptr_t>(
                          source_route_key_vtable))
                 .hex("source_routing_tag",
                      reinterpret_cast<uintptr_t>(source_routing_tag))
                 .uinteger("outer_opcode", outer_opcode)
                 .uinteger("inner_opcode", inner_opcode)
                 .uinteger("opcode", inner_opcode)
                 .uinteger("channel_id", channel_id)
                 .uinteger("result", result)
                 .uinteger("queue_before", queue_before)
                 .uinteger("queue_after", queue_after);
                add_luxor_route_tag_global_fields(
                    f,
                    globals,
                    reinterpret_cast<uintptr_t>(source_routing_tag));
                ReplayDebugTrace::instance().event(
                    "rollback_luxor_queued_opcode_send", f);
            }
            return result;
        }

