        static void** luxor_route_writer_resolve_detour(
            void* connect_root,
            void** writer_out,
            void* route_key)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            void* route_tag = nullptr;
            if (route_key)
            {
                (void)SafeReadPtr(
                    static_cast<const uint8_t*>(route_key) + 0x08,
                    &route_tag);
            }
            const LuxorRouteTagGlobalsSnapshot route_tag_globals =
                sample_luxor_route_tag_globals();
            auto* original =
                reinterpret_cast<ResolveLuxorConnectRouteWriterFn>(
                    s_route_writer_resolve_trampoline);
            void** result = writer_out;
            if (original)
                result = original(connect_root, writer_out, route_key);

            void* writer = nullptr;
            void* writer_ref = nullptr;
            if (writer_out)
            {
                (void)SafeReadPtr(writer_out, &writer);
                (void)SafeReadPtr(writer_out + 1, &writer_ref);
            }
            void* writer_vtable = nullptr;
            uintptr_t writer_send_target = 0;
            if (writer)
            {
                (void)SafeReadPtr(writer, &writer_vtable);
                (void)read_vtable_target(
                    writer, 0x00, writer_send_target);
                (void)install_route_writer_send_hook_for_target(
                    writer_send_target);
            }
            const LuxorRouteWriterRegistrySnapshot registry_snapshot =
                sample_luxor_route_writer_registry(connect_root, writer);

            s_route_writer_resolve_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_route_writer_resolve_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            s_route_writer_resolve_last_root.store(
                reinterpret_cast<uintptr_t>(connect_root),
                std::memory_order_release);
            s_route_writer_resolve_last_route_key.store(
                reinterpret_cast<uintptr_t>(route_key),
                std::memory_order_release);
            s_route_writer_resolve_last_route_tag.store(
                reinterpret_cast<uintptr_t>(route_tag),
                std::memory_order_release);
            s_route_writer_resolve_last_writer.store(
                reinterpret_cast<uintptr_t>(writer),
                std::memory_order_release);
            s_route_writer_resolve_last_writer_ref.store(
                reinterpret_cast<uintptr_t>(writer_ref),
                std::memory_order_release);
            s_route_writer_resolve_last_writer_vtable.store(
                reinterpret_cast<uintptr_t>(writer_vtable),
                std::memory_order_release);
            s_route_writer_resolve_last_writer_send_target.store(
                writer_send_target, std::memory_order_release);
            store_luxor_route_writer_registry_summary(registry_snapshot);

            if (s_session_trace_enabled.load(std::memory_order_acquire))
            {
                ReplayTraceFields f;
                add_session_trace_identity(f);
                f.hex("caller_rva", caller_rva)
                 .hex("connect_root",
                      reinterpret_cast<uintptr_t>(connect_root))
                 .hex("route_key", reinterpret_cast<uintptr_t>(route_key))
                 .hex("route_tag", reinterpret_cast<uintptr_t>(route_tag))
                 .hex("writer", reinterpret_cast<uintptr_t>(writer))
                 .hex("writer_ref", reinterpret_cast<uintptr_t>(writer_ref))
                 .hex("writer_vtable",
                      reinterpret_cast<uintptr_t>(writer_vtable))
                 .hex("writer_send_target", writer_send_target)
                 .boolean(
                     "writer_send_hook_installed",
                     s_route_writer_send_hook_installed.load(
                         std::memory_order_acquire));
                add_luxor_route_tag_global_fields(
                    f,
                    route_tag_globals,
                    reinterpret_cast<uintptr_t>(route_tag));
                add_luxor_route_writer_registry_fields(
                    f, registry_snapshot);
                ReplayDebugTrace::instance().event(
                    "rollback_luxor_route_writer_resolve", f);
            }
            return result;
        }

        static uint8_t luxor_route_writer_owner_tag_match_detour(
            void* requested_route_key,
            void* writer_owner_pair)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            const LuxorRouteTagGlobalsSnapshot route_tag_globals =
                sample_luxor_route_tag_globals();

            void* requested_routing_tag = nullptr;
            if (requested_route_key)
            {
                (void)SafeReadPtr(
                    static_cast<const uint8_t*>(requested_route_key) +
                        kLuxorPacketRouteKeyRoutingTagOff,
                    &requested_routing_tag);
            }

            void* candidate_owner = nullptr;
            void* candidate_owner_ref = nullptr;
            if (writer_owner_pair)
            {
                (void)SafeReadPtr(writer_owner_pair, &candidate_owner);
                (void)SafeReadPtr(
                    static_cast<const uint8_t*>(writer_owner_pair) + 0x08,
                    &candidate_owner_ref);
            }

            void* candidate_owner_vtable = nullptr;
            uintptr_t candidate_key_accessor_target = 0;
            uintptr_t candidate_key_accessor_rva = 0;
            uintptr_t inferred_candidate_route_key = 0;
            uintptr_t inferred_candidate_routing_tag = 0;
            const char* inferred_candidate_key_kind = "unknown";
            if (candidate_owner)
            {
                (void)SafeReadPtr(
                    candidate_owner, &candidate_owner_vtable);
                if (read_vtable_target(
                        candidate_owner, 0x00,
                        candidate_key_accessor_target))
                {
                    candidate_key_accessor_rva = native_rva_for_address(
                        candidate_key_accessor_target);
                    if (candidate_key_accessor_rva ==
                        kRVA_GetLuxorReplacementRouteKey)
                    {
                        inferred_candidate_key_kind =
                            "replacement-singleton";
                        inferred_candidate_route_key =
                            route_tag_globals.replacement_route_key_singleton;
                        inferred_candidate_routing_tag =
                            route_tag_globals
                                .replacement_route_key_routing_tag;
                    }
                    else if (
                        candidate_key_accessor_rva ==
                        kRVA_GetLuxorPeerPacketRouteKey)
                    {
                        inferred_candidate_key_kind = "peer-owner-key";
                        inferred_candidate_route_key =
                            reinterpret_cast<uintptr_t>(candidate_owner) +
                            kLuxorBackendConnectionPeerRouteKeyOff;
                        void* peer_routing_tag = nullptr;
                        if (SafeReadPtr(
                                reinterpret_cast<const void*>(
                                    inferred_candidate_route_key +
                                    kLuxorPacketRouteKeyRoutingTagOff),
                                &peer_routing_tag))
                        {
                            inferred_candidate_routing_tag =
                                reinterpret_cast<uintptr_t>(
                                    peer_routing_tag);
                        }
                    }
                }
            }

            auto* original =
                reinterpret_cast<MatchLuxorRouteWriterOwnerRoutingTagFn>(
                    s_route_writer_owner_tag_match_trampoline);
            uint8_t result = 0;
            if (original)
                result = original(requested_route_key, writer_owner_pair);

            const uintptr_t requested_tag_value =
                reinterpret_cast<uintptr_t>(requested_routing_tag);
            const uintptr_t requested_effective_tag =
                effective_luxor_route_tag(
                    requested_tag_value, route_tag_globals);
            const uint32_t timeline_opcode =
                requested_effective_tag ==
                        route_tag_globals.packet_routing_tag_replacement
                    ? 21u
                    : 0xffu;

            const uint64_t match_call =
                s_route_writer_owner_tag_match_calls.fetch_add(
                    1, std::memory_order_acq_rel) + 1;
            s_route_writer_owner_tag_match_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            s_route_writer_owner_tag_match_last_requested_route_key.store(
                reinterpret_cast<uintptr_t>(requested_route_key),
                std::memory_order_release);
            s_route_writer_owner_tag_match_last_requested_routing_tag.store(
                requested_tag_value, std::memory_order_release);
            s_route_writer_owner_tag_match_last_candidate_owner.store(
                reinterpret_cast<uintptr_t>(candidate_owner),
                std::memory_order_release);
            s_route_writer_owner_tag_match_last_candidate_owner_vtable.store(
                reinterpret_cast<uintptr_t>(candidate_owner_vtable),
                std::memory_order_release);
            s_route_writer_owner_tag_match_last_candidate_accessor_rva.store(
                candidate_key_accessor_rva, std::memory_order_release);
            s_route_writer_owner_tag_match_last_candidate_route_key.store(
                inferred_candidate_route_key, std::memory_order_release);
            s_route_writer_owner_tag_match_last_candidate_routing_tag.store(
                inferred_candidate_routing_tag, std::memory_order_release);
            s_route_writer_owner_tag_match_last_result.store(
                result, std::memory_order_release);

            if (s_session_trace_enabled.load(std::memory_order_acquire) &&
                (match_call <= 4 || (match_call % 600u) == 0u))
            {
                ReplayTraceFields f;
                add_session_trace_identity(f);
                f.hex("caller_rva", caller_rva)
                 .hex("requested_route_key",
                      reinterpret_cast<uintptr_t>(requested_route_key))
                 .hex("requested_routing_tag", requested_tag_value)
                 .hex("requested_routing_tag_effective",
                      requested_effective_tag)
                 .uinteger("timeline_opcode", timeline_opcode)
                 .hex("writer_owner_pair",
                      reinterpret_cast<uintptr_t>(writer_owner_pair))
                 .hex("candidate_owner",
                      reinterpret_cast<uintptr_t>(candidate_owner))
                 .hex("candidate_owner_ref",
                      reinterpret_cast<uintptr_t>(candidate_owner_ref))
                 .hex("candidate_owner_vtable",
                      reinterpret_cast<uintptr_t>(candidate_owner_vtable))
                 .hex("candidate_route_key_accessor_target",
                      candidate_key_accessor_target)
                 .hex("candidate_route_key_accessor_rva",
                      candidate_key_accessor_rva)
                 .string("candidate_route_key_kind",
                         inferred_candidate_key_kind)
                 .hex("candidate_route_key_inferred",
                      inferred_candidate_route_key)
                 .hex("candidate_routing_tag_inferred",
                      inferred_candidate_routing_tag)
                 .boolean(
                     "candidate_routing_tag_matches_requested",
                     inferred_candidate_routing_tag != 0 &&
                         inferred_candidate_routing_tag ==
                             requested_tag_value)
                 .boolean(
                     "candidate_accessor_is_replacement",
                     candidate_key_accessor_rva ==
                         kRVA_GetLuxorReplacementRouteKey)
                 .boolean(
                     "candidate_accessor_is_peer",
                     candidate_key_accessor_rva ==
                         kRVA_GetLuxorPeerPacketRouteKey)
                 .uinteger("result", result);
                add_luxor_route_tag_global_fields(
                    f, route_tag_globals, requested_tag_value);
                ReplayDebugTrace::instance().event(
                    "rollback_luxor_route_writer_owner_tag_match", f);
            }
            return result;
        }

