        static int32_t connect_sender_endpoint_send_detour(
            void* endpoint,
            void* packet,
            uint32_t arg2)
        {
            const uint64_t caller_rva = native_rva_for_address(
                reinterpret_cast<uintptr_t>(_ReturnAddress()));
            void* endpoint_vtable = nullptr;
            uint8_t endpoint_local_user_slot = 0xffu;
            (void)SafeReadPtr(endpoint, &endpoint_vtable);
            if (endpoint)
            {
                (void)SafeReadUInt8(
                    static_cast<const uint8_t*>(endpoint) + 0x08,
                    &endpoint_local_user_slot);
            }
            void* active_connect = resolve_current_active_connect_for_trace();
            const LuxorActiveOpcodeSnapshot packet_before =
                sample_active_opcode_snapshot(active_connect, packet);
            const LuxorOutboundPacketArchiveSnapshot archive_before =
                sample_outbound_packet_archive(packet);
            emit_active_endpoint_send_trace(
                "before-original", caller_rva,
                reinterpret_cast<uintptr_t>(endpoint),
                reinterpret_cast<uintptr_t>(endpoint_vtable),
                endpoint_local_user_slot, arg2, 0xffffffffu,
                packet_before, archive_before, packet_before);

            int32_t result = -1;
            auto* original =
                reinterpret_cast<ConnectSenderEndpointSendPacketFn>(
                    s_active_endpoint_send_trampoline);
            if (original)
                result = original(endpoint, packet, arg2);

            const uint32_t result_value =
                static_cast<uint32_t>(result);
            const LuxorActiveOpcodeSnapshot active_after =
                sample_active_opcode_snapshot(active_connect, packet);
            switch (archive_before.data_byte0)
            {
            case 0:
                s_active_endpoint_send_data_opcode0_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 4:
                s_active_endpoint_send_data_opcode4_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 5:
                s_active_endpoint_send_data_opcode5_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 6:
                s_active_endpoint_send_data_opcode6_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 10:
                s_active_endpoint_send_data_opcode10_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 15:
                s_active_endpoint_send_data_opcode15_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 20:
                s_active_endpoint_send_data_opcode20_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 21:
                s_active_endpoint_send_data_opcode21_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                s_active_endpoint_send_opcode21_last_caller_rva.store(
                    caller_rva, std::memory_order_release);
                s_active_endpoint_send_opcode21_last_result.store(
                    result_value, std::memory_order_release);
                s_active_endpoint_send_opcode21_last_size.store(
                    archive_before.size, std::memory_order_release);
                s_active_endpoint_send_opcode21_last_byte1.store(
                    archive_before.data_byte1,
                    std::memory_order_release);
                s_active_endpoint_send_opcode21_last_byte2.store(
                    archive_before.data_byte2,
                    std::memory_order_release);
                s_active_endpoint_send_opcode21_last_byte3.store(
                    archive_before.data_byte3,
                    std::memory_order_release);
                break;
            default:
                break;
            }
            s_active_endpoint_send_calls.fetch_add(
                1, std::memory_order_acq_rel);
            s_active_endpoint_send_last_caller_rva.store(
                caller_rva, std::memory_order_release);
            store_active_endpoint_send_snapshot(
                reinterpret_cast<uintptr_t>(endpoint),
                reinterpret_cast<uintptr_t>(endpoint_vtable),
                endpoint_local_user_slot,
                arg2,
                result_value,
                packet_before,
                archive_before,
                active_after);
            emit_active_endpoint_send_trace(
                "after-original", caller_rva,
                reinterpret_cast<uintptr_t>(endpoint),
                reinterpret_cast<uintptr_t>(endpoint_vtable),
                endpoint_local_user_slot, arg2, result_value,
                packet_before, archive_before, active_after);
            return result;
        }

