        static uint32_t millis_from_delta_seconds(
            float delta_seconds) noexcept
        {
            if (!(delta_seconds >= 0.0f) || delta_seconds > 1000.0f)
                return 0xffffffffu;
            return static_cast<uint32_t>(delta_seconds * 1000.0f + 0.5f);
        }

