        static bool should_service_session_callback_followup(
            SessionProcessEventKind kind) noexcept
        {
            return kind == SessionProcessEventKind::OnJoinSession
                || kind == SessionProcessEventKind::OnSessionConnect
                || kind == SessionProcessEventKind::OnSessionConnectComplete
                || kind == SessionProcessEventKind::OnSessionMemberJoin
                || kind == SessionProcessEventKind::OnBattleReady
                || kind == SessionProcessEventKind::OnBattleComp
                || kind == SessionProcessEventKind::OnCreateSession;
        }

        static void service_active_session_callback_followup(
            SessionProcessEventKind kind) noexcept
        {
            if (!should_service_session_callback_followup(kind))
                return;
            RollbackP2PHarness* active =
                s_active_instance.load(std::memory_order_acquire);
            if (!active)
                return;
            active->service_session_callback_followup(kind);
        }

        static const char* session_process_event_label(
            SessionProcessEventKind kind) noexcept
        {
            switch (kind)
            {
            case SessionProcessEventKind::OnFindSession:
                return "OnFindSession";
            case SessionProcessEventKind::OnPingSearchResults:
                return "OnPingSearchResults";
            case SessionProcessEventKind::OnCreateSession:
                return "OnCreateSession";
            case SessionProcessEventKind::OnDestroySession:
                return "OnDestroySession";
            case SessionProcessEventKind::OnJoinSession:
                return "OnJoinSession";
            case SessionProcessEventKind::OnSessionConnect:
                return "OnSessionConnect";
            case SessionProcessEventKind::OnSessionConnectComplete:
                return "OnSessionConnectComplete";
            case SessionProcessEventKind::OnSessionDisconnect:
                return "OnSessionDisconnect";
            case SessionProcessEventKind::OnSessionMemberJoin:
                return "OnSessionMemberJoin";
            case SessionProcessEventKind::OnBattleReady:
                return "OnBattleReady";
            case SessionProcessEventKind::OnBattleComp:
                return "OnBattleComp";
            case SessionProcessEventKind::GetSessionResultRoomName:
                return "GetSessionResultRoomName";
            case SessionProcessEventKind::GetSessionResultName:
                return "GetSessionResultName";
            case SessionProcessEventKind::GetSessionResultOwnerNetId:
                return "GetSessionResultOwnerNetId";
            default:
                return "";
            }
        }

        void service_session_callback_followup(
            SessionProcessEventKind kind) noexcept
        {
            if (!m_cfg.enabled || !m_cfg.online_stage_requested)
                return;
            if (m_cfg.online_stage_cleanup_only)
                return;
            if (m_process_event_followup_in_progress)
            {
                return;
            }

            uint64_t followup_tick = m_last_service_tick + 1;
            const uint64_t ready_retry_tick =
                m_online_stage_last_attempt_tick + kOnlineStageReadyRetryTicks;
            if (followup_tick < ready_retry_tick)
                followup_tick = ready_retry_tick;
            if (followup_tick == 0)
                followup_tick = 1;

            ++m_process_event_followup_count;
            m_process_event_followup_last_tick = followup_tick;
            m_process_event_followup_last_kind =
                session_process_event_label(kind);
            m_process_event_followup_pending = true;

            ReplayTraceFields f;
            f.string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .string("function", m_process_event_followup_last_kind)
             .uinteger("followup_count", m_process_event_followup_count)
             .uinteger("followup_tick", followup_tick)
             .uinteger("last_service_tick", m_last_service_tick)
             .uinteger("last_attempt_tick", m_online_stage_last_attempt_tick)
             .boolean("deferred", true);
            ReplayDebugTrace::instance().event(
                "rollback_online_stage_callback_followup", f);
        }

