        static SessionProcessEventKind classify_session_function_name(
            const RC::StringType& fn_name) noexcept
        {
            if (fn_name == STR("OnFindSession"))
                return SessionProcessEventKind::OnFindSession;
            if (fn_name == STR("OnPingSearchResults"))
                return SessionProcessEventKind::OnPingSearchResults;
            if (fn_name == STR("OnCreateSession"))
                return SessionProcessEventKind::OnCreateSession;
            if (fn_name == STR("OnDestroySession"))
                return SessionProcessEventKind::OnDestroySession;
            if (fn_name == STR("OnJoinSession"))
                return SessionProcessEventKind::OnJoinSession;
            if (fn_name == STR("OnSessionConnect"))
                return SessionProcessEventKind::OnSessionConnect;
            if (fn_name == STR("OnSessionConnectComplete"))
                return SessionProcessEventKind::OnSessionConnectComplete;
            if (fn_name == STR("OnSessionDisconnect"))
                return SessionProcessEventKind::OnSessionDisconnect;
            if (fn_name == STR("OnSessionMemberJoin"))
                return SessionProcessEventKind::OnSessionMemberJoin;
            if (fn_name == STR("OnBattleReady"))
                return SessionProcessEventKind::OnBattleReady;
            if (fn_name == STR("OnBattleComp"))
                return SessionProcessEventKind::OnBattleComp;
            if (fn_name == STR("GetSessionResultRoomName"))
                return SessionProcessEventKind::GetSessionResultRoomName;
            if (fn_name == STR("GetSessionResultName"))
                return SessionProcessEventKind::GetSessionResultName;
            if (fn_name == STR("GetSessionResultOwnerNetId"))
                return SessionProcessEventKind::GetSessionResultOwnerNetId;
            return SessionProcessEventKind::None;
        }

        static SessionProcessEventKind classify_session_process_event(
            RC::Unreal::UFunction* function) noexcept
        {
            if (!function) return SessionProcessEventKind::None;
            const uintptr_t key = reinterpret_cast<uintptr_t>(function);
            {
                std::lock_guard<std::mutex> lock(
                    s_process_event_kind_cache_mutex);
                const auto it = s_process_event_kind_cache.find(key);
                if (it != s_process_event_kind_cache.end())
                {
                    return static_cast<SessionProcessEventKind>(it->second);
                }
            }

            RC::StringType fn_name;
            try
            {
                fn_name = function->GetName();
            }
            catch (...)
            {
                return SessionProcessEventKind::None;
            }

            const SessionProcessEventKind kind =
                classify_session_function_name(fn_name);
            {
                std::lock_guard<std::mutex> lock(
                    s_process_event_kind_cache_mutex);
                if (s_process_event_kind_cache.size() > 4096)
                    s_process_event_kind_cache.clear();
                s_process_event_kind_cache.emplace(
                    key, static_cast<uint8_t>(kind));
            }
            return kind;
        }

        static bool should_trace_callback_count(
            int32_t count,
            int32_t first_n = 4,
            int32_t every_n = 120) noexcept
        {
            return count < first_n || (every_n > 0 && (count % every_n) == 0);
        }

        static void emit_session_callback_result(
            SessionProcessEventKind kind,
            bool result,
            int32_t result_type,
            bool full_member_error,
            int32_t true_count,
            int32_t false_count) noexcept
        {
            const int32_t total = true_count + false_count;
            if (!should_trace_callback_count(total, 6, 120)) return;

            std::string request_id;
            std::string client_role;
            std::string native_session_name;
            std::string session_name;
            std::string room_name;
            {
                std::lock_guard<std::mutex> lock(
                    s_session_trace_identity_mutex);
                request_id = s_session_trace_request_id;
                client_role = s_session_trace_client_role;
                native_session_name = s_session_trace_native_session_name;
                session_name = s_session_trace_session_name;
                room_name = s_session_trace_room_name;
            }
            if (request_id.empty()) return;

            ReplayTraceFields f;
            f.string("request_id", request_id)
             .string("client_role", client_role)
             .string("native_session_name", native_session_name)
             .string("session_name", session_name)
             .string("room_name", room_name)
             .string("function", session_process_event_label(kind))
             .boolean("result", result)
             .integer("result_type", result_type)
             .boolean("full_member_error", full_member_error)
             .integer("true_count", true_count)
             .integer("false_count", false_count)
             .integer("total_count", total);
            ReplayDebugTrace::instance().event(
                "rollback_online_stage_callback", f);
        }

        static void trace_session_process_event(
            RC::Unreal::UObject* context,
            RC::Unreal::UFunction* function,
            SessionProcessEventKind kind) noexcept
        {
            if (!function) return;
            try
            {
                if (kind == SessionProcessEventKind::None) return;
                if (kind == SessionProcessEventKind::OnPingSearchResults)
                {
                    const int32_t ping_index =
                        s_ping_search_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(ping_index)) return;
                }
                if (kind == SessionProcessEventKind::OnFindSession)
                {
                    const int32_t find_index =
                        s_find_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(find_index)) return;
                }
                if (kind == SessionProcessEventKind::GetSessionResultRoomName ||
                    kind == SessionProcessEventKind::GetSessionResultName ||
                    kind == SessionProcessEventKind::GetSessionResultOwnerNetId)
                {
                    const int32_t helper_index =
                        s_session_result_helper_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(helper_index, 8, 240))
                        return;
                }
                if (kind == SessionProcessEventKind::OnCreateSession)
                {
                    const int32_t create_index =
                        s_create_session_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(create_index)) return;
                }
                if (kind == SessionProcessEventKind::OnJoinSession)
                {
                    const int32_t join_index =
                        s_join_session_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(join_index)) return;
                }
                if (kind == SessionProcessEventKind::OnSessionConnect ||
                    kind == SessionProcessEventKind::OnSessionConnectComplete)
                {
                    const int32_t connect_index =
                        s_session_connect_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(connect_index)) return;
                }
                if (kind == SessionProcessEventKind::OnSessionDisconnect)
                {
                    const int32_t disconnect_index =
                        s_session_disconnect_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(disconnect_index)) return;
                }
                if (kind == SessionProcessEventKind::OnSessionMemberJoin)
                {
                    const int32_t member_join_index =
                        s_session_member_join_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(member_join_index))
                        return;
                }
                if (kind == SessionProcessEventKind::OnDestroySession)
                {
                    const int32_t destroy_index =
                        s_destroy_session_event_trace_count.fetch_add(
                            1, std::memory_order_acq_rel);
                    if (!should_trace_callback_count(destroy_index)) return;
                }
                const bool priority_event =
                    kind == SessionProcessEventKind::OnJoinSession ||
                    kind == SessionProcessEventKind::OnSessionConnect ||
                    kind == SessionProcessEventKind::OnSessionConnectComplete ||
                    kind == SessionProcessEventKind::OnSessionDisconnect ||
                    kind == SessionProcessEventKind::OnCreateSession ||
                    kind == SessionProcessEventKind::OnDestroySession;
                int32_t index = 0;
                if (priority_event)
                {
                    index = s_session_priority_event_trace_count.fetch_add(
                        1, std::memory_order_acq_rel);
                    if (index >= 128) return;
                    index += 10000;
                }
                else
                {
                    index = s_session_event_trace_count.fetch_add(
                        1, std::memory_order_acq_rel);
                    if (index >= 128) return;
                }
                std::string class_name;
                if (context)
                {
                    RC::Unreal::UClass* cls = context->GetClassPrivate();
                    if (cls && safe_is_real(
                            static_cast<RC::Unreal::UObject*>(cls)))
                    {
                        class_name = narrow_rc_string(
                            static_cast<RC::Unreal::UObject*>(cls)
                                ->GetName());
                    }
                }
                ReplayTraceFields f;
                f.uinteger("index", static_cast<uint32_t>(index))
                 .string("function", session_process_event_label(kind))
                 .string("context_class", class_name)
                 .hex("context", reinterpret_cast<uintptr_t>(context))
                 .hex("function_ptr", reinterpret_cast<uintptr_t>(function));
                ReplayDebugTrace::instance().event(
                    "rollback_online_stage_process_event", f);
            }
            catch (...)
            {
            }
        }

        static void capture_session_callback_state(
            RC::Unreal::UFunction* function,
            SessionProcessEventKind kind,
            void* params) noexcept
        {
            if (!function) return;
            try
            {
                if (kind == SessionProcessEventKind::OnSessionMemberJoin)
                {
                    s_session_member_join_seen.store(
                        true, std::memory_order_release);
                    s_session_member_join_count.fetch_add(
                        1, std::memory_order_acq_rel);
                    return;
                }
                if (kind == SessionProcessEventKind::OnBattleComp)
                {
                    s_battle_comp_seen.store(
                        true, std::memory_order_release);
                    s_battle_comp_count.fetch_add(
                        1, std::memory_order_acq_rel);
                    return;
                }
                if (!params) return;
                if (kind == SessionProcessEventKind::OnCreateSession)
                {
                    s_create_callback_seen.store(
                        true, std::memory_order_release);
                    const bool create_result = reflected_bool_param(
                        function, params, L"bResult", false);
                    s_create_callback_result.store(
                        create_result, std::memory_order_release);
                    const int32_t true_count = create_result
                        ? s_create_callback_true_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_create_callback_true_count.load(
                              std::memory_order_acquire);
                    const int32_t false_count = !create_result
                        ? s_create_callback_false_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_create_callback_false_count.load(
                              std::memory_order_acquire);
                    emit_session_callback_result(
                        kind, create_result, -1, false, true_count,
                        false_count);
                }
                else if (kind == SessionProcessEventKind::OnDestroySession)
                {
                    s_destroy_callback_seen.store(
                        true, std::memory_order_release);
                    bool destroy_result = reflected_bool_param(
                        function, params, L"bResult", false);
                    if (!destroy_result)
                    {
                        destroy_result = reflected_bool_param(
                            function, params, L"bWasSuccessful", false);
                    }
                    s_destroy_callback_result.store(
                        destroy_result,
                        std::memory_order_release);
                    const int32_t true_count = destroy_result
                        ? s_destroy_callback_true_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_destroy_callback_true_count.load(
                              std::memory_order_acquire);
                    const int32_t false_count = !destroy_result
                        ? s_destroy_callback_false_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_destroy_callback_false_count.load(
                              std::memory_order_acquire);
                    emit_session_callback_result(
                        kind, destroy_result, -1, false, true_count,
                        false_count);
                }
                else if (kind == SessionProcessEventKind::OnJoinSession)
                {
                    s_join_complete_seen.store(
                        true, std::memory_order_release);
                    const bool join_result =
                        reflected_bool_param(
                            function, params, L"bResult", false);
                    const int32_t result_type = reflected_int_param(
                        function, params, L"ResultType", -1);
                    s_join_complete_result.store(
                        join_result,
                        std::memory_order_release);
                    s_join_complete_result_type.store(
                        result_type, std::memory_order_release);
                    const int32_t true_count = join_result
                        ? s_join_callback_true_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_join_callback_true_count.load(
                              std::memory_order_acquire);
                    const int32_t false_count = !join_result
                        ? s_join_callback_false_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_join_callback_false_count.load(
                              std::memory_order_acquire);
                    emit_session_callback_result(
                        kind, join_result, result_type, false, true_count,
                        false_count);
                    if (join_result)
                    {
                        s_join_callback_ok.store(
                            true, std::memory_order_release);
                        s_join_callback_failure = "ok";
                    }
                    else
                    {
                        s_join_callback_ok.store(
                            false, std::memory_order_release);
                        s_join_callback_failure =
                            "OnJoinSession result false";
                    }
                }
                else if (kind == SessionProcessEventKind::OnPingSearchResults)
                {
                    s_ping_search_callback_seen.store(
                        true, std::memory_order_release);
                    s_ping_search_callback_result.store(
                        reflected_bool_param(
                            function, params, L"bResult", false),
                        std::memory_order_release);
                }
                else if (
                    kind == SessionProcessEventKind::OnSessionConnectComplete)
                {
                    s_session_connect_complete_seen.store(
                        true, std::memory_order_release);
                    const bool connect_result = reflected_bool_param(
                        function, params, L"bResult", false);
                    s_session_connect_complete_result.store(
                        connect_result, std::memory_order_release);
                    bool full_member_error = reflected_bool_param(
                        function, params, L"bFullMenberError", false);
                    if (!full_member_error)
                    {
                        full_member_error = reflected_bool_param(
                            function, params, L"bFullMemberError", false);
                    }
                    s_session_connect_complete_full_member_error.store(
                        full_member_error, std::memory_order_release);
                    const int32_t true_count = connect_result
                        ? s_session_connect_callback_true_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_session_connect_callback_true_count.load(
                              std::memory_order_acquire);
                    const int32_t false_count = !connect_result
                        ? s_session_connect_callback_false_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_session_connect_callback_false_count.load(
                              std::memory_order_acquire);
                    emit_session_callback_result(
                        kind, connect_result, -1, full_member_error,
                        true_count, false_count);
                }
                else if (kind == SessionProcessEventKind::OnBattleReady)
                {
                    s_battle_ready_seen.store(
                        true, std::memory_order_release);
                    const bool battle_ready_result = reflected_bool_param(
                        function, params, L"bResult", false);
                    s_battle_ready_result.store(
                        battle_ready_result, std::memory_order_release);
                    const int32_t true_count = battle_ready_result
                        ? s_battle_ready_true_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_battle_ready_true_count.load(
                              std::memory_order_acquire);
                    const int32_t false_count = !battle_ready_result
                        ? s_battle_ready_false_count.fetch_add(
                              1, std::memory_order_acq_rel) +
                              1
                        : s_battle_ready_false_count.load(
                              std::memory_order_acquire);
                    emit_session_callback_result(
                        kind, battle_ready_result, -1, false, true_count,
                        false_count);
                }
            }
            catch (...)
            {
            }
        }

        static bool reflected_bool_param(
            RC::Unreal::UFunction* function,
            void* params,
            const wchar_t* name,
            bool fallback) noexcept
        {
            if (!function || !params || !name) return fallback;
            try
            {
                auto* prop = RC::Unreal::CastField<
                    RC::Unreal::FBoolProperty>(
                        function->FindProperty(
                            RC::Unreal::FName(name, RC::Unreal::FNAME_Find)));
                if (!prop) return fallback;
                return prop->GetPropertyValueInContainer(params);
            }
            catch (...)
            {
                return fallback;
            }
        }

        static int32_t reflected_int_param(
            RC::Unreal::UFunction* function,
            void* params,
            const wchar_t* name,
            int32_t fallback) noexcept
        {
            if (!function || !params || !name) return fallback;
            try
            {
                RC::Unreal::FProperty* raw = function->FindProperty(
                    RC::Unreal::FName(name, RC::Unreal::FNAME_Find));
                if (!raw) return fallback;
                if (auto* prop = RC::Unreal::CastField<
                        RC::Unreal::FNumericProperty>(raw))
                {
                    void* value = prop->ContainerPtrToValuePtr<void>(params);
                    if (!value) return fallback;
                    if (prop->IsInteger())
                    {
                        const int64_t signed_value =
                            prop->GetSignedIntPropertyValue(value);
                        if (signed_value < INT32_MIN ||
                            signed_value > INT32_MAX)
                        {
                            return fallback;
                        }
                        return static_cast<int32_t>(signed_value);
                    }
                }
                if (auto* prop = RC::Unreal::CastField<
                        RC::Unreal::FIntProperty>(raw))
                {
                    return *prop->ContainerPtrToValuePtr<int32_t>(params);
                }
                if (auto* prop = RC::Unreal::CastField<
                        RC::Unreal::FByteProperty>(raw))
                {
                    return static_cast<int32_t>(
                        *prop->ContainerPtrToValuePtr<uint8_t>(params));
                }
                if (auto* prop = RC::Unreal::CastField<
                        RC::Unreal::FBoolProperty>(raw))
                {
                    return prop->GetPropertyValueInContainer(params) ? 1 : 0;
                }
                const int32_t bytes = raw->GetSize();
                const void* value = raw->ContainerPtrToValuePtr<void>(params);
                if (!value) return fallback;
                if (bytes == 1)
                {
                    uint8_t v = 0;
                    return SafeReadUInt8(value, &v)
                        ? static_cast<int32_t>(v)
                        : fallback;
                }
                if (bytes == 2)
                {
                    uint16_t v = 0;
                    return SafeReadUInt16(value, &v)
                        ? static_cast<int32_t>(v)
                        : fallback;
                }
                if (bytes == 4)
                {
                    int32_t v = 0;
                    return SafeReadInt32(value, &v) ? v : fallback;
                }
            }
            catch (...)
            {
            }
            return fallback;
        }

        static RC::Unreal::FProperty* reflected_param(
            RC::Unreal::UFunction* function,
            const wchar_t* name) noexcept
        {
            if (!function || !name) return nullptr;
            try
            {
                return function->FindProperty(
                    RC::Unreal::FName(name, RC::Unreal::FNAME_Find));
            }
            catch (...)
            {
                return nullptr;
            }
        }

        static RC::Unreal::UObject* reflected_object_property(
            RC::Unreal::UObject* owner,
            const wchar_t* name) noexcept
        {
            if (!safe_is_real(owner) || !name) return nullptr;
            try
            {
                RC::Unreal::FProperty* prop =
                    owner->GetPropertyByNameInChain(name);
                if (!prop || prop->GetSize() < static_cast<int32_t>(
                        sizeof(void*)))
                {
                    return nullptr;
                }
                void* slot = prop->ContainerPtrToValuePtr<void>(owner);
                void* raw = nullptr;
                if (!slot || !SafeReadPtr(slot, &raw) || !raw)
                    return nullptr;
                auto* object = reinterpret_cast<RC::Unreal::UObject*>(raw);
                return safe_is_real(object) ? object : nullptr;
            }
            catch (...)
            {
                return nullptr;
            }
        }

        static RC::Unreal::UObject* call_get_window_by_name(
            RC::Unreal::UObject* menu,
            const wchar_t* window_name,
            std::string& reason) noexcept
        {
            reason.clear();
            if (!safe_is_real(menu) || !window_name)
            {
                reason = "menu-or-window-name-unavailable";
                return nullptr;
            }
            try
            {
                auto* fn = menu->GetFunctionByNameInChain(
                    L"GetWindowByName");
                if (!fn)
                {
                    reason = "GetWindowByName-unavailable";
                    return nullptr;
                }
                const int32_t param_bytes = fn->GetPropertiesSize();
                if (param_bytes <= 0 || param_bytes > 512)
                {
                    reason = "GetWindowByName-param-size-invalid";
                    return nullptr;
                }

                RC::Unreal::FProperty* name_raw =
                    reflected_param(fn, L"windowName");
                if (!name_raw)
                    name_raw = reflected_param(fn, L"WindowName");
                if (!name_raw)
                    name_raw = reflected_param(fn, L"Name");
                if (!name_raw)
                {
                    for (RC::Unreal::FProperty* prop :
                         RC::Unreal::TFieldRange<RC::Unreal::FProperty>(
                             fn,
                             RC::Unreal::EFieldIterationFlags::None))
                    {
                        if (!reflected_parameter_is_input(prop)) continue;
                        if (RC::Unreal::CastField<
                                RC::Unreal::FNameProperty>(prop) ||
                            RC::Unreal::CastField<
                                RC::Unreal::FStrProperty>(prop))
                        {
                            name_raw = prop;
                            break;
                        }
                    }
                }
                auto* name_prop = RC::Unreal::CastField<
                    RC::Unreal::FNameProperty>(name_raw);
                auto* string_prop = RC::Unreal::CastField<
                    RC::Unreal::FStrProperty>(name_raw);
                auto* return_prop = cast_reflected_object_property(
                    fn->GetReturnProperty());
                if (!return_prop)
                    return_prop = cast_reflected_object_property(
                        reflected_param(fn, L"ReturnValue"));
                if ((!name_prop && !string_prop) || !return_prop)
                {
                    reason = "GetWindowByName-signature-unsupported: " +
                             describe_function_signature(fn);
                    return nullptr;
                }

                std::vector<uint8_t> params(
                    static_cast<size_t>(param_bytes), 0);
                bool string_initialized = false;
                if (string_prop)
                {
                    string_prop->InitializeValue_InContainer(params.data());
                    string_initialized = true;
                    string_prop->SetPropertyValueInContainer(
                        params.data(), RC::Unreal::FString(window_name));
                }
                else
                {
                    *name_prop->ContainerPtrToValuePtr<RC::Unreal::FName>(
                        params.data()) = RC::Unreal::FName(
                            window_name, RC::Unreal::FNAME_Add);
                }

                const bool called =
                    safe_process_event(menu, fn, params.data());
                RC::Unreal::UObject* result = called
                    ? safe_get_reflected_object(return_prop, params.data())
                    : nullptr;
                if (string_initialized)
                    string_prop->DestroyValue_InContainer(params.data());
                if (!called)
                    reason = "GetWindowByName-ProcessEvent-failed";
                else if (!safe_is_real(result))
                    reason = "GetWindowByName-returned-null";
                else
                    reason = "GetWindowByName-ok";
                return safe_is_real(result) ? result : nullptr;
            }
            catch (...)
            {
                reason = "GetWindowByName-exception";
                return nullptr;
            }
        }

        static bool write_reflected_u8_param(
            RC::Unreal::FProperty* prop,
            void* params,
            uint8_t value) noexcept
        {
            if (!prop || !params) return false;
            try
            {
                if (auto* byte_prop = RC::Unreal::CastField<
                        RC::Unreal::FByteProperty>(prop))
                {
                    *byte_prop->ContainerPtrToValuePtr<uint8_t>(params) =
                        value;
                    return true;
                }
                if (prop->GetSize() != 1) return false;
                void* value_ptr = prop->ContainerPtrToValuePtr<void>(params);
                if (!value_ptr) return false;
                *static_cast<uint8_t*>(value_ptr) = value;
                return true;
            }
            catch (...)
            {
                return false;
            }
        }

        static void capture_select_room_state_context(
            RC::Unreal::UObject* context,
            RC::Unreal::UFunction* function,
            SessionProcessEventKind kind) noexcept
        {
            if (!context || !function) return;
            try
            {
                if (kind != SessionProcessEventKind::OnPingSearchResults &&
                    kind != SessionProcessEventKind::OnJoinSession)
                {
                    return;
                }
                RC::Unreal::UClass* cls = context->GetClassPrivate();
                if (!cls ||
                    !safe_is_real(static_cast<RC::Unreal::UObject*>(cls)))
                {
                    return;
                }
                const std::string class_name = narrow_rc_string(
                    static_cast<RC::Unreal::UObject*>(cls)->GetName());
                if (class_name.find("SelectRoomState") ==
                    std::string::npos)
                {
                    return;
                }
                s_select_room_state_context.store(
                    reinterpret_cast<uintptr_t>(context),
                    std::memory_order_release);
            }
            catch (...)
            {
            }
        }

        static bool call_session_result_string_helper(
            const wchar_t* function_name,
            const void* search_result,
            int32_t search_result_bytes,
            std::string& out) noexcept
        {
            out.clear();
            if (!function_name || !search_result || search_result_bytes <= 0)
                return false;
            auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                RC::Unreal::UObject*>(
                    nullptr, nullptr,
                    STR("/Script/LuxorSessionUtil.Default__LuxorSessionData"));
            if (!safe_is_real(cdo)) return false;
            auto* fn = cdo->GetFunctionByNameInChain(function_name);
            if (!fn) return false;
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096) return false;
            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            RC::Unreal::FProperty* result_prop =
                reflected_param(fn, L"inSessionData");
            auto* ret_prop = RC::Unreal::CastField<RC::Unreal::FStrProperty>(
                fn->GetReturnProperty());
            if (!result_prop || !ret_prop) return false;
            const int32_t result_prop_bytes = result_prop->GetSize();
            if (result_prop_bytes <= 0 ||
                result_prop_bytes > search_result_bytes)
            {
                return false;
            }
            if (!SafeReadBytes(
                    search_result,
                    result_prop->ContainerPtrToValuePtr<void>(
                        params.data()),
                    static_cast<size_t>(result_prop_bytes)))
            {
                return false;
            }
            if (!safe_process_event(cdo, fn, params.data())) return false;
            auto* result = ret_prop->ContainerPtrToValuePtr<
                RC::Unreal::FString>(params.data());
            if (!result) return false;
            out = fstring_to_utf8(*result);
            return true;
        }

        static bool session_result_matches_text(
            const std::string& value,
            const std::string& expected) noexcept
        {
            return !expected.empty() && value == expected;
        }

        static bool call_join_session_process_event(
            const void* search_result,
            int32_t search_result_bytes) noexcept
        {
            s_join_callback_requested.store(true, std::memory_order_release);
            s_join_callback_ok.store(false, std::memory_order_release);
            s_join_complete_seen.store(false, std::memory_order_release);
            s_join_complete_result.store(false, std::memory_order_release);
            s_join_complete_result_type.store(-1, std::memory_order_release);

            RC::Unreal::UObject* session_hub =
                reinterpret_cast<RC::Unreal::UObject*>(
                    s_join_session_hub.load(std::memory_order_acquire));
            if (!safe_is_real(session_hub))
            {
                s_join_callback_failure = "join-session-hub-invalid";
                return false;
            }
            if (!search_result || search_result_bytes <= 0)
            {
                s_join_callback_failure = "join-search-result-empty";
                return false;
            }

            try
            {
                RC::Unreal::UFunction* join_fn =
                    session_hub->GetFunctionByName(STR("JoinSession"));
                if (!join_fn)
                {
                    s_join_callback_failure =
                        "ULuxorSessionHub.JoinSession unavailable";
                    return false;
                }

                const int32_t param_bytes = join_fn->GetPropertiesSize();
                if (param_bytes <= 0 || param_bytes > 4096)
                {
                    s_join_callback_failure = "JoinSession param-size invalid";
                    return false;
                }
                std::vector<uint8_t> params(
                    static_cast<size_t>(param_bytes), 0);

                auto* main_user_prop = RC::Unreal::CastField<
                    RC::Unreal::FIntProperty>(
                        reflected_param(join_fn, L"inMainUserId"));
                auto* session_prop = RC::Unreal::CastField<
                    RC::Unreal::FNameProperty>(
                        reflected_param(join_fn, L"inSessionName"));
                RC::Unreal::FProperty* result_prop =
                    reflected_param(join_fn, L"SearchResult");
                if (!main_user_prop || !session_prop || !result_prop)
                {
                    s_join_callback_failure =
                        "JoinSession reflected params unavailable";
                    return false;
                }

                *main_user_prop->ContainerPtrToValuePtr<int32_t>(
                    params.data()) =
                    s_join_main_user_id.load(std::memory_order_acquire);

                const std::string session =
                    s_join_session_name.empty()
                        ? std::string("rollback-p2p")
                        : s_join_session_name;
                const std::wstring session_w = widen_utf8(session);
                RC::Unreal::FName session_name(
                    session_w.c_str(), RC::Unreal::FNAME_Add);
                *session_prop->ContainerPtrToValuePtr<RC::Unreal::FName>(
                    params.data()) = session_name;

                const int32_t result_prop_bytes = result_prop->GetSize();
                if (result_prop_bytes <= 0 ||
                    result_prop_bytes > search_result_bytes)
                {
                    s_join_callback_failure =
                        "JoinSession SearchResult size mismatch";
                    return false;
                }
                s_find_result_element_size.store(
                    result_prop_bytes, std::memory_order_release);
                if (!SafeReadBytes(
                        search_result,
                        result_prop->ContainerPtrToValuePtr<void>(
                            params.data()),
                        static_cast<size_t>(result_prop_bytes)))
                {
                    s_join_callback_failure =
                        "JoinSession SearchResult unreadable";
                    return false;
                }

                session_hub->ProcessEvent(join_fn, params.data());

                bool join_ok = false;
                if (auto* ret_prop = RC::Unreal::CastField<
                        RC::Unreal::FBoolProperty>(
                            join_fn->GetReturnProperty()))
                {
                    join_ok = ret_prop->GetPropertyValueInContainer(
                        params.data());
                }
                s_join_callback_ok.store(join_ok, std::memory_order_release);
                s_join_callback_failure = join_ok ? "ok"
                                                  : "JoinSession returned false";
                return join_ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] JoinSession ProcessEvent threw: {}\n"),
                    RC::to_generic_string(e.what()));
                s_join_callback_failure = "JoinSession ProcessEvent threw";
            }
            catch (...)
            {
                s_join_callback_failure = "JoinSession ProcessEvent threw";
            }
            return false;
        }

        static void handle_process_event_post(
            RC::Unreal::UObject* context,
            RC::Unreal::UFunction* function,
            void* params) noexcept
        {
            RollbackP2PHarness* active =
                s_active_instance.load(std::memory_order_acquire);
            if (active && active->m_cfg.mirrored_versus_requested)
                active->trace_mirrored_versus_lifecycle_event(
                    context, function, params);
            if (active && active->m_cfg.observe_gameflow_requested)
                active->trace_gameflow_observe_process_event(
                    context, function, params);

            const bool trace_enabled =
                s_session_trace_enabled.load(std::memory_order_acquire);
            const bool join_capture =
                s_join_capture_enabled.load(std::memory_order_acquire);
            if (!trace_enabled && !join_capture)
                return;
            if (!function)
                return;
            const SessionProcessEventKind kind =
                classify_session_process_event(function);
            if (kind == SessionProcessEventKind::None)
                return;
            if (trace_enabled)
            {
                trace_session_process_event(context, function, kind);
                capture_session_callback_state(function, kind, params);
                capture_select_room_state_context(context, function, kind);
                service_active_session_callback_followup(kind);
            }
            if (!join_capture)
                return;
            if (s_join_callback_ok.load(std::memory_order_acquire))
                return;
            if (kind != SessionProcessEventKind::OnFindSession)
                return;

            bool expected = false;
            if (!s_join_in_progress.compare_exchange_strong(
                    expected, true, std::memory_order_acq_rel))
            {
                return;
            }

            s_find_callback_seen.store(true, std::memory_order_release);
            const bool result_ok =
                reflected_bool_param(function, params, L"bResult", false);
            s_find_callback_result.store(result_ok, std::memory_order_release);
            if (!result_ok)
            {
                s_join_callback_failure = "OnFindSession result false";
                s_join_in_progress.store(false, std::memory_order_release);
                return;
            }

            try
            {
                auto* results_prop = RC::Unreal::CastField<
                    RC::Unreal::FArrayProperty>(
                        reflected_param(function, L"Results"));
                if (!results_prop)
                {
                    s_join_callback_failure =
                        "OnFindSession Results param unavailable";
                    s_join_in_progress.store(false, std::memory_order_release);
                    return;
                }
                void* array_ptr =
                    results_prop->ContainerPtrToValuePtr<void>(params);
                auto* array_bytes = reinterpret_cast<uint8_t*>(array_ptr);
                void* data_ptr = nullptr;
                int32_t count = 0;
                int32_t max = 0;
                if (!SafeReadPtr(array_bytes, &data_ptr) ||
                    !SafeReadInt32(array_bytes + 8, &count) ||
                    !SafeReadInt32(array_bytes + 12, &max))
                {
                    s_join_callback_failure =
                        "OnFindSession Results header unreadable";
                    s_join_in_progress.store(false,
                                             std::memory_order_release);
                    return;
                }
                const int32_t element_size =
                    results_prop->GetInner()
                        ? results_prop->GetInner()->GetElementSize()
                        : 0;
                s_find_result_count.store(count, std::memory_order_release);
                s_find_result_element_size.store(
                    element_size, std::memory_order_release);
                if (count <= 0 || element_size <= 0)
                {
                    clear_find_result_snapshot();
                    s_join_callback_failure = "OnFindSession empty Results";
                    s_join_in_progress.store(false, std::memory_order_release);
                    return;
                }
                if (!data_ptr || max < count || count > 64)
                {
                    clear_find_result_snapshot();
                    s_join_callback_failure =
                        "OnFindSession Results header invalid";
                    s_join_in_progress.store(false,
                                             std::memory_order_release);
                    return;
                }
                (void)capture_find_result_snapshot(
                    data_ptr, count, element_size);
                s_join_callback_failure =
                    "OnFindSession results available for poll";
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] OnFindSession capture threw: {}\n"),
                    RC::to_generic_string(e.what()));
                s_join_callback_failure = "OnFindSession capture threw";
            }
            catch (...)
            {
                s_join_callback_failure = "OnFindSession capture threw";
            }
            s_join_in_progress.store(false, std::memory_order_release);
        }

        bool write_selected_find_result(
            RC::Unreal::UObject* owner,
            const void* selected_result,
            int32_t selected_result_bytes,
            const char* owner_label,
            bool record_shape,
            std::string& reason) noexcept
        {
            reason.clear();
            if (!safe_is_real(owner))
            {
                reason = std::string(owner_label ? owner_label : "owner")
                    + ".FindResult owner unavailable";
                return false;
            }
            if (!selected_result)
            {
                reason = "selected-search-result-empty";
                return false;
            }

            try
            {
                RC::Unreal::FProperty* find_result_prop =
                    owner->GetPropertyByNameInChain(L"FindResult");
                if (!find_result_prop)
                {
                    reason = std::string(owner_label ? owner_label : "owner")
                        + ".FindResult unavailable";
                    return false;
                }

                const int32_t prop_bytes = find_result_prop->GetSize();
                const int32_t element_bytes =
                    find_result_prop->GetElementSize();
                const int32_t array_dim = find_result_prop->GetArrayDim();
                if (record_shape)
                {
                    m_join_scene_result_bytes = prop_bytes;
                    m_join_scene_result_element_bytes = element_bytes;
                    m_join_scene_result_array_dim = array_dim;
                    m_join_scene_result_offset =
                        find_result_prop->GetOffset_Internal();
                    m_join_scene_result_struct_name.clear();
                    if (auto* struct_prop = RC::Unreal::CastField<
                            RC::Unreal::FStructProperty>(find_result_prop))
                    {
                        if (auto* script_struct =
                                RC::Unreal::ToRawPtr(
                                    struct_prop->GetStruct()))
                        {
                            m_join_scene_result_struct_name =
                                narrow_rc_string(script_struct->GetName());
                        }
                    }
                }

                if (auto* array_prop =
                        RC::Unreal::CastField<RC::Unreal::FArrayProperty>(
                            find_result_prop))
                {
                    auto* inner = array_prop->GetInner();
                    const int32_t inner_bytes =
                        inner ? inner->GetElementSize() : 0;
                    if (!inner || inner_bytes <= 0 ||
                        selected_result_bytes < inner_bytes)
                    {
                        if (record_shape)
                        {
                            m_join_scene_result_struct_name =
                                "FArrayProperty";
                            m_join_scene_result_write_bytes = 0;
                        }
                        else
                        {
                            m_join_scene_select_room_state_result_write_bytes =
                                0;
                        }
                        reason =
                            std::string(owner_label ? owner_label : "owner")
                            + ".FindResult array element mismatch";
                        return false;
                    }

                    auto* array_value =
                        array_prop->ContainerPtrToValuePtr<void>(owner);
                    if (!array_value)
                    {
                        reason =
                            std::string(owner_label ? owner_label : "owner")
                            + ".FindResult array unavailable";
                        return false;
                    }

                    auto* script_array =
                        static_cast<RC::Unreal::FScriptArray*>(array_value);
                    const uint32_t inner_alignment =
                        static_cast<uint32_t>(inner->GetMinAlignment());
                    script_array->Empty(0, inner_bytes, inner_alignment);
                    const int32_t index = script_array->AddZeroed(
                        1, inner_bytes, inner_alignment);
                    uint8_t* dest = static_cast<uint8_t*>(
                        script_array->GetData());
                    if (dest)
                    {
                        dest += static_cast<size_t>(index) *
                                static_cast<size_t>(inner_bytes);
                    }
                    if (!dest ||
                        !SafeWriteBytes(
                            dest,
                            selected_result,
                            static_cast<size_t>(inner_bytes)))
                    {
                        reason =
                            std::string(owner_label ? owner_label : "owner")
                            + ".FindResult array write failed";
                        return false;
                    }
                    if (record_shape)
                    {
                        m_join_scene_result_struct_name = "FArrayProperty";
                        m_join_scene_result_write_bytes = inner_bytes;
                    }
                    else
                    {
                        m_join_scene_select_room_state_result_write_bytes =
                            inner_bytes;
                    }
                    reason =
                        std::string(owner_label ? owner_label : "owner")
                        + ".FindResult native array staged(count=1,elem="
                        + std::to_string(inner_bytes) + ")";
                    return true;
                }

                if (element_bytes <= 0 || element_bytes > 32 ||
                    prop_bytes < element_bytes)
                {
                    reason = std::string(owner_label ? owner_label : "owner")
                        + ".FindResult size mismatch";
                    return false;
                }

                void* dest =
                    find_result_prop->ContainerPtrToValuePtr<void>(owner);
                uint8_t result_storage[64] {};
                if (selected_result_bytes <= 0)
                {
                    reason = "selected-search-result-size-invalid";
                    return false;
                }
                if (selected_result_bytes < element_bytes)
                {
                    reason = std::string(owner_label ? owner_label : "owner")
                        + ".FindResult source smaller than destination";
                    return false;
                }
                const int32_t copy_bytes =
                    std::min<int32_t>(
                        selected_result_bytes,
                        std::min<int32_t>(
                            element_bytes,
                            static_cast<int32_t>(sizeof(result_storage))));
                if (copy_bytes <= 0 ||
                    !SafeReadBytes(
                        selected_result,
                        result_storage,
                        static_cast<size_t>(copy_bytes)))
                {
                    reason = "selected-search-result-unreadable";
                    return false;
                }
                const int32_t write_bytes = element_bytes;
                if (record_shape)
                {
                    m_join_scene_result_write_bytes = write_bytes;
                }
                else
                {
                    m_join_scene_select_room_state_result_write_bytes =
                        write_bytes;
                }
                if (!dest ||
                    !SafeWriteBytes(
                        dest,
                        result_storage,
                        static_cast<size_t>(write_bytes)))
                {
                    reason = std::string(owner_label ? owner_label : "owner")
                        + ".FindResult write failed";
                    return false;
                }

                reason = "ok";
                return true;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] FindResult write threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = std::string(owner_label ? owner_label : "owner")
                    + ".FindResult write threw";
            }
            catch (...)
            {
                reason = std::string(owner_label ? owner_label : "owner")
                    + ".FindResult write threw";
            }
            return false;
        }

        RC::Unreal::UObject* find_active_select_room_state(
            RC::Unreal::UObject* player_match_scene) noexcept
        {
            if (!safe_is_real(player_match_scene)) return nullptr;
            RC::Unreal::UObject* found = nullptr;
            try
            {
                RC::Unreal::UObjectGlobals::ForEachUObject(
                    [&](RC::Unreal::UObject* obj, int32_t, int32_t) {
                        if (!obj || !safe_is_real(obj))
                            return RC::LoopAction::Continue;
                        RC::Unreal::UClass* cls = nullptr;
                        try
                        {
                            cls = obj->GetClassPrivate();
                        }
                        catch (...)
                        {
                            return RC::LoopAction::Continue;
                        }
                        if (!cls ||
                            !safe_is_real(
                                static_cast<RC::Unreal::UObject*>(cls)))
                        {
                            return RC::LoopAction::Continue;
                        }
                        const std::string class_name = narrow_rc_string(
                            static_cast<RC::Unreal::UObject*>(cls)->GetName());
                        if (class_name.find("SelectRoomState") ==
                            std::string::npos)
                        {
                            return RC::LoopAction::Continue;
                        }
                        RC::Unreal::UObject* ref_lobby = nullptr;
                        if (!safe_get_uobject_property(
                                obj, L"RefLobbyScene", ref_lobby) ||
                            ref_lobby != player_match_scene)
                        {
                            return RC::LoopAction::Continue;
                        }
                        found = obj;
                        return RC::LoopAction::Break;
                    });
            }
            catch (...)
            {
                found = nullptr;
            }
            return found;
        }

        RC::Unreal::UObject* find_active_player_match_lobby_state(
            RC::Unreal::UObject* player_match_scene,
            const char* class_fragment,
            std::string* reason = nullptr) noexcept
        {
            if (reason) reason->clear();
            if (!safe_is_real(player_match_scene) || !class_fragment ||
                class_fragment[0] == '\0')
            {
                if (reason) *reason = "invalid-scene-or-class-fragment";
                return nullptr;
            }
            RC::Unreal::UObject* strict_found = nullptr;
            RC::Unreal::UObject* sole_candidate = nullptr;
            uint32_t candidate_count = 0;
            uint32_t linked_candidate_count = 0;
            std::string candidate_sample;
            try
            {
                RC::Unreal::UObjectGlobals::ForEachUObject(
                    [&](RC::Unreal::UObject* obj, int32_t, int32_t) {
                        if (!obj || !safe_is_real(obj))
                            return RC::LoopAction::Continue;
                        RC::Unreal::UClass* cls = nullptr;
                        try
                        {
                            cls = obj->GetClassPrivate();
                        }
                        catch (...)
                        {
                            return RC::LoopAction::Continue;
                        }
                        if (!cls ||
                            !safe_is_real(
                                static_cast<RC::Unreal::UObject*>(cls)))
                        {
                            return RC::LoopAction::Continue;
                        }
                        const std::string class_name = narrow_rc_string(
                            static_cast<RC::Unreal::UObject*>(cls)->GetName());
                        if (class_name.find(class_fragment) ==
                            std::string::npos)
                        {
                            return RC::LoopAction::Continue;
                        }
                        ++candidate_count;
                        if (candidate_count == 1)
                            sole_candidate = obj;
                        else
                            sole_candidate = nullptr;

                        RC::Unreal::UObject* ref_lobby = nullptr;
                        const bool ref_lobby_matches =
                            safe_get_uobject_property(
                                obj, L"RefLobbyScene", ref_lobby) &&
                            ref_lobby == player_match_scene;
                        RC::Unreal::UObject* owner_scene = nullptr;
                        const bool owner_scene_matches =
                            safe_get_uobject_property(
                                obj, L"OwnerScene", owner_scene) &&
                            owner_scene == player_match_scene;
                        if (!candidate_sample.empty())
                            append_limited_name(candidate_sample, "|", 1024);
                        if (candidate_sample.size() < 1024)
                        {
                            std::string sample = class_name + ":" +
                                narrow_rc_string(obj->GetName()) +
                                ":ref=" +
                                (ref_lobby_matches ? "1" : "0") +
                                ":owner=" +
                                (owner_scene_matches ? "1" : "0");
                            append_limited_name(
                                candidate_sample, sample, 1024);
                        }
                        if (!ref_lobby_matches && !owner_scene_matches)
                            return RC::LoopAction::Continue;

                        ++linked_candidate_count;
                        strict_found = obj;
                        return RC::LoopAction::Break;
                    });
            }
            catch (...)
            {
                strict_found = nullptr;
                sole_candidate = nullptr;
            }
            RC::Unreal::UObject* found =
                strict_found ? strict_found
                             : (candidate_count == 1 ? sole_candidate
                                                     : nullptr);
            if (reason)
            {
                *reason = "class=";
                *reason += class_fragment;
                *reason += " candidates=";
                *reason += std::to_string(candidate_count);
                *reason += " linked=";
                *reason += std::to_string(linked_candidate_count);
                *reason += " selected=";
                *reason += found ? narrow_rc_string(found->GetName())
                                 : std::string("<none>");
                if (!candidate_sample.empty())
                {
                    *reason += " sample=";
                    *reason += candidate_sample;
                }
            }
            return found;
        }

        RC::Unreal::UObject* find_active_player_match_in_room_state(
            RC::Unreal::UObject* player_match_scene) noexcept
        {
            if (!safe_is_real(player_match_scene)) return nullptr;
            RC::Unreal::UObject* found = nullptr;
            try
            {
                RC::Unreal::UObjectGlobals::ForEachUObject(
                    [&](RC::Unreal::UObject* obj, int32_t, int32_t) {
                        if (!obj || !safe_is_real(obj))
                            return RC::LoopAction::Continue;
                        RC::Unreal::UClass* cls = nullptr;
                        try
                        {
                            cls = obj->GetClassPrivate();
                        }
                        catch (...)
                        {
                            return RC::LoopAction::Continue;
                        }
                        if (!cls ||
                            !safe_is_real(
                                static_cast<RC::Unreal::UObject*>(cls)))
                        {
                            return RC::LoopAction::Continue;
                        }
                        const std::string class_name = narrow_rc_string(
                            static_cast<RC::Unreal::UObject*>(cls)->GetName());
                        if (class_name.find("PlayerMatchInRoomState") ==
                            std::string::npos)
                        {
                            return RC::LoopAction::Continue;
                        }

                        RC::Unreal::UObject* ref_lobby = nullptr;
                        const bool ref_lobby_matches =
                            safe_get_uobject_property(
                                obj, L"RefLobbyScene", ref_lobby) &&
                            ref_lobby == player_match_scene;
                        RC::Unreal::UObject* owner_scene = nullptr;
                        const bool owner_scene_matches =
                            safe_get_uobject_property(
                                obj, L"OwnerScene", owner_scene) &&
                            owner_scene == player_match_scene;
                        if (!ref_lobby_matches && !owner_scene_matches)
                            return RC::LoopAction::Continue;

                        found = obj;
                        return RC::LoopAction::Break;
                    });
            }
            catch (...)
            {
                found = nullptr;
            }
            return found;
        }

        uint64_t join_scene_ping_wait_elapsed_millis() const noexcept
        {
            if (m_join_scene_ping_wait_started_at ==
                std::chrono::steady_clock::time_point {})
            {
                return 0;
            }
            const auto elapsed = std::chrono::steady_clock::now() -
                                 m_join_scene_ping_wait_started_at;
            return static_cast<uint64_t>(
                std::chrono::duration_cast<std::chrono::milliseconds>(
                    elapsed).count());
        }

        void emit_join_pipeline_trace(const char* phase,
                                      bool ok,
                                      RC::Unreal::UObject* player_match_scene,
                                      uint64_t tick) noexcept
        {
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .string("phase", phase ? phase : "")
             .uinteger("tick", tick)
             .uinteger("join_scene_pipeline_step",
                       static_cast<uint32_t>(m_join_scene_pipeline_step))
              .hex("join_scene_selected_result",
                   m_join_scene_selected_result)
              .integer("join_scene_selected_result_bytes",
                       m_join_scene_selected_result_bytes)
              .uinteger("join_scene_selected_tick",
                        m_join_scene_selected_tick)
              .uinteger("join_scene_last_step_tick",
                        m_join_scene_last_step_tick)
             .string("join_scene_mode", m_join_scene_mode)
             .string("join_scene_failure", m_join_scene_failure)
             .boolean("join_scene_result_staged",
                      m_join_scene_result_staged)
             .boolean("join_scene_select_room_requested",
                      m_join_scene_select_room_requested)
             .boolean("join_scene_select_room_ok",
                      m_join_scene_select_room_ok)
             .boolean("join_scene_select_room_state_found",
                      m_join_scene_select_room_state_found)
             .boolean("join_scene_select_room_state_result_staged",
                      m_join_scene_select_room_state_result_staged)
             .hex("join_scene_active_menu_widget",
                  m_join_scene_active_menu_widget)
             .string("join_scene_active_menu_name",
                     m_join_scene_active_menu_name)
             .integer("join_scene_ui_command_index",
                      m_join_scene_ui_command_index)
             .uinteger("join_scene_ui_command_tick",
                       m_join_scene_ui_command_tick)
             .boolean("join_scene_ui_command_requested",
                      m_join_scene_ui_command_requested)
             .boolean("join_scene_ui_command_ok",
                      m_join_scene_ui_command_ok)
             .string("join_scene_ui_command",
                     m_join_scene_ui_command)
             .string("join_scene_ui_command_failure",
                     m_join_scene_ui_command_failure)
              .uinteger("join_scene_ping_wait_start_tick",
                        m_join_scene_ping_wait_start_tick)
              .uinteger("join_scene_ping_wait_elapsed_millis",
                        join_scene_ping_wait_elapsed_millis())
              .uinteger("join_scene_room_select_menu_wait_start_tick",
                        m_join_scene_room_select_menu_wait_start_tick)
              .uinteger("join_scene_ping_baseline_count",
                        m_join_scene_ping_baseline_count)
              .boolean("join_scene_ping_seen", m_join_scene_ping_seen)
              .boolean("join_scene_ping_result", m_join_scene_ping_result)
              .boolean("join_scene_terminal_failure",
                       m_join_scene_terminal_failure)
              .boolean("join_scene_decide_requested",
                       m_join_scene_decide_requested)
             .boolean("join_scene_decide_ok",
                      m_join_scene_decide_ok)
             .boolean("join_scene_poll_ok", m_join_scene_poll_ok);
            add_uobject_identity_fields(
                f, "player_match_scene",
                describe_uobject(player_match_scene));
            ReplayDebugTrace::instance().event(
                "rollback_online_stage_join_pipeline", f);
        }

        bool latch_failed_join_complete_if_seen() noexcept
        {
            if (!s_join_complete_seen.load(std::memory_order_acquire) ||
                s_join_complete_result.load(std::memory_order_acquire))
            {
                return false;
            }
            const int32_t result_type =
                s_join_complete_result_type.load(std::memory_order_acquire);
            switch (result_type)
            {
            case 1:
                m_join_scene_failure =
                    "OnJoinSession result false: session is full";
                break;
            case 2:
                m_join_scene_failure =
                    "OnJoinSession result false: session does not exist";
                break;
            case 3:
                m_join_scene_failure =
                    "OnJoinSession result false: could not retrieve address";
                break;
            case 4:
                m_join_scene_failure =
                    "OnJoinSession result false: already in session";
                break;
            case 5:
                m_join_scene_failure =
                    "OnJoinSession result false: unknown error";
                break;
            default:
                m_join_scene_failure =
                    "OnJoinSession result false";
                break;
            }
            s_join_callback_failure = m_join_scene_failure.c_str();
            m_join_scene_terminal_failure = true;
            return true;
        }

        bool stage_selected_result_on_player_match_scene(
            RC::Unreal::UObject* player_match_scene,
            const void* selected_result,
            int32_t selected_result_bytes,
            uintptr_t selected_identity,
            uint64_t tick) noexcept
        {
            if (!safe_is_real(player_match_scene))
            {
                m_join_scene_failure =
                    "PlayerMatchLobbyScene unavailable";
                s_join_callback_failure =
                    "PlayerMatchLobbyScene unavailable";
                return false;
            }
            if (!selected_result)
            {
                m_join_scene_failure = "selected-search-result-empty";
                s_join_callback_failure = "selected-search-result-empty";
                return false;
            }
            if (selected_result_bytes <= 0)
            {
                m_join_scene_failure = "selected-search-result-size-invalid";
                s_join_callback_failure =
                    "selected-search-result-size-invalid";
                return false;
            }

            const uintptr_t selected_ptr =
                selected_identity ? selected_identity :
                                    reinterpret_cast<uintptr_t>(selected_result);
            const bool new_selection =
                m_join_scene_pipeline_step == kJoinScenePipelineNone ||
                m_join_scene_selected_result != selected_ptr;
            if (new_selection)
            {
                m_join_scene_result_staged = false;
                m_join_scene_result_bytes = 0;
                m_join_scene_result_element_bytes = 0;
                m_join_scene_result_write_bytes = 0;
                m_join_scene_result_array_dim = 0;
                m_join_scene_result_offset = 0;
                m_join_scene_result_struct_name.clear();
                m_join_scene_select_room_state = 0;
                m_join_scene_select_room_state_found = false;
                m_join_scene_select_room_state_result_staged = false;
                m_join_scene_select_room_state_result_write_bytes = 0;
                m_join_scene_select_room_requested = false;
                m_join_scene_select_room_ok = false;
                m_join_scene_active_menu_widget = 0;
                m_join_scene_active_menu_name.clear();
                m_join_scene_ui_command_index = -1;
                m_join_scene_ui_command_tick = 0;
                m_join_scene_ui_command_requested = false;
                m_join_scene_ui_command_ok = false;
                m_join_scene_ui_command.clear();
                m_join_scene_ui_command_failure.clear();
                m_join_scene_decide_requested = false;
                m_join_scene_decide_ok = false;
                m_join_scene_search_connecting_requested = false;
                m_join_scene_search_connecting_ok = false;
                m_join_scene_poll_ok = false;
                m_join_scene_selected_result = selected_ptr;
                m_join_scene_selected_result_bytes = selected_result_bytes;
                std::vector<uint8_t> selected_storage(
                    static_cast<size_t>(selected_result_bytes), 0);
                if (!SafeReadBytes(
                        selected_result,
                        selected_storage.data(),
                        selected_storage.size()))
                {
                m_join_scene_selected_result = 0;
                m_join_scene_selected_result_bytes = 0;
                m_join_scene_selected_result_storage.clear();
                m_join_scene_pipeline_step = kJoinScenePipelineNone;
                m_join_scene_mode = "not-run";
                m_join_scene_failure =
                    "selected-search-result-unreadable";
                    s_join_callback_failure =
                        "selected-search-result-unreadable";
                    return false;
                }
                m_join_scene_selected_result_storage =
                    std::move(selected_storage);
                m_join_scene_selected_tick = tick;
                m_join_scene_last_step_tick = tick;
                m_join_scene_pipeline_step = kJoinScenePipelineSelected;
                m_join_scene_mode = "player-match-state-compat";
                m_join_scene_failure =
                    tick == 0 ? "selected-search-result" :
                                "selected-search-result-pending-next-tick";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "selected-result-latched", false,
                    player_match_scene, tick);
                if (tick != 0)
                    return false;
            }
            else if (tick != 0 && m_join_scene_last_step_tick == tick)
            {
                m_join_scene_failure = "join-pipeline-waiting-next-tick";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "waiting-next-tick", false,
                    player_match_scene, tick);
                return false;
            }

            if (m_join_scene_terminal_failure)
            {
                s_join_callback_failure = m_join_scene_failure.c_str();
                return false;
            }

            m_join_scene_last_step_tick = tick;
            const void* selected_bytes = selected_result;
            int32_t selected_bytes_size = selected_result_bytes;
            if (!m_join_scene_selected_result_storage.empty())
            {
                selected_bytes = m_join_scene_selected_result_storage.data();
                selected_bytes_size = m_join_scene_selected_result_bytes;
            }

            try
            {
                std::string find_result_reason;
                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineSelected)
                {
                    emit_join_pipeline_trace(
                        "scene-result-stage-begin", false,
                        player_match_scene, tick);
                    m_join_scene_result_staged =
                        write_selected_find_result(
                            player_match_scene,
                            selected_bytes,
                            selected_bytes_size,
                            "PlayerMatchLobbyScene",
                            true,
                            find_result_reason);
                    if (!m_join_scene_result_staged)
                    {
                        m_join_scene_failure = find_result_reason;
                        s_join_callback_failure =
                            "PlayerMatchLobbyScene.FindResult stage failed";
                        return false;
                    }
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineSceneResultStaged;
                    m_join_scene_failure =
                        "PlayerMatchLobbyScene.FindResult staged";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "scene-result-stage-end", true,
                        player_match_scene, tick);
                    return false;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineSceneResultStaged)
                {
                    std::string state_reason;
                    emit_join_pipeline_trace(
                        "select-room-request-begin", false,
                        player_match_scene, tick);
                    m_join_scene_select_room_requested = true;
                    m_join_scene_select_room_ok =
                        request_player_match_lobby_state(
                            player_match_scene,
                            L"SelectRoom",
                            state_reason);
                    if (!m_join_scene_select_room_ok)
                    {
                        m_join_scene_failure = state_reason;
                        s_join_callback_failure =
                            "PlayerMatchLobbyScene.SelectRoom failed";
                        return false;
                    }
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineSelectRoomRequested;
                    m_join_scene_failure = state_reason;
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "select-room-request-end", true,
                        player_match_scene, tick);
                    return false;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineSelectRoomRequested)
                {
                    emit_join_pipeline_trace(
                        "select-room-poll-begin", false,
                        player_match_scene, tick);
                    m_join_scene_poll_ok =
                        call_player_match_polling_change_state(
                            player_match_scene);
                    if (!m_join_scene_poll_ok)
                    {
                        m_join_scene_failure =
                            "PlayerMatchLobbyScene.PollingChangeState failed";
                        s_join_callback_failure =
                            "PlayerMatchLobbyScene.PollingChangeState failed";
                        return false;
                    }
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineStatePolled;
                    m_join_scene_failure =
                        "PlayerMatchLobbyScene.PollingChangeState ok";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "select-room-poll-end", true,
                        player_match_scene, tick);
                    return false;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineStatePolled)
                {
                    emit_join_pipeline_trace(
                        "select-room-state-begin", false,
                        player_match_scene, tick);
                    m_join_scene_select_room_state = 0;
                    m_join_scene_select_room_state_found = false;
                    m_join_scene_select_room_state_result_staged = false;
                    m_join_scene_select_room_state_result_write_bytes = 0;
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineStateResultStaged;
                    m_join_scene_failure =
                        "PlayerMatchSelectRoomState scan skipped";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "select-room-state-end", true,
                        player_match_scene, tick);
                    return false;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineStateResultStaged)
                {
                    m_join_scene_ping_wait_start_tick = tick;
                    m_join_scene_ping_wait_started_at =
                        std::chrono::steady_clock::now();
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineWaitingForPing;
                    m_join_scene_failure =
                        "waiting-for-OnPingSearchResults";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "wait-for-ping-begin", false,
                        player_match_scene, tick);
                    return false;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineWaitingForPing)
                {
                    const uint64_t ping_count =
                        static_cast<uint64_t>(
                            s_ping_search_event_trace_count.load(
                                std::memory_order_acquire));
                    m_join_scene_ping_seen =
                        s_ping_search_callback_seen.load(
                            std::memory_order_acquire) &&
                        ping_count > m_join_scene_ping_baseline_count;
                    m_join_scene_ping_result =
                        s_ping_search_callback_result.load(
                            std::memory_order_acquire);
                    const RollbackOnlinePingStatus ping_status =
                        EvaluateRollbackOnlinePing(
                            m_join_scene_ping_seen,
                            m_join_scene_ping_result,
                            join_scene_ping_wait_elapsed_millis(),
                            kJoinScenePingWaitMilliseconds);
                    if (ping_status ==
                        RollbackOnlinePingStatus::Succeeded)
                    {
                        RC::Unreal::UObject* select_room_state =
                            reinterpret_cast<RC::Unreal::UObject*>(
                                s_select_room_state_context.load(
                                    std::memory_order_acquire));
                        if (!safe_is_real(select_room_state))
                        {
                            m_join_scene_select_room_state = 0;
                            m_join_scene_select_room_state_found = false;
                            m_join_scene_failure =
                                "PlayerMatchSelectRoomState not captured";
                            s_join_callback_failure =
                                m_join_scene_failure.c_str();
                            emit_join_pipeline_trace(
                                "select-room-state-missing", false,
                                player_match_scene, tick);
                        }
                        else
                        {
                            std::string state_result_reason;
                            m_join_scene_select_room_state =
                                reinterpret_cast<uintptr_t>(
                                    select_room_state);
                            m_join_scene_select_room_state_found = true;
                            m_join_scene_select_room_state_result_staged =
                                write_selected_find_result(
                                    select_room_state,
                                    selected_bytes,
                                    selected_bytes_size,
                                    "PlayerMatchSelectRoomState",
                                    false,
                                    state_result_reason);
                            if (!m_join_scene_select_room_state_result_staged)
                            {
                                m_join_scene_failure = state_result_reason;
                                s_join_callback_failure =
                                    m_join_scene_failure.c_str();
                                emit_join_pipeline_trace(
                                    "select-room-state-stage-skipped", false,
                                    player_match_scene, tick);
                            }
                        }
                        m_join_scene_pipeline_step =
                            kJoinScenePipelinePingComplete;
                        m_join_scene_failure =
                            m_join_scene_select_room_state_result_staged
                                ? "PlayerMatchSelectRoomState.FindResult staged"
                                : "OnPingSearchResults ok";
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        emit_join_pipeline_trace(
                            "wait-for-ping-end", true,
                            player_match_scene, tick);
                        return false;
                    }
                    if (ping_status == RollbackOnlinePingStatus::Failed)
                    {
                        m_join_scene_failure =
                            "OnPingSearchResults result false";
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        m_join_scene_terminal_failure = true;
                        emit_join_pipeline_trace(
                            "wait-for-ping-failed", false,
                            player_match_scene, tick);
                        return false;
                    }
                    if (ping_status == RollbackOnlinePingStatus::TimedOut)
                    {
                        m_join_scene_failure =
                            "OnPingSearchResults timeout";
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        m_join_scene_terminal_failure = true;
                        emit_join_pipeline_trace(
                            "wait-for-ping-timeout", false,
                            player_match_scene, tick);
                        return false;
                    }
                    m_join_scene_failure =
                        "waiting-for-OnPingSearchResults";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    return false;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelinePingComplete)
                {
                    emit_join_pipeline_trace(
                        "search-connecting-request-begin", false,
                        player_match_scene, tick);
                    std::string state_reason;
                    m_join_scene_search_connecting_requested = true;
                    m_join_scene_search_connecting_ok =
                        request_player_match_lobby_state(
                            player_match_scene,
                            L"SearchConnecting",
                            state_reason);
                    if (!m_join_scene_search_connecting_ok)
                    {
                        m_join_scene_failure = state_reason;
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        return false;
                    }
                    m_join_scene_poll_ok =
                        call_player_match_polling_change_state(
                            player_match_scene);
                    if (!m_join_scene_poll_ok)
                    {
                        m_join_scene_failure =
                            "PlayerMatchLobbyScene.PollingChangeState failed";
                        s_join_callback_failure =
                            "PlayerMatchLobbyScene.PollingChangeState failed";
                        return false;
                    }
                    emit_join_pipeline_trace(
                        "search-connecting-request-end", true,
                        player_match_scene, tick);
                    emit_join_pipeline_trace(
                        "native-join-request-begin", false,
                        player_match_scene, tick);
                    m_join_scene_decide_requested = true;
                    m_join_scene_decide_ok =
                        call_join_session_process_event(
                            selected_bytes,
                            selected_bytes_size);
                    if (!m_join_scene_decide_ok)
                    {
                        m_join_scene_failure = s_join_callback_failure;
                        return false;
                    }
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineDecideSent;
                    if (latch_failed_join_complete_if_seen())
                    {
                        emit_join_pipeline_trace(
                            "select-room-decide-join-failed", false,
                            player_match_scene, tick);
                        return false;
                    }
                    m_join_scene_failure = "JoinSession requested";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "native-join-request-end", true,
                        player_match_scene, tick);
                    return false;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineDecideSent)
                {
                    if (latch_failed_join_complete_if_seen())
                    {
                        emit_join_pipeline_trace(
                            "join-complete-failed", false,
                            player_match_scene, tick);
                        return false;
                    }
                    emit_join_pipeline_trace(
                        "join-wait-poll-begin", false,
                        player_match_scene, tick);
                    std::string state_reason;
                    m_join_scene_search_connecting_requested = true;
                    m_join_scene_search_connecting_ok =
                        request_player_match_lobby_state(
                            player_match_scene,
                            L"SearchConnecting",
                            state_reason);
                    if (!m_join_scene_search_connecting_ok)
                    {
                        m_join_scene_failure = state_reason;
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        return false;
                    }
                    m_join_scene_poll_ok =
                        call_player_match_polling_change_state(
                            player_match_scene);
                    if (!m_join_scene_poll_ok)
                    {
                        m_join_scene_failure =
                            "PlayerMatchLobbyScene.PollingChangeState failed";
                        s_join_callback_failure =
                            "PlayerMatchLobbyScene.PollingChangeState failed";
                        return false;
                    }
                    s_join_callback_requested.store(
                        true, std::memory_order_release);
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineWaitingForJoin;
                    m_join_scene_failure = "waiting-for-OnJoinSession";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "join-wait-poll-end", true,
                        player_match_scene, tick);
                    return true;
                }

                if (m_join_scene_pipeline_step ==
                    kJoinScenePipelineWaitingForJoin)
                {
                    if (latch_failed_join_complete_if_seen())
                    {
                        emit_join_pipeline_trace(
                            "join-complete-failed", false,
                            player_match_scene, tick);
                        return false;
                    }
                    s_join_callback_requested.store(
                        true, std::memory_order_release);
                    m_join_scene_failure = "waiting-for-OnJoinSession";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "waiting-for-OnJoinSession", true,
                        player_match_scene, tick);
                    return true;
                }

                m_join_scene_failure = "join-pipeline-invalid-step";
                s_join_callback_failure = m_join_scene_failure.c_str();
                return false;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] scene JoinSession handoff threw: {}\n"),
                    RC::to_generic_string(e.what()));
                m_join_scene_failure = "scene-join-handoff-threw";
            }
            catch (...)
            {
                m_join_scene_failure = "scene-join-handoff-threw";
            }
            s_join_callback_failure = "scene-join-handoff-threw";
            return false;
        }

        bool stage_selected_result_with_gameflow_decide(
            OnlineNavigatorObjects& nav,
            const void* selected_result,
            int32_t selected_result_bytes,
            uintptr_t selected_identity,
            uint64_t tick) noexcept
        {
            RC::Unreal::UObject* player_match_scene = nav.current_scene;
            if (!safe_is_real(player_match_scene))
            {
                m_join_scene_failure =
                    "PlayerMatchLobbyScene unavailable";
                s_join_callback_failure =
                    "PlayerMatchLobbyScene unavailable";
                return false;
            }
            if (!selected_result)
            {
                m_join_scene_failure = "selected-search-result-empty";
                s_join_callback_failure = "selected-search-result-empty";
                return false;
            }
            if (selected_result_bytes <= 0)
            {
                m_join_scene_failure = "selected-search-result-size-invalid";
                s_join_callback_failure =
                    "selected-search-result-size-invalid";
                return false;
            }

            const uintptr_t selected_ptr =
                selected_identity ? selected_identity :
                                    reinterpret_cast<uintptr_t>(selected_result);
            const bool new_selection =
                m_join_scene_pipeline_step == kJoinScenePipelineNone ||
                m_join_scene_selected_result != selected_ptr ||
                m_join_scene_mode != "ui-decide";
            if (new_selection)
            {
                m_join_scene_result_staged = false;
                m_join_scene_result_bytes = 0;
                m_join_scene_result_element_bytes = 0;
                m_join_scene_result_write_bytes = 0;
                m_join_scene_result_array_dim = 0;
                m_join_scene_result_offset = 0;
                m_join_scene_result_struct_name.clear();
                m_join_scene_select_room_state = 0;
                m_join_scene_select_room_state_found = false;
                m_join_scene_select_room_state_result_staged = false;
                m_join_scene_select_room_state_result_write_bytes = 0;
                m_join_scene_select_room_requested = false;
                m_join_scene_select_room_ok = false;
                m_join_scene_active_menu_widget = 0;
                m_join_scene_active_menu_name.clear();
                m_join_scene_ui_command_index = -1;
                m_join_scene_ui_command_tick = 0;
                m_join_scene_ui_command_requested = false;
                m_join_scene_ui_command_ok = false;
                m_join_scene_ui_command.clear();
                m_join_scene_ui_command_failure.clear();
                m_join_scene_ping_wait_start_tick = 0;
                m_join_scene_ping_wait_started_at = {};
                m_join_scene_room_select_menu_wait_start_tick = 0;
                m_join_scene_ping_baseline_count = 0;
                m_join_scene_ping_seen = false;
                m_join_scene_ping_result = false;
                m_join_scene_terminal_failure = false;
                m_join_scene_decide_requested = false;
                m_join_scene_decide_ok = false;
                m_join_scene_search_connecting_requested = false;
                m_join_scene_search_connecting_ok = false;
                m_join_scene_poll_ok = false;
                m_join_scene_selected_result = selected_ptr;
                m_join_scene_selected_result_bytes = selected_result_bytes;
                std::vector<uint8_t> selected_storage(
                    static_cast<size_t>(selected_result_bytes), 0);
                if (!SafeReadBytes(
                        selected_result,
                        selected_storage.data(),
                        selected_storage.size()))
                {
                    m_join_scene_selected_result = 0;
                    m_join_scene_selected_result_bytes = 0;
                    m_join_scene_selected_result_storage.clear();
                    m_join_scene_pipeline_step = kJoinScenePipelineNone;
                    m_join_scene_mode = "not-run";
                    m_join_scene_failure =
                        "selected-search-result-unreadable";
                    s_join_callback_failure =
                        "selected-search-result-unreadable";
                    return false;
                }
                m_join_scene_selected_result_storage =
                    std::move(selected_storage);
                m_join_scene_selected_tick = tick;
                m_join_scene_last_step_tick = tick;
                m_join_scene_pipeline_step = kJoinScenePipelineSelected;
                m_join_scene_mode = "ui-decide";
                m_join_scene_failure =
                    tick == 0 ? "selected-search-result" :
                                "selected-search-result-pending-next-tick";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "ui-decide-selected-result-latched", false,
                    player_match_scene, tick);
                if (tick != 0)
                    return false;
            }
            else if (tick != 0 && m_join_scene_last_step_tick == tick)
            {
                m_join_scene_failure = "join-pipeline-waiting-next-tick";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "ui-decide-waiting-next-tick", false,
                    player_match_scene, tick);
                return false;
            }

            if (m_join_scene_terminal_failure)
            {
                s_join_callback_failure = m_join_scene_failure.c_str();
                return false;
            }

            m_join_scene_last_step_tick = tick;
            const void* selected_bytes = selected_result;
            int32_t selected_bytes_size = selected_result_bytes;
            if (!m_join_scene_selected_result_storage.empty())
            {
                selected_bytes = m_join_scene_selected_result_storage.data();
                selected_bytes_size = m_join_scene_selected_result_bytes;
            }

            if (m_join_scene_pipeline_step == kJoinScenePipelineSelected)
            {
                std::string find_result_reason;
                emit_join_pipeline_trace(
                    "ui-decide-scene-result-stage-begin", false,
                    player_match_scene, tick);
                m_join_scene_result_staged =
                    write_selected_find_result(
                        player_match_scene,
                        selected_bytes,
                        selected_bytes_size,
                        "PlayerMatchLobbyScene",
                        true,
                        find_result_reason);
                if (!m_join_scene_result_staged)
                {
                    m_join_scene_failure = find_result_reason;
                    s_join_callback_failure =
                        "PlayerMatchLobbyScene.FindResult stage failed";
                    emit_join_pipeline_trace(
                        "ui-decide-scene-result-stage-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_join_scene_pipeline_step =
                    kJoinScenePipelineSceneResultStaged;
                m_join_scene_failure =
                    "PlayerMatchLobbyScene.FindResult staged for UI decide";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "ui-decide-scene-result-stage-end", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_join_scene_pipeline_step ==
                kJoinScenePipelineSceneResultStaged)
            {
                emit_join_pipeline_trace(
                    "ui-decide-select-room-request-begin", false,
                    player_match_scene, tick);
                std::string state_reason;
                m_join_scene_select_room_requested = true;
                m_join_scene_select_room_ok =
                    request_player_match_lobby_state(
                        player_match_scene,
                        L"SelectRoom",
                        state_reason);
                if (!m_join_scene_select_room_ok)
                {
                    m_join_scene_failure = state_reason;
                    s_join_callback_failure =
                        "PlayerMatchLobbyScene.SelectRoom failed";
                    emit_join_pipeline_trace(
                        "ui-decide-select-room-request-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_join_scene_pipeline_step =
                    kJoinScenePipelineSelectRoomRequested;
                m_join_scene_failure = state_reason;
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "ui-decide-select-room-request-end", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_join_scene_pipeline_step ==
                kJoinScenePipelineSelectRoomRequested)
            {
                emit_join_pipeline_trace(
                    "ui-decide-select-room-poll-begin", false,
                    player_match_scene, tick);
                m_join_scene_poll_ok =
                    call_player_match_polling_change_state(player_match_scene);
                if (!m_join_scene_poll_ok)
                {
                    m_join_scene_failure =
                        "PlayerMatchLobbyScene.PollingChangeState failed";
                    s_join_callback_failure =
                        "PlayerMatchLobbyScene.PollingChangeState failed";
                    emit_join_pipeline_trace(
                        "ui-decide-select-room-poll-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_join_scene_pipeline_step =
                    kJoinScenePipelineStatePolled;
                m_join_scene_failure =
                    "PlayerMatchLobbyScene.PollingChangeState ok";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "ui-decide-select-room-poll-end", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_join_scene_pipeline_step ==
                kJoinScenePipelineStatePolled)
            {
                emit_join_pipeline_trace(
                    "ui-decide-select-room-state-begin", false,
                    player_match_scene, tick);
                m_join_scene_select_room_state = 0;
                m_join_scene_select_room_state_found = false;
                m_join_scene_select_room_state_result_staged = false;
                m_join_scene_select_room_state_result_write_bytes = 0;
                m_join_scene_failure =
                    "waiting for PlayerMatchSelectRoomState callback";
                s_join_callback_failure =
                    m_join_scene_failure.c_str();
                m_join_scene_pipeline_step =
                    kJoinScenePipelineStateResultStaged;
                emit_join_pipeline_trace(
                    "ui-decide-select-room-state-end", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_join_scene_pipeline_step ==
                kJoinScenePipelineStateResultStaged)
            {
                m_join_scene_ping_wait_start_tick = tick;
                m_join_scene_ping_wait_started_at =
                    std::chrono::steady_clock::now();
                m_join_scene_pipeline_step =
                    kJoinScenePipelineWaitingForPing;
                m_join_scene_failure =
                    "waiting-for-OnPingSearchResults";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "ui-decide-wait-for-ping-begin", false,
                    player_match_scene, tick);
                return false;
            }

            if (m_join_scene_pipeline_step ==
                kJoinScenePipelineWaitingForPing)
            {
                const uint64_t ping_count =
                    static_cast<uint64_t>(
                        s_ping_search_event_trace_count.load(
                            std::memory_order_acquire));
                m_join_scene_ping_seen =
                    s_ping_search_callback_seen.load(
                        std::memory_order_acquire) &&
                    ping_count > m_join_scene_ping_baseline_count;
                m_join_scene_ping_result =
                    s_ping_search_callback_result.load(
                        std::memory_order_acquire);
                const RollbackOnlinePingStatus ping_status =
                    EvaluateRollbackOnlinePing(
                        m_join_scene_ping_seen,
                        m_join_scene_ping_result,
                        join_scene_ping_wait_elapsed_millis(),
                        kJoinScenePingWaitMilliseconds);
                if (ping_status == RollbackOnlinePingStatus::Succeeded)
                {
                    RC::Unreal::UObject* select_room_state =
                        reinterpret_cast<RC::Unreal::UObject*>(
                            s_select_room_state_context.load(
                                std::memory_order_acquire));
                    if (safe_is_real(select_room_state))
                    {
                        m_join_scene_select_room_state =
                            reinterpret_cast<uintptr_t>(select_room_state);
                        m_join_scene_select_room_state_found = true;
                        // FindResult is the lobby scene's TArray. The active
                        // SelectRoom state reads RefLobbyScene.FindResult and
                        // does not own a second result field.
                        m_join_scene_select_room_state_result_staged = false;
                    }
                    else
                    {
                        m_join_scene_select_room_state = 0;
                        m_join_scene_select_room_state_found = false;
                        m_join_scene_failure =
                            "PlayerMatchSelectRoomState not captured";
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        emit_join_pipeline_trace(
                            "ui-decide-select-room-state-missing", false,
                            player_match_scene, tick);
                    }
                    m_join_scene_pipeline_step =
                        kJoinScenePipelineWaitingForRoomSelectMenu;
                    m_join_scene_room_select_menu_wait_start_tick = tick;
                    m_join_scene_failure =
                        "OnPingSearchResults ok; waiting-for-RoomSelectMenu";
                    s_join_callback_failure =
                        m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "ui-decide-wait-for-ping-end", true,
                        player_match_scene, tick);
                    return false;
                }
                if (ping_status == RollbackOnlinePingStatus::Failed)
                {
                    m_join_scene_failure =
                        "OnPingSearchResults result false";
                    s_join_callback_failure =
                        m_join_scene_failure.c_str();
                    m_join_scene_terminal_failure = true;
                    emit_join_pipeline_trace(
                        "ui-decide-wait-for-ping-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                if (ping_status == RollbackOnlinePingStatus::TimedOut)
                {
                    m_join_scene_failure =
                        "OnPingSearchResults timeout";
                    s_join_callback_failure =
                        m_join_scene_failure.c_str();
                    m_join_scene_terminal_failure = true;
                    emit_join_pipeline_trace(
                        "ui-decide-wait-for-ping-timeout", false,
                        player_match_scene, tick);
                    return false;
                }
                m_join_scene_failure =
                    "waiting-for-OnPingSearchResults";
                s_join_callback_failure = m_join_scene_failure.c_str();
                return false;
            }

            if (m_join_scene_pipeline_step ==
                kJoinScenePipelineWaitingForRoomSelectMenu)
            {
                std::wstring menu_w;
                std::string menu_name;
                RC::Unreal::UObject* menu_widget = nullptr;
                std::string menu_reason;
                const bool room_select_input_ready =
                    resolve_room_select_menu_for_join(
                    player_match_scene,
                    menu_w,
                    menu_name,
                    menu_widget,
                    menu_reason);
                (void)menu_w;
                m_join_scene_active_menu_name = menu_name;
                m_join_scene_active_menu_widget =
                    reinterpret_cast<uintptr_t>(menu_widget);
                if (room_select_input_ready &&
                    m_cfg.online_stage_diagnostic_reflection)
                    emit_scene_reflection_once(menu_widget);
                if (room_select_input_ready)
                {
                    std::string focus_reason;
                    (void)call_room_select_change_focus(
                        menu_widget, 0, focus_reason);
                    m_join_scene_pipeline_step =
                        kJoinScenePipelinePingComplete;
                    m_join_scene_failure =
                        menu_name + " ready for room-list input";
                    if (!focus_reason.empty())
                    {
                        m_join_scene_failure += "; ";
                        m_join_scene_failure += focus_reason;
                    }
                    s_join_callback_failure =
                        m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "ui-decide-room-select-input-ready", true,
                        player_match_scene, tick);
                    return false;
                }

                if (tick >= m_join_scene_room_select_menu_wait_start_tick &&
                    tick - m_join_scene_room_select_menu_wait_start_tick >=
                        kJoinSceneRoomSelectMenuWaitTicks)
                {
                    m_join_scene_failure =
                        "RoomSelectMenu timeout active=" +
                        (menu_name.empty() ? std::string("<none>") :
                                             menu_name) +
                        " reason=" + menu_reason;
                    s_join_callback_failure =
                        m_join_scene_failure.c_str();
                    m_join_scene_terminal_failure = true;
                    emit_join_pipeline_trace(
                        "ui-decide-room-select-menu-timeout", false,
                        player_match_scene, tick);
                    return false;
                }

                m_join_scene_failure =
                    "waiting-for-RoomSelectMenu active=" +
                    (menu_name.empty() ? std::string("<none>") :
                                         menu_name) +
                    " reason=" + menu_reason;
                s_join_callback_failure = m_join_scene_failure.c_str();
                return false;
            }

            if (m_join_scene_pipeline_step ==
                kJoinScenePipelinePingComplete)
            {
                emit_join_pipeline_trace(
                    "ui-decide-input-begin", false,
                    player_match_scene, tick);
                s_join_callback_requested.store(
                    true, std::memory_order_release);
                s_join_callback_ok.store(false, std::memory_order_release);
                s_join_complete_seen.store(false, std::memory_order_release);
                s_join_complete_result.store(
                    false, std::memory_order_release);
                s_join_complete_result_type.store(
                    -1, std::memory_order_release);
                m_join_scene_decide_requested = true;
                std::string input_reason;
                m_join_scene_decide_ok =
                    send_player_match_join_menu_command(
                        player_match_scene, 0, input_reason, true);
                if (!m_join_scene_decide_ok)
                {
                    if (input_reason.find("waiting-for-RoomSelectMenu") !=
                        std::string::npos)
                    {
                        m_join_scene_pipeline_step =
                            kJoinScenePipelineWaitingForRoomSelectMenu;
                        if (m_join_scene_room_select_menu_wait_start_tick == 0)
                            m_join_scene_room_select_menu_wait_start_tick =
                                tick;
                        m_join_scene_failure = input_reason;
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        emit_join_pipeline_trace(
                            "ui-decide-room-select-menu-lost", false,
                            player_match_scene, tick);
                        return false;
                    }
                    if (!m_join_scene_decide_ok)
                    {
                        m_join_scene_failure = input_reason;
                        s_join_callback_failure =
                            m_join_scene_failure.c_str();
                        emit_join_pipeline_trace(
                            "ui-decide-input-failed", false,
                            player_match_scene, tick);
                        return false;
                    }
                }
                m_join_scene_pipeline_step =
                    kJoinScenePipelineUiDecideSent;
                m_join_scene_failure =
                    input_reason + "; waiting for SC6 JoinSession";
                s_join_callback_failure = m_join_scene_failure.c_str();
                emit_join_pipeline_trace(
                    "ui-decide-input-end", true,
                    player_match_scene, tick);
                return true;
            }

            if (m_join_scene_pipeline_step == kJoinScenePipelineUiDecideSent)
            {
                if (latch_failed_join_complete_if_seen())
                {
                    emit_join_pipeline_trace(
                        "ui-decide-join-complete-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                if (m_join_complete_seen && m_join_complete_result)
                {
                    m_join_request_ok = true;
                    s_join_callback_ok.store(
                        true, std::memory_order_release);
                    m_join_scene_failure =
                        "OnJoinSession complete; waiting for native session connection";
                    s_join_callback_failure =
                        m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "ui-decide-join-complete-seen", true,
                        player_match_scene, tick);
                    return true;
                }
                s_join_callback_requested.store(
                    true, std::memory_order_release);
                m_join_scene_failure = "waiting-for-OnJoinSession";
                s_join_callback_failure = m_join_scene_failure.c_str();
                if (tick == m_join_scene_ui_command_tick + 1 ||
                    (tick % 30u) == 0u)
                {
                    emit_join_pipeline_trace(
                        "ui-decide-waiting-for-OnJoinSession", true,
                        player_match_scene, tick);
                }
                return true;
            }

            m_join_scene_failure = "ui-decide-join-pipeline-invalid-step";
            s_join_callback_failure = m_join_scene_failure.c_str();
            emit_join_pipeline_trace(
                "ui-decide-invalid-step", false, player_match_scene, tick);
            return false;
        }

        bool call_player_match_input_command(
            RC::Unreal::UObject* player_match_scene,
            const wchar_t* menu_name,
            const wchar_t* command_name,
            RC::Unreal::UObject* menu_widget,
            RC::Unreal::UObject* target_widget,
            std::string& reason,
            RC::Unreal::UObject* game_flow_scene = nullptr,
            const wchar_t* param_string = nullptr,
            const char* scene_label = "PlayerMatchLobbyScene") noexcept
        {
            reason.clear();
            if (!safe_is_real(player_match_scene))
            {
                reason = std::string(scene_label ? scene_label
                                                 : "GameFlowScene") +
                         " unavailable";
                return false;
            }
            auto* fn = player_match_scene->GetFunctionByNameInChain(
                L"OnRequestInputCommand");
            if (!fn)
            {
                reason = std::string(scene_label ? scene_label
                                                 : "GameFlowScene") +
                         ".OnRequestInputCommand unavailable";
                return false;
            }

            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096)
            {
                reason = "OnRequestInputCommand param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            auto* menu_prop = RC::Unreal::CastField<
                RC::Unreal::FStrProperty>(
                    reflected_param(fn, L"MenuName"));
            auto* command_prop = RC::Unreal::CastField<
                RC::Unreal::FStrProperty>(
                    reflected_param(fn, L"CommandName"));
            auto* controller_prop = RC::Unreal::CastField<
                RC::Unreal::FIntProperty>(
                    reflected_param(fn, L"ControllerId"));
            RC::Unreal::FProperty* menu_widget_prop =
                reflected_param(fn, L"menuWidget");
            RC::Unreal::FProperty* target_widget_prop =
                reflected_param(fn, L"TargetWidget");
            RC::Unreal::FProperty* game_flow_scene_prop =
                reflected_param(fn, L"GameFlowScene");
            RC::Unreal::FProperty* param_prop =
                reflected_param(fn, L"Param");
            if (!menu_prop || !command_prop || !controller_prop ||
                !param_prop)
            {
                reason =
                    "OnRequestInputCommand reflected params unavailable";
                return false;
            }

            bool menu_initialized = false;
            bool command_initialized = false;
            bool param_initialized = false;
            bool param_copied_from_string = false;
            LuxDataTablePathNative param_value {};
            try
            {
                menu_prop->InitializeValue_InContainer(params.data());
                menu_initialized = true;
                command_prop->InitializeValue_InContainer(params.data());
                command_initialized = true;
                if (param_string && param_string[0])
                {
                    std::string param_reason;
                    if (!create_ui_data_object_from_string(
                            param_string, param_value, param_reason))
                    {
                        reason = "OnRequestInputCommand Param create "
                                 "failed: " +
                                 param_reason;
                        if (command_initialized)
                            command_prop->DestroyValue_InContainer(
                                params.data());
                        if (menu_initialized)
                            menu_prop->DestroyValue_InContainer(
                                params.data());
                        return false;
                    }
                    const int32_t param_value_bytes =
                        param_prop->GetSize();
                    if (param_value_bytes <= 0 ||
                        param_value_bytes >
                            static_cast<int32_t>(
                                sizeof(LuxDataTablePathNative)))
                    {
                        destroy_ui_data_object(param_value);
                        reason = "OnRequestInputCommand Param size "
                                 "mismatch";
                        if (command_initialized)
                            command_prop->DestroyValue_InContainer(
                                params.data());
                        if (menu_initialized)
                            menu_prop->DestroyValue_InContainer(
                                params.data());
                        return false;
                    }
                    void* param_slot =
                        param_prop->ContainerPtrToValuePtr<void>(
                            params.data());
                    if (!param_slot)
                    {
                        destroy_ui_data_object(param_value);
                        reason = "OnRequestInputCommand Param slot "
                                 "unavailable";
                        if (command_initialized)
                            command_prop->DestroyValue_InContainer(
                                params.data());
                        if (menu_initialized)
                            menu_prop->DestroyValue_InContainer(
                                params.data());
                        return false;
                    }
                    std::memcpy(param_slot, &param_value,
                                static_cast<size_t>(param_value_bytes));
                    param_copied_from_string = true;
                }
                else
                {
                    param_prop->InitializeValue_InContainer(params.data());
                    param_initialized = true;
                }

                menu_prop->SetPropertyValueInContainer(
                    params.data(),
                    RC::Unreal::FString(menu_name ? menu_name : L""));
                command_prop->SetPropertyValueInContainer(
                    params.data(),
                    RC::Unreal::FString(command_name ? command_name : L""));
                if (game_flow_scene_prop)
                {
                    auto** out = reinterpret_cast<RC::Unreal::UObject**>(
                        game_flow_scene_prop->ContainerPtrToValuePtr<void>(
                            params.data()));
                    if (out)
                    {
                        *out = safe_is_real(game_flow_scene)
                                   ? game_flow_scene
                                   : nullptr;
                    }
                }
                if (menu_widget_prop)
                {
                    auto** out = reinterpret_cast<RC::Unreal::UObject**>(
                        menu_widget_prop->ContainerPtrToValuePtr<void>(
                            params.data()));
                    if (out) *out = menu_widget;
                }
                if (target_widget_prop)
                {
                    auto** out = reinterpret_cast<RC::Unreal::UObject**>(
                        target_widget_prop->ContainerPtrToValuePtr<void>(
                            params.data()));
                    if (out) *out = target_widget ? target_widget
                                                  : menu_widget;
                }
                *controller_prop->ContainerPtrToValuePtr<int32_t>(
                    params.data()) = -1;

                const bool ok =
                    safe_process_event(player_match_scene, fn, params.data());
                reason = ok
                    ? (std::string("called OnRequestInputCommand") +
                       (param_copied_from_string ? " Param=string" : "") +
                       (game_flow_scene_prop ? " with GameFlowScene" : ""))
                    : "OnRequestInputCommand failed";

                if (param_initialized)
                    param_prop->DestroyValue_InContainer(params.data());
                if (param_copied_from_string)
                    destroy_ui_data_object(param_value);
                if (command_initialized)
                    command_prop->DestroyValue_InContainer(params.data());
                if (menu_initialized)
                    menu_prop->DestroyValue_InContainer(params.data());
                return ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] OnRequestInputCommand threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "OnRequestInputCommand threw";
            }
            catch (...)
            {
                reason = "OnRequestInputCommand threw";
            }

            if (param_initialized)
                param_prop->DestroyValue_InContainer(params.data());
            if (param_copied_from_string)
                destroy_ui_data_object(param_value);
            if (command_initialized)
                command_prop->DestroyValue_InContainer(params.data());
            if (menu_initialized)
                menu_prop->DestroyValue_InContainer(params.data());
            return false;
        }

        bool get_active_gameflow_menu(
            RC::Unreal::UObject* player_match_scene,
            std::wstring& menu_name,
            std::string& menu_name_utf8,
            RC::Unreal::UObject*& menu_widget,
            std::string& reason,
            bool allow_cached_player_match_window = true) noexcept
        {
            menu_name.clear();
            menu_name_utf8.clear();
            menu_widget = nullptr;

            auto* cached_window = reinterpret_cast<RC::Unreal::UObject*>(
                m_host_room_create_navigation_widget);
            if (allow_cached_player_match_window &&
                safe_is_real(cached_window) &&
                cached_window->GetFunctionByNameInChain(L"OnHandleInput"))
            {
                menu_name = L"PlayerMatchRoomCreationWindow";
                menu_name_utf8 = "PlayerMatchRoomCreationWindow";
                menu_widget = cached_window;
                reason = "cached PlayerMatchRoomCreationWindow_C";
                return true;
            }
            if (!safe_is_real(player_match_scene))
            {
                reason = "PlayerMatchLobbyScene unavailable";
                return false;
            }
            auto* fn =
                player_match_scene->GetFunctionByNameInChain(L"GetActiveMenu");
            if (!fn)
            {
                reason = "PlayerMatchLobbyScene.GetActiveMenu unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096)
            {
                reason = "GetActiveMenu param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            auto* name_prop = RC::Unreal::CastField<RC::Unreal::FStrProperty>(
                reflected_param(fn, L"Name"));
            RC::Unreal::FProperty* widget_prop =
                reflected_param(fn, L"menuWidget");
            if (!name_prop || !widget_prop)
            {
                reason = "GetActiveMenu reflected params unavailable";
                return false;
            }

            bool name_initialized = false;
            try
            {
                name_prop->InitializeValue_InContainer(params.data());
                name_initialized = true;
                auto** widget_ptr =
                    reinterpret_cast<RC::Unreal::UObject**>(
                        widget_prop->ContainerPtrToValuePtr<void>(
                            params.data()));
                if (widget_ptr) *widget_ptr = nullptr;

                const bool process_ok =
                    safe_process_event(player_match_scene, fn, params.data());
                bool return_value = process_ok;
                if (auto* ret_prop = RC::Unreal::CastField<
                        RC::Unreal::FBoolProperty>(
                            fn->GetReturnProperty()))
                {
                    return_value = ret_prop->GetPropertyValueInContainer(
                        params.data());
                }

                auto* name_value =
                    name_prop->ContainerPtrToValuePtr<RC::Unreal::FString>(
                        params.data());
                if (name_value)
                {
                    menu_name_utf8 = fstring_to_utf8(*name_value);
                    const wchar_t* chars = **name_value;
                    const int32_t len = name_value->Len();
                    if (chars && len > 0)
                        menu_name.assign(chars, chars + len);
                }
                if (widget_ptr)
                    menu_widget = *widget_ptr;

                if (name_initialized)
                    name_prop->DestroyValue_InContainer(params.data());

                if (!process_ok)
                {
                    reason = "GetActiveMenu ProcessEvent failed";
                    return false;
                }
                if (!return_value)
                {
                    reason = "GetActiveMenu returned false";
                    return false;
                }
                if (!safe_is_real(menu_widget))
                {
                    reason = "GetActiveMenu widget unavailable";
                    return false;
                }
                reason = "GetActiveMenu ok name=" +
                         (menu_name_utf8.empty() ? std::string("<empty>")
                                                 : menu_name_utf8);
                return true;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] GetActiveMenu threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "GetActiveMenu threw";
            }
            catch (...)
            {
                reason = "GetActiveMenu threw";
            }

            if (name_initialized)
                name_prop->DestroyValue_InContainer(params.data());
            return false;
        }

        bool resolve_room_select_menu_for_join(
            RC::Unreal::UObject* player_match_scene,
            std::wstring& menu_name,
            std::string& menu_name_utf8,
            RC::Unreal::UObject*& menu_widget,
            std::string& reason) noexcept
        {
            std::wstring active_menu_w;
            std::string active_menu;
            RC::Unreal::UObject* active_widget = nullptr;
            std::string active_reason;
            const bool active_ok = get_active_gameflow_menu(
                player_match_scene,
                active_menu_w,
                active_menu,
                active_widget,
                active_reason);
            if (active_ok && active_menu == "RoomSelectMenu")
            {
                menu_name = active_menu_w;
                menu_name_utf8 = active_menu;
                menu_widget = active_widget;
                reason = active_reason;
                return true;
            }

            RC::Unreal::UObject* player_match_menu =
                reflected_object_property(
                    player_match_scene, L"RefPlayerMatchMenu");
            if (safe_is_real(player_match_menu))
            {
                if (m_cfg.online_stage_diagnostic_reflection)
                    emit_scene_reflection_once(player_match_menu);
                std::wstring child_menu_w;
                std::string child_menu;
                RC::Unreal::UObject* child_widget = nullptr;
                std::string child_reason;
                const bool child_ok = get_active_gameflow_menu(
                    player_match_menu,
                    child_menu_w,
                    child_menu,
                    child_widget,
                    child_reason);
                if (child_ok && child_menu == "RoomSelectMenu")
                {
                    menu_name = child_menu_w;
                    menu_name_utf8 = child_menu;
                    menu_widget = child_widget;
                    reason = active_reason + "; RefPlayerMatchMenu " +
                        child_reason;
                    return true;
                }
                if (!child_reason.empty())
                {
                    active_reason += "; RefPlayerMatchMenu ";
                    active_reason += child_reason;
                }
            }

            RC::Unreal::UObject* select_room_state =
                reinterpret_cast<RC::Unreal::UObject*>(
                    s_select_room_state_context.load(
                        std::memory_order_acquire));
            if (safe_is_real(select_room_state))
            {
                RC::Unreal::UObject* ref_room_select =
                    reflected_object_property(
                        select_room_state, L"RefRoomSelect");
                if (safe_is_real(ref_room_select) &&
                    ref_room_select->GetFunctionByNameInChain(
                        L"OnHandleInput"))
                {
                    menu_name = L"RoomSelectMenu";
                    menu_name_utf8 = "RoomSelectMenu";
                    menu_widget = ref_room_select;
                    reason = active_reason +
                        "; PlayerMatchSelectRoomState.RefRoomSelect";
                    return true;
                }
            }

            if (m_cfg.online_stage_diagnostic_reflection)
            {
                try
                {
                    auto* found = RC::Unreal::UObjectGlobals::FindFirstOf(
                        L"RoomSelectMenu_C");
                    if (safe_is_real(found) &&
                        found->GetFunctionByNameInChain(L"OnHandleInput"))
                    {
                        menu_name = L"RoomSelectMenu";
                        menu_name_utf8 = "RoomSelectMenu";
                        menu_widget = found;
                        reason = active_reason +
                            "; found RoomSelectMenu_C while active=" +
                            (active_menu.empty() ? std::string("<none>") :
                                                   active_menu);
                        return true;
                    }
                }
                catch (...)
                {
                }
            }

            menu_name = active_menu_w;
            menu_name_utf8 = active_menu;
            menu_widget = active_widget;
            reason = active_reason;
            return false;
        }

        bool call_widget_request_input_command(
            RC::Unreal::UObject* menu_widget,
            const wchar_t* command_name,
            std::string& reason,
            const wchar_t* param_string = nullptr) noexcept
        {
            if (!safe_is_real(menu_widget))
            {
                reason = "active menu widget unavailable";
                return false;
            }
            auto* fn =
                menu_widget->GetFunctionByNameInChain(L"RequestInputCommand");
            if (!fn)
            {
                reason = "BaseUserWidget.RequestInputCommand unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096)
            {
                reason = "RequestInputCommand param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            auto* command_prop = RC::Unreal::CastField<
                RC::Unreal::FStrProperty>(
                    reflected_param(fn, L"CommandName"));
            auto* controller_prop = RC::Unreal::CastField<
                RC::Unreal::FIntProperty>(
                    reflected_param(fn, L"ControllerId"));
            RC::Unreal::FProperty* param_prop =
                reflected_param(fn, L"Param");
            if (!command_prop || !controller_prop || !param_prop)
            {
                reason =
                    "RequestInputCommand reflected params unavailable";
                return false;
            }

            bool command_initialized = false;
            bool param_initialized = false;
            bool param_copied_from_string = false;
            LuxDataTablePathNative param_value {};
            try
            {
                command_prop->InitializeValue_InContainer(params.data());
                command_initialized = true;
                if (param_string && param_string[0])
                {
                    std::string param_reason;
                    if (!create_ui_data_object_from_string(
                            param_string, param_value, param_reason))
                    {
                        reason = "RequestInputCommand Param create "
                                 "failed: " +
                                 param_reason;
                        if (command_initialized)
                            command_prop->DestroyValue_InContainer(
                                params.data());
                        return false;
                    }
                    const int32_t param_value_bytes =
                        param_prop->GetSize();
                    if (param_value_bytes <= 0 ||
                        param_value_bytes >
                            static_cast<int32_t>(
                                sizeof(LuxDataTablePathNative)))
                    {
                        destroy_ui_data_object(param_value);
                        reason = "RequestInputCommand Param size "
                                 "mismatch";
                        if (command_initialized)
                            command_prop->DestroyValue_InContainer(
                                params.data());
                        return false;
                    }
                    void* param_slot =
                        param_prop->ContainerPtrToValuePtr<void>(
                            params.data());
                    if (!param_slot)
                    {
                        destroy_ui_data_object(param_value);
                        reason = "RequestInputCommand Param slot "
                                 "unavailable";
                        if (command_initialized)
                            command_prop->DestroyValue_InContainer(
                                params.data());
                        return false;
                    }
                    std::memcpy(param_slot, &param_value,
                                static_cast<size_t>(param_value_bytes));
                    param_copied_from_string = true;
                }
                else
                {
                    param_prop->InitializeValue_InContainer(params.data());
                    param_initialized = true;
                }

                command_prop->SetPropertyValueInContainer(
                    params.data(),
                    RC::Unreal::FString(command_name ? command_name : L""));
                *controller_prop->ContainerPtrToValuePtr<int32_t>(
                    params.data()) = -1;

                const bool ok =
                    safe_process_event(menu_widget, fn, params.data());
                reason = ok
                    ? (std::string("called active-menu "
                                   "RequestInputCommand") +
                       (param_copied_from_string ? " Param=string" : ""))
                    : "active-menu RequestInputCommand failed";

                if (param_initialized)
                    param_prop->DestroyValue_InContainer(params.data());
                if (param_copied_from_string)
                    destroy_ui_data_object(param_value);
                if (command_initialized)
                    command_prop->DestroyValue_InContainer(params.data());
                return ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] RequestInputCommand threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "RequestInputCommand threw";
            }
            catch (...)
            {
                reason = "RequestInputCommand threw";
            }

            if (param_initialized)
                param_prop->DestroyValue_InContainer(params.data());
            if (param_copied_from_string)
                destroy_ui_data_object(param_value);
            if (command_initialized)
                command_prop->DestroyValue_InContainer(params.data());
            return false;
        }

