        bool call_room_select_refresh_data(
            RC::Unreal::UObject* menu_widget,
            RC::Unreal::UObject* player_match_scene,
            std::string& reason) noexcept
        {
            if (!safe_is_real(menu_widget))
            {
                reason = "RoomSelectMenu widget unavailable";
                return false;
            }
            if (!safe_is_real(player_match_scene))
            {
                reason = "PlayerMatchLobbyScene unavailable";
                return false;
            }
            auto* fn =
                menu_widget->GetFunctionByNameInChain(L"RefleshData");
            if (!fn)
            {
                reason = "RoomSelectMenu.RefleshData unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 8192)
            {
                reason = "RoomSelectMenu.RefleshData param-size invalid";
                return false;
            }

            auto* find_data_prop = RC::Unreal::CastField<
                RC::Unreal::FArrayProperty>(
                    reflected_param(fn, L"FindData"));
            auto* scene_find_prop = RC::Unreal::CastField<
                RC::Unreal::FArrayProperty>(
                    player_match_scene->GetPropertyByNameInChain(
                        L"FindResult"));
            if (!find_data_prop)
            {
                reason = "RoomSelectMenu.RefleshData FindData unavailable";
                return false;
            }

            const int32_t element_size =
                find_data_prop->GetInner()
                    ? find_data_prop->GetInner()->GetElementSize()
                    : 0;
            void* data = nullptr;
            int32_t count = 0;
            int32_t max = 0;
            const char* source = "none";

            if (scene_find_prop)
            {
                void* scene_array =
                    scene_find_prop->ContainerPtrToValuePtr<void>(
                        player_match_scene);
                void* scene_data = nullptr;
                int32_t scene_count = 0;
                int32_t scene_max = 0;
                if (scene_array &&
                    SafeReadPtr(scene_array, &scene_data) &&
                    SafeReadInt32(
                        static_cast<uint8_t*>(scene_array) + 8,
                        &scene_count) &&
                    SafeReadInt32(
                        static_cast<uint8_t*>(scene_array) + 12,
                        &scene_max) &&
                    scene_data && scene_count > 0 &&
                    scene_max >= scene_count && scene_count <= 64)
                {
                    data = scene_data;
                    count = scene_count;
                    max = scene_max;
                    source = "scene-FindResult";
                }
            }

            if (!data && element_size > 0 &&
                !m_join_scene_selected_result_storage.empty() &&
                m_join_scene_selected_result_bytes >= element_size)
            {
                data = m_join_scene_selected_result_storage.data();
                count = 1;
                max = 1;
                source = "selected-result";
            }

            if (!data || count <= 0 || max < count)
            {
                reason = "RoomSelectMenu.RefleshData source unavailable";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            try
            {
                auto* array_bytes = static_cast<uint8_t*>(
                    find_data_prop->ContainerPtrToValuePtr<void>(
                        params.data()));
                if (!array_bytes)
                {
                    reason = "RoomSelectMenu.RefleshData array unavailable";
                    return false;
                }
                *reinterpret_cast<void**>(array_bytes) = data;
                *reinterpret_cast<int32_t*>(array_bytes + 8) = count;
                *reinterpret_cast<int32_t*>(array_bytes + 12) = max;

                const bool ok =
                    safe_process_event(menu_widget, fn, params.data());
                reason = ok
                    ? "called RoomSelectMenu.RefleshData"
                    : "RoomSelectMenu.RefleshData failed";
                reason += "(source=";
                reason += source;
                reason += ",count=";
                reason += std::to_string(count);
                reason += ",elem=";
                reason += std::to_string(element_size);
                reason += ")";
                return ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] RefleshData threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "RoomSelectMenu.RefleshData threw";
            }
            catch (...)
            {
                reason = "RoomSelectMenu.RefleshData threw";
            }
            return false;
        }

        struct TemporaryFindResultArrayAlias
        {
            uint8_t* array_bytes {nullptr};
            void* original_data {nullptr};
            int32_t original_count {0};
            int32_t original_max {0};
            bool applied {false};
        };

        bool alias_player_match_find_result_for_input(
            RC::Unreal::UObject* player_match_scene,
            TemporaryFindResultArrayAlias& alias,
            std::string& reason) noexcept
        {
            alias = {};
            if (!safe_is_real(player_match_scene))
            {
                reason = "PlayerMatchLobbyScene unavailable";
                return false;
            }
            if (m_join_scene_selected_result_storage.empty())
            {
                reason = "selected-result-storage-empty";
                return false;
            }

            try
            {
                auto* find_result_prop = RC::Unreal::CastField<
                    RC::Unreal::FArrayProperty>(
                        player_match_scene->GetPropertyByNameInChain(
                            L"FindResult"));
                if (!find_result_prop)
                {
                    reason =
                        "PlayerMatchLobbyScene.FindResult array unavailable";
                    return false;
                }
                const int32_t element_size =
                    find_result_prop->GetInner()
                        ? find_result_prop->GetInner()->GetElementSize()
                        : 0;
                if (element_size <= 0 ||
                    m_join_scene_selected_result_bytes < element_size)
                {
                    reason =
                        "PlayerMatchLobbyScene.FindResult element mismatch";
                    return false;
                }
                auto* array_bytes = static_cast<uint8_t*>(
                    find_result_prop->ContainerPtrToValuePtr<void>(
                        player_match_scene));
                if (!array_bytes ||
                    !SafeReadPtr(array_bytes, &alias.original_data) ||
                    !SafeReadInt32(
                        array_bytes + 8, &alias.original_count) ||
                    !SafeReadInt32(
                        array_bytes + 12, &alias.original_max))
                {
                    reason =
                        "PlayerMatchLobbyScene.FindResult header unreadable";
                    return false;
                }
                if (alias.original_data && alias.original_count > 0)
                {
                    reason = "PlayerMatchLobbyScene.FindResult present";
                    reason += "(count=";
                    reason += std::to_string(alias.original_count);
                    reason += ")";
                    return false;
                }

                alias.array_bytes = array_bytes;
                *reinterpret_cast<void**>(array_bytes) =
                    m_join_scene_selected_result_storage.data();
                *reinterpret_cast<int32_t*>(array_bytes + 8) = 1;
                *reinterpret_cast<int32_t*>(array_bytes + 12) = 1;
                alias.applied = true;
                reason = "aliased PlayerMatchLobbyScene.FindResult";
                reason += "(elem=";
                reason += std::to_string(element_size);
                reason += ",orig_count=";
                reason += std::to_string(alias.original_count);
                reason += ")";
                return true;
            }
            catch (...)
            {
                reason = "PlayerMatchLobbyScene.FindResult alias threw";
                return false;
            }
        }

        static void restore_player_match_find_result_alias(
            TemporaryFindResultArrayAlias& alias) noexcept
        {
            if (!alias.applied || !alias.array_bytes)
                return;
            __try
            {
                *reinterpret_cast<void**>(alias.array_bytes) =
                    alias.original_data;
                *reinterpret_cast<int32_t*>(alias.array_bytes + 8) =
                    alias.original_count;
                *reinterpret_cast<int32_t*>(alias.array_bytes + 12) =
                    alias.original_max;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
            }
            alias.applied = false;
        }

        bool call_room_select_handle_input(
            RC::Unreal::UObject* menu_widget,
            RC::Unreal::UObject* player_match_scene,
            uint8_t input_type,
            uint8_t key,
            std::string& reason) noexcept
        {
            if (!safe_is_real(menu_widget))
            {
                reason = "RoomSelectMenu widget unavailable";
                return false;
            }
            auto* fn = menu_widget->GetFunctionByNameInChain(
                L"OnHandleInput");
            if (!fn)
            {
                reason = "RoomSelectMenu.OnHandleInput unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 512)
            {
                reason = "RoomSelectMenu.OnHandleInput param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            RC::Unreal::FProperty* input_prop =
                reflected_param(fn, L"InputType");
            auto* controller_prop = RC::Unreal::CastField<
                RC::Unreal::FIntProperty>(
                    reflected_param(fn, L"ControllerId"));
            RC::Unreal::FProperty* key_prop =
                reflected_param(fn, L"Key");
            auto* default_prop = RC::Unreal::CastField<
                RC::Unreal::FBoolProperty>(
                    reflected_param(fn, L"IsDefaultPrevented"));
            auto* prevent_prop = RC::Unreal::CastField<
                RC::Unreal::FBoolProperty>(
                    reflected_param(fn, L"bPreventDefault"));
            if (!input_prop || !controller_prop || !key_prop ||
                !default_prop || !prevent_prop)
            {
                reason = "RoomSelectMenu.OnHandleInput params unavailable";
                return false;
            }

            TemporaryFindResultArrayAlias find_alias;
            try
            {
                std::string alias_reason;
                (void)alias_player_match_find_result_for_input(
                    player_match_scene, find_alias, alias_reason);
                if (!write_reflected_u8_param(
                        input_prop, params.data(), input_type) ||
                    !write_reflected_u8_param(
                        key_prop, params.data(), key))
                {
                    restore_player_match_find_result_alias(find_alias);
                    reason = "RoomSelectMenu.OnHandleInput enum write failed";
                    return false;
                }
                *controller_prop->ContainerPtrToValuePtr<int32_t>(
                    params.data()) = -1;
                default_prop->SetPropertyValueInContainer(
                    params.data(), false);
                prevent_prop->SetPropertyValueInContainer(
                    params.data(), false);

                const bool ok =
                    safe_process_event(menu_widget, fn, params.data());
                restore_player_match_find_result_alias(find_alias);
                const bool prevented =
                    prevent_prop->GetPropertyValueInContainer(params.data());
                reason = ok
                    ? "called RoomSelectMenu.OnHandleInput"
                    : "RoomSelectMenu.OnHandleInput failed";
                reason += "(type=";
                reason += std::to_string(static_cast<int>(input_type));
                reason += ",key=";
                reason += std::to_string(static_cast<int>(key));
                reason += ",prevent=";
                reason += prevented ? "1)" : "0)";
                if (!alias_reason.empty())
                {
                    reason += ",find=";
                    reason += alias_reason;
                }
                return ok;
            }
            catch (const std::exception& e)
            {
                restore_player_match_find_result_alias(find_alias);
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] OnHandleInput threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "RoomSelectMenu.OnHandleInput threw";
            }
            catch (...)
            {
                restore_player_match_find_result_alias(find_alias);
                reason = "RoomSelectMenu.OnHandleInput threw";
            }
            return false;
        }

        static const char* ui_input_key_name(UiInputKey key) noexcept
        {
            switch (key)
            {
            case UiInputKey::Up:
                return "Up";
            case UiInputKey::Down:
                return "Down";
            case UiInputKey::Left:
                return "Left";
            case UiInputKey::Right:
                return "Right";
            case UiInputKey::Start:
                return "Start";
            case UiInputKey::Decide:
                return "Decide";
            case UiInputKey::Cancel:
                return "Cancel";
            default:
                return "Unknown";
            }
        }

        static bool parse_ui_input_key_token(const std::string& token,
                                             UiInputKey& out)
        {
            std::string normalized;
            normalized.reserve(token.size());
            for (char c : token)
            {
                if (c == '-' || c == '_')
                    continue;
                normalized.push_back(
                    static_cast<char>(
                        std::tolower(static_cast<unsigned char>(c))));
            }
            if (normalized == "up")
            {
                out = UiInputKey::Up;
                return true;
            }
            if (normalized == "down")
            {
                out = UiInputKey::Down;
                return true;
            }
            if (normalized == "left")
            {
                out = UiInputKey::Left;
                return true;
            }
            if (normalized == "right")
            {
                out = UiInputKey::Right;
                return true;
            }
            if (normalized == "start")
            {
                out = UiInputKey::Start;
                return true;
            }
            if (normalized == "decide" || normalized == "ok" ||
                normalized == "submit" || normalized == "enter")
            {
                out = UiInputKey::Decide;
                return true;
            }
            if (normalized == "cancel" || normalized == "back")
            {
                out = UiInputKey::Cancel;
                return true;
            }
            return false;
        }

        static std::vector<UiInputKey> parse_ui_input_route(
            const std::string& route)
        {
            std::vector<UiInputKey> keys;
            std::string token;
            auto flush_token = [&]() noexcept
            {
                if (token.empty())
                    return;
                UiInputKey key {};
                if (parse_ui_input_key_token(token, key))
                    keys.push_back(key);
                token.clear();
            };
            for (char c : route)
            {
                if (c == ',' || c == '>' || c == ';' ||
                    std::isspace(static_cast<unsigned char>(c)))
                {
                    flush_token();
                    continue;
                }
                token.push_back(c);
            }
            flush_token();
            return keys;
        }

        static bool to_rollback_navigation_key(
            UiInputKey key,
            RollbackUiNavigationKey& out) noexcept
        {
            switch (key)
            {
            case UiInputKey::Up:
                out = RollbackUiNavigationKey::Up;
                return true;
            case UiInputKey::Down:
                out = RollbackUiNavigationKey::Down;
                return true;
            case UiInputKey::Left:
                out = RollbackUiNavigationKey::Left;
                return true;
            case UiInputKey::Right:
                out = RollbackUiNavigationKey::Right;
                return true;
            case UiInputKey::Decide:
                out = RollbackUiNavigationKey::Decide;
                return true;
            case UiInputKey::Cancel:
                out = RollbackUiNavigationKey::Cancel;
                return true;
            default:
                return false;
            }
        }

        static UiInputKey from_rollback_navigation_key(
            RollbackUiNavigationKey key) noexcept
        {
            switch (key)
            {
            case RollbackUiNavigationKey::Up:
                return UiInputKey::Up;
            case RollbackUiNavigationKey::Down:
                return UiInputKey::Down;
            case RollbackUiNavigationKey::Left:
                return UiInputKey::Left;
            case RollbackUiNavigationKey::Right:
                return UiInputKey::Right;
            case RollbackUiNavigationKey::Decide:
                return UiInputKey::Decide;
            case RollbackUiNavigationKey::Cancel:
                return UiInputKey::Cancel;
            }
            return UiInputKey::Down;
        }

        static WORD rollback_navigation_xinput_button(
            RollbackUiNavigationKey key) noexcept
        {
            switch (key)
            {
            case RollbackUiNavigationKey::Up:
                return XINPUT_GAMEPAD_DPAD_UP;
            case RollbackUiNavigationKey::Down:
                return XINPUT_GAMEPAD_DPAD_DOWN;
            case RollbackUiNavigationKey::Left:
                return XINPUT_GAMEPAD_DPAD_LEFT;
            case RollbackUiNavigationKey::Right:
                return XINPUT_GAMEPAD_DPAD_RIGHT;
            case RollbackUiNavigationKey::Decide:
                return XINPUT_GAMEPAD_A;
            case RollbackUiNavigationKey::Cancel:
                return XINPUT_GAMEPAD_B;
            }
            return 0;
        }

        static RollbackUiNavigationScene rollback_navigation_scene(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            if (identity_contains_scene(info, "PlayerMatchInviteScene"))
                return RollbackUiNavigationScene::PlayerMatchInvite;
            if (identity_contains_scene(info, "PlayerMatchLobbyScene"))
                return RollbackUiNavigationScene::PlayerMatchLobby;
            if (identity_contains_scene(info, "PlayerMatchSetupScene"))
                return RollbackUiNavigationScene::PlayerMatchSetup;
            if (identity_contains_scene(info, "PlayerMatchScene"))
                return RollbackUiNavigationScene::PlayerMatchBattle;
            if (identity_contains_scene(info, "MainMenuScene"))
                return RollbackUiNavigationScene::MainMenu;
            if (identity_contains_scene(info, "TitleScene")
                || identity_contains_scene(info, "AdvertiseScene")
                || identity_contains_scene(info, "InitScene"))
                return RollbackUiNavigationScene::Title;
            return info.object_real
                ? RollbackUiNavigationScene::Other
                : RollbackUiNavigationScene::Unknown;
        }

        static RollbackUiNavigationScene rollback_navigation_scene(
            RC::Unreal::UObject* current_scene) noexcept
        {
            return rollback_navigation_scene(
                describe_uobject(current_scene));
        }

        static uint64_t rollback_navigation_scene_generation(
            RC::Unreal::UObject* current_scene) noexcept
        {
            const uint64_t generation = static_cast<uint64_t>(
                reinterpret_cast<uintptr_t>(current_scene));
            return generation != 0 ? generation : 1;
        }

        static const char* rollback_navigation_state_name(
            RollbackUiNavigationState state) noexcept
        {
            switch (state)
            {
            case RollbackUiNavigationState::Idle:
                return "idle";
            case RollbackUiNavigationState::ReadyToDispatch:
                return "ready-to-dispatch";
            case RollbackUiNavigationState::DispatchPending:
                return "dispatch-pending";
            case RollbackUiNavigationState::AwaitingAcknowledgement:
                return "awaiting-acknowledgement";
            case RollbackUiNavigationState::Succeeded:
                return "succeeded";
            case RollbackUiNavigationState::Failed:
                return "failed";
            }
            return "unknown";
        }

        bool build_main_menu_navigation_route(
            std::array<RollbackUiNavigationKey,
                       RollbackUiNavigationDriver::kMaxRouteSteps>& out,
            size_t& out_count,
            std::string& reason)
        {
            out = {};
            out_count = 0;
            std::vector<UiInputKey> route =
                parse_ui_input_route(m_cfg.main_menu_player_match_route);
            if (route.empty())
            {
                route = {
                    UiInputKey::Down,
                    UiInputKey::Down,
                    UiInputKey::Down,
                    UiInputKey::Down,
                    // Commit Network (root index 4), then select Player Match
                    // (Network submenu index 1).  The cooked
                    // DB_MainMenuList asset proves both indexes.
                    UiInputKey::Decide,
                    UiInputKey::Down,
                    UiInputKey::Decide,
                };
            }
            if (route.size() > out.size())
            {
                reason = "main-menu input route exceeds 16 steps";
                return false;
            }
            for (const UiInputKey key : route)
            {
                if (!to_rollback_navigation_key(key, out[out_count]))
                {
                    reason = "main-menu input route contains unsupported key";
                    return false;
                }
                ++out_count;
            }
            if (out_count == 0
                || out[out_count - 1] != RollbackUiNavigationKey::Decide)
            {
                reason = "main-menu input route must end in Decide";
                return false;
            }
            return true;
        }

        void emit_main_menu_input_trace(bool ok,
                                        RC::Unreal::UObject* handler,
                                        RC::Unreal::UObject* target_widget,
                                        UiInputKey key,
                                        const std::string& reason,
                                        bool dispatch_accepted,
                                        bool native_input_consumed,
                                        bool action_acknowledged,
                                        bool scene_transitioned,
                                        bool semantic_action_started = false,
                                        bool target_scene_queued = false) noexcept
        {
            const auto pulse = GameImGui::XInputHook::instance()
                .observable_pulse_status();
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .boolean("call_success", dispatch_accepted)
             .boolean("dispatch_accepted", dispatch_accepted)
             .boolean("native_input_consumed", native_input_consumed)
             .boolean("action_acknowledged", action_acknowledged)
             .boolean("semantic_action_started",
                      semantic_action_started)
             .boolean("target_scene_queued", target_scene_queued)
             .boolean("selection_changed",
                      main_menu_focus_changed(
                          m_main_menu_focus_before,
                          m_main_menu_focus_after))
             .boolean("scene_transitioned", scene_transitioned)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .uinteger("attempts", m_main_menu_input_attempts)
             .uinteger("sequence_step", m_main_menu_input_sequence_step)
             .boolean("sequence_complete",
                      m_main_menu_input_sequence_complete)
             .uinteger("key", static_cast<uint64_t>(
                              static_cast<uint8_t>(key)))
             .string("key_name", ui_input_key_name(key))
             .string("route", m_cfg.main_menu_player_match_route)
             .string("reason", reason)
             .uinteger("navigation_generation",
                       m_main_menu_navigation_driver.generation())
             .uinteger("navigation_dispatch_id",
                       m_main_menu_navigation_dispatch_id)
             .uinteger("navigation_connectivity_lease_generation",
                       m_main_menu_navigation_lease_generation)
             .uinteger("navigation_state",
                       static_cast<uint64_t>(
                           m_main_menu_navigation_driver.state()))
             .string("navigation_state_name",
                     rollback_navigation_state_name(
                         m_main_menu_navigation_driver.state()))
             .string("navigation_failure",
                     RollbackUiNavigationDriver::failure_name(
                         m_main_menu_navigation_driver.failure()))
             .uinteger("navigation_step",
                       m_main_menu_navigation_driver.step_index())
             .uinteger("navigation_route_length",
                       m_main_menu_navigation_driver.route_length())
             .uinteger("navigation_step_attempts",
                       m_main_menu_navigation_driver.attempts_for_step())
             .uinteger("navigation_total_dispatches",
                       m_main_menu_navigation_driver.total_dispatches())
             .uinteger("xinput_pulse_generation",
                       m_main_menu_navigation_pulse_generation)
             .uinteger("xinput_status_generation", pulse.generation)
             .uinteger("xinput_phase",
                       static_cast<uint64_t>(pulse.phase))
             .uinteger("xinput_failure",
                       static_cast<uint64_t>(pulse.failure))
             .uinteger("xinput_selected_api",
                       static_cast<uint64_t>(pulse.selected_api))
             .uinteger("xinput_state_api_mask",
                       pulse.hooked_state_api_mask)
             .uinteger("xinput_capabilities_api_mask",
                       pulse.hooked_capabilities_api_mask)
             .uinteger("xinput_generation_state_reads",
                       pulse.generation_state_reads)
             .uinteger("xinput_neutral_reads", pulse.neutral_reads)
             .uinteger("xinput_press_reads", pulse.press_reads)
             .uinteger("xinput_release_reads", pulse.release_reads)
             .uinteger("xinput_force_rescan_writes",
                       pulse.native_force_rescan_writes)
             .uinteger("xinput_connectivity_lease_generation",
                       pulse.connectivity_lease_generation)
             .uinteger("xinput_connectivity_lease_pad",
                       pulse.connectivity_lease_pad)
             .uinteger("xinput_connectivity_lease_api",
                       static_cast<uint64_t>(
                           pulse.connectivity_lease_api))
             .uinteger("xinput_connectivity_lease_state_reads",
                       pulse.connectivity_lease_state_reads)
             .uinteger(
                 "xinput_connectivity_lease_forced_state_reads",
                 pulse.connectivity_lease_forced_state_reads)
             .boolean("xinput_connectivity_lease_active",
                      pulse.connectivity_lease_active)
             .boolean("xinput_hook_installed", pulse.installed)
             .boolean("xinput_native_poller_entry_verified",
                      pulse.native_poller_entry_verified)
             .boolean("xinput_native_poller_hook_installed",
                      pulse.native_poller_hook_installed)
             .boolean("focus_before_attempted",
                      m_main_menu_focus_before.attempted)
             .boolean("focus_before_ok", m_main_menu_focus_before.ok)
             .boolean("focus_before_function_backed",
                      m_main_menu_focus_before.function_backed)
             .boolean("focus_before_live_dispatchable",
                      m_main_menu_focus_before.live_dispatchable)
             .boolean("focus_before_menu_id_ok",
                      m_main_menu_focus_before.menu_id_ok)
             .string("focus_before_menu_id",
                     m_main_menu_focus_before.menu_id)
             .boolean("focus_before_menu_index_ok",
                      m_main_menu_focus_before.menu_index_ok)
             .integer("focus_before_menu_index",
                      m_main_menu_focus_before.menu_index)
             .hex("focus_before_source_object",
                  m_main_menu_focus_before.source_object)
             .string("focus_before_source",
                     m_main_menu_focus_before.source)
             .string("focus_before_source_name",
                     m_main_menu_focus_before.source_object_name)
             .string("focus_before_source_class",
                     m_main_menu_focus_before.source_class_name)
             .string("focus_before_failure",
                     m_main_menu_focus_before.failure)
             .boolean("focus_after_attempted",
                      m_main_menu_focus_after.attempted)
             .boolean("focus_after_ok", m_main_menu_focus_after.ok)
             .boolean("focus_after_function_backed",
                      m_main_menu_focus_after.function_backed)
             .boolean("focus_after_live_dispatchable",
                      m_main_menu_focus_after.live_dispatchable)
             .boolean("focus_after_menu_id_ok",
                      m_main_menu_focus_after.menu_id_ok)
             .string("focus_after_menu_id",
                     m_main_menu_focus_after.menu_id)
             .boolean("focus_after_menu_index_ok",
                      m_main_menu_focus_after.menu_index_ok)
             .integer("focus_after_menu_index",
                      m_main_menu_focus_after.menu_index)
             .hex("focus_after_source_object",
                  m_main_menu_focus_after.source_object)
             .string("focus_after_source",
                     m_main_menu_focus_after.source)
             .string("focus_after_source_name",
                     m_main_menu_focus_after.source_object_name)
             .string("focus_after_source_class",
                     m_main_menu_focus_after.source_class_name)
             .string("focus_after_failure",
                     m_main_menu_focus_after.failure);
            add_uobject_identity_fields(
                f, "handler", describe_uobject(handler));
            add_uobject_identity_fields(
                f, "target_widget", describe_uobject(target_widget));
            ReplayDebugTrace::instance().event(
                "rollback_main_menu_input_navigation", f);
        }

        bool call_ui_handle_input(RC::Unreal::UObject* input_handler,
                                  RC::Unreal::UObject* target_widget,
                                  uint8_t input_type,
                                  uint8_t key,
                                  const char* label,
                                  std::string& reason) noexcept
        {
            if (!safe_is_real(input_handler))
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput handler unavailable";
                return false;
            }
            auto* fn = input_handler->GetFunctionByNameInChain(
                L"OnHandleInput");
            if (!fn)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 512)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            RC::Unreal::FProperty* widget_prop =
                reflected_param(fn, L"Widget");
            RC::Unreal::FProperty* input_prop =
                reflected_param(fn, L"InputType");
            auto* controller_prop = RC::Unreal::CastField<
                RC::Unreal::FIntProperty>(
                    reflected_param(fn, L"ControllerId"));
            RC::Unreal::FProperty* key_prop =
                reflected_param(fn, L"Key");
            auto* default_prop = RC::Unreal::CastField<
                RC::Unreal::FBoolProperty>(
                    reflected_param(fn, L"IsDefaultPrevented"));
            auto* prevent_prop = RC::Unreal::CastField<
                RC::Unreal::FBoolProperty>(
                    reflected_param(fn, L"bPreventDefault"));
            if (!input_prop || !controller_prop || !key_prop ||
                !default_prop || !prevent_prop)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput params unavailable";
                return false;
            }

            try
            {
                if (widget_prop)
                {
                    auto** widget_ptr =
                        reinterpret_cast<RC::Unreal::UObject**>(
                            widget_prop->ContainerPtrToValuePtr<void>(
                                params.data()));
                    if (widget_ptr)
                        *widget_ptr = safe_is_real(target_widget)
                            ? target_widget
                            : nullptr;
                }
                if (!write_reflected_u8_param(
                        input_prop, params.data(), input_type) ||
                    !write_reflected_u8_param(
                        key_prop, params.data(), key))
                {
                    reason = std::string(label ? label : "UI") +
                             ".OnHandleInput enum write failed";
                    return false;
                }
                *controller_prop->ContainerPtrToValuePtr<int32_t>(
                    params.data()) = 0;
                default_prop->SetPropertyValueInContainer(
                    params.data(), false);
                prevent_prop->SetPropertyValueInContainer(
                    params.data(), false);

                const bool ok =
                    safe_process_event(input_handler, fn, params.data());
                const bool prevented =
                    prevent_prop->GetPropertyValueInContainer(params.data());
                reason = ok
                    ? (std::string("called ") +
                       (label ? label : "UI") + ".OnHandleInput")
                    : (std::string(label ? label : "UI") +
                       ".OnHandleInput failed");
                reason += "(type=";
                reason += std::to_string(static_cast<int>(input_type));
                reason += ",key=";
                reason += std::to_string(static_cast<int>(key));
                reason += ",prevent=";
                reason += prevented ? "1)" : "0)";
                return ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] UI OnHandleInput threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput threw";
            }
            catch (...)
            {
                reason = std::string(label ? label : "UI") +
                         ".OnHandleInput threw";
            }
            return false;
        }

        bool request_main_menu_input_navigation(
            OnlineNavigatorObjects& nav,
            RC::Unreal::UObject* ref_main_menu,
            RC::Unreal::UObject* main_menu_widget,
            RC::Unreal::UObject* main_menu_impl,
            RC::Unreal::UObject* active_widget,
            std::string& reason) noexcept
        {
            try
            {
                reason.clear();
                const uint64_t tick = m_online_nav_attempts;
                const RollbackUiNavigationScene scene =
                    rollback_navigation_scene(nav.current_scene_identity);
                const uint64_t scene_generation =
                    rollback_navigation_scene_generation(nav.current_scene);

                if (m_main_menu_navigation_driver.state()
                    == RollbackUiNavigationState::Idle)
                {
                    m_main_menu_focus_before = MainMenuFocusSnapshot {};
                    m_main_menu_focus_after = MainMenuFocusSnapshot {};
                    std::array<
                        RollbackUiNavigationKey,
                        RollbackUiNavigationDriver::kMaxRouteSteps> route {};
                    size_t route_count = 0;
                    if (!build_main_menu_navigation_route(
                            route, route_count, reason))
                    {
                        (void)m_main_menu_navigation_driver.begin(
                            scene_generation, nullptr, 0, tick, scene);
                    }
                    else
                    {
                        (void)m_main_menu_navigation_driver.begin(
                            scene_generation,
                            route.data(),
                            route_count,
                            tick,
                            scene);
                    }
                }

                const RollbackUiNavigationResult scene_result =
                    m_main_menu_navigation_driver.observe_scene(
                        scene_generation, tick, scene);
                m_main_menu_input_sequence_step =
                    m_main_menu_navigation_driver.step_index();
                m_main_menu_input_sequence_complete =
                    m_main_menu_navigation_driver.sequence_complete();
                m_main_menu_input_attempts =
                    m_main_menu_navigation_driver.total_dispatches();

                UiInputKey trace_key = UiInputKey::Down;
                switch (static_cast<UiInputKey>(
                    static_cast<uint8_t>(m_main_menu_input_last_key)))
                {
                case UiInputKey::Up:
                case UiInputKey::Down:
                case UiInputKey::Left:
                case UiInputKey::Right:
                case UiInputKey::Start:
                case UiInputKey::Decide:
                case UiInputKey::Cancel:
                    trace_key = static_cast<UiInputKey>(
                        static_cast<uint8_t>(
                            m_main_menu_input_last_key));
                    break;
                default:
                    break;
                }

                if (scene_result == RollbackUiNavigationResult::Succeeded
                    || m_main_menu_navigation_driver.sequence_complete())
                {
                    reason = "current Player Match scene acknowledged";
                    m_main_menu_input_last_ok = true;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        true, nullptr, active_widget, trace_key, reason,
                        false, false, true, true);
                    return true;
                }

                const bool target_scene_queued =
                    identity_is_player_match_nav_context(
                        nav.next_scene_identity) ||
                    identity_is_player_match_nav_context(
                        nav.next_scene_direct_identity);
                if (target_scene_queued &&
                    m_main_menu_navigation_driver.state() ==
                        RollbackUiNavigationState::AwaitingAcknowledgement &&
                    m_main_menu_navigation_dispatch_id != 0)
                {
                    const RollbackUiNavigationResult queued_result =
                        m_main_menu_navigation_driver
                            .acknowledge_target_scene_queued(
                                m_main_menu_navigation_driver.generation(),
                                m_main_menu_navigation_dispatch_id,
                                tick,
                                scene);
                    const bool queued_acknowledged =
                        queued_result ==
                        RollbackUiNavigationResult::WaitingForTargetScene;
                    if (queued_acknowledged)
                        m_main_menu_navigation_target_scene_queued = true;
                    reason = queued_acknowledged
                        ? "Player Match scene queued; waiting for current scene"
                        : "Player Match queue evidence rejected";
                    m_main_menu_input_last_ok = queued_acknowledged;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        queued_acknowledged,
                        nullptr,
                        active_widget,
                        trace_key,
                        reason,
                        false,
                        false,
                        false,
                        false,
                        false,
                        queued_acknowledged);
                    return queued_acknowledged;
                }
                if (m_main_menu_navigation_driver.state()
                    == RollbackUiNavigationState::Failed)
                {
                    m_main_menu_navigation_blueprint_dispatch = false;
                    if (reason.empty())
                    {
                        reason = "main-menu navigation failed: ";
                        reason += RollbackUiNavigationDriver::failure_name(
                            m_main_menu_navigation_driver.failure());
                    }
                    m_main_menu_input_last_ok = false;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        false, nullptr, active_widget, trace_key, reason,
                        false, false, false, false);
                    return false;
                }

                if (m_main_menu_navigation_driver.state()
                        == RollbackUiNavigationState::AwaitingAcknowledgement
                    && m_main_menu_navigation_dispatch_id != 0
                    && m_main_menu_navigation_blueprint_dispatch)
                {
                    constexpr uint64_t kFocusSampleIntervalTicks = 3;
                    bool sampled_focus = false;
                    if (m_main_menu_focus_last_sample_tick == 0 ||
                        tick - m_main_menu_focus_last_sample_tick >=
                            kFocusSampleIntervalTicks)
                    {
                        sampled_focus = sample_main_menu_focus(
                            ref_main_menu,
                            main_menu_widget,
                            main_menu_impl,
                            m_main_menu_focus_after);
                        m_main_menu_focus_last_sample_tick = tick;
                    }
                    const bool final_decide =
                        trace_key == UiInputKey::Decide &&
                        m_main_menu_navigation_driver.step_index() + 1 >=
                            m_main_menu_navigation_driver.route_length();
                    const bool intermediate_decide =
                        trace_key == UiInputKey::Decide && !final_decide;
                    bool focus_confirmed = false;
                    if (sampled_focus &&
                        m_main_menu_focus_before.live_dispatchable &&
                        m_main_menu_focus_after.live_dispatchable)
                    {
                        if (intermediate_decide)
                        {
                            focus_confirmed =
                                m_main_menu_focus_before.menu_id_ok &&
                                ascii_iequals(
                                    m_main_menu_focus_before.menu_id,
                                    "ENETWORK") &&
                                m_main_menu_focus_after.menu_id_ok &&
                                !ascii_iequals(
                                    m_main_menu_focus_after.menu_id,
                                    "ENETWORK") &&
                                m_main_menu_focus_after.menu_index_ok &&
                                m_main_menu_focus_after.menu_index == 0 &&
                                main_menu_hierarchy_changed(
                                    m_main_menu_focus_before,
                                    m_main_menu_focus_after);
                        }
                        else if (trace_key == UiInputKey::Down ||
                                 trace_key == UiInputKey::Up)
                        {
                            const int32_t delta =
                                trace_key == UiInputKey::Down ? 1 : -1;
                            const int64_t expected_index =
                                static_cast<int64_t>(
                                    m_main_menu_focus_before.menu_index) +
                                delta;
                            focus_confirmed =
                                m_main_menu_focus_before.menu_index_ok &&
                                m_main_menu_focus_after.menu_index_ok &&
                                expected_index >= 0 &&
                                expected_index <= INT32_MAX &&
                                m_main_menu_focus_after.menu_index ==
                                    expected_index &&
                                m_main_menu_focus_before.source_object ==
                                    m_main_menu_focus_after.source_object;
                            if (focus_confirmed && expected_index == 4)
                            {
                                focus_confirmed =
                                    m_main_menu_focus_after.menu_id_ok &&
                                    ascii_iequals(
                                        m_main_menu_focus_after.menu_id,
                                        "ENETWORK");
                            }
                            const bool precedes_final_decide =
                                m_main_menu_navigation_driver.step_index() +
                                        2 ==
                                    m_main_menu_navigation_driver
                                        .route_length();
                            if (focus_confirmed && precedes_final_decide)
                            {
                                focus_confirmed =
                                    m_main_menu_focus_after.menu_id_ok &&
                                    ascii_iequals(
                                        m_main_menu_focus_after.menu_id,
                                        "EPLAYERMATCH");
                            }
                        }
                    }
                    const RollbackUiNavigationResult ack_result =
                        m_main_menu_navigation_driver
                            .acknowledge_focus_change(
                                m_main_menu_navigation_driver.generation(),
                                m_main_menu_navigation_dispatch_id,
                                tick,
                                scene,
                                focus_confirmed);
                    m_main_menu_input_sequence_step =
                        m_main_menu_navigation_driver.step_index();
                    m_main_menu_input_sequence_complete =
                        m_main_menu_navigation_driver.sequence_complete();
                    m_main_menu_input_attempts =
                        m_main_menu_navigation_driver.total_dispatches();
                    const bool destination_seen =
                        ack_result == RollbackUiNavigationResult::Succeeded;
                    const bool step_advanced =
                        ack_result ==
                        RollbackUiNavigationResult::ActionAcknowledged;
                    if (step_advanced || destination_seen)
                        m_main_menu_navigation_blueprint_dispatch = false;
                    reason = destination_seen
                        ? "Player Match scene acknowledged"
                        : step_advanced
                            ? "semantic Blueprint focus change acknowledged"
                            : final_decide
                                ? "semantic Decide started; waiting for "
                                  "queued/current Player Match scene"
                                : sampled_focus
                                    ? "semantic Blueprint dispatch accepted; "
                                      "reflected focus unchanged"
                                    : "semantic Blueprint dispatch accepted; "
                                      "waiting for bounded focus sample";
                    m_main_menu_input_last_ok =
                        step_advanced || destination_seen;
                    m_main_menu_input_last_reason = reason;
                    if (step_advanced || destination_seen)
                    {
                        emit_main_menu_input_trace(
                            true,
                            reinterpret_cast<RC::Unreal::UObject*>(
                                m_main_menu_focus_before.source_object),
                            active_widget,
                            trace_key,
                            reason,
                            false,
                            false,
                            true,
                            destination_seen);
                        return true;
                    }
                }

                const bool ready_for_command =
                    m_main_menu_navigation_driver.state() ==
                        RollbackUiNavigationState::ReadyToDispatch &&
                    tick >= m_main_menu_navigation_driver
                                .next_dispatch_not_before_tick();
                MainMenuFocusSnapshot dispatch_focus {};
                const bool dispatch_focus_ready = ready_for_command &&
                    sample_main_menu_focus(
                        ref_main_menu,
                        main_menu_widget,
                        main_menu_impl,
                        dispatch_focus);
                const bool dispatcher_available =
                    ready_for_command
                    && dispatch_focus_ready
                    && dispatch_focus.live_dispatchable
                    && main_menu_impl != nullptr;
                RollbackUiNavigationCommand command {};
                if (!m_main_menu_navigation_driver.next_command(
                        scene_generation,
                        tick,
                        scene,
                        dispatcher_available,
                        command))
                {
                    m_main_menu_input_sequence_step =
                        m_main_menu_navigation_driver.step_index();
                    m_main_menu_input_sequence_complete =
                        m_main_menu_navigation_driver.sequence_complete();
                    m_main_menu_input_attempts =
                        m_main_menu_navigation_driver.total_dispatches();
                    if (m_main_menu_navigation_driver.state()
                        == RollbackUiNavigationState::Failed)
                    {
                        m_main_menu_navigation_blueprint_dispatch = false;
                        reason = "main-menu navigation failed: ";
                        reason += RollbackUiNavigationDriver::failure_name(
                            m_main_menu_navigation_driver.failure());
                    }
                    else if (ready_for_command && !dispatch_focus_ready)
                    {
                        reason = "reflected MainMenu focus unavailable; input "
                                 "dispatch held";
                    }
                    else if (!ready_for_command &&
                             m_main_menu_navigation_driver.state() ==
                                 RollbackUiNavigationState::ReadyToDispatch)
                    {
                        reason = "navigation retry waiting for fresh focus "
                                 "baseline";
                    }
                    else if (ready_for_command && !dispatcher_available)
                    {
                        reason = "semantic MainMenu Blueprint dispatcher "
                                 "unavailable";
                    }
                    else if (reason.empty())
                    {
                        reason = "main-menu navigation command pending";
                    }
                    m_main_menu_input_last_ok = false;
                    m_main_menu_input_last_reason = reason;
                    emit_main_menu_input_trace(
                        false, nullptr, active_widget, trace_key, reason,
                        false, false, false, false);
                    return false;
                }

                m_main_menu_focus_before = std::move(dispatch_focus);
                m_main_menu_focus_after = MainMenuFocusSnapshot {};
                m_main_menu_focus_last_sample_tick = 0;
                m_main_menu_navigation_dispatch_id = command.dispatch_id;
                m_main_menu_navigation_pulse_generation = 0;
                m_main_menu_navigation_blueprint_dispatch = false;
                m_main_menu_navigation_target_scene_queued = false;
                const bool final_decide =
                    command.key == RollbackUiNavigationKey::Decide &&
                    command.step_index + 1 >=
                        m_main_menu_navigation_driver.route_length();
                const char* expected_decide_menu_id = final_decide
                    ? "EPLAYERMATCH"
                    : command.key == RollbackUiNavigationKey::Decide
                        ? "ENETWORK"
                        : nullptr;
                if (expected_decide_menu_id &&
                    (!m_main_menu_focus_before.menu_id_ok ||
                     !ascii_iequals(
                         m_main_menu_focus_before.menu_id,
                         expected_decide_menu_id)))
                {
                    (void)m_main_menu_navigation_driver.on_dispatch_result(
                        command.generation,
                        command.dispatch_id,
                        tick,
                        false);
                    m_main_menu_navigation_blueprint_dispatch = false;
                    reason = "Decide held: reflected selection is ";
                    reason += m_main_menu_focus_before.menu_id_ok
                        ? m_main_menu_focus_before.menu_id
                        : "unavailable";
                    reason += ", expected ";
                    reason += expected_decide_menu_id;
                    m_main_menu_input_last_ok = false;
                    m_main_menu_input_last_reason = reason;
                    trace_key = from_rollback_navigation_key(command.key);
                    m_main_menu_input_last_key =
                        static_cast<uint8_t>(trace_key);
                    emit_main_menu_input_trace(
                        false,
                        nullptr,
                        active_widget,
                        trace_key,
                        reason,
                        false,
                        false,
                        false,
                        false);
                    return false;
                }
                RC::Unreal::UObject* dispatched_item = nullptr;
                std::string semantic_reason;
                const bool delivered =
                    dispatch_main_menu_blueprint_navigation(
                        main_menu_impl,
                        m_main_menu_focus_before,
                        command.key,
                        dispatched_item,
                        semantic_reason);
                m_main_menu_navigation_blueprint_dispatch = delivered;
                (void)m_main_menu_navigation_driver.on_dispatch_result(
                    command.generation,
                    command.dispatch_id,
                    tick,
                    delivered);
                bool semantic_action_started = false;
                if (delivered && final_decide)
                {
                    const RollbackUiNavigationResult semantic_result =
                        m_main_menu_navigation_driver
                            .acknowledge_semantic_action_started(
                                command.generation,
                                command.dispatch_id,
                                tick,
                                scene);
                    semantic_action_started =
                        semantic_result ==
                            RollbackUiNavigationResult::WaitingForTargetScene ||
                        semantic_result ==
                            RollbackUiNavigationResult::Succeeded;
                }

                trace_key = from_rollback_navigation_key(command.key);
                m_main_menu_input_last_key =
                    static_cast<uint8_t>(trace_key);
                m_main_menu_input_sequence_step =
                    m_main_menu_navigation_driver.step_index();
                m_main_menu_input_sequence_complete =
                    m_main_menu_navigation_driver.sequence_complete();
                m_main_menu_input_attempts =
                    m_main_menu_navigation_driver.total_dispatches();
                m_main_menu_input_last_ok = delivered;
                reason = semantic_reason;
                if (semantic_action_started)
                {
                    reason += "; semantic action started; waiting for "
                              "queued/current Player Match scene";
                }
                m_main_menu_input_last_reason = reason;
                emit_main_menu_input_trace(
                    delivered,
                    reinterpret_cast<RC::Unreal::UObject*>(
                        m_main_menu_focus_before.source_object),
                    active_widget,
                    trace_key,
                    reason,
                    delivered,
                    false,
                    false,
                    false,
                    semantic_action_started,
                    false);
                return delivered;
            }
            catch (const std::exception& e)
            {
                m_main_menu_navigation_blueprint_dispatch = false;
                reason = "main-menu navigation exception: ";
                reason += e.what();
            }
            catch (...)
            {
                m_main_menu_navigation_blueprint_dispatch = false;
                reason = "main-menu navigation unknown exception";
            }
            m_main_menu_input_last_ok = false;
            m_main_menu_input_last_reason = reason;
            return false;
        }

        static const wchar_t* player_match_join_command(
            int32_t index) noexcept
        {
            static constexpr const wchar_t* kCommands[] = {
                L"Decide",
                L"Submit",
                L"OK",
                L"Ok",
                L"Join",
                L"Select",
                L"Enter",
            };
            if (index < 0 ||
                index >= static_cast<int32_t>(
                    sizeof(kCommands) / sizeof(kCommands[0])))
            {
                return nullptr;
            }
            return kCommands[index];
        }

        bool send_player_match_join_menu_command(
            RC::Unreal::UObject* player_match_scene,
            int32_t command_index,
            std::string& reason,
            bool require_room_select_menu = false) noexcept
        {
            const wchar_t* command =
                player_match_join_command(command_index);
            if (!command)
            {
                reason = "join menu command list exhausted";
                return false;
            }

            std::wstring active_menu_w;
            std::string active_menu;
            RC::Unreal::UObject* active_widget = nullptr;
            std::string active_reason;
            const bool active_ok = resolve_room_select_menu_for_join(
                player_match_scene,
                active_menu_w,
                active_menu,
                active_widget,
                active_reason);
            m_join_scene_active_menu_name = active_menu;
            m_join_scene_active_menu_widget =
                reinterpret_cast<uintptr_t>(active_widget);
            if (active_ok && m_cfg.online_stage_diagnostic_reflection)
                emit_scene_reflection_once(active_widget);
            if (require_room_select_menu &&
                (!active_ok || active_menu != "RoomSelectMenu"))
            {
                reason = "waiting-for-RoomSelectMenu active=" +
                         (active_menu.empty() ? std::string("<none>") :
                                                active_menu) +
                         " reason=" + active_reason;
                m_join_scene_ui_command_requested = false;
                m_join_scene_ui_command_ok = false;
                m_join_scene_ui_command_failure = reason;
                return false;
            }
            m_join_scene_ui_command_index = command_index;
            m_join_scene_ui_command = narrow_wide_utf8(command);

            std::string focus_reason;
            std::string refresh_reason;
            if (active_ok && active_menu == "RoomSelectMenu")
            {
                (void)call_room_select_change_focus(
                    active_widget, 0, focus_reason);
                (void)call_room_select_refresh_data(
                    active_widget,
                    player_match_scene,
                    refresh_reason);
            }

            std::string handle_reason;
            bool ok = false;
            if (active_ok && active_menu == "RoomSelectMenu" &&
                command_index == 0)
            {
                ok = call_room_select_handle_input(
                    active_widget,
                    player_match_scene,
                    static_cast<uint8_t>(UiInputType::KeyDown),
                    static_cast<uint8_t>(UiInputKey::Decide),
                    handle_reason);
            }

            std::string widget_reason;
            if (active_ok)
            {
                if (!ok)
                {
                    ok = call_widget_request_input_command(
                        active_widget, command, widget_reason);
                }
                else
                {
                    widget_reason = "skipped after OnHandleInput";
                }
            }
            else
            {
                widget_reason = active_reason;
            }

            std::string scene_reason;
            if (!ok)
            {
                const wchar_t* menu_name =
                    active_menu_w.empty() ? L"" : active_menu_w.c_str();
                ok = call_player_match_input_command(
                    player_match_scene,
                    menu_name,
                    command,
                    active_widget,
                    active_widget,
                    scene_reason);
            }
            m_join_scene_ui_command_requested = true;
            m_join_scene_ui_command_ok = ok;
            m_join_scene_ui_command_tick = m_join_scene_last_step_tick;
            reason = "menu=" +
                     (active_menu.empty() ? std::string("<none>")
                                          : active_menu) +
                     " command=" + m_join_scene_ui_command +
                     " active=" + active_reason +
                     " widget=" + widget_reason;
            if (!focus_reason.empty())
            {
                reason += " focus=";
                reason += focus_reason;
            }
            if (!refresh_reason.empty())
            {
                reason += " refresh=";
                reason += refresh_reason;
            }
            if (!handle_reason.empty())
            {
                reason += " handle=";
                reason += handle_reason;
            }
            if (!scene_reason.empty())
            {
                reason += " scene=";
                reason += scene_reason;
            }
            m_join_scene_ui_command_failure = reason;
            return ok;
        }

