        bool resolve_player_match_creation_window(
            RC::Unreal::UObject* player_match_scene,
            std::wstring& menu_name,
            std::string& menu_name_utf8,
            RC::Unreal::UObject*& menu_widget,
            std::string& reason) noexcept
        {
            menu_name.clear();
            menu_name_utf8.clear();
            menu_widget = nullptr;

            std::wstring active_menu_w;
            std::string active_menu;
            RC::Unreal::UObject* active_widget = nullptr;
            std::string active_reason;
            const bool active_ok = get_active_gameflow_menu(
                player_match_scene,
                active_menu_w,
                active_menu,
                active_widget,
                active_reason);
            if (active_ok &&
                active_menu.find("PlayerMatchRoomCreationWindow") !=
                    std::string::npos)
            {
                menu_name = active_menu_w;
                menu_name_utf8 = active_menu;
                menu_widget = active_widget;
                reason = active_reason;
                return true;
            }

            RC::Unreal::UObject* player_match_menu =
                reflected_object_property(
                    player_match_scene, L"RefPlayerMatchMenu");
            if (safe_is_real(player_match_menu))
            {
                if (m_cfg.online_stage_diagnostic_reflection)
                    emit_scene_reflection_once(player_match_menu);
                std::string owned_window_reason;
                RC::Unreal::UObject* owned_window =
                    call_get_window_by_name(
                        player_match_menu,
                        L"PlayerMatchRoomCreationWindow",
                        owned_window_reason);
                if (safe_is_real(owned_window))
                {
                    menu_name = L"PlayerMatchRoomCreationWindow";
                    menu_name_utf8 = "PlayerMatchRoomCreationWindow";
                    menu_widget = owned_window;
                    reason = active_reason + "; RefPlayerMatchMenu." +
                             owned_window_reason;
                    return true;
                }
                if (!owned_window_reason.empty())
                {
                    active_reason += "; RefPlayerMatchMenu.";
                    active_reason += owned_window_reason;
                }
                std::wstring child_menu_w;
                std::string child_menu;
                RC::Unreal::UObject* child_widget = nullptr;
                std::string child_reason;
                const bool child_ok = get_active_gameflow_menu(
                    player_match_menu,
                    child_menu_w,
                    child_menu,
                    child_widget,
                    child_reason);
                if (child_ok &&
                    child_menu.find("PlayerMatchRoomCreationWindow") !=
                        std::string::npos)
                {
                    menu_name = child_menu_w;
                    menu_name_utf8 = child_menu;
                    menu_widget = child_widget;
                    reason = active_reason + "; RefPlayerMatchMenu " +
                        child_reason;
                    return true;
                }
                if (!child_reason.empty())
                {
                    active_reason += "; RefPlayerMatchMenu ";
                    active_reason += child_reason;
                }
            }

            menu_name = active_menu_w;
            menu_name_utf8 = active_menu;
            menu_widget = active_widget;
            reason = active_reason;
            return false;
        }

        bool send_player_match_creation_input(
            RC::Unreal::UObject* player_match_scene,
            UiInputKey key,
            const char* action,
            uint64_t tick,
            std::string& reason) noexcept
        {
            std::wstring menu_w;
            std::string menu_name;
            RC::Unreal::UObject* menu_widget = nullptr;
            std::string active_reason;
            const bool active_ok = resolve_player_match_creation_window(
                player_match_scene,
                menu_w,
                menu_name,
                menu_widget,
                active_reason);
            m_host_room_create_active_menu_name = menu_name;
            m_host_room_create_active_menu_widget =
                reinterpret_cast<uintptr_t>(menu_widget);
            if (active_ok && m_cfg.online_stage_diagnostic_reflection)
                emit_scene_reflection_once(menu_widget);

            reason = "menu=" +
                     (menu_name.empty()
                          ? std::string("<none>")
                     : menu_name) +
                      " active=" + active_reason +
                      " widget=required";
            if (!active_ok || !safe_is_real(menu_widget))
            {
                reason += " scene=waiting-for-PlayerMatchRoomCreationWindow";
                m_host_room_create_command_failure = reason;
                m_host_room_create_last_step_tick = tick;
                return false;
            }

            const uintptr_t widget_address =
                reinterpret_cast<uintptr_t>(menu_widget);
            if (m_host_room_create_navigation_widget == 0)
                m_host_room_create_navigation_widget = widget_address;
            else if (m_host_room_create_navigation_widget != widget_address)
            {
                reason += " creation-window-changed";
                m_host_room_create_command_failure = reason;
                m_host_room_create_last_step_tick = tick;
                return false;
            }

            std::string input_reason;
            bool ok = false;
            if (menu_widget->GetFunctionByNameInChain(L"OnHandleInput"))
            {
                ok = call_ui_handle_input(
                    menu_widget,
                    menu_widget,
                    static_cast<uint8_t>(UiInputType::KeyDown),
                    static_cast<uint8_t>(key),
                    "PlayerMatchRoomCreationWindow",
                    input_reason);
            }
            else
            {
                const wchar_t* command = nullptr;
                switch (key)
                {
                case UiInputKey::Up: command = L"Up"; break;
                case UiInputKey::Down: command = L"Down"; break;
                case UiInputKey::Left: command = L"Left"; break;
                case UiInputKey::Right: command = L"Right"; break;
                case UiInputKey::Decide: command = L"Decide"; break;
                case UiInputKey::Cancel: command = L"Cancel"; break;
                default: break;
                }
                if (!command)
                {
                    input_reason = "unsupported creation-window input";
                }
                else
                {
                    ok = call_player_match_input_command(
                        player_match_scene,
                        L"PlayerMatchRoomCreationWindow",
                        command,
                        menu_widget,
                        menu_widget,
                        input_reason);
                }
            }

            if (!input_reason.empty())
            {
                reason += " action=";
                reason += action ? action : "unknown";
                reason += " input=";
                reason += input_reason;
            }
            m_host_room_create_command_failure = reason;
            m_host_room_create_last_step_tick = tick;
            return ok;
        }

        bool read_player_match_creation_private_slot(
            RC::Unreal::UObject* menu_widget,
            int32_t& value,
            std::string& matched_path,
            std::string& reason) noexcept
        {
            value = -1;
            matched_path.clear();
            reason.clear();
            if (!safe_is_real(menu_widget))
            {
                reason = "creation window unavailable";
                return false;
            }
            auto* get_fn = menu_widget->GetFunctionByNameInChain(
                L"getPropertyValue");
            if (!get_fn)
                get_fn = menu_widget->GetFunctionByNameInChain(
                    L"GetPropertyValue");
            auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                RC::Unreal::UObject*>(
                    nullptr, nullptr,
                    STR("/Script/UMGUtil.Default__UMGUtilUIDataObjectLibrary"));
            auto* int_fn = safe_is_real(cdo)
                ? cdo->GetFunctionByNameInChain(L"Conv_UIDataObjectToInt")
                : nullptr;
            if (!get_fn || !int_fn)
            {
                reason = "UIDataObject private-slot readers unavailable";
                return false;
            }

            auto* path_prop = RC::Unreal::CastField<RC::Unreal::FStrProperty>(
                reflected_param(get_fn, L"Path"));
            RC::Unreal::FProperty* get_ret = get_fn->GetReturnProperty();
            RC::Unreal::FProperty* data_prop =
                reflected_param(int_fn, L"InDataObject");
            RC::Unreal::FProperty* int_ret = int_fn->GetReturnProperty();
            if (!path_prop || !get_ret || !data_prop || !int_ret
                || get_ret->GetSize() <= 0
                || get_ret->GetSize() >
                    static_cast<int32_t>(sizeof(LuxDataTablePathNative))
                || data_prop->GetSize() != get_ret->GetSize()
                || int_ret->GetSize() != sizeof(int32_t))
            {
                reason = "UIDataObject private-slot reflected ABI mismatch";
                return false;
            }

            constexpr const wchar_t* kPaths[] = {
                L"privateSlot.value",
                L"list.privateSlot.value",
                L"window.list.privateSlot.value",
                L"privateSlot",
            };
            for (const wchar_t* path : kPaths)
            {
                const int32_t get_bytes = get_fn->GetPropertiesSize();
                const int32_t int_bytes = int_fn->GetPropertiesSize();
                if (get_bytes <= 0 || get_bytes > 4096
                    || int_bytes <= 0 || int_bytes > 4096)
                    continue;
                std::vector<uint8_t> get_params(
                    static_cast<size_t>(get_bytes), 0);
                bool path_initialized = false;
                LuxDataTablePathNative data {};
                try
                {
                    path_prop->InitializeValue_InContainer(get_params.data());
                    path_initialized = true;
                    path_prop->SetPropertyValueInContainer(
                        get_params.data(), RC::Unreal::FString(path));
                    if (!safe_process_event(
                            menu_widget, get_fn, get_params.data()))
                    {
                        path_prop->DestroyValue_InContainer(get_params.data());
                        continue;
                    }
                    void* get_slot = get_ret->ContainerPtrToValuePtr<void>(
                        get_params.data());
                    if (!get_slot || !SafeReadBytes(
                            get_slot, &data,
                            static_cast<size_t>(get_ret->GetSize())))
                    {
                        path_prop->DestroyValue_InContainer(get_params.data());
                        continue;
                    }
                    path_prop->DestroyValue_InContainer(get_params.data());
                    path_initialized = false;

                    std::vector<uint8_t> int_params(
                        static_cast<size_t>(int_bytes), 0);
                    void* data_slot = data_prop->ContainerPtrToValuePtr<void>(
                        int_params.data());
                    if (!data_slot)
                    {
                        destroy_ui_data_object(data);
                        continue;
                    }
                    std::memcpy(data_slot, &data,
                                static_cast<size_t>(data_prop->GetSize()));
                    const bool int_ok = safe_process_event(
                        cdo, int_fn, int_params.data());
                    void* int_slot = int_ret->ContainerPtrToValuePtr<void>(
                        int_params.data());
                    int32_t candidate = -1;
                    const bool read_ok = int_ok && int_slot
                        && SafeReadBytes(int_slot, &candidate,
                                         sizeof(candidate));
                    destroy_ui_data_object(data);
                    if (read_ok && (candidate == 0 || candidate == 1))
                    {
                        value = candidate;
                        matched_path = narrow_wide_utf8(path);
                        reason = "privateSlot read from live UI data";
                        return true;
                    }
                }
                catch (...)
                {
                    if (path_initialized)
                        path_prop->DestroyValue_InContainer(
                            get_params.data());
                    destroy_ui_data_object(data);
                }
            }

            reason = "privateSlot live UI path unavailable";
            return false;
        }

        bool send_player_match_creation_decide(
            RC::Unreal::UObject* player_match_scene,
            uint64_t tick,
            std::string& reason) noexcept
        {
            return send_player_match_creation_input(
                player_match_scene,
                UiInputKey::Decide,
                "create-room-decide",
                tick,
                reason);
        }

        bool send_player_match_create_room_command(
            OnlineNavigatorObjects& nav,
            RC::Unreal::UObject* player_match_scene,
            uint64_t tick,
            std::string& reason) noexcept
        {
            std::wstring menu_w;
            std::string menu_name;
            RC::Unreal::UObject* menu_widget = nullptr;
            std::string active_reason;
            const bool active_ok = get_active_gameflow_menu(
                player_match_scene,
                menu_w,
                menu_name,
                menu_widget,
                active_reason);
            m_host_room_create_active_menu_name = menu_name;
            m_host_room_create_active_menu_widget =
                reinterpret_cast<uintptr_t>(menu_widget);
            if (active_ok && m_cfg.online_stage_diagnostic_reflection)
                emit_scene_reflection_once(menu_widget);

            std::string select_state_reason;
            RC::Unreal::UObject* select_room_type_state =
                find_active_player_match_lobby_state(
                    player_match_scene,
                    "PlayerMatchSelectRoomTypeState",
                    &select_state_reason);
            if (m_cfg.online_stage_diagnostic_reflection &&
                safe_is_real(select_room_type_state))
                emit_scene_reflection_once(select_room_type_state);

            bool ok = false;
            std::string state_reason;
            const wchar_t* active_menu_name =
                menu_w.empty() ? L"PlayerMatchMenu" : menu_w.c_str();
            if (safe_is_real(select_room_type_state))
            {
                ok = call_player_match_input_command(
                    select_room_type_state,
                    active_menu_name,
                    L"CreateRoom",
                    menu_widget,
                    menu_widget,
                    state_reason,
                    player_match_scene);
            }
            else
            {
                state_reason = select_state_reason;
            }

            std::string scene_reason;
            if (!ok)
            {
                ok = call_player_match_input_command(
                    player_match_scene,
                    active_menu_name,
                    L"CreateRoom",
                    menu_widget,
                    menu_widget,
                    scene_reason);
            }

            std::string widget_reason;
            if (!ok && active_ok)
                ok = call_widget_request_input_command(
                    menu_widget, L"CreateRoom", widget_reason);
            else
                widget_reason = active_reason;

            std::string gameflow_reason;
            if (!ok)
            {
                ok = emulate_gameflow_input(
                    nav, UiInputKey::Decide, gameflow_reason);
            }

            std::string fallback_reason;
            if (!ok)
            {
                ok = request_player_match_lobby_state(
                    player_match_scene, L"MakeRoom",
                    fallback_reason, tick);
            }

            reason = "menu=" +
                     (menu_name.empty()
                          ? std::string("<none>")
                          : menu_name) +
                     " active=" + active_reason +
                     " state=" + state_reason +
                     " scene=" + scene_reason +
                     " widget=" + widget_reason +
                     " gameflow=" + gameflow_reason +
                     " fallback=" + fallback_reason;
            m_host_room_create_command_failure = reason;
            m_host_room_create_last_step_tick = tick;
            return ok;
        }

        bool use_targeted_native_player_session_create() const noexcept
        {
            // Owner targeting is a guest-side search constraint; it must not
            // bypass the host's visible Make Room flow. Keep direct native
            // creation only for explicitly named diagnostic sessions.
            return !m_cfg.room_name.empty() ||
                   !m_cfg.session_name.empty();
        }

        RollbackOnlineNamedSessionEvidence
        current_named_session_evidence() const noexcept
        {
            RollbackOnlineNamedSessionEvidence evidence {};
            evidence.sampled_ok = m_native_named_session_ok;
            evidence.named_session = m_native_named_session_ptr;
            evidence.session_info = m_native_named_session_info;
            evidence.lobby_id = m_native_named_session_lobby_id;
            evidence.public_connections =
                m_native_named_session_public_connections;
            evidence.hosting_player_num =
                m_native_named_session_hosting_player_num;
            evidence.online_state = m_native_named_session_state;
            evidence.lobby_owner_sampled =
                m_native_named_session_lobby_owner_sampled;
            evidence.lobby_owner_id =
                m_native_named_session_lobby_owner_id;
            return evidence;
        }

        bool has_reusable_host_named_session() const noexcept
        {
            return CanAdoptRollbackHostSession(
                current_named_session_evidence(),
                m_session_main_user_id,
                m_steam_local_id);
        }

        bool has_reusable_guest_named_session() const noexcept
        {
            return CanAdoptRollbackGuestSession(
                current_named_session_evidence(),
                m_cfg.target_owner_id);
        }

        bool service_host_native_create_pipeline(
            OnlineNavigatorObjects& nav,
            uint64_t tick) noexcept
        {
            // SC6 may report a provisional OnCreateSession(false) before a
            // later OnCreateSession(true) for the same native request. The
            // July 8 two-process trace observed that exact sequence, so latch
            // any success and let false-only callbacks wait for the bounded
            // create timeout instead of retrying or failing immediately.
            const int32_t create_true_count =
                s_create_callback_true_count.load(std::memory_order_acquire);
            const int32_t create_false_count =
                s_create_callback_false_count.load(std::memory_order_acquire);
            const uint64_t create_elapsed =
                m_host_room_create_start_tick != 0
                    && tick >= m_host_room_create_start_tick
                ? tick - m_host_room_create_start_tick
                : 0;
            const RollbackOnlineCreateDecision create_decision =
                EvaluateRollbackOnlineCreate(
                    create_true_count,
                    create_false_count,
                    m_create_callback_seen,
                    m_create_callback_result,
                    create_elapsed,
                    kHostRoomCreateWaitTicks);
            if (create_decision.status ==
                RollbackOnlineCreateStatus::Succeeded)
            {
                m_create_requested = true;
                m_create_request_ok = true;
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineComplete;
                m_host_room_create_failure = "ok";
                emit_host_room_create_pipeline_trace(
                    "native-create-callback-complete", true,
                    nav.current_scene, tick);
                return true;
            }
            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineComplete)
            {
                return m_create_request_ok;
            }
            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineFailed)
            {
                return false;
            }
            if (m_host_room_create_start_tick == 0)
                m_host_room_create_start_tick = tick;

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineNone)
            {
                // Acceptance requests are intentionally layered, but the
                // native PlayerMatch named session survives between them.
                // Sample once before creating so the next phase adopts the
                // valid public room instead of issuing a duplicate request.
                m_native_session_sample_tick = tick;
                sample_named_online_session_state(tick, false);
                if (has_reusable_host_named_session())
                {
                    m_host_adopted_existing_session = true;
                    m_create_requested = true;
                    m_create_request_ok = true;
                    m_host_room_create_make_room_requested = false;
                    m_host_room_create_make_room_ok = true;
                    m_host_room_create_pipeline_step =
                        kHostRoomCreatePipelineComplete;
                    m_host_room_create_failure =
                        "ok-existing-native-session";
                    emit_host_room_create_pipeline_trace(
                        "native-create-adopted-existing-session", true,
                        nav.current_scene, tick);
                    return true;
                }
                if (!nav.session_hub)
                {
                    m_host_room_create_failure =
                        "session-hub-unavailable";
                    emit_host_room_create_pipeline_trace(
                        "native-create-session-hub-unavailable", false,
                        nav.current_scene, tick);
                    return false;
                }
                if (m_host_room_create_last_step_tick == tick)
                    return false;

                ++m_host_room_create_attempts;
                m_create_requested = true;
                m_host_room_create_make_room_requested = true;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_command_failure =
                    "native CreatePlayerSession";
                m_host_room_create_make_room_ok =
                    call_create_player_session(
                        nav.session_hub, m_session_main_user_id);
                if (!m_host_room_create_make_room_ok)
                {
                    m_host_room_create_failure =
                        "native CreatePlayerSession returned false";
                    if (tick >= m_host_room_create_start_tick &&
                        tick - m_host_room_create_start_tick >=
                            kHostRoomCreateWaitTicks)
                    {
                        m_host_room_create_pipeline_step =
                            kHostRoomCreatePipelineFailed;
                    }
                    emit_host_room_create_pipeline_trace(
                        "native-create-request-failed", false,
                        nav.current_scene, tick);
                    return false;
                }

                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineWaitingForCreateSession;
                m_host_room_create_failure =
                    "waiting-for-native-OnCreateSession";
                emit_host_room_create_pipeline_trace(
                    "native-create-requested", true,
                    nav.current_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineWaitingForCreateSession)
            {
                const bool provisional_false_seen =
                    create_decision.provisional_false_seen;
                if (create_decision.status ==
                    RollbackOnlineCreateStatus::TimedOut)
                {
                    m_host_room_create_pipeline_step =
                        kHostRoomCreatePipelineFailed;
                    m_host_room_create_failure = provisional_false_seen
                        ? "native OnCreateSession timeout after provisional false"
                        : "native OnCreateSession timeout";
                    emit_host_room_create_pipeline_trace(
                        provisional_false_seen
                            ? "native-create-timeout-after-provisional-false"
                            : "native-create-timeout",
                        false,
                        nav.current_scene, tick);
                    return false;
                }
                const bool first_provisional_false =
                    provisional_false_seen &&
                    m_host_room_create_failure !=
                        "waiting-after-provisional-native-OnCreateSession-false";
                m_host_room_create_failure = provisional_false_seen
                    ? "waiting-after-provisional-native-OnCreateSession-false"
                    : "waiting-for-native-OnCreateSession";
                if (first_provisional_false ||
                    tick == m_host_room_create_start_tick + 1 ||
                    (tick % 30u) == 0u)
                {
                    emit_host_room_create_pipeline_trace(
                        provisional_false_seen
                            ? "native-create-provisional-false-waiting"
                            : "native-create-waiting",
                        false,
                        nav.current_scene, tick);
                }
                return false;
            }

            m_host_room_create_pipeline_step =
                kHostRoomCreatePipelineFailed;
            m_host_room_create_failure =
                "native-create-pipeline-invalid-step";
            emit_host_room_create_pipeline_trace(
                "native-create-invalid-step", false,
                nav.current_scene, tick);
            return false;
        }

        bool service_host_room_create_pipeline(
            OnlineNavigatorObjects& nav,
            uint64_t tick) noexcept
        {
            if (m_create_callback_seen && m_create_callback_result)
            {
                m_create_requested = true;
                m_create_request_ok = true;
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineComplete;
                m_host_room_create_failure = "ok";
                emit_host_room_create_pipeline_trace(
                    "create-session-callback-complete", true,
                    nav.current_scene, tick);
                return true;
            }

            RC::Unreal::UObject* player_match_scene = nav.current_scene;
            if (!player_match_scene)
            {
                m_host_room_create_failure =
                    "PlayerMatchLobbyScene unavailable";
                emit_host_room_create_pipeline_trace(
                    "scene-unavailable", false, player_match_scene, tick);
                return false;
            }

            if (!identity_contains_scene(
                    nav.current_scene_identity,
                    "PlayerMatchLobbyScene"))
            {
                m_host_room_create_failure =
                    "waiting-for-PlayerMatchLobbyScene";
                emit_host_room_create_pipeline_trace(
                    "waiting-scene", false, player_match_scene, tick);
                return false;
            }

            if (use_targeted_native_player_session_create())
            {
                return service_host_native_create_pipeline(nav, tick);
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineComplete)
            {
                return m_create_request_ok;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineFailed)
            {
                return false;
            }

            if (m_host_room_create_start_tick == 0)
                m_host_room_create_start_tick = tick;

            if (m_host_room_create_last_step_tick == tick)
                return false;

            m_create_requested = true;
            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineNone)
            {
                std::string state_reason;
                ++m_host_room_create_attempts;
                m_host_room_create_make_room_requested = true;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_make_room_ok =
                    request_player_match_lobby_state(
                        player_match_scene, L"MakeRoom",
                        state_reason, tick);
                m_host_room_create_failure = state_reason;
                if (!m_host_room_create_make_room_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "make-room-request-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineMakeRoomRequested;
                emit_host_room_create_pipeline_trace(
                    "make-room-requested", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineMakeRoomRequested)
            {
                m_host_room_create_last_step_tick = tick;
                m_player_match_poll_requested = true;
                ++m_player_match_poll_count;
                m_host_room_create_make_room_poll_ok =
                    call_player_match_polling_change_state(
                        player_match_scene);
                m_player_match_poll_ok = m_host_room_create_make_room_poll_ok;
                m_host_room_create_failure =
                    m_host_room_create_make_room_poll_ok
                        ? "MakeRoom PollingChangeState ok"
                        : "MakeRoom PollingChangeState failed";
                if (!m_host_room_create_make_room_poll_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "make-room-poll-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineMakeRoomPolled;
                emit_host_room_create_pipeline_trace(
                    "make-room-polled", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                    kHostRoomCreatePipelineMakeRoomPolled ||
                m_host_room_create_pipeline_step ==
                    kHostRoomCreatePipelineNavigatingToPrivateRoom)
            {
                std::string input_reason;
                m_host_room_create_last_step_tick = tick;
                const bool input_ok = send_player_match_creation_input(
                    player_match_scene,
                    UiInputKey::Down,
                    "navigate-to-private-room",
                    tick,
                    input_reason);
                m_host_room_create_failure = input_reason;
                if (!input_ok)
                {
                    if (tick >= m_host_room_create_start_tick &&
                        tick - m_host_room_create_start_tick >=
                            kHostRoomCreateWaitTicks)
                    {
                        m_host_room_create_pipeline_step =
                            kHostRoomCreatePipelineFailed;
                        m_host_room_create_failure =
                            "PlayerMatchRoomCreationWindow private-room "
                            "navigation timeout: " + input_reason;
                        emit_host_room_create_pipeline_trace(
                            "private-room-navigation-timeout", false,
                            player_match_scene, tick);
                        return false;
                    }
                    emit_host_room_create_pipeline_trace(
                        "private-room-navigation-waiting", false,
                        player_match_scene, tick);
                    return false;
                }
                ++m_host_room_create_private_room_down_count;
                m_host_room_create_pipeline_step =
                    m_host_room_create_private_room_down_count ==
                            kHostRoomCreatePrivateRoomRow
                        ? kHostRoomCreatePipelinePrivateRoomSelected
                        : kHostRoomCreatePipelineNavigatingToPrivateRoom;
                emit_host_room_create_pipeline_trace(
                    m_host_room_create_pipeline_step ==
                            kHostRoomCreatePipelinePrivateRoomSelected
                        ? "private-room-selected"
                        : "private-room-navigation-down",
                    true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelinePrivateRoomSelected)
            {
                std::string input_reason;
                m_host_room_create_last_step_tick = tick;
                const bool input_ok = send_player_match_creation_input(
                    player_match_scene,
                    // The cooked creation-window contract orders privateSlot
                    // as 0=Off, 1=On, so enabling it requires incrementing
                    // with Right. Left at the default 0 is a no-op.
                    UiInputKey::Right,
                    "enable-private-room",
                    tick,
                    input_reason);
                m_host_room_create_failure = input_reason;
                if (!input_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "private-room-enable-waiting", false,
                        player_match_scene, tick);
                    return false;
                }
                ++m_host_room_create_private_room_right_count;
                m_host_room_create_private_room_enabled = true;
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelinePrivateRoomEnabled;
                emit_host_room_create_pipeline_trace(
                    "private-room-enabled", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                    kHostRoomCreatePipelinePrivateRoomEnabled ||
                m_host_room_create_pipeline_step ==
                    kHostRoomCreatePipelineNavigatingToCreateRoom)
            {
                if (m_host_room_create_pipeline_step ==
                    kHostRoomCreatePipelinePrivateRoomEnabled)
                {
                    std::wstring menu_w;
                    std::string menu_name;
                    RC::Unreal::UObject* menu_widget = nullptr;
                    std::string resolve_reason;
                    int32_t private_value = -1;
                    std::string private_path;
                    std::string read_reason;
                    m_host_room_create_private_room_readback_attempted = true;
                    const bool resolved = resolve_player_match_creation_window(
                        player_match_scene, menu_w, menu_name, menu_widget,
                        resolve_reason);
                    m_host_room_create_private_room_readback_ok = resolved
                        && read_player_match_creation_private_slot(
                            menu_widget, private_value, private_path,
                            read_reason);
                    m_host_room_create_private_room_readback_value =
                        private_value;
                    m_host_room_create_private_room_readback_path =
                        private_path;
                    m_host_room_create_private_room_readback_failure =
                        m_host_room_create_private_room_readback_ok
                            ? (private_value == 1 ? "ok" :
                               "privateSlot-live-value-is-Off")
                            : (!read_reason.empty() ? read_reason :
                               resolve_reason);
                    m_host_room_create_private_room_enabled =
                        m_host_room_create_private_room_readback_ok
                        && private_value == 1;
                    if (!m_host_room_create_private_room_enabled)
                    {
                        m_host_room_create_failure =
                            "private-room live readback failed: " +
                            m_host_room_create_private_room_readback_failure;
                        if (tick >= m_host_room_create_start_tick &&
                            tick - m_host_room_create_start_tick >=
                                kHostRoomCreateWaitTicks)
                        {
                            m_host_room_create_pipeline_step =
                                kHostRoomCreatePipelineFailed;
                        }
                        emit_host_room_create_pipeline_trace(
                            "private-room-readback-waiting", false,
                            player_match_scene, tick);
                        return false;
                    }
                    emit_host_room_create_pipeline_trace(
                        "private-room-readback-on", true,
                        player_match_scene, tick);
                }
                std::string input_reason;
                m_host_room_create_last_step_tick = tick;
                const bool input_ok = send_player_match_creation_input(
                    player_match_scene,
                    UiInputKey::Up,
                    "navigate-to-create-room",
                    tick,
                    input_reason);
                m_host_room_create_failure = input_reason;
                if (!input_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "create-room-navigation-waiting", false,
                        player_match_scene, tick);
                    return false;
                }
                ++m_host_room_create_private_room_up_count;
                m_host_room_create_pipeline_step =
                    m_host_room_create_private_room_up_count ==
                            kHostRoomCreatePrivateRoomRow
                        ? kHostRoomCreatePipelineCreateRoomSelected
                        : kHostRoomCreatePipelineNavigatingToCreateRoom;
                emit_host_room_create_pipeline_trace(
                    m_host_room_create_pipeline_step ==
                            kHostRoomCreatePipelineCreateRoomSelected
                        ? "create-room-selected"
                        : "create-room-navigation-up",
                    true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineCreateRoomSelected)
            {
                std::string decide_reason;
                m_host_room_create_decide_requested = true;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_decide_ok =
                    send_player_match_creation_decide(
                        player_match_scene, tick, decide_reason);
                m_host_room_create_failure = decide_reason;
                if (!m_host_room_create_decide_ok)
                {
                    if (tick >= m_host_room_create_start_tick &&
                        tick - m_host_room_create_start_tick >=
                            kHostRoomCreateWaitTicks)
                    {
                        m_host_room_create_pipeline_step =
                            kHostRoomCreatePipelineFailed;
                        m_host_room_create_failure =
                            "PlayerMatchRoomCreationWindow Decide timeout: " +
                            decide_reason;
                        emit_host_room_create_pipeline_trace(
                            "creation-decide-timeout", false,
                            player_match_scene, tick);
                        return false;
                    }
                    emit_host_room_create_pipeline_trace(
                        "creation-decide-waiting", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineDecideSent;
                emit_host_room_create_pipeline_trace(
                    "creation-decide-sent", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineDecideSent)
            {
                m_host_room_create_last_step_tick = tick;
                m_player_match_poll_requested = true;
                ++m_player_match_poll_count;
                m_host_room_create_make_connecting_poll_ok =
                    call_player_match_polling_change_state(
                        player_match_scene);
                m_player_match_poll_ok =
                    m_host_room_create_make_connecting_poll_ok;
                m_host_room_create_failure =
                    m_host_room_create_make_connecting_poll_ok
                        ? "post-Decide PollingChangeState ok; "
                          "waiting-for-OnCreateSession"
                        : "post-Decide PollingChangeState failed";
                if (!m_host_room_create_make_connecting_poll_ok)
                {
                    if (tick >= m_host_room_create_start_tick &&
                        tick - m_host_room_create_start_tick >=
                            kHostRoomCreateWaitTicks)
                    {
                        m_host_room_create_pipeline_step =
                            kHostRoomCreatePipelineFailed;
                        m_host_room_create_failure =
                            "post-Decide PollingChangeState timeout";
                    }
                    emit_host_room_create_pipeline_trace(
                        "post-decide-poll-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineWaitingForCreateSession;
                emit_host_room_create_pipeline_trace(
                    "post-decide-polled-waiting-for-create-session", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineMakeConnectingRequested)
            {
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_make_connecting_poll_ok =
                    call_player_match_polling_change_state(
                        player_match_scene);
                m_host_room_create_failure =
                    m_host_room_create_make_connecting_poll_ok
                        ? "MakeConnecting PollingChangeState ok"
                        : "MakeConnecting PollingChangeState failed";
                if (!m_host_room_create_make_connecting_poll_ok)
                {
                    emit_host_room_create_pipeline_trace(
                        "make-connecting-poll-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineMakeConnectingPolled;
                emit_host_room_create_pipeline_trace(
                    "make-connecting-polled", true,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineMakeConnectingPolled)
            {
                m_host_room_create_pipeline_step =
                    kHostRoomCreatePipelineWaitingForCreateSession;
                m_host_room_create_last_step_tick = tick;
                m_host_room_create_failure =
                    "waiting-for-OnCreateSession";
                emit_host_room_create_pipeline_trace(
                    "waiting-for-create-session", false,
                    player_match_scene, tick);
                return false;
            }

            if (m_host_room_create_pipeline_step ==
                kHostRoomCreatePipelineWaitingForCreateSession)
            {
                if (m_create_callback_seen && !m_create_callback_result)
                {
                    m_host_room_create_failure =
                        "OnCreateSession result false";
                    emit_host_room_create_pipeline_trace(
                        "create-session-result-false", false,
                        player_match_scene, tick);
                    return false;
                }
                if (tick >= m_host_room_create_start_tick &&
                    tick - m_host_room_create_start_tick >=
                        kHostRoomCreateWaitTicks)
                {
                    m_host_room_create_pipeline_step =
                        kHostRoomCreatePipelineFailed;
                    m_host_room_create_failure =
                        "OnCreateSession timeout";
                    emit_host_room_create_pipeline_trace(
                        "create-session-timeout", false,
                        player_match_scene, tick);
                    return false;
                }
                m_host_room_create_failure =
                    "waiting-for-OnCreateSession";
                emit_host_room_create_pipeline_trace(
                    "waiting-for-create-session", false,
                    player_match_scene, tick);
                return false;
            }

            m_host_room_create_pipeline_step =
                kHostRoomCreatePipelineFailed;
            m_host_room_create_failure =
                "host-room-create-pipeline-invalid-step";
            emit_host_room_create_pipeline_trace(
                "invalid-step", false, player_match_scene, tick);
            return false;
        }

        bool sample_search_results(
            void* search,
            std::string& sample,
            int32_t& count,
            int32_t& max,
            uintptr_t& result_ptr,
            bool& target_found,
            int32_t& selected_index,
            const char*& failure,
            size_t sample_limit) noexcept
        {
            count = 0;
            max = 0;
            result_ptr = 0;
            target_found = false;
            selected_index = -1;
            failure = "starting";
            if (!search)
            {
                failure = "search-object-unavailable";
                return false;
            }

            auto* search_bytes = reinterpret_cast<uint8_t*>(search);
            void* results = nullptr;
            if (!SafeReadPtr(search_bytes + 8, &results) ||
                !SafeReadInt32(search_bytes + 0x10, &count) ||
                !SafeReadInt32(search_bytes + 0x14, &max))
            {
                failure = "search-results-header-unreadable";
                return false;
            }

            result_ptr = reinterpret_cast<uintptr_t>(results);
            if (count <= 0)
            {
                failure = "waiting-for-search-results";
                return false;
            }
            if (!results || max < count || count > 64)
            {
                failure = "search-results-header-invalid";
                return false;
            }

            const bool require_target_match =
                !m_cfg.room_name.empty()
                || !m_cfg.session_name.empty()
                || m_cfg.target_owner_id != 0;
            for (int32_t i = 0; i < count; ++i)
            {
                void* candidate =
                    reinterpret_cast<uint8_t*>(results)
                    + static_cast<size_t>(i) * 200u;
                void* result_wrapper = candidate;
                std::string room;
                std::string name;
                std::string owner;
                (void)call_session_result_string_helper(
                    L"GetSessionResultRoomName",
                    &result_wrapper,
                    static_cast<int32_t>(sizeof(result_wrapper)),
                    room);
                (void)call_session_result_string_helper(
                    L"GetSessionResultName",
                    &result_wrapper,
                    static_cast<int32_t>(sizeof(result_wrapper)),
                    name);
                (void)call_session_result_string_helper(
                    L"GetSessionResultOwnerNetId",
                    &result_wrapper,
                    static_cast<int32_t>(sizeof(result_wrapper)),
                    owner);
                char prefix[96] {};
                std::snprintf(
                    prefix,
                    sizeof(prefix),
                    "i=%d ptr=0x%llX",
                    i,
                    static_cast<unsigned long long>(
                        reinterpret_cast<uintptr_t>(candidate)));
                std::string item = prefix;
                if (!room.empty())
                {
                    item += " room=";
                    item += room;
                }
                if (!name.empty())
                {
                    item += " name=";
                    item += name;
                }
                if (!owner.empty())
                {
                    item += " owner=";
                    item += owner;
                }
                append_limited_name(sample, item, sample_limit);

                const bool room_match = m_cfg.room_name.empty()
                    || session_result_matches_text(room, m_cfg.room_name);
                const bool session_match = m_cfg.session_name.empty()
                    || session_result_matches_text(name, m_cfg.session_name);
                const bool owner_match = m_cfg.target_owner_id == 0
                    || session_result_owner_matches(
                           owner, m_cfg.target_owner_id);
                const bool matches = require_target_match
                    && room_match && session_match && owner_match;
                if (!require_target_match || matches)
                {
                    target_found = matches;
                    selected_index = i;
                    failure = matches ? "ok" : "results-present";
                    return true;
                }
            }

            failure = require_target_match
                ? "target-search-result-not-found"
                : "exact-host-search-target-not-configured";
            return false;
        }

        bool set_search_presence_flag(
            void* search,
            bool presence,
            const char*& failure) noexcept
        {
            failure = "starting";
            if (!search)
            {
                failure = "search-object-unavailable";
                return false;
            }

            const uintptr_t set_bool_addr =
                native_address(kRVA_SetOnlineSearchSettingBool);
            if (!set_bool_addr)
            {
                failure = "native-query-functions-unavailable";
                return false;
            }

            RC::Unreal::FName presence_key(
                STR("PRESENCESEARCH"), RC::Unreal::FNAME_Add);
            auto* set_bool =
                reinterpret_cast<SetOnlineSearchSettingBoolFn>(
                    set_bool_addr);
            __try
            {
                set_bool(
                    reinterpret_cast<uint8_t*>(search) + 0x20,
                    presence_key.ToUnstableInt(),
                    &presence,
                    0);
                failure = "ok";
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                failure = "presence-query-update-exception";
                return false;
            }
        }

        bool debug_disable_find_presence_after_call(
            RC::Unreal::UObject* session_hub) noexcept
        {
            m_debug_find_presence_post_override_requested = true;
            m_debug_find_presence_post_override_ok = false;
            if (!m_cfg.debug_steam_probe)
            {
                m_debug_find_presence_post_override_failure = "disabled";
                return false;
            }
            if (!safe_is_real(session_hub))
            {
                m_debug_find_presence_post_override_failure =
                    "session-hub-unavailable";
                return false;
            }
            auto* hub_bytes = reinterpret_cast<uint8_t*>(session_hub);
            void* search = nullptr;
            if (!SafeReadPtr(hub_bytes + 0x38, &search) || !search)
            {
                m_debug_find_presence_post_override_failure =
                    "search-object-unavailable";
                return false;
            }
            const char* failure = "not-run";
            m_debug_find_presence_post_override_ok =
                set_search_presence_flag(search, false, failure);
            m_debug_find_presence_post_override_failure = failure;
            return m_debug_find_presence_post_override_ok;
        }

        bool start_no_presence_find_probe(
            RC::Unreal::UObject* session_hub,
            int32_t main_user_id,
            uint64_t tick) noexcept
        {
            ++m_no_presence_find_attempts;
            m_no_presence_find_requested = true;
            m_no_presence_find_start_tick = tick;
            m_no_presence_find_polled = false;
            m_no_presence_find_join_requested = false;
            m_no_presence_find_join_ok = false;
            m_no_presence_find_result_count = 0;
            m_no_presence_find_result_max = 0;
            m_no_presence_find_result_target_found = false;
            m_no_presence_find_selected_index = -1;
            m_no_presence_find_search_ptr = 0;
            m_no_presence_find_result_ptr = 0;
            m_no_presence_find_sample.clear();
            m_no_presence_find_attempt_empty_counted = false;
            m_no_presence_find_presence_disabled = false;
            m_no_presence_find_failure = "starting";

            if (!safe_is_real(session_hub))
            {
                m_no_presence_find_failure = "session-hub-unavailable";
                return false;
            }

            auto* hub_bytes = reinterpret_cast<uint8_t*>(session_hub);
            void* search = nullptr;
            if (!SafeReadPtr(hub_bytes + 0x38, &search) || !search)
            {
                m_no_presence_find_failure = "search-object-unavailable";
                return false;
            }
            m_no_presence_find_search_ptr =
                reinterpret_cast<uintptr_t>(search);

            const uintptr_t get_online_addr =
                native_address(kRVA_GetOnlineSessionInterfaceShared);
            if (!get_online_addr)
            {
                m_no_presence_find_failure =
                    "native-query-functions-unavailable";
                return false;
            }

            const char* presence_failure = "not-run";
            if (!set_search_presence_flag(search, false, presence_failure))
            {
                m_no_presence_find_failure = presence_failure;
                return false;
            }
            m_no_presence_find_presence_disabled = true;

            SharedInterfaceNative online {};
            if (!safe_get_online_session_interface(
                    reinterpret_cast<GetOnlineSessionInterfaceSharedFn>(
                        get_online_addr),
                    0,
                    &online) ||
                !online.object)
            {
                m_no_presence_find_failure =
                    "online-session-interface-unavailable";
                return false;
            }

            void* vtable = nullptr;
            void* slot = nullptr;
            if (!SafeReadPtr(online.object, &vtable) || !vtable ||
                !SafeReadPtr(
                    reinterpret_cast<uint8_t*>(vtable)
                        + kOnlineSessionFindSessionsVtableOffset,
                    &slot) ||
                !slot)
            {
                m_no_presence_find_failure =
                    "find-sessions-slot-unavailable";
                return false;
            }

            auto* find_sessions =
                reinterpret_cast<OnlineSessionFindSessionsFn>(slot);
            auto* search_shared =
                reinterpret_cast<SharedInterfaceNative*>(hub_bytes + 0x38);
            __try
            {
                m_no_presence_find_call_ok =
                    find_sessions(online.object, main_user_id, search_shared);
                m_no_presence_find_failure =
                    m_no_presence_find_call_ok
                        ? "waiting-for-search-results"
                        : "find-sessions-returned-false";
                return m_no_presence_find_call_ok;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                m_no_presence_find_failure =
                    "find-sessions-call-exception";
                return false;
            }
        }

        void poll_no_presence_find_probe(
            RC::Unreal::UObject* session_hub,
            RC::Unreal::UObject* player_match_scene,
            uint64_t tick) noexcept
        {
            if (!m_no_presence_find_requested ||
                !m_no_presence_find_call_ok)
            {
                return;
            }
            if (m_no_presence_find_join_requested)
                return;

            m_no_presence_find_polled = true;
            void* search = reinterpret_cast<void*>(
                m_no_presence_find_search_ptr);
            if (safe_is_real(session_hub))
            {
                void* current_search = nullptr;
                auto* hub_bytes = reinterpret_cast<uint8_t*>(session_hub);
                if (SafeReadPtr(hub_bytes + 0x38, &current_search) &&
                    current_search)
                {
                    search = current_search;
                    m_no_presence_find_search_ptr =
                        reinterpret_cast<uintptr_t>(current_search);
                }
            }

            const char* failure = "not-run";
            const bool sampled = sample_search_results(
                search,
                m_no_presence_find_sample,
                m_no_presence_find_result_count,
                m_no_presence_find_result_max,
                m_no_presence_find_result_ptr,
                m_no_presence_find_result_target_found,
                m_no_presence_find_selected_index,
                failure,
                5000);
            m_no_presence_find_failure =
                sampled ? failure : failure;
            if (sampled
                && m_no_presence_find_result_count <= 0
                && !m_no_presence_find_attempt_empty_counted)
            {
                ++m_no_presence_find_empty_attempts;
                m_no_presence_find_attempt_empty_counted = true;
            }
            if (sampled
                && m_no_presence_find_result_target_found
                && !m_no_presence_find_join_requested
                && !m_join_request_ok)
            {
                void* selected_result =
                    reinterpret_cast<uint8_t*>(
                        reinterpret_cast<void*>(
                            m_no_presence_find_result_ptr))
                    + static_cast<size_t>(
                        m_no_presence_find_selected_index) * 200u;
                m_no_presence_find_join_requested = true;
                prepare_join_callback_capture(
                    session_hub,
                    effective_join_session_name(),
                    m_session_main_user_id);
                if (safe_is_real(player_match_scene))
                {
                    void* selected_wrapper = selected_result;
                    m_no_presence_find_join_ok =
                        stage_selected_result_on_player_match_scene(
                            player_match_scene,
                            &selected_wrapper,
                            static_cast<int32_t>(sizeof(selected_wrapper)),
                            reinterpret_cast<uintptr_t>(selected_result),
                            tick);
                    if (m_no_presence_find_join_ok)
                    {
                        m_no_presence_find_failure = "ok";
                        sync_join_callback_state();
                        return;
                    }
                }
                if (safe_is_real(player_match_scene))
                {
                    std::string state_reason;
                    m_join_scene_search_connecting_requested = true;
                    m_join_scene_search_connecting_ok =
                        request_player_match_lobby_state(
                            player_match_scene,
                            L"SearchConnecting",
                            state_reason);
                    if (!m_join_scene_search_connecting_ok)
                    {
                        m_join_scene_failure = state_reason;
                    }
                    else
                    {
                        m_join_scene_poll_ok =
                            call_player_match_polling_change_state(
                                player_match_scene);
                        m_join_scene_failure =
                            m_join_scene_poll_ok
                                ? "ok"
                                : "PlayerMatchLobbyScene."
                                  "PollingChangeState failed";
                    }
                }
                void* luxor_result_wrapper = selected_result;
                m_no_presence_find_join_ok =
                    call_join_session_process_event(
                        &luxor_result_wrapper,
                        static_cast<int32_t>(
                            sizeof(luxor_result_wrapper)));
                if (m_no_presence_find_join_ok &&
                    safe_is_real(player_match_scene) &&
                    (!m_join_scene_search_connecting_requested ||
                     !m_join_scene_poll_ok))
                {
                    std::string state_reason;
                    m_join_scene_search_connecting_requested = true;
                    m_join_scene_search_connecting_ok =
                        request_player_match_lobby_state(
                            player_match_scene,
                            L"SearchConnecting",
                            state_reason);
                    if (!m_join_scene_search_connecting_ok)
                        m_join_scene_failure = state_reason;
                    else
                    {
                        m_join_scene_poll_ok =
                            call_player_match_polling_change_state(
                                player_match_scene);
                        if (!m_join_scene_poll_ok)
                        {
                            m_join_scene_failure =
                                "PlayerMatchLobbyScene."
                                "PollingChangeState failed";
                        }
                        else
                        {
                            m_join_scene_failure = "ok";
                        }
                    }
                }
                if (!m_no_presence_find_join_ok)
                    m_no_presence_find_failure =
                        "presence-disabled-join-handoff-failed";
                sync_join_callback_state();
            }
        }

        bool poll_search_results_and_join(
            RC::Unreal::UObject* session_hub,
            OnlineNavigatorObjects& nav,
            uint64_t tick) noexcept
        {
            RC::Unreal::UObject* player_match_scene = nav.current_scene;
            m_find_result_polled = true;
            if (!safe_is_real(session_hub))
            {
                m_join_callback_failure = "join-session-hub-invalid";
                s_join_callback_failure = m_join_callback_failure;
                return false;
            }

            if (m_join_scene_selected_result != 0 &&
                m_join_scene_pipeline_step != kJoinScenePipelineNone)
            {
                bool joined = false;
                if (m_join_scene_mode == "player-match-state-compat")
                {
                    joined = stage_selected_result_on_player_match_scene(
                        player_match_scene,
                        m_join_scene_selected_result_storage.data(),
                        m_join_scene_selected_result_bytes,
                        m_join_scene_selected_result,
                        tick);
                }
                else if (m_join_scene_mode == "ui-decide")
                {
                    joined = stage_selected_result_with_gameflow_decide(
                        nav,
                        m_join_scene_selected_result_storage.data(),
                        m_join_scene_selected_result_bytes,
                        m_join_scene_selected_result,
                        tick);
                }
                else if (m_join_scene_mode == "direct-native")
                {
                    if (latch_failed_join_complete_if_seen())
                    {
                        emit_join_pipeline_trace(
                            "native-join-direct-complete-failed", false,
                            player_match_scene, tick);
                        sync_join_callback_state();
                        return false;
                    }
                    s_join_callback_requested.store(
                        true, std::memory_order_release);
                    m_join_scene_failure = "waiting-for-OnJoinSession";
                    s_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "native-join-direct-waiting-for-OnJoinSession", true,
                        player_match_scene, tick);
                    joined = true;
                }
                sync_join_callback_state();
                return joined;
            }

            auto* hub_bytes = reinterpret_cast<uint8_t*>(session_hub);
            void* search = nullptr;
            if (!SafeReadPtr(hub_bytes + 0x38, &search) || !search)
            {
                m_join_callback_failure = "search-object-unavailable";
                s_join_callback_failure = m_join_callback_failure;
                return false;
            }
            m_find_search_ptr = reinterpret_cast<uintptr_t>(search);

            auto* search_bytes = reinterpret_cast<uint8_t*>(search);
            void* results = nullptr;
            int32_t count = 0;
            int32_t max = 0;
            if (!SafeReadPtr(search_bytes + 8, &results) ||
                !SafeReadInt32(search_bytes + 0x10, &count) ||
                !SafeReadInt32(search_bytes + 0x14, &max))
            {
                m_join_callback_failure =
                    "search-results-header-unreadable";
                s_join_callback_failure = m_join_callback_failure;
                return false;
            }

            m_find_result_ptr = reinterpret_cast<uintptr_t>(results);
            std::vector<uint8_t> snapshot;
            int32_t snapshot_count = 0;
            int32_t snapshot_element_size = 0;
            const bool have_snapshot =
                copy_find_result_snapshot(
                    snapshot, snapshot_count, snapshot_element_size)
                && snapshot_count > 0
                && snapshot_element_size > 0
                && snapshot.size() >=
                    static_cast<size_t>(snapshot_count) *
                    static_cast<size_t>(snapshot_element_size);

            if (count <= 0 && !have_snapshot)
            {
                m_join_callback_failure = "waiting-for-search-results";
                s_join_callback_failure = m_join_callback_failure;
                return false;
            }
            if ((!results || max < count || count > 64) && !have_snapshot)
            {
                m_join_callback_failure =
                    "search-results-header-invalid";
                s_join_callback_failure = m_join_callback_failure;
                return false;
            }

            int32_t selected_index = -1;
            const void* selected_result = nullptr;
            int32_t selected_result_bytes = 0;
            uintptr_t selected_identity = 0;
            void* fallback_selected_wrapper = nullptr;
            const bool require_target_match =
                !m_cfg.room_name.empty()
                || !m_cfg.session_name.empty()
                || m_cfg.target_owner_id != 0;
            const int32_t source_count = have_snapshot ? snapshot_count : count;
            const int32_t source_element_size =
                have_snapshot
                    ? snapshot_element_size
                    : static_cast<int32_t>(sizeof(void*));
            m_find_result_count = source_count;
            m_find_result_max = have_snapshot ? snapshot_count : max;
            m_find_result_element_size = source_element_size;
            s_find_result_count.store(
                source_count, std::memory_order_release);
            s_find_result_element_size.store(
                source_element_size, std::memory_order_release);
            for (int32_t i = 0; i < source_count; ++i)
            {
                const uint8_t* snapshot_candidate = nullptr;
                void* live_candidate = nullptr;
                const void* helper_result = nullptr;
                int32_t helper_result_bytes = 0;
                uintptr_t candidate_identity = 0;
                if (have_snapshot)
                {
                    snapshot_candidate =
                        snapshot.data() +
                        static_cast<size_t>(i) *
                            static_cast<size_t>(snapshot_element_size);
                    helper_result = snapshot_candidate;
                    helper_result_bytes = snapshot_element_size;
                    candidate_identity =
                        reinterpret_cast<uintptr_t>(results)
                        + static_cast<uintptr_t>(i) *
                            static_cast<uintptr_t>(snapshot_element_size);
                }
                else
                {
                    live_candidate =
                        reinterpret_cast<uint8_t*>(results)
                        + static_cast<size_t>(i) * 200u;
                    fallback_selected_wrapper = live_candidate;
                    helper_result = &fallback_selected_wrapper;
                    helper_result_bytes =
                        static_cast<int32_t>(
                            sizeof(fallback_selected_wrapper));
                    candidate_identity =
                        reinterpret_cast<uintptr_t>(live_candidate);
                }
                std::string room;
                std::string name;
                std::string owner;
                (void)call_session_result_string_helper(
                    L"GetSessionResultRoomName",
                    helper_result,
                    helper_result_bytes,
                    room);
                (void)call_session_result_string_helper(
                    L"GetSessionResultName",
                    helper_result,
                    helper_result_bytes,
                    name);
                (void)call_session_result_string_helper(
                    L"GetSessionResultOwnerNetId",
                    helper_result,
                    helper_result_bytes,
                    owner);
                char prefix[96] {};
                std::snprintf(
                    prefix,
                    sizeof(prefix),
                    "i=%d ptr=0x%llX bytes=%d src=%s",
                    i,
                    static_cast<unsigned long long>(
                        candidate_identity),
                    helper_result_bytes,
                    have_snapshot ? "callback" : "search");
                std::string sample = prefix;
                if (!room.empty())
                {
                    sample += " room=";
                    sample += room;
                }
                if (!name.empty())
                {
                    sample += " name=";
                    sample += name;
                }
                if (!owner.empty())
                {
                    sample += " owner=";
                    sample += owner;
                }
                append_limited_name(m_find_result_sample, sample, 5000);

                const bool room_match = m_cfg.room_name.empty()
                    || session_result_matches_text(room, m_cfg.room_name);
                const bool session_match = m_cfg.session_name.empty()
                    || session_result_matches_text(name, m_cfg.session_name);
                const bool owner_match = m_cfg.target_owner_id == 0
                    || session_result_owner_matches(
                           owner, m_cfg.target_owner_id);
                const bool target_match = require_target_match
                    && room_match && session_match && owner_match;
                // Production joining must never fall back to whichever room
                // happened to occupy result slot zero.  A configured room,
                // session, or owner must match before a result is staged.
                if (target_match)
                {
                    selected_index = i;
                    if (have_snapshot)
                    {
                        selected_result = snapshot_candidate;
                        selected_result_bytes = snapshot_element_size;
                    }
                    else
                    {
                        selected_result = &fallback_selected_wrapper;
                        selected_result_bytes =
                            static_cast<int32_t>(
                                sizeof(fallback_selected_wrapper));
                    }
                    selected_identity = candidate_identity;
                    m_find_result_target_found = target_match;
                    break;
                }
            }

            if (!selected_result)
            {
                m_find_result_target_found = false;
                m_find_result_selected_index = -1;
                m_join_callback_failure = require_target_match
                    ? "target-search-result-not-found"
                    : "exact-host-search-target-not-configured";
                s_join_callback_failure = m_join_callback_failure;
                return false;
            }
            m_find_result_selected_index = selected_index;
            s_join_capture_enabled.store(false, std::memory_order_release);
            if (m_cfg.online_stage_find_only)
            {
                m_join_callback_failure = m_find_result_target_found
                    ? "find-only-target-found"
                    : "find-only-results-present";
                s_join_callback_failure = m_join_callback_failure;
                return false;
            }

            s_find_callback_seen.store(true, std::memory_order_release);
            s_find_callback_result.store(true, std::memory_order_release);
            // The stock menu does more than call JoinSession: it stages the
            // selected result on the lobby/select-room states, pings, and only
            // then enters SearchConnecting. Keep that UI-shaped handoff as the
            // default and reserve the immediate native JoinSession shortcut for
            // diagnostics.
            const bool use_native_join_handoff =
                m_cfg.online_stage_direct_native_join_diagnostic;
            if (use_native_join_handoff)
            {
                emit_join_pipeline_trace(
                    "native-join-direct-begin", false,
                    player_match_scene, tick);
                std::string stage_reason;
                m_join_scene_result_staged =
                    write_selected_find_result(
                        player_match_scene,
                        selected_result,
                        selected_result_bytes,
                        "PlayerMatchLobbyScene",
                        true,
                        stage_reason);
                if (!m_join_scene_result_staged)
                {
                    m_join_scene_failure = stage_reason;
                    m_join_callback_failure =
                        "PlayerMatchLobbyScene.FindResult stage failed";
                    s_join_callback_failure = m_join_callback_failure;
                    emit_join_pipeline_trace(
                        "native-join-direct-stage-failed", false,
                        player_match_scene, tick);
                    return false;
                }

                // Bypass the controller-driven room-list/ping UI, but retain
                // the stock SearchConnecting state setup that owns SC6's
                // post-join transport and scene transition.
                std::string state_reason;
                m_join_scene_search_connecting_requested = true;
                m_join_scene_search_connecting_ok =
                    request_player_match_lobby_state(
                        player_match_scene,
                        L"SearchConnecting",
                        state_reason);
                if (!m_join_scene_search_connecting_ok)
                {
                    m_join_scene_failure = state_reason;
                    m_join_callback_failure = m_join_scene_failure.c_str();
                    s_join_callback_failure = m_join_callback_failure;
                    emit_join_pipeline_trace(
                        "native-join-direct-search-connecting-failed", false,
                        player_match_scene, tick);
                    return false;
                }
                m_join_scene_poll_ok =
                    call_player_match_polling_change_state(
                        player_match_scene);
                if (!m_join_scene_poll_ok)
                {
                    m_join_scene_failure =
                        "PlayerMatchLobbyScene.PollingChangeState failed";
                    m_join_callback_failure = m_join_scene_failure.c_str();
                    s_join_callback_failure = m_join_callback_failure;
                    emit_join_pipeline_trace(
                        "native-join-direct-search-connecting-poll-failed",
                        false, player_match_scene, tick);
                    return false;
                }

                m_join_scene_decide_requested = true;
                m_join_scene_decide_ok = call_join_session_process_event(
                    selected_result,
                    selected_result_bytes);
                if (!m_join_scene_decide_ok)
                {
                    m_join_scene_failure = s_join_callback_failure;
                    m_join_callback_failure = m_join_scene_failure.c_str();
                    emit_join_pipeline_trace(
                        "native-join-direct-failed", false,
                        player_match_scene, tick);
                    sync_join_callback_state();
                    return false;
                }
                m_join_scene_selected_result =
                    selected_identity ? selected_identity :
                                        reinterpret_cast<uintptr_t>(
                                            selected_result);
                m_join_scene_selected_result_bytes = selected_result_bytes;
                m_join_scene_selected_result_storage.assign(
                    static_cast<const uint8_t*>(selected_result),
                    static_cast<const uint8_t*>(selected_result)
                        + static_cast<size_t>(selected_result_bytes));
                m_join_scene_pipeline_step = kJoinScenePipelineDecideSent;
                m_join_scene_mode = "direct-native-search-connecting";
                m_join_scene_failure = "JoinSession requested";
                m_join_callback_failure = m_join_scene_failure.c_str();
                s_join_callback_failure = m_join_callback_failure;
                emit_join_pipeline_trace(
                    "native-join-direct-end", true,
                    player_match_scene, tick);
                sync_join_callback_state();
                return true;
            }
            const bool joined = stage_selected_result_with_gameflow_decide(
                nav,
                selected_result,
                selected_result_bytes,
                selected_identity,
                tick);
            sync_join_callback_state();
            return joined;
        }

        static bool safe_get_uobject_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property_name,
            RC::Unreal::UObject*& out) noexcept
        {
            out = nullptr;
            if (!obj || !property_name) return false;
            __try
            {
                auto** p = obj->GetValuePtrByPropertyNameInChain<
                    RC::Unreal::UObject*>(property_name);
                if (!p || !*p) return false;
                out = *p;
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                out = nullptr;
                return false;
            }
        }

        static bool safe_process_event(RC::Unreal::UObject* obj,
                                       RC::Unreal::UFunction* fn,
                                       void* params) noexcept
        {
            if (!obj || !fn) return false;
            __try
            {
                obj->ProcessEvent(fn, params);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool call_bool_query(RC::Unreal::UObject* obj,
                                    const wchar_t* name,
                                    bool& out) noexcept
        {
            out = false;
            if (!obj || !name) return false;
            RC::Unreal::UFunction* fn = nullptr;
            __try
            {
                fn = obj->GetFunctionByNameInChain(name);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
            if (!fn) return false;
            struct Params
            {
                bool ReturnValue {false};
            } params{};
            if (!safe_process_event(obj, fn, &params)) return false;
            out = params.ReturnValue;
            return true;
        }

        static bool call_uobject_param_function(
            RC::Unreal::UObject* obj,
            const wchar_t* name,
            RC::Unreal::UObject* value) noexcept
        {
            if (!safe_is_real(obj) || !name) return false;
            auto* fn = obj->GetFunctionByNameInChain(name);
            if (!fn) return false;
            struct Params
            {
                RC::Unreal::UObject* Value {nullptr};
            } params {};
            params.Value = value;
            return safe_process_event(obj, fn, &params);
        }

        static RC::Unreal::UObject* call_uobject_return_function(
            RC::Unreal::UObject* obj,
            const wchar_t* name) noexcept
        {
            if (!safe_is_real(obj) || !name) return nullptr;
            auto* fn = obj->GetFunctionByNameInChain(name);
            if (!fn) return nullptr;
            struct Params
            {
                RC::Unreal::UObject* ReturnValue {nullptr};
            } params {};
            if (!safe_process_event(obj, fn, &params)) return nullptr;
            return safe_is_real(params.ReturnValue) ? params.ReturnValue
                                                    : nullptr;
        }

