        static constexpr uint32_t direct_stage_required_setup_mask() noexcept
        {
            // Native action code 6 expands to setup types 0, 1, 2, 4, 5,
            // with dummy type 3 added only when BattleSetup owns dummy data.
            // It is not itself a setup slot.
            return (uint32_t{1} << 0) | (uint32_t{1} << 1) |
                   (uint32_t{1} << 2) | (uint32_t{1} << 4) |
                   (uint32_t{1} << 5);
        }

        static constexpr uint64_t kDirectStageBattleSceneStableTicks = 3;
        static constexpr uint64_t kDirectStageBattleContextStableTicks = 3;

        static int32_t direct_stage_map_index(int32_t raw_stage) noexcept
        {
            return raw_stage > 0xff ? raw_stage & 0xff : raw_stage;
        }

        static bool direct_stage_metadata_valid(int32_t stage,
                                                int32_t left,
                                                int32_t right) noexcept
        {
            const int32_t stage_map = direct_stage_map_index(stage);
            return stage >= 0 && stage <= 0xfff &&
                   stage_map >= 0 && stage_map <= 0xff &&
                   left >= 0 && left <= 0xfe &&
                   right >= 0 && right <= 0xfe;
        }

