        static bool read_stage_asset_path_registry_counts(
            int32_t& count,
            int32_t& capacity) noexcept
        {
            count = 0;
            capacity = 0;
            const uintptr_t base = NativeBinding::imageBase();
            if (!base) return false;
            auto* registry =
                reinterpret_cast<uint8_t*>(base + kRVA_StageAssetPathRegistry);
            const bool count_ok =
                SafeReadBytes(registry + kStageAssetPathRegistryCountOff,
                              &count, sizeof(count));
            const bool capacity_ok =
                SafeReadBytes(registry + kStageAssetPathRegistryCapacityOff,
                              &capacity, sizeof(capacity));
            if (!count_ok || !capacity_ok)
            {
                count = 0;
                capacity = 0;
                return false;
            }
            if (count < 0 || capacity < 0 || count > capacity ||
                capacity > 4096)
            {
                return false;
            }
            return true;
        }

