        static RC::Unreal::FProperty* reflected_param_any(
            RC::Unreal::UFunction* function,
            const wchar_t* first,
            const wchar_t* second = nullptr) noexcept
        {
            RC::Unreal::FProperty* prop = reflected_param(function, first);
            if (!prop && second)
                prop = reflected_param(function, second);
            return prop;
        }

        static bool reflected_write_i32(
            RC::Unreal::FProperty* prop,
            void* params,
            int32_t value) noexcept
        {
            if (!prop || !params) return false;
            void* slot = prop->ContainerPtrToValuePtr<void>(params);
            if (!slot || prop->GetSize() < static_cast<int32_t>(sizeof(value)))
                return false;
            return SafeWriteBytes(slot, &value, sizeof(value));
        }

        static bool call_chara_code_by_index(
            RC::Unreal::UObject* ui_game_content,
            int32_t chara_index,
            std::wstring& out_code,
            std::string& out_code_utf8,
            std::string& reason) noexcept
        {
            out_code.clear();
            out_code_utf8.clear();
            if (!safe_is_real(ui_game_content))
            {
                reason = "UIGameContent unavailable";
                return false;
            }
            auto* fn = ui_game_content->GetFunctionByNameInChain(
                L"GetCharaCodeByCharaIndex");
            if (!fn)
            {
                reason = "GetCharaCodeByCharaIndex unavailable";
                return false;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096)
            {
                reason = "GetCharaCodeByCharaIndex params invalid";
                return false;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            RC::Unreal::FProperty* index_prop =
                reflected_param_any(fn, L"InCharaIndex", L"inCharaIndex");
            auto* ret_prop = RC::Unreal::CastField<RC::Unreal::FStrProperty>(
                fn->GetReturnProperty());
            if (!index_prop || !ret_prop)
            {
                reason = "GetCharaCodeByCharaIndex reflection mismatch";
                return false;
            }
            if (!reflected_write_i32(index_prop, params.data(), chara_index))
            {
                reason = "GetCharaCodeByCharaIndex param write failed";
                return false;
            }
            if (!safe_process_event(ui_game_content, fn, params.data()))
            {
                reason = "GetCharaCodeByCharaIndex ProcessEvent failed";
                return false;
            }
            auto* result = ret_prop->ContainerPtrToValuePtr<
                RC::Unreal::FString>(params.data());
            if (!result)
            {
                reason = "GetCharaCodeByCharaIndex return missing";
                return false;
            }
            const wchar_t* chars = **result;
            const int32_t len = result->Len();
            if (!chars || len <= 0)
            {
                reason = "GetCharaCodeByCharaIndex returned empty";
                return false;
            }
            out_code.assign(chars, chars + len);
            out_code_utf8 = fstring_to_utf8(*result);
            reason = "ok";
            return !out_code.empty();
        }

        static RC::Unreal::UObject* call_creation_profile_by_chara_code(
            RC::Unreal::UObject* ui_game_content,
            const std::wstring& chara_code,
            int32_t profile_index,
            std::string& reason) noexcept
        {
            if (!safe_is_real(ui_game_content))
            {
                reason = "UIGameContent unavailable";
                return nullptr;
            }
            if (chara_code.empty())
            {
                reason = "chara code empty";
                return nullptr;
            }
            auto* fn = ui_game_content->GetFunctionByNameInChain(
                L"GetCreationProfileByCharaCode");
            if (!fn)
            {
                reason = "GetCreationProfileByCharaCode unavailable";
                return nullptr;
            }
            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096)
            {
                reason = "GetCreationProfileByCharaCode params invalid";
                return nullptr;
            }
            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            RC::Unreal::FProperty* code_prop =
                reflected_param_any(fn, L"inCharaCode", L"InCharaCode");
            RC::Unreal::FProperty* index_prop =
                reflected_param_any(fn, L"inIndex", L"InIndex");
            RC::Unreal::FProperty* ret_prop = fn->GetReturnProperty();
            if (!code_prop || !index_prop || !ret_prop)
            {
                reason = "GetCreationProfileByCharaCode reflection mismatch";
                return nullptr;
            }
            auto* code_slot = code_prop->ContainerPtrToValuePtr<
                RC::Unreal::FString>(params.data());
            if (!code_slot)
            {
                reason = "GetCreationProfileByCharaCode code slot missing";
                return nullptr;
            }
            *code_slot = RC::Unreal::FString(chara_code.c_str());
            if (!reflected_write_i32(index_prop, params.data(),
                                     profile_index))
            {
                reason = "GetCreationProfileByCharaCode index write failed";
                return nullptr;
            }
            if (!safe_process_event(ui_game_content, fn, params.data()))
            {
                reason = "GetCreationProfileByCharaCode ProcessEvent failed";
                return nullptr;
            }
            auto* result = ret_prop->ContainerPtrToValuePtr<
                RC::Unreal::UObject*>(params.data());
            if (!result || !safe_is_real(*result))
            {
                reason = "GetCreationProfileByCharaCode returned null";
                return nullptr;
            }
            reason = "ok";
            return *result;
        }

        static RC::Unreal::UObject* resolve_creation_profile_for_chara(
            RC::Unreal::UObject* ui_game_content,
            int32_t raw_chara_index,
            int32_t setup_chara_index,
            std::wstring& out_code,
            std::string& out_code_utf8,
            int32_t& out_chara_index,
            int32_t& out_profile_index,
            bool& out_code_ok,
            std::string& reason) noexcept
        {
            out_code.clear();
            out_code_utf8.clear();
            out_chara_index = -1;
            out_profile_index = -1;
            out_code_ok = false;
            reason = "profile candidates exhausted";
            int32_t candidates[] = {
                raw_chara_index,
                setup_chara_index,
                raw_chara_index + 1,
            };
            int32_t seen[3] = {-1, -1, -1};
            int32_t seen_count = 0;
            for (int32_t candidate : candidates)
            {
                if (candidate < 0 || candidate > 0xfe) continue;
                bool duplicate = false;
                for (int32_t i = 0; i < seen_count; ++i)
                {
                    if (seen[i] == candidate)
                    {
                        duplicate = true;
                        break;
                    }
                }
                if (duplicate) continue;
                seen[seen_count++] = candidate;

                std::wstring code;
                std::string code_utf8;
                std::string code_reason;
                if (!call_chara_code_by_index(ui_game_content, candidate,
                                              code, code_utf8, code_reason))
                {
                    reason = code_reason;
                    continue;
                }
                if (!out_code_ok)
                {
                    out_code = code;
                    out_code_utf8 = code_utf8;
                    out_chara_index = candidate;
                    out_code_ok = true;
                }
                for (int32_t profile_index = 0; profile_index < 8;
                     ++profile_index)
                {
                    std::string profile_reason;
                    RC::Unreal::UObject* profile =
                        call_creation_profile_by_chara_code(
                            ui_game_content, code, profile_index,
                            profile_reason);
                    if (safe_is_real(profile))
                    {
                        out_code = code;
                        out_code_utf8 = code_utf8;
                        out_chara_index = candidate;
                        out_profile_index = profile_index;
                        reason = "ok";
                        return profile;
                    }
                    reason = std::string("profile lookup failed for ") +
                        code_utf8 + "[" +
                        std::to_string(profile_index) + "]: " +
                        profile_reason;
                }
            }
            return nullptr;
        }

        bool resolve_direct_stage_natives() noexcept
        {
            if (m_lux_character_to_battle_setup_index &&
                m_set_active_stage_map_path_by_hex_stage_number &&
                m_handle_world_context_url_browse &&
                m_get_world_context_travel_blocked_flag &&
                m_construct_class_lux_battle_manager &&
                m_spawn_portable_battle_manager &&
                m_battle_manager_begin_play_spawn_pipeline &&
                m_get_active_battle_manager &&
                m_get_battle_manager_move_provider &&
                m_get_gameflow_move_provider &&
                m_lookup_stage_asset_path_name_by_packed_stage_id &&
                m_move_construct_battle_async_request_entry &&
                m_create_battle_player_setup_from_profile &&
                m_fmemory_free)
            {
                return true;
            }
            const uintptr_t base = NativeBinding::imageBase();
            if (!base) return false;
            m_lux_character_to_battle_setup_index =
                reinterpret_cast<LuxCharacterToBattleSetupIndexFn>(
                    base + kRVA_LuxCharacterToBattleSetupIndex);
            m_set_active_stage_map_path_by_hex_stage_number =
                reinterpret_cast<SetActiveStageMapPathByHexStageNumberFn>(
                    base + kRVA_SetActiveStageMapPathByHexStageNumber);
            m_handle_world_context_url_browse =
                reinterpret_cast<HandleWorldContextUrlBrowseFn>(
                    base + kRVA_HandleWorldContextUrlBrowse);
            m_get_world_context_travel_blocked_flag =
                reinterpret_cast<GetWorldContextTravelBlockedFlagFn>(
                    base + kRVA_GetWorldContextTravelBlockedFlag);
            m_construct_class_lux_battle_manager =
                reinterpret_cast<ConstructClass_ALuxBattleManagerFn>(
                    base + kRVA_ConstructClass_ALuxBattleManager);
            m_spawn_portable_battle_manager =
                reinterpret_cast<SpawnPortableBattleManagerFn>(
                    base + kRVA_SpawnPortableBattleManager);
            m_battle_manager_begin_play_spawn_pipeline =
                reinterpret_cast<BattleManagerBeginPlaySpawnPipelineFn>(
                    base + kRVA_ALuxBattleManagerBeginPlaySpawnPipeline);
            m_get_active_battle_manager =
                reinterpret_cast<GetActiveBattleManagerFn>(
                    base + kRVA_GetActiveBattleManager);
            m_get_battle_manager_move_provider =
                reinterpret_cast<GetBattleManagerMoveProviderFn>(
                    base + kRVA_GetBattleManagerMoveProvider);
            m_get_gameflow_move_provider =
                reinterpret_cast<GetGameFlowMoveProviderFn>(
                    base + kRVA_GetGameFlowMoveProvider);
            m_lookup_stage_asset_path_name_by_packed_stage_id =
                reinterpret_cast<LookupStageAssetPathNameByPackedStageIdFn>(
                    base + kRVA_LookupLuxStageAssetPathNameByPackedStageId);
            m_move_construct_battle_async_request_entry =
                reinterpret_cast<MoveConstructBattleAsyncRequestEntryFn>(
                    base + kRVA_MoveConstructBattleAsyncRequestEntry);
            m_create_battle_player_setup_from_profile =
                reinterpret_cast<CreateBattlePlayerSetupFromProfileFn>(
                    base + kRVA_CreateBattlePlayerSetupFromProfile);
            m_fmemory_free =
                reinterpret_cast<FMemoryFreeFn>(base + kRVA_FMemoryFree);
            return m_lux_character_to_battle_setup_index != nullptr &&
                   m_set_active_stage_map_path_by_hex_stage_number != nullptr &&
                   m_handle_world_context_url_browse != nullptr &&
                   m_get_world_context_travel_blocked_flag != nullptr &&
                   m_construct_class_lux_battle_manager != nullptr &&
                   m_spawn_portable_battle_manager != nullptr &&
                   m_battle_manager_begin_play_spawn_pipeline != nullptr &&
                   m_get_active_battle_manager != nullptr &&
                   m_get_battle_manager_move_provider != nullptr &&
                   m_get_gameflow_move_provider != nullptr &&
                   m_lookup_stage_asset_path_name_by_packed_stage_id !=
                       nullptr &&
                   m_move_construct_battle_async_request_entry != nullptr &&
                   m_create_battle_player_setup_from_profile != nullptr &&
                   m_fmemory_free != nullptr;
        }

