        static void* safe_get_battle_manager_move_provider(
            GetBattleManagerMoveProviderFn fn,
            void* battle_manager) noexcept
        {
            if (!fn || !battle_manager) return nullptr;
            __try
            {
                return fn(battle_manager);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return nullptr;
            }
        }

