        static uintptr_t direct_stage_callback_rva(void* callback_raw) noexcept
        {
            const uintptr_t base = NativeBinding::imageBase();
            const uintptr_t callback =
                reinterpret_cast<uintptr_t>(callback_raw);
            if (!base || callback < base) return 0;
            return callback - base;
        }

        static const char* direct_stage_callback_name(
            void* callback_raw) noexcept
        {
            switch (direct_stage_callback_rva(callback_raw))
            {
            case kRVA_HandleFinishLoadBattleAssetEvent:
                return "HandleFinishLoadBattleAssetEvent";
            case kRVA_HandleDeferredStageMapPathOpen:
                return "HandleDeferredStageMapPathOpen";
            default:
                return "unknown";
            }
        }

        static bool safe_get_game_instance_world_context(
            RC::Unreal::UObject* gi,
            void*& out) noexcept
        {
            out = nullptr;
            if (!gi) return false;
            void* vtable = nullptr;
            void* fn_raw = nullptr;
            if (!SafeReadPtr(gi, &vtable) || !vtable ||
                !SafeReadPtr(static_cast<uint8_t*>(vtable) +
                                 kGameInstanceWorldContextVfuncOff,
                             &fn_raw) ||
                !fn_raw)
            {
                return false;
            }
            auto* fn = reinterpret_cast<GameInstanceWorldContextFn>(fn_raw);
            __try
            {
                out = fn(gi);
                return out != nullptr;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                out = nullptr;
                return false;
            }
        }

        static bool safe_read_raw_fstring_header(
            const void* p,
            RawFStringNative& out) noexcept
        {
            out = {};
            return p && SafeReadBytes(p, &out, sizeof(out));
        }

        static bool safe_read_wchar_at(const wchar_t* p,
                                       int32_t index,
                                       wchar_t& out) noexcept
        {
            out = L'\0';
            if (!p || index < 0) return false;
            __try
            {
                out = p[index];
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                out = L'\0';
                return false;
            }
        }

        static std::string narrow_wide_utf8(const std::wstring& wide)
        {
            if (wide.empty()) return {};
            const int need = WideCharToMultiByte(
                CP_UTF8, 0, wide.c_str(), static_cast<int>(wide.size()),
                nullptr, 0, nullptr, nullptr);
            if (need <= 0) return {};
            std::string out(static_cast<size_t>(need), '\0');
            WideCharToMultiByte(CP_UTF8, 0, wide.c_str(),
                                static_cast<int>(wide.size()), out.data(),
                                need, nullptr, nullptr);
            return out;
        }

        static bool safe_sample_raw_fstring(
            const RawFStringNative& s,
            int32_t max_chars,
            std::string& sample,
            uint64_t& hash) noexcept
        {
            sample.clear();
            hash = 0;
            if (!s.data || s.num <= 0 || s.max < s.num ||
                s.num > max_chars)
            {
                return false;
            }

            std::wstring wide;
            wide.reserve(static_cast<size_t>(s.num));
            uint64_t h = 1469598103934665603ull;
            for (int32_t i = 0; i < s.num && i < max_chars; ++i)
            {
                wchar_t ch = L'\0';
                if (!safe_read_wchar_at(s.data, i, ch))
                    return false;
                if (ch == L'\0')
                    break;
                wide.push_back(ch);
                const uint16_t code = static_cast<uint16_t>(ch);
                const uint8_t lo = static_cast<uint8_t>(code & 0xffu);
                const uint8_t hi = static_cast<uint8_t>(code >> 8);
                h ^= lo;
                h *= 1099511628211ull;
                h ^= hi;
                h *= 1099511628211ull;
            }
            sample = narrow_wide_utf8(wide);
            hash = wide.empty() ? 0 : h;
            return !wide.empty();
        }

        void sample_direct_stage_travel_context(
            RC::Unreal::UObject* gi) noexcept
        {
            m_direct_stage_travel_probe = {};
            void* world_context = nullptr;
            if (!safe_get_game_instance_world_context(gi, world_context))
            {
                m_direct_stage_travel_probe.failure =
                    "world context unavailable";
                return;
            }

            DirectStageTravelProbe p {};
            p.world_context = reinterpret_cast<uintptr_t>(world_context);
            p.world_context_ok = true;
            auto* bytes = static_cast<uint8_t*>(world_context);
            void* game_viewport = nullptr;
            p.game_viewport_read_ok =
                SafeReadPtr(bytes + kWorldContextGameViewportOff,
                            &game_viewport);
            p.game_viewport = reinterpret_cast<uintptr_t>(game_viewport);
            p.travel_type_read_ok =
                SafeReadInt32(bytes + kWorldContextPendingTravelTypeOff,
                              &p.pending_travel_type);
            RawFStringNative travel_url {};
            p.travel_url_header_ok =
                safe_read_raw_fstring_header(
                    bytes + kWorldContextTravelUrlOff, travel_url);
            p.travel_url_data =
                reinterpret_cast<uintptr_t>(travel_url.data);
            p.travel_url_len = travel_url.num;
            p.travel_url_capacity = travel_url.max;
            p.travel_url_text_ok =
                safe_sample_raw_fstring(travel_url, 512,
                                        p.travel_url_sample,
                                        p.travel_url_hash);
            p.last_failure_read_ok =
                SafeReadInt32(bytes + kWorldContextLastTravelFailureOff,
                              &p.last_travel_failure_code);

            if (!p.game_viewport_read_ok)
                p.failure = "game viewport unreadable";
            else if (!p.travel_type_read_ok)
                p.failure = "pending travel type unreadable";
            else if (!p.travel_url_header_ok)
                p.failure = "TravelURL header unreadable";
            else if (p.travel_url_len <= 0)
                p.failure = "TravelURL empty";
            else if (!p.travel_url_text_ok)
                p.failure = "TravelURL text unreadable";
            else
                p.failure = "ok";
            m_direct_stage_travel_probe = std::move(p);
        }

