        static void* safe_read_gengine() noexcept
        {
            const uintptr_t base = NativeBinding::imageBase();
            if (!base) return nullptr;
            void* engine = nullptr;
            if (!SafeReadPtr(reinterpret_cast<const void*>(
                                 base + ReplayScrubDiag::kRVA_GEngine),
                             &engine))
                return nullptr;
            return engine;
        }

