        void sample_direct_stage_travel_handler() noexcept
        {
            m_direct_stage_travel_handler_probe = {};
            if (!resolve_direct_stage_natives())
            {
                m_direct_stage_travel_handler_probe.failure =
                    "direct stage native helpers unresolved";
                return;
            }
            void* world_context =
                reinterpret_cast<void*>(
                    m_direct_stage_travel_probe.world_context);
            void* engine = safe_read_gengine();
            void* handler = safe_get_world_context_travel_handler(
                m_get_world_context_travel_blocked_flag,
                engine,
                world_context);
            if (!handler)
            {
                m_direct_stage_travel_handler_probe.failure =
                    "travel handler unavailable";
                return;
            }

            DirectStageTravelHandlerProbe p {};
            p.handler = reinterpret_cast<uintptr_t>(handler);
            p.handler_ok = true;
            auto* bytes = static_cast<uint8_t*>(handler);
            uint8_t active = 0;
            uint8_t same_package = 0;
            p.active_read_ok =
                SafeReadUInt8(bytes + kTravelHandlerActiveOff, &active);
            p.same_package_read_ok =
                SafeReadUInt8(bytes + kTravelHandlerSamePackageOff,
                              &same_package);
            p.active = p.active_read_ok && active != 0;
            p.same_package =
                p.same_package_read_ok && same_package != 0;

            RawFStringNative map_name {};
            p.map_name_header_ok =
                safe_read_raw_fstring_header(
                    bytes + kTravelHandlerMapNameOff,
                    map_name);
            p.map_name_data =
                reinterpret_cast<uintptr_t>(map_name.data);
            p.map_name_len = map_name.num;
            p.map_name_capacity = map_name.max;
            p.map_name_text_ok =
                safe_sample_raw_fstring(map_name, 512,
                                        p.map_name_sample,
                                        p.map_name_hash);

            GuidNative guid {};
            p.guid_read_ok =
                SafeReadBytes(bytes + kTravelHandlerPackageGuidOff,
                              &guid, sizeof(guid));
            if (p.guid_read_ok)
            {
                p.package_guid_a = guid.a;
                p.package_guid_b = guid.b;
                p.package_guid_c = guid.c;
                p.package_guid_d = guid.d;
            }

            void* handler_world = nullptr;
            void* loaded_package = nullptr;
            void* loaded_world = nullptr;
            p.pointers_read_ok =
                SafeReadPtr(bytes + kTravelHandlerWorldContextOff,
                            &handler_world) &&
                SafeReadPtr(bytes + kTravelHandlerLoadedPackageOff,
                            &loaded_package) &&
                SafeReadPtr(bytes + kTravelHandlerLoadedWorldOff,
                            &loaded_world);
            p.world_context =
                reinterpret_cast<uintptr_t>(handler_world);
            p.loaded_package =
                reinterpret_cast<uintptr_t>(loaded_package);
            p.loaded_world = reinterpret_cast<uintptr_t>(loaded_world);
            if (loaded_world)
            {
                auto* world_bytes =
                    static_cast<uint8_t*>(loaded_world);
                void* persistent_level = nullptr;
                void* levels = nullptr;
                p.loaded_world_header_ok =
                    SafeReadInt32(world_bytes + kUObjectObjectIndexOff,
                                  &p.loaded_world_object_index) &&
                    SafeReadPtr(world_bytes + kUWorldPersistentLevelOff,
                                &persistent_level) &&
                    SafeReadPtr(world_bytes + kUWorldLevelsOff, &levels);
                p.loaded_world_persistent_level =
                    reinterpret_cast<uintptr_t>(persistent_level);
                p.loaded_world_levels =
                    reinterpret_cast<uintptr_t>(levels);
                p.loaded_world_levels_ok =
                    SafeReadInt32(world_bytes + kUWorldLevelsCountOff,
                                  &p.loaded_world_levels_count) &&
                    SafeReadInt32(world_bytes + kUWorldLevelsCapacityOff,
                                  &p.loaded_world_levels_capacity);
                p.loaded_world_type_ok =
                    SafeReadInt32(world_bytes + kUWorldTypeOff,
                                  &p.loaded_world_type);

                RawFStringNative streaming_prefix {};
                p.loaded_world_streaming_prefix_header_ok =
                    safe_read_raw_fstring_header(
                        world_bytes + kUWorldStreamingLevelsPrefixOff,
                        streaming_prefix);
                p.loaded_world_streaming_prefix_data =
                    reinterpret_cast<uintptr_t>(
                        streaming_prefix.data);
                p.loaded_world_streaming_prefix_len =
                    streaming_prefix.num;
                p.loaded_world_streaming_prefix_capacity =
                    streaming_prefix.max;
                p.loaded_world_streaming_prefix_text_ok =
                    safe_sample_raw_fstring(
                        streaming_prefix, 128,
                        p.loaded_world_streaming_prefix_sample,
                        p.loaded_world_streaming_prefix_hash);
            }
            if (loaded_package)
            {
                p.loaded_package_pie_instance_id_ok =
                    SafeReadInt32(static_cast<uint8_t*>(loaded_package) +
                                      kUPackagePieInstanceIdOff,
                                  &p.loaded_package_pie_instance_id);
            }

            if (!p.active_read_ok)
                p.failure = "active flag unreadable";
            else if (!p.map_name_header_ok)
                p.failure = "map name header unreadable";
            else if (p.active && p.map_name_len <= 0)
                p.failure = "active travel handler has empty map";
            else if (p.map_name_len > 0 && !p.map_name_text_ok)
                p.failure = "map name text unreadable";
            else if (!p.guid_read_ok)
                p.failure = "package guid unreadable";
            else if (!p.pointers_read_ok)
                p.failure = "handler pointers unreadable";
            else if (loaded_world && !p.loaded_world_header_ok)
                p.failure = "loaded world header unreadable";
            else if (loaded_world && !p.loaded_world_levels_ok)
                p.failure = "loaded world levels unreadable";
            else if (loaded_world && !p.loaded_world_type_ok)
                p.failure = "loaded world type unreadable";
            else if (loaded_world &&
                     !p.loaded_world_streaming_prefix_header_ok)
                p.failure = "loaded world prefix unreadable";
            else if (loaded_world &&
                     p.loaded_world_streaming_prefix_len > 0 &&
                     !p.loaded_world_streaming_prefix_text_ok)
                p.failure = "loaded world prefix text unreadable";
            else if (loaded_package &&
                     !p.loaded_package_pie_instance_id_ok)
                p.failure = "loaded package pie id unreadable";
            else
                p.failure = "ok";
            m_direct_stage_travel_handler_probe = std::move(p);
        }

