        static uint8_t* safe_get_battle_replay_ptr(
            RC::Unreal::UObject* battle_setup) noexcept
        {
            if (!safe_is_real(battle_setup)) return nullptr;
            __try
            {
                auto* replay =
                    battle_setup->GetValuePtrByPropertyNameInChain<uint8_t>(
                        L"BattleReplay");
                if (replay) return replay;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
            }

            return reinterpret_cast<uint8_t*>(battle_setup) +
                   kLuxBattleSetupBattleReplayOff;
        }

        static uint8_t* safe_get_battle_rule_ptr(
            RC::Unreal::UObject* battle_setup) noexcept
        {
            if (!safe_is_real(battle_setup)) return nullptr;
            __try
            {
                return battle_setup->GetValuePtrByPropertyNameInChain<uint8_t>(
                    L"BattleRule");
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return nullptr;
            }
        }

        static bool safe_write_bool_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property,
            bool value,
            bool& read_ok,
            bool& observed) noexcept
        {
            read_ok = false;
            observed = !value;
            if (!safe_is_real(obj) || !property) return false;
            __try
            {
                bool* slot =
                    obj->GetValuePtrByPropertyNameInChain<bool>(property);
                if (!slot) return false;
                if (!SafeWriteBytes(slot, &value, sizeof(value)))
                    return false;
                read_ok = SafeReadBytes(slot, &observed, sizeof(observed));
                return read_ok && observed == value;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool safe_read_bool_property(
            RC::Unreal::UObject* obj,
            const wchar_t* property,
            bool& observed) noexcept
        {
            observed = false;
            if (!safe_is_real(obj) || !property) return false;
            __try
            {
                bool* slot =
                    obj->GetValuePtrByPropertyNameInChain<bool>(property);
                if (!slot) return false;
                return SafeReadBytes(slot, &observed, sizeof(observed));
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        bool sample_direct_battle_setup_rules(
            RC::Unreal::UObject* battle_setup,
            const char* source) noexcept
        {
            m_direct_stage_battle_rule_source =
                source && source[0] ? source : "unknown";
            m_direct_stage_battle_rule_read_ok = false;
            m_direct_stage_battle_rule_finite = false;
            m_direct_stage_battle_rule_ptr = 0;
            m_direct_stage_battle_rule_lib_version = -1;
            m_direct_stage_battle_rule_time = -1;
            m_direct_stage_battle_rule_type = -1;
            m_direct_stage_battle_setup_endless_read_ok = false;
            m_direct_stage_battle_setup_endless = false;
            m_direct_stage_battle_setup_autostart_read_ok = false;
            m_direct_stage_battle_setup_autostart = false;
            m_direct_stage_battle_setup_local_provider_read_ok = false;
            m_direct_stage_battle_setup_local_provider = false;

            uint8_t* rule = safe_get_battle_rule_ptr(battle_setup);
            m_direct_stage_battle_rule_ptr =
                reinterpret_cast<uintptr_t>(rule);
            bool lib_ok = false;
            bool time_ok = false;
            bool type_ok = false;
            if (rule)
            {
                lib_ok = SafeReadBytes(
                    rule + kLuxBattleRuleParamLibVersionOff,
                    &m_direct_stage_battle_rule_lib_version,
                    sizeof(m_direct_stage_battle_rule_lib_version));
                time_ok = SafeReadBytes(
                    rule + kLuxBattleRuleParamTimeOff,
                    &m_direct_stage_battle_rule_time,
                    sizeof(m_direct_stage_battle_rule_time));
                type_ok = SafeReadBytes(
                    rule + kLuxBattleRuleParamTypeOff,
                    &m_direct_stage_battle_rule_type,
                    sizeof(m_direct_stage_battle_rule_type));
            }

            m_direct_stage_battle_setup_endless_read_ok =
                safe_read_bool_property(
                    battle_setup, L"bEndless",
                    m_direct_stage_battle_setup_endless);
            m_direct_stage_battle_setup_autostart_read_ok =
                safe_read_bool_property(
                    battle_setup, L"bAutoStart",
                    m_direct_stage_battle_setup_autostart);
            m_direct_stage_battle_setup_local_provider_read_ok =
                safe_read_bool_property(
                    battle_setup, L"bLocalBattleProvider",
                    m_direct_stage_battle_setup_local_provider);

            m_direct_stage_battle_rule_read_ok =
                rule && lib_ok && time_ok && type_ok;
            m_direct_stage_battle_rule_finite =
                m_direct_stage_battle_rule_read_ok &&
                m_direct_stage_battle_rule_time > 0 &&
                m_direct_stage_battle_rule_time != -1 &&
                m_direct_stage_battle_rule_type >= 0;
            return m_direct_stage_battle_rule_finite;
        }

        bool patch_direct_battle_setup_online_rules(
            RC::Unreal::UObject* battle_setup) noexcept
        {
            m_direct_stage_rule_patch_attempted = true;
            m_direct_stage_rule_patch_ok = false;
            m_direct_stage_battle_rule_ptr = 0;
            m_direct_stage_battle_rule_read_ok = false;
            m_direct_stage_battle_rule_finite = false;
            m_direct_stage_battle_rule_source = "patched-battle-setup";
            m_direct_stage_battle_rule_lib_version = -1;
            m_direct_stage_battle_rule_time = -1;
            m_direct_stage_battle_rule_type = -1;
            m_direct_stage_battle_setup_endless_read_ok = false;
            m_direct_stage_battle_setup_endless = true;
            m_direct_stage_battle_setup_autostart_read_ok = false;
            m_direct_stage_battle_setup_autostart = false;
            m_direct_stage_battle_setup_local_provider_read_ok = false;
            m_direct_stage_battle_setup_local_provider = false;

            uint8_t* rule = safe_get_battle_rule_ptr(battle_setup);
            m_direct_stage_battle_rule_ptr =
                reinterpret_cast<uintptr_t>(rule);
            const int32_t battle_time = kDirectBattleRuleTimeSeconds;
            const int32_t battle_type = kDirectBattleRuleTypeNormal;
            bool rule_write_ok = false;
            if (rule)
            {
                const bool time_ok = SafeWriteBytes(
                    rule + kLuxBattleRuleParamTimeOff,
                    &battle_time,
                    sizeof(battle_time));
                const bool type_ok = SafeWriteBytes(
                    rule + kLuxBattleRuleParamTypeOff,
                    &battle_type,
                    sizeof(battle_type));
                (void)SafeReadBytes(
                    rule + kLuxBattleRuleParamLibVersionOff,
                    &m_direct_stage_battle_rule_lib_version,
                    sizeof(m_direct_stage_battle_rule_lib_version));
                (void)SafeReadBytes(
                    rule + kLuxBattleRuleParamTimeOff,
                    &m_direct_stage_battle_rule_time,
                    sizeof(m_direct_stage_battle_rule_time));
                (void)SafeReadBytes(
                    rule + kLuxBattleRuleParamTypeOff,
                    &m_direct_stage_battle_rule_type,
                    sizeof(m_direct_stage_battle_rule_type));
                rule_write_ok =
                    time_ok && type_ok &&
                    m_direct_stage_battle_rule_time == battle_time &&
                    m_direct_stage_battle_rule_type == battle_type;
                m_direct_stage_battle_rule_read_ok =
                    m_direct_stage_battle_rule_time == battle_time &&
                    m_direct_stage_battle_rule_type == battle_type;
                m_direct_stage_battle_rule_finite =
                    m_direct_stage_battle_rule_read_ok &&
                    m_direct_stage_battle_rule_time > 0;
            }

            bool endless_ok = safe_write_bool_property(
                battle_setup, L"bEndless", false,
                m_direct_stage_battle_setup_endless_read_ok,
                m_direct_stage_battle_setup_endless);
            bool autostart_ok = safe_write_bool_property(
                battle_setup, L"bAutoStart", true,
                m_direct_stage_battle_setup_autostart_read_ok,
                m_direct_stage_battle_setup_autostart);
            bool provider_ok = safe_write_bool_property(
                battle_setup, L"bLocalBattleProvider", true,
                m_direct_stage_battle_setup_local_provider_read_ok,
                m_direct_stage_battle_setup_local_provider);

            m_direct_stage_rule_patch_ok =
                rule_write_ok && endless_ok && autostart_ok && provider_ok;
            return m_direct_stage_rule_patch_ok;
        }

        static bool safe_set_direct_replay_launch_flags(
            uint8_t* replay) noexcept
        {
            if (!replay) return false;
            __try
            {
                *reinterpret_cast<bool*>(
                    replay + kLuxBattleReplayParamRecordingOff) = false;
                *reinterpret_cast<bool*>(
                    replay + kLuxBattleReplayParamPlayingBackOff) = true;
                *reinterpret_cast<bool*>(
                    replay + kLuxBattleReplayParamIgnoreSetupOff) = false;
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        bool set_direct_replay_launch_path_on_setup(
            RC::Unreal::UObject* battle_setup,
            const char* phase,
            std::string& reason) noexcept
        {
            uint8_t* replay = safe_get_battle_replay_ptr(battle_setup);
            if (!replay)
            {
                reason = "ULuxBattleSetup.BattleReplay unavailable";
                return false;
            }
            if (!safe_set_direct_replay_launch_flags(replay))
            {
                reason = "BattleReplay flag write failed";
                return false;
            }

            const std::wstring launch_path =
                widen_utf8(m_cfg.replay_input_file);
            auto* recording_path =
                reinterpret_cast<RC::Unreal::FString*>(
                    replay + kLuxBattleReplayParamRecordingPathOff);
            auto* playing_path =
                reinterpret_cast<RC::Unreal::FString*>(
                    replay + kLuxBattleReplayParamPlayingBackPathOff);
            RC::Unreal::FString empty_path(L"");
            RC::Unreal::FString path_value(launch_path.c_str());
            *recording_path = empty_path;
            *playing_path = path_value;

            ReplayTraceFields f;
            f.boolean("ok", true)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .string("phase", phase ? phase : "?")
             .hex("battle_setup", reinterpret_cast<uintptr_t>(battle_setup))
             .hex("battle_replay", reinterpret_cast<uintptr_t>(replay))
             .string("launch_path", m_cfg.replay_input_file);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_replay_path_set", f);
            reason = "BattleReplay path set";
            return true;
        }

        bool request_direct_stage_battle_asset(
            RC::Unreal::UObject* gi,
            RC::Unreal::UObject* battle_setup,
            std::string& reason) noexcept
        {
            m_direct_stage_asset_requested = true;
            m_direct_stage_asset_ok = false;
            m_direct_stage_asset_failure = "not-run";

            if (!safe_is_real(gi))
            {
                m_direct_stage_asset_failure =
                    "OwningGameInstance unavailable";
                reason = m_direct_stage_asset_failure;
                return false;
            }

            if (!m_direct_stage_replay_path_set)
            {
                std::string path_reason;
                m_direct_stage_replay_path_set =
                    set_direct_replay_launch_path_on_setup(
                        battle_setup, "before_request_assets", path_reason);
                if (!m_direct_stage_replay_path_set)
                {
                    m_direct_stage_asset_failure = path_reason;
                    reason = m_direct_stage_asset_failure;
                    return false;
                }
            }

            const bool ok = call_no_param_function(gi, L"RequestBattleAsset");
            m_direct_stage_asset_ok = ok;
            if (ok)
            {
                std::string path_reason;
                m_direct_stage_replay_path_after_asset_set =
                    set_direct_replay_launch_path_on_setup(
                        battle_setup, "after_request_assets", path_reason);
                m_direct_stage_asset_failure =
                    m_direct_stage_replay_path_after_asset_set
                        ? "ok"
                        : path_reason;
            }
            else
            {
                m_direct_stage_asset_failure =
                    "RequestBattleAsset failed";
            }

            reason = m_direct_stage_asset_failure;
            ReplayTraceFields f;
            f.boolean("ok", m_direct_stage_asset_ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .hex("game_instance", reinterpret_cast<uintptr_t>(gi))
             .hex("battle_setup", reinterpret_cast<uintptr_t>(battle_setup))
             .boolean("replay_launch_path_set",
                      m_direct_stage_replay_path_set)
             .boolean("replay_launch_path_after_asset_set",
                      m_direct_stage_replay_path_after_asset_set)
             .string("failure", m_direct_stage_asset_failure);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_battle_asset_request", f);
            return m_direct_stage_asset_ok &&
                   m_direct_stage_replay_path_after_asset_set;
        }

        bool service_direct_stage_native_launch(
            RC::Unreal::UObject* gi,
            RC::Unreal::UObject* battle_setup,
            bool battle_context_live,
            std::string& reason) noexcept
        {
            if (battle_context_live)
            {
                reason = "battle context already live";
                return true;
            }
            if (!safe_is_real(gi))
            {
                reason = "OwningGameInstance unavailable";
                return false;
            }
            if (!safe_is_real(battle_setup))
            {
                reason = "ULuxBattleSetup unavailable";
                return false;
            }

            if (!m_direct_stage_portable_setup_attempted)
            {
                if (!initialize_direct_portable_battle(gi, battle_setup))
                {
                    reason = m_direct_stage_portable_setup_failure;
                    return false;
                }
            }
            else if (!m_direct_stage_portable_setup_ok)
            {
                reason = m_direct_stage_portable_setup_failure;
                return false;
            }
            else
            {
                auto* portable = reinterpret_cast<RC::Unreal::UObject*>(
                    m_direct_stage_portable_battle);
                refresh_direct_portable_load_state(portable);
            }

            if (!m_direct_stage_asset_requested ||
                !m_direct_stage_asset_ok ||
                !m_direct_stage_replay_path_after_asset_set)
            {
                if (!request_direct_stage_battle_asset(
                        gi, battle_setup, reason))
                {
                    return false;
                }
            }

            if (m_direct_stage_manual_launch_ok)
            {
                reason = "waiting for direct-stage battle context";
                return true;
            }

            bool pending = false;
            m_direct_stage_pending_query_ok =
                call_bool_query(gi, L"HasAnyBattleRequest", pending);
            m_direct_stage_battle_request_pending =
                m_direct_stage_pending_query_ok && pending;
            if (!m_direct_stage_pending_query_ok)
            {
                reason = "HasAnyBattleRequest unavailable";
                return false;
            }
            if (m_direct_stage_battle_request_pending)
            {
                reason = "HasAnyBattleRequest true";
                return false;
            }

            bool ready = false;
            m_direct_stage_can_launch_query_ok =
                call_bool_query(gi, L"CanLaunchBattleManually", ready);
            m_direct_stage_can_launch_ready =
                m_direct_stage_can_launch_query_ok && ready;
            if (!m_direct_stage_can_launch_query_ok)
            {
                reason = "CanLaunchBattleManually unavailable";
                return false;
            }
            if (!m_direct_stage_can_launch_ready)
            {
                reason = "CanLaunchBattleManually false";
                return false;
            }

            const bool first_manual_launch_request =
                !m_direct_stage_manual_launch_requested;
            if (!m_direct_stage_manual_launch_requested)
            {
                m_direct_stage_manual_launch_requested = true;
                m_direct_stage_manual_launch_ok =
                    call_no_param_function(gi, L"ManualLaunchBattle");
                m_direct_stage_manual_launch_failure =
                    m_direct_stage_manual_launch_ok
                        ? "ok"
                        : "ManualLaunchBattle failed";
            }

            reason = m_direct_stage_manual_launch_failure;
            if (first_manual_launch_request ||
                !m_direct_stage_manual_launch_ok)
            {
                ReplayTraceFields f;
                f.boolean("ok", m_direct_stage_manual_launch_ok)
                 .string("request_id", m_cfg.request_id)
                 .string("client_role", m_cfg.client_role)
                 .hex("game_instance", reinterpret_cast<uintptr_t>(gi))
                 .hex("battle_setup", reinterpret_cast<uintptr_t>(battle_setup))
                 .boolean("portable_setup_ok",
                          m_direct_stage_portable_setup_ok)
                 .boolean("battle_asset_requested",
                          m_direct_stage_asset_requested)
                 .boolean("battle_asset_request_ok",
                          m_direct_stage_asset_ok)
                 .string("battle_asset_failure",
                         m_direct_stage_asset_failure)
                 .boolean("has_battle_request_query_ok",
                          m_direct_stage_pending_query_ok)
                 .boolean("has_battle_request_pending",
                          m_direct_stage_battle_request_pending)
                 .boolean("can_launch_query_ok",
                          m_direct_stage_can_launch_query_ok)
                 .boolean("can_launch_ready",
                          m_direct_stage_can_launch_ready)
                 .boolean("manual_launch_requested",
                          m_direct_stage_manual_launch_requested)
                 .string("failure",
                         m_direct_stage_manual_launch_failure);
                ReplayDebugTrace::instance().event(
                    "rollback_direct_stage_native_launch", f);
            }
            return m_direct_stage_manual_launch_ok;
        }

        bool service_direct_stage_portable_spawn(
            RC::Unreal::UObject* gi,
            RC::Unreal::UObject* battle_setup,
            std::string& reason) noexcept
        {
            if (!safe_is_real(gi))
            {
                reason = "OwningGameInstance unavailable";
                return false;
            }
            if (!safe_is_real(battle_setup))
            {
                reason = "ULuxBattleSetup unavailable";
                return false;
            }

            if (!m_direct_stage_portable_setup_attempted)
            {
                if (!initialize_direct_portable_battle(gi, battle_setup))
                {
                    reason = m_direct_stage_portable_setup_failure;
                    return false;
                }
            }
            else if (!m_direct_stage_portable_setup_ok)
            {
                reason = m_direct_stage_portable_setup_failure;
                return false;
            }

            auto* portable = reinterpret_cast<RC::Unreal::UObject*>(
                m_direct_stage_portable_battle);
            if (!safe_is_real(portable))
            {
                reason = "PortableBattle unavailable";
                return false;
            }

            refresh_direct_portable_load_state(portable);
            (void)sample_direct_stage_portable_state(portable, battle_setup);
            const uint32_t required_mask = direct_stage_required_setup_mask();
            const bool load_queries_ok =
                (m_direct_stage_portable_has_loaded_query_mask &
                 required_mask) == required_mask;
            const bool loads_ready =
                (m_direct_stage_portable_has_loaded_mask & required_mask) ==
                required_mask;
            if (!load_queries_ok || !loads_ready)
            {
                reason = "waiting for PortableBattle loads";
                return false;
            }

            if (!m_direct_stage_spawn_battle_manager_requested)
            {
                if (!spawn_direct_stage_battle_manager(portable, battle_setup))
                {
                    reason = m_direct_stage_spawn_battle_manager_failure;
                    return false;
                }
            }
            else if (!m_direct_stage_spawn_battle_manager_ok)
            {
                reason = m_direct_stage_spawn_battle_manager_failure;
                return false;
            }

            reason = "SpawnBattleManager submitted";
            return true;
        }

        static bool call_quick_battle_request(RC::Unreal::UObject* gi,
                                              uint8_t left,
                                              uint8_t right,
                                              int32_t stage) noexcept
        {
            if (!safe_is_real(gi)) return false;
            auto* fn = gi->GetFunctionByNameInChain(L"QuickBattleRequest");
            if (!fn) return false;
            struct Params
            {
                uint8_t InLeft {0};
                uint8_t InRight {0};
                uint8_t Pad[2] {};
                int32_t InStage {0};
            } params {};
            static_assert(sizeof(Params) == 8,
                          "QuickBattleRequest params layout changed");
            params.InLeft = left;
            params.InRight = right;
            params.InStage = stage;
            return safe_process_event(gi, fn, &params);
        }

        static bool safe_native_battle_launcher_start(
            uintptr_t start_addr,
            void* battle_launcher,
            void* start_param) noexcept
        {
            if (!start_addr || !battle_launcher || !start_param)
                return false;
            using StartFn = void(__fastcall*)(void*, void*);
            auto* fn = reinterpret_cast<StartFn>(start_addr);
            __try
            {
                fn(battle_launcher, start_param);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        bool call_direct_battle_launcher_start(
            RC::Unreal::UObject* battle_launcher,
            RC::Unreal::UObject* completion_target) noexcept
        {
            m_direct_stage_launcher_start_requested = true;
            m_direct_stage_launcher_start_ok = false;
            m_direct_stage_launcher_start_via_scene_request = false;
            m_direct_stage_launcher_start_failure = "not-run";

            UIBattleLauncherStartParamNative params {};
            const wchar_t* completion_function_wide = nullptr;
            const char* completion_function = "";
            RC::Unreal::UFunction* completion_ufunction = nullptr;
            bool setup_hook_ok = true;
            bool delegate_bound = false;
            bool delegate_object_bound = false;
            bool delegate_name_bound = false;
            bool delegate_chain_roundtrip = false;
            if (safe_is_real(completion_target))
            {
                if (completion_target->GetFunctionByNameInChain(
                        L"OnSetupBattleLauncher"))
                {
                    setup_hook_ok = call_no_param_function(
                        completion_target, L"OnSetupBattleLauncher");
                }
                // LoadedBattleResource is implemented by the Blueprint base
                // BattleSetupScene_C while the live object is the derived
                // VersusBattleSetupScene_C.  Search the full class chain so
                // the native launcher completion delegate matches the stock
                // Blueprint binding.
                completion_ufunction =
                    completion_target->GetFunctionByNameInChain(
                        L"LoadedBattleResource");
                if (completion_ufunction)
                {
                    completion_function_wide = L"LoadedBattleResource";
                    completion_function = "LoadedBattleResource";
                }
            }
            if (completion_function_wide && completion_ufunction)
            {
                // UE4SS FScriptDelegate::IsBound() re-resolves with
                // GetFunctionByName(), which excludes inherited functions.
                // LoadedBattleResource lives on BattleSetupScene_C while the
                // live object is VersusBattleSetupScene_C, so validate the
                // stored weak object/name with the same chain-aware lookup
                // used to discover the callback instead of accepting that
                // false negative.
                params.OnUIBattleLauncherStartCompleted.BindUFunction(
                    completion_target,
                    completion_ufunction->GetFName());
                delegate_object_bound =
                    params.OnUIBattleLauncherStartCompleted.Object.
                            ObjectIndex >= 0
                    && params.OnUIBattleLauncherStartCompleted.Object.
                            ObjectSerialNumber > 0;
                const RC::Unreal::FName bound_name =
                    params.OnUIBattleLauncherStartCompleted.
                        GetFunctionName();
                delegate_name_bound =
                    bound_name != RC::Unreal::NAME_None;
                delegate_chain_roundtrip = delegate_name_bound
                    && completion_target->GetFunctionByNameInChain(
                           bound_name) == completion_ufunction;
                delegate_bound = delegate_object_bound
                    && delegate_name_bound
                    && delegate_chain_roundtrip;
            }
            m_direct_stage_launcher_start_param_object_index =
                params.OnUIBattleLauncherStartCompleted.Object.ObjectIndex;
            m_direct_stage_launcher_start_param_object_serial =
                params.OnUIBattleLauncherStartCompleted.Object.
                    ObjectSerialNumber;
            m_direct_stage_launcher_start_param_function =
                delegate_bound ? completion_function : "";

            const uintptr_t start_addr =
                NativeBinding::launcherStartAddress();
            bool ok = false;
            if (!safe_is_real(battle_launcher))
            {
                m_direct_stage_launcher_start_failure =
                    "BattleLauncher unavailable";
            }
            else if (!start_addr)
            {
                m_direct_stage_launcher_start_failure =
                    "ULuxUIBattleLauncher.Start unresolved";
            }
            else if (!setup_hook_ok)
            {
                m_direct_stage_launcher_start_failure =
                    "BattleSetupScene.OnSetupBattleLauncher failed";
            }
            else if (!delegate_bound)
            {
                m_direct_stage_launcher_start_failure =
                    "BattleSetup launcher completion delegate unavailable";
            }
            else
            {
                ok = safe_native_battle_launcher_start(
                    start_addr, battle_launcher, &params);
                m_direct_stage_launcher_start_failure =
                    ok ? "ok"
                       : "ULuxUIBattleLauncher.Start exception";
            }
            m_direct_stage_launcher_start_ok = ok;

            const RollbackP2PUObjectIdentity launcher_info =
                describe_uobject(battle_launcher);
            const RollbackP2PUObjectIdentity completion_info =
                describe_uobject(completion_target);
            if (safe_is_real(completion_target))
                emit_scene_reflection_once(completion_target);
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .hex("battle_launcher",
                  reinterpret_cast<uintptr_t>(battle_launcher))
             .hex("completion_target",
                  reinterpret_cast<uintptr_t>(completion_target))
             .hex("start_fn", start_addr)
             .boolean("setup_hook_ok", setup_hook_ok)
             .boolean("start_param_chain_resolved",
                      completion_ufunction != nullptr)
             .boolean("start_param_object_bound",
                      delegate_object_bound)
             .boolean("start_param_name_bound", delegate_name_bound)
             .boolean("start_param_chain_roundtrip",
                      delegate_chain_roundtrip)
             .boolean("start_param_bound", delegate_bound)
             .integer("start_param_object_index",
                      params.OnUIBattleLauncherStartCompleted.Object.
                          ObjectIndex)
             .integer("start_param_object_serial",
                      params.OnUIBattleLauncherStartCompleted.Object.
                          ObjectSerialNumber)
             .string("start_param_function",
                     m_direct_stage_launcher_start_param_function)
             .string("failure",
                     m_direct_stage_launcher_start_failure);
            add_uobject_identity_fields(f, "battle_launcher",
                                        launcher_info);
            add_uobject_identity_fields(f, "completion_target",
                                        completion_info);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_battle_launcher_start", f);
            return ok;
        }

        bool call_stock_battle_setup_versus_info(
            RC::Unreal::UObject* setup_scene,
            RC::Unreal::UObject* battle_launcher) noexcept
        {
            m_mirrored_stock_phase_requested = true;
            m_mirrored_stock_phase_ok = false;
            m_mirrored_stock_scene_selection_ok = false;
            m_mirrored_stock_phase_failure = "not-run";
            bool ok = false;
            if (!safe_is_real(setup_scene))
            {
                m_mirrored_stock_phase_failure =
                    "BattleSetup scene unavailable";
            }
            else
            {
                emit_scene_reflection_once(setup_scene);
                const std::wstring left_code = widen_utf8(
                    m_direct_stage_left_chara_code);
                const std::wstring right_code = widen_utf8(
                    m_direct_stage_right_chara_code);
                wchar_t stage_code[8] {};
                const int32_t selected_stage =
                    m_direct_stage_stage_lookup_selected >= 0
                        ? m_direct_stage_stage_lookup_selected
                        : m_direct_setup_stage_index;
                _snwprintf_s(stage_code, _countof(stage_code), _TRUNCATE,
                             L"%03X", selected_stage & 0xfff);

                // The direct battle-setup patch updates the native setup
                // object.  OnStartVersusInfo consumes the Blueprint scene's
                // semantic selection fields, so mirror the synchronized
                // descriptor there before entering the stock phase machine.
                const bool left_decide_ok = safe_set_fstring_property(
                    setup_scene, L"DecideCharaCode_L", left_code.c_str());
                const bool right_decide_ok = safe_set_fstring_property(
                    setup_scene, L"DecideCharaCode_R", right_code.c_str());
                const bool left_decided_ok = safe_set_fstring_property(
                    setup_scene, L"DecidedCharaCode_L", left_code.c_str());
                const bool right_decided_ok = safe_set_fstring_property(
                    setup_scene, L"DecidedCharaCode_R", right_code.c_str());
                const bool stage_ok = safe_set_fstring_property(
                    setup_scene, L"DecidedStageCode", stage_code);
                const bool left_color_ok = safe_set_int32_property(
                    setup_scene, L"DecidedCharaColor_L", 0);
                const bool right_color_ok = safe_set_int32_property(
                    setup_scene, L"DecidedCharaColor_R", 0);
                m_mirrored_stock_scene_selection_ok =
                    left_decide_ok && right_decide_ok &&
                    left_decided_ok && right_decided_ok && stage_ok &&
                    left_color_ok && right_color_ok;

                std::string phase_reason;
                ok = m_mirrored_stock_scene_selection_ok &&
                    call_fname_param_function(
                        setup_scene, L"ChangePhase", L"inPhaseName",
                        L"VersusInfoInit", phase_reason);
                m_mirrored_stock_phase_failure = ok
                    ? "ok"
                    : !m_mirrored_stock_scene_selection_ok
                        ? "BattleSetup scene selection patch failed"
                        : phase_reason;
            }
            m_mirrored_stock_phase_ok = ok;

            const RollbackP2PUObjectIdentity setup_info =
                describe_uobject(setup_scene);
            const RollbackP2PUObjectIdentity launcher_info =
                describe_uobject(battle_launcher);
            const RollbackP2PUObjectIdentity phase_info =
                describe_uobject(reflected_object_property(
                    setup_scene, L"CurrentPhase"));
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .hex("setup_scene",
                  reinterpret_cast<uintptr_t>(setup_scene))
             .hex("battle_launcher",
                  reinterpret_cast<uintptr_t>(battle_launcher))
             .string("submit_function", "ChangePhase")
             .string("requested_phase", "VersusInfoInit")
             .boolean("scene_selection_ok",
                      m_mirrored_stock_scene_selection_ok)
             .string("left_chara_code",
                     m_direct_stage_left_chara_code)
             .string("right_chara_code",
                     m_direct_stage_right_chara_code)
             .integer("stage",
                      m_direct_stage_stage_lookup_selected)
             .string("failure", m_mirrored_stock_phase_failure);
            add_uobject_identity_fields(f, "setup_scene", setup_info);
            add_uobject_identity_fields(f, "battle_launcher",
                                        launcher_info);
            add_uobject_identity_fields(f, "current_phase", phase_info);
            ReplayDebugTrace::instance().event(
                "rollback_stock_battle_setup_versus_info", f);
            return ok;
        }

        static bool resolve_active_game_instance(
            RC::Unreal::UObject*& out,
            std::string& reason) noexcept
        {
            out = nullptr;
            void* engine_raw = nullptr;
            if (!ReplayScrubDiag::read_gengine_ptr(&engine_raw))
            {
                reason = "GEngine unavailable";
                return false;
            }

            void* viewport_raw = nullptr;
            if (!SafeReadPtr(static_cast<uint8_t*>(engine_raw) +
                                 ReplayScrubDiag::kUEngine_GameViewport_Off,
                             &viewport_raw) || !viewport_raw)
            {
                reason = "GameViewport unavailable";
                return false;
            }

            void* world_raw = nullptr;
            if (!ReplayScrubDiag::safe_get_world_vfunc_138(viewport_raw,
                                                           &world_raw) &&
                !ReplayScrubDiag::safe_get_world(
                    reinterpret_cast<RC::Unreal::UObject*>(viewport_raw),
                    &world_raw))
            {
                reason = "UWorld unavailable";
                return false;
            }

            __try
            {
                auto* world_obj =
                    reinterpret_cast<RC::Unreal::UObject*>(world_raw);
                auto** gi = world_obj
                    ? world_obj->GetValuePtrByPropertyNameInChain<
                          RC::Unreal::UObject*>(L"OwningGameInstance")
                    : nullptr;
                if (gi && *gi)
                {
                    out = *gi;
                    return true;
                }
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
            }

            reason = "OwningGameInstance unavailable";
            return false;
        }

        static RC::Unreal::UObject* call_static_uobject_return(
            const wchar_t* object_path,
            const wchar_t* function_name) noexcept
        {
            if (!object_path || !function_name) return nullptr;
            auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                RC::Unreal::UObject*>(nullptr, nullptr, object_path);
            if (!safe_is_real(cdo)) return nullptr;
            auto* fn = cdo->GetFunctionByNameInChain(function_name);
            if (!fn) return nullptr;
            struct Params
            {
                RC::Unreal::UObject* ReturnValue {nullptr};
            } params{};
            if (!safe_process_event(cdo, fn, &params)) return nullptr;
            return safe_is_real(params.ReturnValue) ? params.ReturnValue
                                                    : nullptr;
        }

        static RC::Unreal::UObject* resolve_umg_util_via_library() noexcept
        {
            return call_static_uobject_return(
                L"/Script/UMGUtil.Default__UMGUtilLibrary",
                L"GetUMGUtil");
        }

        static RC::Unreal::UObject*
        resolve_gameflow_manager_via_library() noexcept
        {
            return call_static_uobject_return(
                L"/Script/UMGUtil.Default__UMGUtilLibrary",
                L"GameFlowManager");
        }

        static bool object_is_uclass(RC::Unreal::UObject* obj) noexcept
        {
            if (!safe_is_real(obj)) return false;
            const RollbackP2PUObjectIdentity info = describe_uobject(obj);
            return info.class_name.find("Class") != std::string::npos;
        }

        static RC::Unreal::UClass* uclass_from_object(
            RC::Unreal::UObject* obj) noexcept
        {
            return object_is_uclass(obj)
                ? reinterpret_cast<RC::Unreal::UClass*>(obj)
                : nullptr;
        }

        static RC::Unreal::UClass* resolve_bp_ui_automation_class(
            std::string& source) noexcept
        {
            source.clear();
            RC::Unreal::UClass* klass = nullptr;
            try
            {
                klass = RC::Unreal::UObjectGlobals::StaticFindObject<
                    RC::Unreal::UClass*>(
                        nullptr, nullptr,
                        STR("/Game/UI/GameFlow/BP_UIAutomation.BP_UIAutomation_C"));
            }
            catch (...)
            {
                klass = nullptr;
            }
            if (safe_is_real(static_cast<RC::Unreal::UObject*>(klass)))
            {
                source = "bp-class-static-path";
                return klass;
            }

            RC::Unreal::UObject* class_obj = nullptr;
            try
            {
                class_obj = RC::Unreal::UObjectGlobals::FindFirstOf(
                    L"BP_UIAutomation_C");
            }
            catch (...)
            {
                class_obj = nullptr;
            }
            klass = uclass_from_object(class_obj);
            if (safe_is_real(static_cast<RC::Unreal::UObject*>(klass)))
            {
                source = "bp-class-findfirst";
                return klass;
            }

            try
            {
                class_obj = RC::Unreal::UObjectGlobals::FindFirstOf(
                    L"UIGameFlowAutomation");
            }
            catch (...)
            {
                class_obj = nullptr;
            }
            klass = uclass_from_object(class_obj);
            if (safe_is_real(static_cast<RC::Unreal::UObject*>(klass)))
            {
                source = "native-class-findfirst";
                return klass;
            }

            source = "class-unavailable";
            return nullptr;
        }

        static RC::Unreal::UObject* resolve_bp_ui_automation_cdo(
            std::string& source) noexcept
        {
            source.clear();
            RC::Unreal::UObject* cdo = nullptr;
            try
            {
                cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                    RC::Unreal::UObject*>(
                        nullptr, nullptr,
                        STR("/Game/UI/GameFlow/BP_UIAutomation.Default__BP_UIAutomation_C"));
            }
            catch (...)
            {
                cdo = nullptr;
            }
            if (safe_is_real(cdo))
            {
                source = "bp-cdo-static-path";
                return cdo;
            }

            try
            {
                cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                    RC::Unreal::UObject*>(
                        nullptr, nullptr,
                        STR("/Script/UMGUtil.Default__UIGameFlowAutomation"));
            }
            catch (...)
            {
                cdo = nullptr;
            }
            if (safe_is_real(cdo))
            {
                source = "native-cdo-static-path";
                return cdo;
            }

            source = "cdo-unavailable";
            return nullptr;
        }

        static RC::Unreal::UObject* resolve_or_create_gameflow_automation(
            RC::Unreal::UObject* outer,
            std::string& source) noexcept
        {
            (void)outer;
            source.clear();
            for (const wchar_t* name :
                 {L"BP_UIAutomation_C", L"UIGameFlowAutomation"})
            {
                RC::Unreal::UObject* obj = nullptr;
                try
                {
                    obj = RC::Unreal::UObjectGlobals::FindFirstOf(name);
                }
                catch (...)
                {
                    obj = nullptr;
                }
                if (safe_is_real(obj) && !object_is_uclass(obj))
                {
                    source = std::string("instance-findfirst:") +
                             (name && name[0] == L'B'
                                  ? "BP_UIAutomation_C"
                                  : "UIGameFlowAutomation");
                    return obj;
                }
            }

            std::string class_source;
            RC::Unreal::UClass* klass =
                resolve_bp_ui_automation_class(class_source);
            (void)klass;
            source = class_source.empty()
                ? "unavailable"
                : "diagnostic-reflection-disabled:" + class_source;
            return nullptr;
        }

        static bool safe_native_lux_datatable_path_init_as_null(
            LuxDataTablePathInitAsNullFn fn,
            LuxDataTablePathNative* path) noexcept
        {
            if (!fn || !path) return false;
            __try
            {
                fn(path);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static void safe_native_lux_datatable_path_dtor(
            LuxDataTablePathDtorFn fn,
            LuxDataTablePathNative* path) noexcept
        {
            if (!fn || !path) return;
            __try
            {
                fn(path);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
            }
        }

        static bool safe_copy_current_gameflow_scene_data_path(
            CopyCurrentGameFlowSceneDataPathFn fn,
            void* game_flow_manager,
            LuxDataTablePathNative* out_path) noexcept
        {
            if (!fn || !game_flow_manager || !out_path) return false;
            __try
            {
                return fn(game_flow_manager, out_path);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool safe_lookup_lux_datatable_object_field_path(
            LookupLuxDataTableObjectFieldPathFn fn,
            LuxDataTablePathNative* parent_path,
            RC::Unreal::FString* key,
            LuxDataTablePathNative* out_path) noexcept
        {
            if (!fn || !parent_path || !key || !out_path) return false;
            __try
            {
                return fn(parent_path, key, out_path);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool safe_read_lux_datatable_path_string_field(
            ReadLuxDataTablePathStringFieldFn fn,
            LuxDataTablePathNative* object_path,
            RC::Unreal::FString* key,
            RC::Unreal::FString* out_value) noexcept
        {
            if (!fn || !object_path || !key || !out_value) return false;
            __try
            {
                return fn(object_path, key, out_value);
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        static bool safe_native_complete_gameflow_current_scene_stop(
            UIGameFlowManagerCurrentSceneStopCompleteFn fn,
            void* game_flow_manager) noexcept
        {
            if (!fn || !game_flow_manager) return false;
            __try
            {
                fn(game_flow_manager);
                return true;
            }
            __except (EXCEPTION_EXECUTE_HANDLER)
            {
                return false;
            }
        }

        bool resolve_gameflow_natives() noexcept
        {
            if (m_lux_datatable_path_init_as_null &&
                m_lux_datatable_path_dtor &&
                m_copy_current_gameflow_scene_data_path &&
                m_lookup_lux_datatable_object_field_path &&
                m_read_lux_datatable_path_string_field &&
                m_gameflow_current_scene_stop_complete)
            {
                return true;
            }
            const uintptr_t base = NativeBinding::imageBase();
            if (!base) return false;
            m_lux_datatable_path_init_as_null =
                reinterpret_cast<LuxDataTablePathInitAsNullFn>(
                    base + kRVA_LuxDataTablePathInitAsNull);
            m_lux_datatable_path_dtor =
                reinterpret_cast<LuxDataTablePathDtorFn>(
                    base + kRVA_LuxDataTablePathDtor);
            m_copy_current_gameflow_scene_data_path =
                reinterpret_cast<CopyCurrentGameFlowSceneDataPathFn>(
                    base + kRVA_CopyCurrentGameFlowSceneDataPath);
            m_lookup_lux_datatable_object_field_path =
                reinterpret_cast<LookupLuxDataTableObjectFieldPathFn>(
                    base + kRVA_LookupLuxDataTableObjectFieldPath);
            m_read_lux_datatable_path_string_field =
                reinterpret_cast<ReadLuxDataTablePathStringFieldFn>(
                    base + kRVA_ReadLuxDataTablePathStringField);
            m_gameflow_current_scene_stop_complete =
                reinterpret_cast<UIGameFlowManagerCurrentSceneStopCompleteFn>(
                    base + kRVA_UIGameFlowManagerCurrentSceneStopComplete);
            return m_lux_datatable_path_init_as_null != nullptr &&
                   m_lux_datatable_path_dtor != nullptr &&
                   m_copy_current_gameflow_scene_data_path != nullptr &&
                   m_lookup_lux_datatable_object_field_path != nullptr &&
                   m_read_lux_datatable_path_string_field != nullptr &&
                   m_gameflow_current_scene_stop_complete != nullptr;
        }

        bool probe_direct_stage_transition_table(
            OnlineNavigatorObjects& nav,
            const wchar_t*& selected_tag,
            const char*& selected_tag_utf8,
            std::string& reason) noexcept
        {
            selected_tag = nullptr;
            selected_tag_utf8 = nullptr;
            if (!safe_is_real(nav.game_flow_manager))
                nav = resolve_online_navigator_objects();
            if (!safe_is_real(nav.game_flow_manager))
            {
                reason = "UIGameFlowManager unavailable";
                return false;
            }
            if (!resolve_gameflow_natives())
            {
                reason = "gameflow transition probe natives unavailable";
                return false;
            }

            struct Candidate
            {
                const wchar_t* wide;
                const char* utf8;
            };
            static constexpr Candidate kCandidates[] = {
                {L"battle", "battle"},
                {L"training", "training"},
                {L"battlesetup", "battlesetup"},
                {L"replay_list", "replay_list"},
                {L"replaylist", "replaylist"},
                {L"replaybattle", "replaybattle"},
                {L"playermatch", "playermatch"},
                {L"casualmatch", "casualmatch"},
                {L"creation", "creation"},
                {L"mainmenu", "mainmenu"},
            };

            LuxDataTablePathNative scene_path {};
            LuxDataTablePathNative transitions_path {};
            bool scene_path_inited = false;
            bool transitions_path_inited = false;
            bool scene_ok = false;
            bool transitions_ok = false;
            uint32_t found_tags = 0;
            uint32_t found_next_scene_fields = 0;
            uint32_t found_next_scene_string_values = 0;

            scene_path_inited = safe_native_lux_datatable_path_init_as_null(
                m_lux_datatable_path_init_as_null, &scene_path);
            transitions_path_inited =
                safe_native_lux_datatable_path_init_as_null(
                    m_lux_datatable_path_init_as_null, &transitions_path);

            if (scene_path_inited && transitions_path_inited)
            {
                scene_ok = safe_copy_current_gameflow_scene_data_path(
                    m_copy_current_gameflow_scene_data_path,
                    nav.game_flow_manager, &scene_path);
                RC::Unreal::FString transition_methods_key(
                    L"transitionMethods");
                transitions_ok =
                    scene_ok &&
                    safe_lookup_lux_datatable_object_field_path(
                        m_lookup_lux_datatable_object_field_path,
                        &scene_path, &transition_methods_key,
                        &transitions_path);
            }

            for (const Candidate& candidate : kCandidates)
            {
                LuxDataTablePathNative tag_path {};
                LuxDataTablePathNative next_scene_path {};
                const bool tag_path_inited =
                    safe_native_lux_datatable_path_init_as_null(
                        m_lux_datatable_path_init_as_null, &tag_path);
                const bool next_scene_path_inited =
                    safe_native_lux_datatable_path_init_as_null(
                        m_lux_datatable_path_init_as_null,
                        &next_scene_path);

                bool tag_found = false;
                bool next_scene_found = false;
                bool next_scene_value_read_ok = false;
                bool next_scene_value_text_ok = false;
                uint64_t next_scene_value_hash = 0;
                std::string next_scene_value_sample;
                if (transitions_ok && tag_path_inited &&
                    next_scene_path_inited)
                {
                    RC::Unreal::FString tag_key(candidate.wide);
                    tag_found =
                        safe_lookup_lux_datatable_object_field_path(
                            m_lookup_lux_datatable_object_field_path,
                            &transitions_path, &tag_key, &tag_path);
                    if (tag_found)
                    {
                        ++found_tags;
                        RC::Unreal::FString next_scene_key(L"nextScene");
                        next_scene_found =
                            safe_lookup_lux_datatable_object_field_path(
                                m_lookup_lux_datatable_object_field_path,
                                &tag_path, &next_scene_key,
                                &next_scene_path);
                        if (next_scene_found)
                        {
                            ++found_next_scene_fields;
                            RC::Unreal::FString next_scene_value;
                            next_scene_value_read_ok =
                                safe_read_lux_datatable_path_string_field(
                                    m_read_lux_datatable_path_string_field,
                                    &tag_path,
                                    &next_scene_key,
                                    &next_scene_value);
                            if (next_scene_value_read_ok)
                            {
                                RawFStringNative next_scene_raw {};
                                static_assert(
                                    sizeof(next_scene_raw) ==
                                        sizeof(next_scene_value),
                                    "FString layout drifted");
                                std::memcpy(&next_scene_raw,
                                            &next_scene_value,
                                            sizeof(next_scene_raw));
                                next_scene_value_text_ok =
                                    safe_sample_raw_fstring(
                                        next_scene_raw,
                                        128,
                                        next_scene_value_sample,
                                        next_scene_value_hash);
                            }
                            if (next_scene_value_text_ok)
                            {
                                ++found_next_scene_string_values;
                            }
                            if (next_scene_value_text_ok && !selected_tag)
                            {
                                selected_tag = candidate.wide;
                                selected_tag_utf8 = candidate.utf8;
                            }
                        }
                    }
                }

                const bool emit =
                    !m_direct_stage_transition_probe_emitted ||
                    (m_direct_stage_attempts % 120u) == 0u;
                if (emit)
                {
                    ReplayTraceFields f;
                    f.boolean("ok", transitions_ok)
                     .string("request_id", m_cfg.request_id)
                     .string("client_role", m_cfg.client_role)
                     .string("candidate_tag", candidate.utf8)
                     .boolean("scene_path_init_ok", scene_path_inited)
                     .boolean("transitions_path_init_ok",
                              transitions_path_inited)
                     .boolean("scene_data_ok", scene_ok)
                      .boolean("transition_methods_found", transitions_ok)
                      .boolean("tag_found", tag_found)
                      .boolean("next_scene_field_found", next_scene_found)
                      .boolean("next_scene_value_read_ok",
                               next_scene_value_read_ok)
                      .boolean("next_scene_value_text_ok",
                               next_scene_value_text_ok)
                      .hex("next_scene_value_hash",
                           next_scene_value_hash)
                      .string("next_scene_value_sample",
                              next_scene_value_sample)
                      .hex("game_flow_manager",
                           reinterpret_cast<uintptr_t>(
                               nav.game_flow_manager))
                     .hex("current_scene",
                          reinterpret_cast<uintptr_t>(nav.current_scene));
                    ReplayDebugTrace::instance().event(
                        "rollback_direct_stage_transition_probe", f);
                }

                if (next_scene_path_inited)
                    safe_native_lux_datatable_path_dtor(
                        m_lux_datatable_path_dtor, &next_scene_path);
                if (tag_path_inited)
                    safe_native_lux_datatable_path_dtor(
                        m_lux_datatable_path_dtor, &tag_path);
            }
            m_direct_stage_transition_probe_emitted = true;

            if (transitions_path_inited)
                safe_native_lux_datatable_path_dtor(
                    m_lux_datatable_path_dtor, &transitions_path);
            if (scene_path_inited)
                safe_native_lux_datatable_path_dtor(
                    m_lux_datatable_path_dtor, &scene_path);

            if (selected_tag)
            {
                reason = std::string("selected transition tag ") +
                         selected_tag_utf8;
                return true;
            }
            reason = "no probed transition tag with nextScene; tags=" +
                      std::to_string(found_tags) + " nextScene=" +
                      std::to_string(found_next_scene_fields) +
                      " nextSceneString=" +
                      std::to_string(found_next_scene_string_values);
            return false;
        }

        template <typename Resolver>
        RC::Unreal::UObject* resolve_cached_navigation_object(
            OnlineNavigatorObjectCache& cache,
            std::chrono::milliseconds interval,
            Resolver&& resolver) noexcept
        {
            const auto now = std::chrono::steady_clock::now();
            if (cache.attempted
                && now - cache.last_validation < interval)
            {
                ++cache.cache_hits;
                return cache.object;
            }

            cache.attempted = true;
            cache.last_validation = now;
            ++cache.validations;
            if (cache.object && safe_is_real(cache.object))
                return cache.object;

            cache.object = nullptr;
            ++cache.searches;
            try
            {
                cache.object = resolver();
            }
            catch (...)
            {
                cache.object = nullptr;
            }
            return cache.object;
        }

        static void remember_navigation_object(
            OnlineNavigatorObjectCache& cache,
            RC::Unreal::UObject* object) noexcept
        {
            if (!object) return;
            if (cache.object != object)
            {
                cache.object = object;
                cache.last_validation = std::chrono::steady_clock::now();
                cache.attempted = true;
            }
        }

        RollbackP2PUObjectIdentity describe_navigation_object(
            RC::Unreal::UObject* object) noexcept
        {
            if (!object) return {};
            const auto now = std::chrono::steady_clock::now();
            for (auto& entry : m_online_nav_identity_cache)
            {
                if (entry.object == object)
                {
                    if (now - entry.last_validation
                        < kOnlineNavigatorIdentityRevalidateInterval)
                    {
                        ++m_online_nav_identity_cache_hits;
                        return entry.identity;
                    }
                    ++m_online_nav_identity_cache_misses;
                    entry.last_validation = now;
                    entry.identity = describe_uobject(object);
                    return entry.identity;
                }
            }

            ++m_online_nav_identity_cache_misses;
            auto& entry = m_online_nav_identity_cache[
                m_online_nav_identity_cache_cursor
                    % m_online_nav_identity_cache.size()];
            ++m_online_nav_identity_cache_cursor;
            entry.object = object;
            entry.last_validation = now;
            entry.identity = describe_uobject(object);
            return entry.identity;
        }

        void reset_online_navigator_caches() noexcept
        {
            m_online_nav_umg_util_cache = {};
            m_online_nav_game_flow_manager_cache = {};
            m_online_nav_session_hub_cache = {};
            m_online_nav_ui_game_content_cache = {};
            m_online_nav_automation_cache = {};
            m_online_nav_automation_source.clear();
            m_online_nav_identity_cache = {};
            m_online_nav_identity_cache_cursor = 0;
            m_online_nav_identity_cache_hits = 0;
            m_online_nav_identity_cache_misses = 0;
        }

        OnlineNavigatorObjects resolve_online_navigator_objects(
            bool discover_game_flow_automation = false) noexcept
        {
            OnlineNavigatorObjects nav{};
            nav.umg_util = resolve_cached_navigation_object(
                m_online_nav_umg_util_cache,
                kOnlineNavigatorObjectRevalidateInterval,
                []() -> RC::Unreal::UObject* {
                    RC::Unreal::UObject* object =
                        RC::Unreal::UObjectGlobals::FindFirstOf(L"UMGUtil");
                    return object ? object : resolve_umg_util_via_library();
                });
            if (nav.umg_util)
            {
                (void)safe_get_uobject_property(
                    nav.umg_util, L"UIGameFlowManager",
                    nav.game_flow_manager);
                (void)safe_get_uobject_property(
                    nav.umg_util, L"UIGameFlowAutomation",
                    nav.game_flow_automation);
                if (nav.game_flow_manager)
                {
                    remember_navigation_object(
                        m_online_nav_game_flow_manager_cache,
                        nav.game_flow_manager);
                }
                if (nav.game_flow_automation)
                {
                    remember_navigation_object(
                        m_online_nav_automation_cache,
                        nav.game_flow_automation);
                    nav.game_flow_automation_source = "umg-property";
                }
            }
            if (!nav.game_flow_manager)
            {
                nav.game_flow_manager = resolve_cached_navigation_object(
                    m_online_nav_game_flow_manager_cache,
                    kOnlineNavigatorObjectRevalidateInterval,
                    []() -> RC::Unreal::UObject* {
                        RC::Unreal::UObject* object =
                            resolve_gameflow_manager_via_library();
                        return object ? object
                            : RC::Unreal::UObjectGlobals::FindFirstOf(
                                  L"LuxUIGameFlowManager");
                    });
            }
            if (!nav.game_flow_automation
                && discover_game_flow_automation)
            {
                nav.game_flow_automation = resolve_cached_navigation_object(
                    m_online_nav_automation_cache,
                    kOnlineNavigatorAutomationRetryInterval,
                    [this, &nav]() -> RC::Unreal::UObject* {
                        std::string source;
                        RC::Unreal::UObject* object =
                            resolve_or_create_gameflow_automation(
                                nav.umg_util, source);
                        m_online_nav_automation_source = std::move(source);
                        return object;
                    });
                nav.game_flow_automation_source =
                    m_online_nav_automation_source.empty()
                        ? "automation-probe-cached-negative"
                        : m_online_nav_automation_source;
            }
            else if (!nav.game_flow_automation)
            {
                // Ordinary release navigation uses the verified XInput/native
                // path. Do not scan the whole object array for an optional
                // diagnostic automation object on every engine tick.
                nav.game_flow_automation_source =
                    "automation-discovery-not-requested";
            }
            if (nav.game_flow_manager)
            {
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"CurrentScene",
                    nav.current_scene);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"NextScene", nav.next_scene);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"CeBankManager",
                    nav.ce_bank_manager);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"SigninManager",
                    nav.signin_manager);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"SessionHub", nav.session_hub);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"BattleLauncher",
                    nav.battle_launcher);
                (void)safe_get_uobject_property(
                    nav.game_flow_manager, L"UIGameContent",
                    nav.ui_game_content);

                auto* gfm = reinterpret_cast<uint8_t*>(
                    nav.game_flow_manager);
                void* raw = nullptr;
                if (SafeReadPtr(gfm + 0x270, &raw) && raw)
                {
                    nav.match_lobby =
                        reinterpret_cast<RC::Unreal::UObject*>(raw);
                }
                raw = nullptr;
                if (SafeReadPtr(gfm + 0x150, &raw))
                    nav.current_scene_direct =
                        reinterpret_cast<RC::Unreal::UObject*>(raw);
                raw = nullptr;
                if (SafeReadPtr(gfm + 0x158, &raw))
                    nav.next_scene_direct =
                        reinterpret_cast<RC::Unreal::UObject*>(raw);
                uint8_t flag = 0;
                nav.manager_ready_flag_ok =
                    SafeReadBytes(gfm + 0xF8, &flag, sizeof(flag));
                nav.manager_ready_flag =
                    nav.manager_ready_flag_ok && flag != 0;
                flag = 0;
                nav.manager_start_latch_flag_ok =
                    SafeReadBytes(gfm + 0xF9, &flag, sizeof(flag));
                nav.manager_start_latch_flag =
                    nav.manager_start_latch_flag_ok && flag != 0;
                flag = 0;
                nav.manager_enable_change_flag_ok =
                    SafeReadBytes(gfm + 0xFA, &flag, sizeof(flag));
                nav.manager_enable_change_flag =
                    nav.manager_enable_change_flag_ok && flag != 0;
                if (!nav.current_scene &&
                    safe_is_real(nav.current_scene_direct))
                {
                    nav.current_scene = nav.current_scene_direct;
                }
                if (!nav.next_scene && safe_is_real(nav.next_scene_direct))
                    nav.next_scene = nav.next_scene_direct;
            }
            if (!nav.session_hub)
            {
                nav.session_hub = resolve_cached_navigation_object(
                    m_online_nav_session_hub_cache,
                    kOnlineNavigatorObjectRevalidateInterval,
                    []() -> RC::Unreal::UObject* {
                        return RC::Unreal::UObjectGlobals::FindFirstOf(
                            L"LuxorSessionHub");
                    });
            }
            else
            {
                remember_navigation_object(
                    m_online_nav_session_hub_cache, nav.session_hub);
            }
            if (!nav.ui_game_content)
            {
                nav.ui_game_content = resolve_cached_navigation_object(
                    m_online_nav_ui_game_content_cache,
                    kOnlineNavigatorObjectRevalidateInterval,
                    []() -> RC::Unreal::UObject* {
                        return RC::Unreal::UObjectGlobals::FindFirstOf(
                            L"LuxUIGameContent");
                    });
            }
            else
            {
                remember_navigation_object(
                    m_online_nav_ui_game_content_cache,
                    nav.ui_game_content);
            }
            if (nav.game_flow_automation)
            {
                (void)safe_get_fstring_property(
                    nav.game_flow_automation, L"CurrentSceneName",
                    nav.current_scene_name);
                (void)safe_get_fstring_property(
                    nav.game_flow_automation, L"PrevScenename",
                    nav.prev_scene_name);
            }
            nav.ready_to_start_ok = call_bool_query(
                nav.game_flow_manager, L"IsReadyToStart",
                nav.ready_to_start);
            nav.enable_change_scene_ok = call_bool_query(
                nav.game_flow_manager, L"IsEnableChangeScene",
                nav.enable_change_scene);
            nav.current_scene_identity =
                describe_navigation_object(nav.current_scene);
            nav.next_scene_identity =
                describe_navigation_object(nav.next_scene);
            nav.next_scene_direct_identity =
                describe_navigation_object(nav.next_scene_direct);
            nav.match_lobby_identity =
                describe_navigation_object(nav.match_lobby);
            nav.battle_launcher_identity =
                describe_navigation_object(nav.battle_launcher);
            return nav;
        }

        bool change_gameflow_scene(RC::Unreal::UObject* owner,
                                   const wchar_t* transition_tag,
                                   const char* owner_name,
                                   std::string& reason) noexcept
        {
            if (!safe_is_real(owner))
            {
                reason = std::string(owner_name ? owner_name : "owner") +
                         " unavailable";
                return false;
            }
            auto* fn = owner->GetFunctionByNameInChain(L"ChangeScene");
            if (!fn)
            {
                reason = std::string(owner_name ? owner_name : "owner") +
                         ".ChangeScene unavailable";
                return false;
            }
            if (!resolve_gameflow_natives())
            {
                reason = "native UIDataObject initializer unavailable";
                return false;
            }

            struct ChangeSceneParams
            {
                RC::Unreal::FString TransitionTag;
                LuxDataTablePathNative InheritedData {};
                NullScriptDelegateNative ChangeSceneParam {};

                explicit ChangeSceneParams(const wchar_t* tag)
                    : TransitionTag(tag ? tag : L"")
                {}
            };
            static_assert(sizeof(ChangeSceneParams) == 0x38,
                          "GameFlow ChangeScene params drifted");

            ChangeSceneParams params{transition_tag};
            if (!safe_native_lux_datatable_path_init_as_null(
                    m_lux_datatable_path_init_as_null,
                    &params.InheritedData))
            {
                reason = "native UIDataObject init failed";
                return false;
            }

            const bool ok = safe_process_event(owner, fn, &params);
            safe_native_lux_datatable_path_dtor(
                m_lux_datatable_path_dtor, &params.InheritedData);
            if (!ok)
            {
                reason = std::string(owner_name ? owner_name : "owner") +
                         ".ChangeScene failed";
                return false;
            }
            reason = std::string("called ") +
                     (owner_name ? owner_name : "owner") +
                     ".ChangeScene";
            return true;
        }

        static bool call_no_param_function(RC::Unreal::UObject* obj,
                                           const wchar_t* name) noexcept
        {
            if (!safe_is_real(obj) || !name) return false;
            auto* fn = obj->GetFunctionByNameInChain(name);
            if (!fn) return false;
            char no_params[1] {};
            return safe_process_event(obj, fn, no_params);
        }

        static bool start_gameflow_manager(
            RC::Unreal::UObject* game_flow_manager,
            bool reserve_to_start_on_ready = false) noexcept
        {
            if (!safe_is_real(game_flow_manager)) return false;
            auto* fn = game_flow_manager->GetFunctionByNameInChain(L"Start");
            if (!fn) return false;
            struct Params
            {
                bool ReserveToStartOnReady {false};
            } params{};
            params.ReserveToStartOnReady = reserve_to_start_on_ready;
            return safe_process_event(game_flow_manager, fn, &params);
        }

        static bool call_signin_login(RC::Unreal::UObject* signin_manager,
                                      bool is_startup,
                                      bool is_interrupt_flow) noexcept
        {
            if (!safe_is_real(signin_manager)) return false;
            auto* fn = signin_manager->GetFunctionByNameInChain(
                L"RequestLogin");
            if (!fn) return false;
            struct Params
            {
                bool IsStartUp {false};
                bool IsInterraptFlow {false};
            } params{};
            params.IsStartUp = is_startup;
            params.IsInterraptFlow = is_interrupt_flow;
            return safe_process_event(signin_manager, fn, &params);
        }

        static bool call_signin_decide_main_user(
            RC::Unreal::UObject* signin_manager,
            int32_t force_decide_user) noexcept
        {
            if (!safe_is_real(signin_manager)) return false;
            auto* fn = signin_manager->GetFunctionByNameInChain(
                L"RequestDecideMainUser");
            if (!fn) return false;
            struct Params
            {
                int32_t ForceDecideUser {0};
            } params{};
            params.ForceDecideUser = force_decide_user;
            return safe_process_event(signin_manager, fn, &params);
        }

        bool complete_current_gameflow_scene_stop(
            RC::Unreal::UObject* game_flow_manager) noexcept
        {
            if (!safe_is_real(game_flow_manager)) return false;
            if (!resolve_gameflow_natives()) return false;
            return safe_native_complete_gameflow_current_scene_stop(
                m_gameflow_current_scene_stop_complete,
                game_flow_manager);
        }

        void reset_current_gameflow_scene_stop_if_changed(
            RC::Unreal::UObject* current_scene) noexcept
        {
            const uintptr_t scene =
                reinterpret_cast<uintptr_t>(current_scene);
            if (m_current_scene_stop_scene == scene)
                return;

            m_current_scene_stop_scene = scene;
            m_current_scene_stop_requested = false;
            m_current_scene_stop_request_ok = false;
            m_current_scene_ready_to_stop_requested = false;
            m_current_scene_ready_to_stop_request_ok = false;
            m_current_scene_stop_complete_requested = false;
            m_current_scene_stop_complete_ok = false;
        }

        bool pump_current_gameflow_scene_stop(
            OnlineNavigatorObjects& nav,
            const char* scene_label,
            std::string& reason,
            bool allow_manager_complete = true) noexcept
        {
            if (!safe_is_real(nav.current_scene) ||
                !safe_is_real(nav.game_flow_manager))
            {
                nav = resolve_online_navigator_objects();
            }
            const std::string label =
                scene_label && scene_label[0] ? scene_label : "CurrentScene";
            if (!safe_is_real(nav.current_scene))
            {
                reason = label + ".current_scene unavailable";
                return false;
            }
            if (!safe_is_real(nav.game_flow_manager))
            {
                reason = label + ".game_flow_manager unavailable";
                return false;
            }

            reset_current_gameflow_scene_stop_if_changed(
                nav.current_scene);

            if (!m_current_scene_stop_requested)
            {
                m_current_scene_stop_requested = true;
                m_current_scene_stop_request_ok = call_no_param_function(
                    nav.current_scene, L"OnRequestToStop");
                reason = m_current_scene_stop_request_ok
                    ? "called " + label + ".OnRequestToStop"
                    : label + ".OnRequestToStop unavailable";
                return m_current_scene_stop_request_ok;
            }

            if (!m_current_scene_ready_to_stop_requested)
            {
                m_current_scene_ready_to_stop_requested = true;
                m_current_scene_ready_to_stop_request_ok =
                    call_no_param_function(nav.current_scene,
                                           L"ReadyToStop");
                reason = m_current_scene_ready_to_stop_request_ok
                    ? "called " + label + ".ReadyToStop"
                    : label + ".ReadyToStop unavailable";
                return m_current_scene_ready_to_stop_request_ok;
            }

            if (m_current_scene_stop_complete_requested)
            {
                reason = m_current_scene_stop_complete_ok
                    ? "UIGameFlowManager.CurrentSceneStopComplete already called"
                    : "UIGameFlowManager.CurrentSceneStopComplete already failed";
                return m_current_scene_stop_complete_ok;
            }

            if (!allow_manager_complete)
            {
                reason = m_current_scene_ready_to_stop_request_ok
                    ? "called " + label +
                          ".ReadyToStop; waiting for manager scene transition"
                    : label +
                          ".ReadyToStop failed; not calling manager stop complete";
                return m_current_scene_ready_to_stop_request_ok;
            }

            m_current_scene_stop_complete_requested = true;
            m_current_scene_stop_complete_ok =
                complete_current_gameflow_scene_stop(
                    nav.game_flow_manager);
            reason = m_current_scene_stop_complete_ok
                ? "called UIGameFlowManager.CurrentSceneStopComplete"
                : "UIGameFlowManager.CurrentSceneStopComplete failed";
            return m_current_scene_stop_complete_ok;
        }

        static bool emulate_title_decide(std::string& reason) noexcept
        {
            auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                RC::Unreal::UObject*>(
                    nullptr, nullptr,
                    STR("/Script/LuxorGame.Default__LuxInputUtil"));
            if (!safe_is_real(cdo))
            {
                reason = "Default__LuxInputUtil unavailable";
                return false;
            }
            if (!call_no_param_function(cdo, L"EmulateTitleDecide"))
            {
                reason = "ULuxInputUtil.EmulateTitleDecide failed";
                return false;
            }
            reason = "called ULuxInputUtil.EmulateTitleDecide";
            return true;
        }

        bool emulate_gameflow_input(OnlineNavigatorObjects& nav,
                                    UiInputKey key,
                                    std::string& reason) noexcept
        {
            if (!safe_is_real(nav.game_flow_automation))
                nav = resolve_online_navigator_objects(true);
            if (!safe_is_real(nav.game_flow_automation))
            {
                reason = "UIGameFlowAutomation unavailable";
                return false;
            }

            auto* fn = nav.game_flow_automation->GetFunctionByNameInChain(
                L"EmulateInputImmidiately");
            if (!fn)
            {
                reason = "EmulateInputImmidiately unavailable";
                return false;
            }

            struct EmulateInputParams
            {
                uint8_t Key {0};
            } params{};
            params.Key = static_cast<uint8_t>(key);
            if (!safe_process_event(nav.game_flow_automation, fn, &params))
            {
                reason = "EmulateInputImmidiately failed";
                return false;
            }

            ++m_gameflow_input_attempts;
            reason = "emulated gameflow ";
            reason += ui_input_key_name(key);
            return true;
        }

        void emit_title_input_navigation_trace(
            bool ok,
            const OnlineNavigatorObjects& nav,
            const std::string& reason,
            bool dispatch_accepted,
            bool native_input_consumed,
            bool scene_transitioned,
            bool target_scene_queued = false) noexcept
        {
            const auto pulse = GameImGui::XInputHook::instance()
                .observable_pulse_status();
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .string("reason", reason)
             .boolean("dispatch_accepted", dispatch_accepted)
             .boolean("native_input_consumed", native_input_consumed)
             .boolean("action_acknowledged",
                      scene_transitioned || target_scene_queued)
             .boolean("semantic_scene_acknowledged",
                      scene_transitioned || target_scene_queued)
             .boolean("scene_transitioned", scene_transitioned)
             .boolean("target_scene_queued", target_scene_queued)
             .uinteger("title_scene_stable_ticks",
                       m_title_scene_stability.stable_ticks())
             .boolean("title_scene_stable",
                      m_title_scene_stability.stable_ticks()
                          >= kTitleSceneStableTicks)
             .uinteger("navigation_generation",
                       m_title_navigation_driver.generation())
             .uinteger("navigation_dispatch_id",
                       m_title_navigation_dispatch_id)
             .uinteger("navigation_state",
                       static_cast<uint64_t>(
                           m_title_navigation_driver.state()))
             .string("navigation_state_name",
                     rollback_navigation_state_name(
                         m_title_navigation_driver.state()))
             .string("navigation_failure",
                     RollbackUiNavigationDriver::failure_name(
                         m_title_navigation_driver.failure()))
             .uinteger("navigation_attempts",
                       m_title_navigation_driver.total_dispatches())
             .uinteger("xinput_pulse_generation",
                       m_title_navigation_pulse_generation)
             .uinteger("xinput_consumed_pulse_generation",
                       m_title_navigation_consumed_pulse_generation)
             .uinteger("xinput_phase",
                       static_cast<uint64_t>(pulse.phase))
             .uinteger("xinput_state_reads",
                       pulse.generation_state_reads)
             .uinteger("xinput_force_rescan_writes",
                       pulse.native_force_rescan_writes)
             .uinteger("xinput_lease_generation",
                       pulse.connectivity_lease_generation)
             .uinteger("xinput_lease_state_reads",
                       pulse.connectivity_lease_state_reads)
             .boolean("xinput_lease_active",
                      pulse.connectivity_lease_active);
            add_uobject_identity_fields(
                f, "current_scene", nav.current_scene_identity);
            add_uobject_identity_fields(
                f, "next_scene", nav.next_scene_identity);
            ReplayDebugTrace::instance().event(
                "rollback_title_input_navigation", f);
        }

        void cancel_title_navigation_pulse() noexcept
        {
            if (m_title_navigation_pulse_generation != 0)
            {
                (void)GameImGui::XInputHook::instance()
                    .fail_observable_pulse(
                        m_title_navigation_pulse_generation);
            }
            m_title_navigation_dispatch_id = 0;
            m_title_navigation_pulse_generation = 0;
            m_title_navigation_acknowledged_pulse_generation = 0;
            m_title_navigation_consumed_pulse_generation = 0;
        }

        bool request_title_to_main_menu(
            OnlineNavigatorObjects& nav,
            std::string& reason) noexcept
        {
            try
            {
                const uint64_t tick = m_online_nav_attempts;
                const RollbackUiNavigationScene scene =
                    rollback_navigation_scene(nav.current_scene_identity);
                const uint64_t scene_generation =
                    rollback_navigation_scene_generation(nav.current_scene);
                static constexpr RollbackUiNavigationKey kRoute[] = {
                    RollbackUiNavigationKey::Decide,
                };

                const bool exact_title_scene = identity_contains_scene(
                    nav.current_scene_identity, "TitleScene");
                const bool title_stable = m_title_scene_stability.observe(
                    scene_generation,
                    exact_title_scene,
                    kTitleSceneStableTicks);
                auto& input_hook = GameImGui::XInputHook::instance();
                bool title_connectivity_hook_ok = true;
                if (exact_title_scene
                    && m_title_navigation_lease_generation == 0)
                {
                    // EmulateTitleDecide submits Gamepad_Special_Right for
                    // local user zero through SC6's own input dispatcher.
                    // Keep controller zero logically connected, but do not
                    // synthesize a button: the native UFunction supplies the
                    // semantic Start/Menu key after the title hierarchy is
                    // stable.
                    title_connectivity_hook_ok = input_hook.install();
                    if (title_connectivity_hook_ok)
                    {
                        m_title_navigation_lease_generation =
                            input_hook.begin_observable_connectivity_lease(0);
                    }
                }
                const auto title_connectivity =
                    input_hook.observable_pulse_status();
                const bool title_connectivity_ready =
                    title_connectivity_hook_ok
                    && m_title_navigation_lease_generation != 0
                    && title_connectivity.connectivity_lease_active
                    && title_connectivity.connectivity_lease_generation
                        == m_title_navigation_lease_generation
                    && title_connectivity.connectivity_lease_state_reads != 0;
                const bool target_scene_queued =
                    identity_is_main_menu(nav.next_scene_identity)
                    || identity_is_main_menu(
                        nav.next_scene_direct_identity);
                m_title_navigation_target_scene_queued =
                    target_scene_queued;

                if (target_scene_queued
                    && m_title_navigation_driver.state()
                        == RollbackUiNavigationState::AwaitingAcknowledgement
                    && m_title_navigation_dispatch_id != 0)
                {
                    const RollbackUiNavigationResult ack =
                        m_title_navigation_driver.acknowledge(
                            m_title_navigation_driver.generation(),
                            m_title_navigation_dispatch_id,
                            tick,
                            RollbackUiNavigationScene::MainMenu,
                            false);
                    if (ack == RollbackUiNavigationResult::Succeeded)
                    {
                        m_title_navigation_semantic_acknowledged = true;
                        m_title_to_main_menu_requested = true;
                        reason = "MainMenuScene transition queued";
                        emit_title_input_navigation_trace(
                            true, nav, reason, false, false, false, true);
                        return true;
                    }
                }

                if (m_title_navigation_driver.state()
                    == RollbackUiNavigationState::Idle)
                {
                    if (!title_stable)
                    {
                        reason = exact_title_scene
                            ? "waiting for stable TitleScene input hierarchy"
                            : "waiting for exact TitleScene";
                        return false;
                    }
                    (void)m_title_navigation_driver.begin(
                        scene_generation,
                        kRoute,
                        1,
                        tick,
                        scene);
                }

                const RollbackUiNavigationResult scene_result =
                    m_title_navigation_driver.observe_scene(
                        scene_generation, tick, scene);
                m_title_to_main_menu_attempts =
                    m_title_navigation_driver.total_dispatches();
                if (scene_result == RollbackUiNavigationResult::Succeeded
                    || m_title_navigation_driver.sequence_complete())
                {
                    m_title_navigation_semantic_acknowledged = true;
                    m_title_to_main_menu_requested = true;
                    reason = "current MainMenuScene acknowledged";
                    emit_title_input_navigation_trace(
                        true, nav, reason, false, false, true);
                    cancel_title_navigation_pulse();
                    return true;
                }
                if (m_title_navigation_driver.state()
                    == RollbackUiNavigationState::Failed)
                {
                    reason = "title navigation failed: ";
                    reason += RollbackUiNavigationDriver::failure_name(
                        m_title_navigation_driver.failure());
                    cancel_title_navigation_pulse();
                    return false;
                }

                if (m_title_navigation_driver.state()
                        == RollbackUiNavigationState::AwaitingAcknowledgement
                    && m_title_navigation_pulse_generation != 0)
                {
                    const auto pulse = input_hook.observable_pulse_status();
                    if (pulse.generation
                            == m_title_navigation_pulse_generation
                        && pulse.phase
                            == GameImGui::XInputHook::
                                ObservablePulsePhase::Complete
                        && pulse.completion_generation
                            == m_title_navigation_pulse_generation
                        && m_title_navigation_consumed_pulse_generation
                            != m_title_navigation_pulse_generation)
                    {
                        // Poller consumption proves only that SC6 sampled the
                        // Start/Menu pulse.  It must not acknowledge this
                        // transaction; a queued/current MainMenu scene is the
                        // sole semantic success signal.
                        m_title_navigation_consumed_pulse_generation =
                            m_title_navigation_pulse_generation;
                        reason = "native Start/Menu pulse consumed; waiting "
                                 "for MainMenuScene";
                        emit_title_input_navigation_trace(
                            true, nav, reason, false, true, false);
                    }
                }

                if (m_title_navigation_driver.state()
                        == RollbackUiNavigationState::ReadyToDispatch
                    && !title_stable)
                {
                    reason = "waiting for stable TitleScene before retry";
                    return false;
                }

                const bool dispatcher_available =
                    exact_title_scene && title_stable
                    && title_connectivity_ready;
                RollbackUiNavigationCommand command {};
                if (!m_title_navigation_driver.next_command(
                        scene_generation,
                        tick,
                        scene,
                        dispatcher_available,
                        command))
                {
                    m_title_to_main_menu_attempts =
                        m_title_navigation_driver.total_dispatches();
                    if (m_title_navigation_driver.state()
                        == RollbackUiNavigationState::Failed)
                    {
                        reason = "title navigation failed: ";
                        reason += RollbackUiNavigationDriver::failure_name(
                            m_title_navigation_driver.failure());
                        emit_title_input_navigation_trace(
                            false, nav, reason, false, false, false);
                        cancel_title_navigation_pulse();
                    }
                    else if (!dispatcher_available)
                    {
                        reason = !exact_title_scene
                            ? "exact TitleScene unavailable"
                            : !title_stable
                                ? "waiting for stable TitleScene"
                                : "waiting for controller-zero connectivity";
                    }
                    else
                    {
                        reason = "waiting for current MainMenuScene";
                    }
                    return false;
                }

                m_title_navigation_dispatch_id = command.dispatch_id;
                // Ghidra: ULuxInputUtil::EmulateTitleDecide dispatches the
                // game-owned Gamepad_Special_Right (Start/Menu) FKey for user
                // zero. Mirror that proven semantic key through the verified
                // native XInput poller; the previous face-button-A pulse was
                // the wrong key and poller completion was a false UI ack.
                m_title_navigation_pulse_generation =
                    input_hook.arm_observable_button_pulse(
                        XINPUT_GAMEPAD_START,
                        0,
                        2,
                        2,
                        2,
                        true,
                        false);
                const auto armed = input_hook.observable_pulse_status();
                const bool delivered =
                    armed.generation
                        == m_title_navigation_pulse_generation
                    && (armed.active
                        || armed.phase
                            == GameImGui::XInputHook::
                                ObservablePulsePhase::Complete)
                    && armed.failure
                        == GameImGui::XInputHook::
                            ObservablePulseFailure::None;
                ++m_title_navigation_native_dispatches;
                m_title_navigation_last_native_dispatch_ok = delivered;
                (void)m_title_navigation_driver.on_dispatch_result(
                    command.generation,
                    command.dispatch_id,
                    tick,
                    delivered);
                m_title_to_main_menu_attempts =
                    m_title_navigation_driver.total_dispatches();
                reason = delivered
                    ? "observable Gamepad_Special_Right pulse armed"
                    : "Gamepad_Special_Right pulse rejected";
                emit_title_input_navigation_trace(
                    delivered,
                    nav,
                    reason,
                    delivered,
                    false,
                    false);
                return delivered;
            }
            catch (...)
            {
                cancel_title_navigation_pulse();
                reason = "title navigation exception";
                return false;
            }
        }

        static bool is_startup_or_title_scene(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            return info.class_name.find("Title") != std::string::npos
                || info.object_name.find("Title") != std::string::npos
                || info.class_name.find("AdvertiseScene") !=
                       std::string::npos
                || info.object_name.find("AdvertiseScene") !=
                       std::string::npos
                || info.class_name.find("InitScene") != std::string::npos
                || info.object_name.find("InitScene") != std::string::npos;
        }

        static bool is_advertise_scene(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            return info.class_name.find("AdvertiseScene") != std::string::npos
                || info.object_name.find("AdvertiseScene") != std::string::npos;
        }

        bool request_advertise_scene_advance(
            OnlineNavigatorObjects& nav,
            std::string& reason) noexcept
        {
            if (!safe_is_real(nav.current_scene))
            {
                m_advertise_scene_advance_failure =
                    "AdvertiseScene unavailable";
                reason = m_advertise_scene_advance_failure;
                return false;
            }
            m_advertise_scene_advance_requested = true;
            ++m_advertise_scene_advance_attempts;

            bool ok = false;
            const char* method = "not-run";
            const uint64_t route =
                (m_advertise_scene_advance_attempts - 1u) % 5u;
            if (!m_game_initialize_requested &&
                safe_is_real(nav.game_flow_manager))
            {
                method = "GameInitialize";
                ok = call_no_param_function(
                    nav.game_flow_manager, L"GameInitialize");
                m_game_initialize_requested = ok;
                reason = ok ? "called LuxUIGameFlowManager.GameInitialize"
                            : "LuxUIGameFlowManager.GameInitialize failed";
            }
            else if (route == 0)
            {
                method = "EmulateTitleDecide";
                ok = emulate_title_decide(reason);
                if (ok) m_title_to_main_menu_requested = true;
            }
            else if (route == 1)
            {
                method = "Start";
                ok = start_gameflow_manager(nav.game_flow_manager);
                m_gameflow_start_requested =
                    m_gameflow_start_requested || ok;
                reason = ok ? "called UIGameFlowManager.Start(false)"
                            : "UIGameFlowManager.Start(false) failed";
            }
            else if (route == 2)
            {
                method = "CeBank.TitleToMainMenu";
                ok = safe_is_real(nav.ce_bank_manager) &&
                    call_no_param_function(nav.ce_bank_manager,
                                           L"TitleToMainMenu");
                reason = ok ? "called ULuxCeBankManager.TitleToMainMenu"
                            : "ULuxCeBankManager.TitleToMainMenu unavailable";
            }
            else if (route == 3)
            {
                method = "AdvertiseSceneStop";
                ok = pump_current_gameflow_scene_stop(
                    nav, "AdvertiseScene", reason, false);
            }
            else
            {
                method = "AdvertiseSceneStop";
                ok = pump_current_gameflow_scene_stop(
                    nav, "AdvertiseScene", reason, false);
            }

            m_advertise_scene_advance_method = method;
            m_advertise_scene_advance_ok = ok;
            m_advertise_scene_advance_failure =
                ok
                    ? "ok"
                    : (std::string("AdvertiseScene safe route ") + method +
                       " failed");
            if (!ok)
                reason = m_advertise_scene_advance_failure + ": " + reason;
            return ok;
        }

        bool request_direct_title_to_main_menu(
            OnlineNavigatorObjects& nav,
            std::string& reason) noexcept
        {
            const uint64_t attempt = m_title_to_main_menu_attempts++;
            if (attempt < 20 && emulate_title_decide(reason))
                return true;

            if (!safe_is_real(nav.ce_bank_manager) ||
                !safe_is_real(nav.signin_manager))
            {
                nav = resolve_online_navigator_objects();
            }

            const uint64_t routed_attempt =
                attempt >= 20 ? attempt - 20 : attempt;
            switch (routed_attempt % 10)
            {
            case 0:
                if (call_no_param_function(nav.current_scene,
                                           L"OpenTitleMenu"))
                {
                    reason = "called TitleScene.OpenTitleMenu";
                    return true;
                }
                reason = "TitleScene.OpenTitleMenu unavailable";
                return false;
            case 1:
                m_direct_title_to_main_menu_requested = true;
                m_direct_title_to_main_menu_ok =
                    call_no_param_function(nav.current_scene, L"ToMainMenu");
                reason = m_direct_title_to_main_menu_ok
                    ? "called TitleScene.ToMainMenu"
                    : "TitleScene.ToMainMenu unavailable";
                return m_direct_title_to_main_menu_ok;
            case 2:
                if (!m_direct_title_to_main_menu_requested)
                {
                    reason = "waiting for TitleScene.ToMainMenu";
                    return false;
                }
                m_current_scene_stop_requested = true;
                m_current_scene_stop_request_ok = call_no_param_function(
                    nav.current_scene, L"OnRequestToStop");
                reason = m_current_scene_stop_request_ok
                    ? "called TitleScene.OnRequestToStop"
                    : "TitleScene.OnRequestToStop failed";
                return m_current_scene_stop_request_ok;
            case 3:
                if (!m_direct_title_to_main_menu_requested)
                {
                    reason = "waiting for TitleScene.ToMainMenu";
                    return false;
                }
                m_current_scene_ready_to_stop_requested = true;
                m_current_scene_ready_to_stop_request_ok =
                    call_no_param_function(nav.current_scene,
                                           L"OnReadyToStop");
                reason = m_current_scene_ready_to_stop_request_ok
                    ? "called TitleScene.OnReadyToStop"
                    : "TitleScene.OnReadyToStop failed";
                return m_current_scene_ready_to_stop_request_ok;
            case 4:
                if (!m_direct_title_to_main_menu_requested)
                {
                    reason = "waiting for TitleScene.ToMainMenu";
                    return false;
                }
                m_current_scene_stop_complete_requested = true;
                m_current_scene_stop_complete_ok =
                    complete_current_gameflow_scene_stop(
                        nav.game_flow_manager);
                reason = m_current_scene_stop_complete_ok
                    ? "called UIGameFlowManager.CurrentSceneStopComplete"
                    : "UIGameFlowManager.CurrentSceneStopComplete failed";
                return m_current_scene_stop_complete_ok;
            case 5:
                return emulate_gameflow_input(
                    nav, UiInputKey::Start, reason);
            case 6:
                return emulate_gameflow_input(
                    nav, UiInputKey::Decide, reason);
            case 7:
                if (call_no_param_function(nav.current_scene,
                                           L"OnRequestToStart"))
                {
                    reason = "called TitleScene.OnRequestToStart";
                    return true;
                }
                reason = "TitleScene.OnRequestToStart failed";
                return false;
            case 8:
                if (call_no_param_function(nav.current_scene, L"OnStart"))
                {
                    reason = "called TitleScene.OnStart";
                    return true;
                }
                reason = "TitleScene.OnStart failed";
                return false;
            case 9:
                m_direct_title_to_main_menu_requested = true;
                m_direct_title_to_main_menu_ok =
                    call_no_param_function(nav.current_scene, L"ToMainMenu");
                reason = m_direct_title_to_main_menu_ok
                    ? "called TitleScene.ToMainMenu"
                    : "TitleScene.ToMainMenu unavailable";
                return m_direct_title_to_main_menu_ok;
            default:
                reason = "direct title route exhausted";
                return false;
            }
        }

        bool request_direct_title_to_main_menu_replay_style(
            OnlineNavigatorObjects& nav,
            std::string& reason) noexcept
        {
            if (emulate_title_decide(reason))
            {
                m_title_to_main_menu_requested = true;
                return true;
            }

            if (!safe_is_real(nav.ce_bank_manager))
                nav = resolve_online_navigator_objects();
            if (safe_is_real(nav.ce_bank_manager) &&
                call_no_param_function(nav.ce_bank_manager,
                                       L"TitleToMainMenu"))
            {
                m_title_to_main_menu_requested = true;
                reason = "called ULuxCeBankManager.TitleToMainMenu";
                return true;
            }

            std::string fallback_reason;
            const bool ok = change_gameflow_scene(
                nav.game_flow_manager, L"TitleToMainMenu",
                "UIGameFlowManager", fallback_reason);
            if (ok) m_title_to_main_menu_requested = true;
            reason = ok ? ("title-to-main-menu fallback " +
                           fallback_reason)
                        : ("title-to-main-menu fallback failed: " +
                           fallback_reason);
            return ok;
        }

        static bool is_direct_stage_ready_scene(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            if (is_startup_or_title_scene(info) ||
                is_advertise_scene(info))
            {
                return false;
            }
            if (is_direct_online_battle_scene(info))
                return true;
            const bool player_match =
                info.class_name.find("PlayerMatch") != std::string::npos ||
                info.object_name.find("PlayerMatch") != std::string::npos;
            const bool replay_scene =
                info.class_name.find("Replay") != std::string::npos ||
                info.object_name.find("Replay") != std::string::npos;
            if (player_match || replay_scene)
                return false;
            return info.class_name.find("MainMenu") != std::string::npos ||
                   info.object_name.find("MainMenu") != std::string::npos ||
                   info.class_name.find("BattleSetup") !=
                       std::string::npos ||
                   info.object_name.find("BattleSetup") !=
                       std::string::npos ||
                   info.class_name.find("BattleScene") !=
                       std::string::npos ||
                   info.object_name.find("BattleScene") !=
                       std::string::npos;
        }

        bool request_direct_replay_setup_scene(
            bool& scene_complete,
            std::string& reason) noexcept
        {
            scene_complete = false;
            m_direct_stage_replay_setup_scene_requested = true;

            OnlineNavigatorObjects nav = resolve_online_navigator_objects();
            const RollbackP2PUObjectIdentity& current_info =
                nav.current_scene_identity;
            const RollbackP2PUObjectIdentity& next_info =
                nav.next_scene_identity;
            const bool startup_or_title_scene =
                is_startup_or_title_scene(current_info);
            const bool advertise_scene = is_advertise_scene(current_info);
            if (!startup_or_title_scene && !advertise_scene)
            {
                m_direct_stage_navigation_ready = true;
                if (m_direct_stage_navigation_reason == "not-run")
                    m_direct_stage_navigation_reason =
                        "replay setup scene route active";
            }

            const bool in_replay_setup =
                current_info.class_name.find("ReplaySetupScene") !=
                    std::string::npos ||
                current_info.object_name.find("ReplaySetupScene") !=
                    std::string::npos;
            const bool in_replay_battle =
                current_info.class_name.find("ReplayBattleScene") !=
                    std::string::npos ||
                current_info.object_name.find("ReplayBattleScene") !=
                    std::string::npos;
            const bool in_replay_list =
                current_info.class_name.find("ReplayListScene") !=
                    std::string::npos ||
                current_info.object_name.find("ReplayListScene") !=
                    std::string::npos;
            const bool in_creation =
                current_info.class_name.find("CreationScene") !=
                    std::string::npos ||
                current_info.object_name.find("CreationScene") !=
                    std::string::npos;
            const bool transition_queued =
                nav.next_scene != nullptr || nav.next_scene_direct != nullptr;

            const wchar_t* transition_tag = L"replay_list";
            const char* transition_tag_utf8 = "replay_list";
            const char* transition_owner = "game_flow_manager";
            bool change_queued = false;
            bool ok = false;

            if (startup_or_title_scene || advertise_scene)
            {
                std::string nav_reason;
                ok = pump_direct_replay_gameflow_navigation(
                    nav, startup_or_title_scene, advertise_scene,
                    nav_reason);
                reason = nav_reason;
                transition_tag = L"mainmenu";
                transition_tag_utf8 = "mainmenu";
                transition_owner = "direct_replay_gameflow_navigation";
            }
            else if (in_replay_setup)
            {
                scene_complete = true;
                ok = true;
                reason = "ReplaySetupScene active";
            }
            else if (in_replay_battle)
            {
                transition_tag = L"replaylist";
                transition_tag_utf8 = "replaylist";
            }
            else if (in_replay_list)
            {
                transition_tag = L"battlesetup";
                transition_tag_utf8 = "battlesetup";
            }
            else if (in_creation)
            {
                transition_tag = L"mainmenu";
                transition_tag_utf8 = "mainmenu";
                transition_owner = "current_scene";
            }

            if (!ok && transition_queued)
            {
                reason = "waiting for replay setup scene transition";
            }
            else if (!ok && nav.enable_change_scene_ok &&
                     !nav.enable_change_scene)
            {
                reason =
                    "UIGameFlowManager not ready for replay setup change";
            }
            else if (!ok)
            {
                std::string change_reason;
                if (in_creation)
                {
                    ok = change_gameflow_scene(
                        nav.current_scene, transition_tag, "CurrentScene",
                        change_reason);
                }
                else
                {
                    ok = change_gameflow_scene(
                        nav.game_flow_manager, transition_tag,
                        "UIGameFlowManager", change_reason);
                }
                reason = change_reason;
                if (ok)
                {
                    OnlineNavigatorObjects after =
                        resolve_online_navigator_objects();
                    change_queued =
                        after.next_scene != nullptr ||
                        after.next_scene_direct != nullptr;
                    if (!change_queued && !in_creation)
                    {
                        ok = false;
                        reason += "; did not queue NextScene";
                    }
                }
            }

            m_direct_stage_replay_setup_scene_ok = ok;
            m_direct_stage_replay_setup_scene_ready = scene_complete;
            m_direct_stage_replay_setup_scene_reason = reason;

            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .boolean("scene_complete", scene_complete)
             .boolean("transition_queued", transition_queued)
             .boolean("change_queued", change_queued)
             .boolean("enable_change_scene_query_ok",
                      nav.enable_change_scene_ok)
             .boolean("enable_change_scene", nav.enable_change_scene)
             .string("transition_tag", transition_tag_utf8)
             .string("transition_owner", transition_owner)
             .string("reason", reason);
            add_uobject_identity_fields(f, "current_scene", current_info);
            add_uobject_identity_fields(f, "next_scene", next_info);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_replay_setup_scene", f);
            return ok;
        }

        bool request_direct_main_menu_scene(
            bool& scene_complete,
            std::string& reason) noexcept
        {
            scene_complete = false;
            OnlineNavigatorObjects nav = resolve_online_navigator_objects();
            const RollbackP2PUObjectIdentity& current_info =
                nav.current_scene_identity;
            const RollbackP2PUObjectIdentity& next_info =
                nav.next_scene_identity;
            const bool startup_or_title_scene =
                is_startup_or_title_scene(current_info);
            const bool advertise_scene = is_advertise_scene(current_info);
            const bool in_main_menu =
                current_info.class_name.find("MainMenuScene") !=
                    std::string::npos ||
                current_info.object_name.find("MainMenuScene") !=
                    std::string::npos;
            const bool transition_queued =
                nav.next_scene != nullptr || nav.next_scene_direct != nullptr;

            m_direct_stage_navigation_requested = true;
            bool ok = false;
            bool change_queued = false;
            const char* method = "wait";

            if (in_main_menu)
            {
                scene_complete = true;
                ok = true;
                method = "mainmenu-active";
                reason = "MainMenuScene active";
            }
            else if (startup_or_title_scene || advertise_scene)
            {
                method = "gameflow-navigation";
                ok = pump_direct_replay_gameflow_navigation(
                    nav, startup_or_title_scene, advertise_scene, reason);
            }
            else if (transition_queued)
            {
                method = "transition-wait";
                reason = "waiting for main menu scene transition";
            }
            else if (nav.enable_change_scene_ok && !nav.enable_change_scene)
            {
                method = "change-disabled";
                reason = "UIGameFlowManager not ready for main menu change";
            }
            else
            {
                method = "manager-mainmenu";
                ok = change_gameflow_scene(
                    nav.game_flow_manager, L"mainmenu",
                    "UIGameFlowManager", reason);
                if (ok)
                {
                    OnlineNavigatorObjects after =
                        resolve_online_navigator_objects();
                    change_queued =
                        after.next_scene != nullptr ||
                        after.next_scene_direct != nullptr;
                    if (!change_queued)
                    {
                        ok = false;
                        reason += "; did not queue NextScene";
                    }
                }
            }

            m_direct_stage_navigation_ready = scene_complete;
            m_direct_stage_navigation_reason = reason;
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .boolean("scene_complete", scene_complete)
             .boolean("transition_queued", transition_queued)
             .boolean("change_queued", change_queued)
             .string("method", method)
             .string("reason", reason)
             .boolean("enable_change_scene_query_ok",
                      nav.enable_change_scene_ok)
             .boolean("enable_change_scene", nav.enable_change_scene)
             .boolean("ready_to_start_query_ok", nav.ready_to_start_ok)
             .boolean("ready_to_start", nav.ready_to_start);
            add_uobject_identity_fields(f, "current_scene", current_info);
            add_uobject_identity_fields(f, "next_scene", next_info);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_main_menu_scene", f);
            return ok;
        }

        bool request_direct_battle_setup_scene(
            bool& scene_complete,
            std::string& reason) noexcept
        {
            scene_complete = false;
            OnlineNavigatorObjects nav = resolve_online_navigator_objects();
            const RollbackP2PUObjectIdentity& current_info =
                nav.current_scene_identity;
            const RollbackP2PUObjectIdentity& next_info =
                nav.next_scene_identity;
            const RollbackP2PUObjectIdentity& launcher_info =
                nav.battle_launcher_identity;
            const bool startup_or_title_scene =
                is_startup_or_title_scene(current_info);
            const bool advertise_scene = is_advertise_scene(current_info);
            const bool in_battle_setup =
                current_info.class_name.find("BattleSetup") !=
                    std::string::npos ||
                current_info.object_name.find("BattleSetup") !=
                    std::string::npos;
            const bool in_battle_scene =
                current_info.class_name.find("BattleScene") !=
                    std::string::npos ||
                current_info.object_name.find("BattleScene") !=
                    std::string::npos;
            const bool in_main_menu =
                current_info.class_name.find("MainMenuScene") !=
                    std::string::npos ||
                current_info.object_name.find("MainMenuScene") !=
                    std::string::npos;
            const bool transition_queued =
                nav.next_scene != nullptr || nav.next_scene_direct != nullptr;

            m_direct_stage_navigation_requested = true;
            bool ok = false;
            bool current_scene_attempted = false;
            bool current_scene_queued = false;
            bool manager_attempted = false;
            bool manager_queued = false;
            const char* method = "wait";
            const wchar_t* direct_transition_tag = L"battlesetup";
            const char* direct_transition_tag_utf8 = "battlesetup";
            std::string transition_probe_reason;

            if (in_battle_setup || in_battle_scene)
            {
                scene_complete = true;
                ok = true;
                method = in_battle_setup ? "battlesetup-active"
                                         : "battle-scene-active";
                reason = in_battle_setup ? "BattleSetup scene active"
                                         : "Battle scene active";
            }
            else if (startup_or_title_scene || advertise_scene)
            {
                method = "gameflow-navigation";
                ok = pump_direct_replay_gameflow_navigation(
                    nav, startup_or_title_scene, advertise_scene, reason);
            }
            else if (transition_queued)
            {
                method = "transition-wait";
                reason = "waiting for direct battle setup scene transition";
            }
            else if (in_main_menu)
            {
                if (probe_direct_stage_transition_table(
                        nav, direct_transition_tag,
                        direct_transition_tag_utf8,
                        transition_probe_reason))
                {
                    method = "mainmenu-probed-transition";
                }
                else
                {
                    method = "mainmenu-battlesetup";
                }

                if (nav.enable_change_scene_ok && !nav.enable_change_scene)
                {
                    method = "mainmenu-change-disabled";
                    reason =
                        "UIGameFlowManager not ready for direct battle setup scene change";
                }
                else
                {
                    std::string manager_reason;
                    method = "mainmenu-manager-transition";
                    manager_attempted = true;
                    ok = change_gameflow_scene(
                        nav.game_flow_manager, direct_transition_tag,
                        "UIGameFlowManager", manager_reason);
                    if (ok)
                    {
                        OnlineNavigatorObjects after =
                            resolve_online_navigator_objects();
                        manager_queued =
                            after.next_scene != nullptr ||
                            after.next_scene_direct != nullptr;
                        if (manager_queued)
                        {
                            reason = manager_reason;
                        }
                        else
                        {
                            ok = false;
                            reason = manager_reason +
                                     "; did not queue direct NextScene";
                        }
                    }
                    else
                    {
                        reason = "manager failed: " + manager_reason;
                    }
                }
            }
            else if (nav.enable_change_scene_ok && !nav.enable_change_scene)
            {
                method = "change-disabled";
                reason =
                    "UIGameFlowManager not ready for direct battle setup scene change";
            }
            else
            {
                std::string current_reason;
                method = "current-battlesetup";
                current_scene_attempted = true;
                ok = change_gameflow_scene(
                    nav.current_scene, L"battlesetup", "CurrentScene",
                    current_reason);
                if (ok)
                {
                    OnlineNavigatorObjects after =
                        resolve_online_navigator_objects();
                    current_scene_queued =
                        after.next_scene != nullptr ||
                        after.next_scene_direct != nullptr;
                    if (current_scene_queued)
                    {
                        reason = current_reason;
                    }
                    else
                    {
                        std::string manager_reason;
                        method = "current-then-manager-battlesetup";
                        manager_attempted = true;
                        const bool manager_ok = change_gameflow_scene(
                            nav.game_flow_manager, L"battlesetup",
                            "UIGameFlowManager", manager_reason);
                        if (manager_ok)
                        {
                            OnlineNavigatorObjects after_manager =
                                resolve_online_navigator_objects();
                            manager_queued =
                                after_manager.next_scene != nullptr ||
                                after_manager.next_scene_direct != nullptr;
                            if (manager_queued)
                            {
                                reason =
                                    current_reason +
                                    "; did not queue BattleSetup NextScene; "
                                    "manager " +
                                    manager_reason;
                            }
                            else
                            {
                                ok = false;
                                reason =
                                    current_reason +
                                    "; did not queue BattleSetup NextScene; "
                                    "manager " +
                                    manager_reason +
                                    "; did not queue BattleSetup NextScene";
                            }
                        }
                        else
                        {
                            ok = false;
                            reason =
                                current_reason +
                                "; did not queue BattleSetup NextScene; "
                                "manager failed: " +
                                manager_reason;
                        }
                    }
                }
                else
                {
                    std::string manager_reason;
                    method = "manager-battlesetup";
                    manager_attempted = true;
                    ok = change_gameflow_scene(
                        nav.game_flow_manager, L"battlesetup",
                        "UIGameFlowManager", manager_reason);
                    if (ok)
                    {
                        OnlineNavigatorObjects after =
                            resolve_online_navigator_objects();
                        manager_queued =
                            after.next_scene != nullptr ||
                            after.next_scene_direct != nullptr;
                        if (manager_queued)
                        {
                            reason = "CurrentScene route failed: " +
                                     current_reason + "; manager " +
                                     manager_reason;
                        }
                        else
                        {
                            ok = false;
                            reason = "CurrentScene route failed: " +
                                     current_reason + "; manager " +
                                     manager_reason +
                                     "; did not queue BattleSetup NextScene";
                        }
                    }
                    else
                    {
                        reason = "CurrentScene route failed: " +
                                 current_reason + "; manager failed: " +
                                 manager_reason;
                    }
                }
            }

            m_direct_stage_navigation_ready = scene_complete;
            m_direct_stage_navigation_reason = reason;
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .boolean("scene_complete", scene_complete)
             .boolean("transition_queued", transition_queued)
             .boolean("current_scene_attempted", current_scene_attempted)
             .boolean("current_scene_queued", current_scene_queued)
             .boolean("manager_attempted", manager_attempted)
             .boolean("manager_queued", manager_queued)
             .string("method", method)
             .string("transition_tag", direct_transition_tag_utf8)
             .string("transition_probe_reason", transition_probe_reason)
             .string("reason", reason)
             .boolean("enable_change_scene_query_ok",
                      nav.enable_change_scene_ok)
             .boolean("enable_change_scene", nav.enable_change_scene)
             .boolean("ready_to_start_query_ok", nav.ready_to_start_ok)
             .boolean("ready_to_start", nav.ready_to_start)
             .hex("battle_launcher",
                  reinterpret_cast<uintptr_t>(nav.battle_launcher));
            add_uobject_identity_fields(f, "current_scene", current_info);
            add_uobject_identity_fields(f, "next_scene", next_info);
            add_uobject_identity_fields(f, "battle_launcher",
                                        launcher_info);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_battle_setup_scene", f);
            return ok;
        }

        bool request_direct_battle_scene(
            bool& scene_complete,
            std::string& reason) noexcept
        {
            scene_complete = false;
            m_direct_stage_battle_scene_requested = true;

            OnlineNavigatorObjects nav = resolve_online_navigator_objects();
            const RollbackP2PUObjectIdentity& current_info =
                nav.current_scene_identity;
            const RollbackP2PUObjectIdentity& next_info =
                nav.next_scene_identity;
            const RollbackP2PUObjectIdentity& next_direct_info =
                nav.next_scene_direct_identity;
            const uintptr_t current_scene_addr =
                reinterpret_cast<uintptr_t>(nav.current_scene);
            const bool in_battle_setup =
                current_info.class_name.find("BattleSetup") !=
                    std::string::npos ||
                current_info.object_name.find("BattleSetup") !=
                    std::string::npos;
            const bool in_battle_scene =
                !in_battle_setup &&
                is_direct_online_battle_scene(current_info);
            const bool transition_queued =
                nav.next_scene != nullptr || nav.next_scene_direct != nullptr;

            const wchar_t* transition_tag = L"battle";
            const char* transition_tag_utf8 = "battle";
            const char* transition_owner = "wait";
            bool current_scene_attempted = false;
            bool current_scene_queued = false;
            bool manager_attempted = false;
            bool manager_queued = false;
            bool stop_attempted = false;
            bool stop_ok = false;
            bool resources_loaded_query_ok = false;
            bool resources_loaded = false;
            bool request_next_phase_query_ok = false;
            bool request_next_phase = false;
            bool versus_animation_finished_query_ok = false;
            bool versus_animation_finished = false;
            bool setup_scene_complete = false;
            bool ok = false;
            const char* method = "wait";
            std::string transition_probe_reason;

            if (in_battle_setup &&
                m_direct_stage_battle_scene_change_attempted &&
                m_direct_stage_battle_scene_change_scene !=
                    current_scene_addr)
            {
                m_direct_stage_battle_scene_change_attempted = false;
                m_direct_stage_battle_scene_change_ok = false;
                m_direct_stage_battle_scene_change_queued = false;
                m_direct_stage_battle_scene_change_scene = 0;
            }

            if (in_battle_scene)
            {
                if (m_direct_stage_battle_scene_stable_scene ==
                    current_scene_addr)
                {
                    ++m_direct_stage_battle_scene_stable_ticks;
                }
                else
                {
                    m_direct_stage_battle_scene_stable_scene =
                        current_scene_addr;
                    m_direct_stage_battle_scene_stable_ticks = 1;
                }
                scene_complete =
                    m_direct_stage_battle_scene_stable_ticks >=
                    kDirectStageBattleSceneStableTicks;
                ok = true;
                method = "battle-scene-active";
                transition_owner = "current_scene";
                reason = scene_complete
                    ? "Battle scene stable"
                    : "Battle scene active; waiting for stable scene sample";
            }
            else if (transition_queued)
            {
                m_direct_stage_battle_scene_stable_scene = 0;
                m_direct_stage_battle_scene_stable_ticks = 0;
                method = "transition-wait";
                reason = "waiting for direct battle scene transition";
            }
            else if (!in_battle_setup)
            {
                m_direct_stage_battle_scene_stable_scene = 0;
                m_direct_stage_battle_scene_stable_ticks = 0;
                method = "route-to-battle-setup";
                transition_owner = "battle_setup_route";
                ok = request_direct_battle_setup_scene(
                    setup_scene_complete, reason);
                if (setup_scene_complete)
                    reason = "BattleSetup scene active; waiting for battle scene";
            }
            else
            {
                m_direct_stage_battle_scene_stable_scene = 0;
                m_direct_stage_battle_scene_stable_ticks = 0;
                resources_loaded_query_ok = safe_read_bool_property(
                    nav.current_scene, L"bLoadedBattleResource",
                    resources_loaded);
                request_next_phase_query_ok = safe_read_bool_property(
                    nav.current_scene, L"bRequestNextPhase",
                    request_next_phase);
                versus_animation_finished_query_ok =
                    safe_read_bool_property(
                        nav.current_scene, L"bVersusAnmFinished",
                        versus_animation_finished);
                const RollbackBattleSceneTransitionDecision decision =
                    EvaluateRollbackBattleSceneTransition({
                        false,
                        false,
                        true,
                        m_mirrored_stock_phase_requested,
                        m_mirrored_stock_phase_requested,
                        m_mirrored_stock_phase_ok,
                        m_direct_stage_launcher_start_requested,
                        m_direct_stage_launcher_start_ok,
                        resources_loaded_query_ok,
                        resources_loaded,
                        m_direct_stage_battle_scene_change_attempted,
                        m_direct_stage_battle_scene_change_ok,
                    });
                method = decision.reason;
                reason = decision.reason;
                ok = decision.waiting;
                if (decision.state ==
                        RollbackBattleSceneTransitionState::Fatal &&
                    !m_direct_stage_launcher_start_ok &&
                    m_direct_stage_launcher_start_requested)
                {
                    reason = m_direct_stage_launcher_start_failure;
                }
                if (decision.call_request_change_scene)
                {
                    current_scene_attempted = true;
                    transition_owner = "BattleSetupScene.RequestChangeScene";
                    method = "battlesetup-native-request-change-scene";
                    m_direct_stage_battle_scene_change_attempted = true;
                    m_direct_stage_battle_scene_change_scene =
                        current_scene_addr;
                    ok = call_no_param_function(
                        nav.current_scene, L"RequestChangeScene");
                    m_direct_stage_battle_scene_change_ok = ok;
                    OnlineNavigatorObjects after =
                        resolve_online_navigator_objects();
                    current_scene_queued = ok &&
                        (after.next_scene != nullptr ||
                         after.next_scene_direct != nullptr);
                    m_direct_stage_battle_scene_change_queued =
                        current_scene_queued;
                    reason = ok
                        ? current_scene_queued
                              ? "BattleSetupScene.RequestChangeScene queued native NextScene"
                              : "BattleSetupScene.RequestChangeScene submitted; waiting for native game-flow transition"
                        : "BattleSetupScene.RequestChangeScene failed";
                }
                else if (m_direct_stage_battle_scene_change_attempted)
                    current_scene_queued =
                        m_direct_stage_battle_scene_change_queued;
            }

            m_direct_stage_battle_scene_ok = ok;
            m_direct_stage_battle_scene_ready = scene_complete;
            m_direct_stage_battle_scene_reason = reason;
            m_direct_stage_battle_scene_transition_tag =
                transition_tag_utf8 ? transition_tag_utf8 : "";
            m_direct_stage_battle_scene_transition_owner =
                transition_owner ? transition_owner : "";

            const RollbackP2PUObjectIdentity current_phase_info =
                describe_uobject(reflected_object_property(
                    nav.current_scene, L"CurrentPhase"));

            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .boolean("scene_complete", scene_complete)
             .boolean("setup_scene_complete", setup_scene_complete)
             .boolean("transition_queued", transition_queued)
             .boolean("current_scene_attempted", current_scene_attempted)
             .boolean("current_scene_queued", current_scene_queued)
             .boolean("manager_attempted", manager_attempted)
             .boolean("manager_queued", manager_queued)
             .boolean("stop_attempted", stop_attempted)
             .boolean("stop_ok", stop_ok)
             .boolean("resources_loaded_query_ok",
                      resources_loaded_query_ok)
             .boolean("resources_loaded", resources_loaded)
             .boolean("request_next_phase_query_ok",
                      request_next_phase_query_ok)
             .boolean("request_next_phase", request_next_phase)
             .boolean("versus_animation_finished_query_ok",
                      versus_animation_finished_query_ok)
             .boolean("versus_animation_finished",
                      versus_animation_finished)
             .boolean("battle_scene_change_attempted",
                      m_direct_stage_battle_scene_change_attempted)
             .boolean("battle_scene_change_ok",
                      m_direct_stage_battle_scene_change_ok)
             .boolean("battle_scene_change_queued",
                      m_direct_stage_battle_scene_change_queued)
             .hex("battle_scene_change_scene",
                  m_direct_stage_battle_scene_change_scene)
             .boolean("battle_launcher_start_via_scene_request",
                      m_direct_stage_launcher_start_via_scene_request)
             .boolean("stock_phase_requested",
                      m_mirrored_stock_phase_requested)
             .boolean("stock_phase_ok", m_mirrored_stock_phase_ok)
             .boolean("stock_scene_selection_ok",
                      m_mirrored_stock_scene_selection_ok)
             .string("stock_phase_failure",
                     m_mirrored_stock_phase_failure)
             .string("method", method)
             .string("transition_tag",
                     transition_tag_utf8 ? transition_tag_utf8 : "")
             .string("transition_owner",
                     transition_owner ? transition_owner : "")
             .string("transition_probe_reason", transition_probe_reason)
             .string("reason", reason)
             .boolean("enable_change_scene_query_ok",
                      nav.enable_change_scene_ok)
             .boolean("enable_change_scene", nav.enable_change_scene)
             .boolean("ready_to_start_query_ok", nav.ready_to_start_ok)
             .boolean("ready_to_start", nav.ready_to_start)
             .boolean("manager_ready_flag_ok",
                      nav.manager_ready_flag_ok)
             .boolean("manager_ready_flag", nav.manager_ready_flag)
             .boolean("manager_start_latch_flag_ok",
                      nav.manager_start_latch_flag_ok)
             .boolean("manager_start_latch_flag",
                      nav.manager_start_latch_flag)
             .boolean("manager_enable_change_flag_ok",
                      nav.manager_enable_change_flag_ok)
             .boolean("manager_enable_change_flag",
                      nav.manager_enable_change_flag)
             .hex("current_scene_stop_scene",
                  m_current_scene_stop_scene)
             .boolean("current_scene_stop_requested",
                      m_current_scene_stop_requested)
             .boolean("current_scene_stop_request_ok",
                      m_current_scene_stop_request_ok)
             .boolean("current_scene_ready_to_stop_requested",
                      m_current_scene_ready_to_stop_requested)
             .boolean("current_scene_ready_to_stop_request_ok",
                      m_current_scene_ready_to_stop_request_ok)
             .boolean("current_scene_stop_complete_requested",
                      m_current_scene_stop_complete_requested)
             .boolean("current_scene_stop_complete_ok",
                      m_current_scene_stop_complete_ok)
             .hex("battle_scene_stable_scene",
                  m_direct_stage_battle_scene_stable_scene)
             .uinteger("battle_scene_stable_ticks",
                       m_direct_stage_battle_scene_stable_ticks);
            add_uobject_identity_fields(f, "current_scene", current_info);
            add_uobject_identity_fields(f, "next_scene", next_info);
            add_uobject_identity_fields(f, "next_scene_direct",
                                        next_direct_info);
            add_uobject_identity_fields(f, "current_phase",
                                        current_phase_info);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_battle_scene", f);
            return ok;
        }

        bool pump_direct_replay_gameflow_navigation(
            OnlineNavigatorObjects& nav,
            bool startup_or_title_scene,
            bool advertise_scene,
            std::string& reason) noexcept
        {
            ++m_direct_stage_navigation_attempts;
            m_direct_stage_navigation_requested = true;

            bool ok = false;
            if (!m_game_initialize_requested &&
                     safe_is_real(nav.current_scene))
            {
                ok = call_no_param_function(
                    nav.game_flow_manager, L"GameInitialize");
                m_game_initialize_requested = ok;
                reason = ok ? "called LuxUIGameFlowManager.GameInitialize"
                            : "LuxUIGameFlowManager.GameInitialize failed";
            }
            else if (startup_or_title_scene || advertise_scene)
            {
                ok = request_direct_title_to_main_menu_replay_style(
                    nav, reason);
            }
            else
            {
                reason = "waiting for replay setup navigation";
            }

            if (ok)
            {
                OnlineNavigatorObjects after =
                    resolve_online_navigator_objects();
                const RollbackP2PUObjectIdentity after_current =
                    describe_uobject(after.current_scene);
                const bool still_early =
                    is_startup_or_title_scene(after_current) ||
                    is_advertise_scene(after_current);
                const bool after_transition_queued =
                    after.next_scene != nullptr ||
                    after.next_scene_direct != nullptr;
                if (still_early && !after_transition_queued)
                {
                    ok = false;
                    reason += "; no scene transition observed";
                }
            }

            m_direct_stage_navigation_reason = reason;
            ReplayTraceFields f;
            const RollbackP2PUObjectIdentity& current_info =
                nav.current_scene_identity;
            const RollbackP2PUObjectIdentity& next_info =
                nav.next_scene_identity;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .string("reason", reason)
             .uinteger("navigation_attempts",
                       m_direct_stage_navigation_attempts)
             .boolean("startup_or_title_scene", startup_or_title_scene)
             .boolean("advertise_scene", advertise_scene)
             .boolean("game_initialize_requested",
                      m_game_initialize_requested)
             .boolean("title_to_main_menu_requested",
                      m_title_to_main_menu_requested)
             .boolean("enable_change_scene_query_ok",
                      nav.enable_change_scene_ok)
             .boolean("enable_change_scene", nav.enable_change_scene)
             .boolean("ready_to_start_query_ok", nav.ready_to_start_ok)
             .boolean("ready_to_start", nav.ready_to_start);
            add_uobject_identity_fields(f, "current_scene", current_info);
            add_uobject_identity_fields(f, "next_scene", next_info);
            ReplayDebugTrace::instance().event(
                "rollback_direct_stage_replay_gameflow_navigation", f);
            return ok;
        }

        bool pump_direct_stage_navigation(
            OnlineNavigatorObjects& nav,
            bool battle_context_live,
            std::string& reason) noexcept
        {
            ++m_direct_stage_navigation_attempts;
            nav = resolve_online_navigator_objects();
            const RollbackP2PUObjectIdentity& current_info =
                nav.current_scene_identity;
            const RollbackP2PUObjectIdentity& next_info =
                nav.next_scene_identity;
            const bool startup_or_title_scene =
                is_startup_or_title_scene(current_info);
            const bool advertise_scene = is_advertise_scene(current_info);
            const bool direct_ready_scene =
                is_direct_stage_ready_scene(current_info);
            const bool transition_queued =
                nav.next_scene != nullptr || nav.next_scene_direct != nullptr;

            if (startup_or_title_scene)
                emit_scene_reflection_once(
                    nav.current_scene, &nav.current_scene_identity);

            if (battle_context_live)
            {
                reason = "battle context already live";
                m_direct_stage_navigation_ready = true;
                return true;
            }
            if (direct_ready_scene && !transition_queued &&
                (!nav.enable_change_scene_ok || nav.enable_change_scene))
            {
                reason = "direct launch scene ready";
                m_direct_stage_navigation_ready = true;
                return true;
            }
            if (transition_queued)
            {
                reason = "waiting for direct-stage scene transition";
                return false;
            }

            m_direct_stage_navigation_requested = true;
            bool acted = false;
            if (advertise_scene)
            {
                acted = request_advertise_scene_advance(nav, reason);
            }
            else if (startup_or_title_scene)
            {
                ++m_startup_scene_route_attempts;
                acted = request_direct_title_to_main_menu(nav, reason);
                if (acted)
                {
                    m_startup_scene_route_requested = true;
                    m_title_to_main_menu_requested = true;
                }
            }
            else if (!m_game_initialize_requested && nav.current_scene)
            {
                acted = call_no_param_function(
                    nav.game_flow_manager, L"GameInitialize");
                m_game_initialize_requested = acted;
                reason = acted ? "called LuxUIGameFlowManager.GameInitialize"
                               : "LuxUIGameFlowManager.GameInitialize failed";
            }
            else if (nav.enable_change_scene_ok &&
                     !nav.enable_change_scene)
            {
                reason = "UIGameFlowManager not ready for mainmenu change";
            }
            else
            {
                std::string current_reason;
                acted = change_gameflow_scene(
                    nav.current_scene, L"mainmenu",
                    "CurrentScene", current_reason);
                if (!acted)
                {
                    std::string manager_reason;
                    acted = change_gameflow_scene(
                        nav.game_flow_manager, L"mainmenu",
                        "UIGameFlowManager", manager_reason);
                    reason = "direct mainmenu route current=" +
                             current_reason + "; manager=" +
                             manager_reason;
                }
                else
                {
                    reason = current_reason;
                }
            }

            if (acted)
                m_direct_stage_navigation_reason = reason;
            else if (!reason.empty())
                m_direct_stage_navigation_reason = reason;
            else
                m_direct_stage_navigation_reason =
                    "direct-stage navigation waiting";
            (void)next_info;
            return false;
        }

        bool request_main_menu_change_scene(
            RC::Unreal::UObject* main_menu_scene,
            const wchar_t* command,
            std::string& reason) noexcept
        {
            reason.clear();
            if (!safe_is_real(main_menu_scene))
            {
                reason = "MainMenuScene unavailable";
                return false;
            }
            auto* fn = main_menu_scene->GetFunctionByNameInChain(
                L"requestChangeScene");
            if (!fn)
            {
                reason = "MainMenuScene.requestChangeScene unavailable";
                return false;
            }

            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096)
            {
                reason = "requestChangeScene param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            auto* command_prop = RC::Unreal::CastField<
                RC::Unreal::FStrProperty>(reflected_param(fn, L"command"));
            if (!command_prop)
            {
                command_prop = RC::Unreal::CastField<
                    RC::Unreal::FStrProperty>(
                        reflected_param(fn, L"Command"));
            }
            if (!command_prop)
            {
                reason = "requestChangeScene command param unavailable";
                return false;
            }

            bool command_initialized = false;
            try
            {
                command_prop->InitializeValue_InContainer(params.data());
                command_initialized = true;
                command_prop->SetPropertyValueInContainer(
                    params.data(),
                    RC::Unreal::FString(command ? command : L""));
                const bool ok =
                    safe_process_event(main_menu_scene, fn, params.data());
                reason = ok ? "called MainMenuScene.requestChangeScene"
                            : "MainMenuScene.requestChangeScene failed";
                if (command_initialized)
                    command_prop->DestroyValue_InContainer(params.data());
                return ok;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] MainMenu requestChangeScene threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "MainMenuScene.requestChangeScene threw";
            }
            catch (...)
            {
                reason = "MainMenuScene.requestChangeScene threw";
            }

            if (command_initialized)
                command_prop->DestroyValue_InContainer(params.data());
            return false;
        }

        bool create_ui_data_object_from_json(
            const wchar_t* json,
            LuxDataTablePathNative& out,
            std::string& reason) noexcept
        {
            out = {};
            reason.clear();
            auto* cdo = RC::Unreal::UObjectGlobals::StaticFindObject<
                RC::Unreal::UObject*>(
                    nullptr, nullptr,
                    STR("/Script/UMGUtil.Default__UMGUtilUIDataObjectLibrary"));
            if (!safe_is_real(cdo))
            {
                reason = "Default__UMGUtilUIDataObjectLibrary unavailable";
                return false;
            }
            auto* fn = cdo->GetFunctionByNameInChain(L"Parse");
            if (!fn)
            {
                reason = "UMGUtilUIDataObjectLibrary.Parse unavailable";
                return false;
            }

            const int32_t param_bytes = fn->GetPropertiesSize();
            if (param_bytes <= 0 || param_bytes > 4096)
            {
                reason = "Parse param-size invalid";
                return false;
            }

            std::vector<uint8_t> params(
                static_cast<size_t>(param_bytes), 0);
            auto* json_prop = RC::Unreal::CastField<
                RC::Unreal::FStrProperty>(
                    reflected_param(fn, L"JsonStringToParse"));
            if (!json_prop)
            {
                json_prop = RC::Unreal::CastField<
                    RC::Unreal::FStrProperty>(
                        reflected_param(fn, L"JsonString"));
            }
            RC::Unreal::FProperty* ret_prop = fn->GetReturnProperty();
            if (!json_prop || !ret_prop)
            {
                reason = "Parse reflected params unavailable";
                return false;
            }

            const int32_t ret_bytes = ret_prop->GetSize();
            if (ret_bytes <= 0 ||
                ret_bytes > static_cast<int32_t>(sizeof(out)))
            {
                reason = "Parse return size mismatch";
                return false;
            }

            bool json_initialized = false;
            try
            {
                json_prop->InitializeValue_InContainer(params.data());
                json_initialized = true;
                json_prop->SetPropertyValueInContainer(
                    params.data(),
                    RC::Unreal::FString(json ? json : L""));
                const bool ok = safe_process_event(cdo, fn, params.data());
                if (!ok)
                {
                    reason = "UMGUtilUIDataObjectLibrary.Parse failed";
                    if (json_initialized)
                        json_prop->DestroyValue_InContainer(params.data());
                    return false;
                }

                void* ret_slot =
                    ret_prop->ContainerPtrToValuePtr<void>(params.data());
                if (!ret_slot ||
                    !SafeReadBytes(ret_slot, &out,
                                   static_cast<size_t>(ret_bytes)))
                {
                    reason = "Parse return unreadable";
                    if (json_initialized)
                        json_prop->DestroyValue_InContainer(params.data());
                    out = {};
                    return false;
                }

                if (json_initialized)
                    json_prop->DestroyValue_InContainer(params.data());
                reason = "created FUIDataObject from JSON";
                return true;
            }
            catch (const std::exception& e)
            {
                RC::Output::send<RC::LogLevel::Error>(STR(
                    "[RollbackP2P] UMGUtilUIDataObjectLibrary.Parse threw: {}\n"),
                    RC::to_generic_string(e.what()));
                reason = "UMGUtilUIDataObjectLibrary.Parse threw";
            }
            catch (...)
            {
                reason = "UMGUtilUIDataObjectLibrary.Parse threw";
            }

            if (json_initialized)
                json_prop->DestroyValue_InContainer(params.data());
            out = {};
            return false;
        }

