        struct SteamPresenceSearchSnapshot
        {
            uint8_t state {0xff};
            uint8_t success {0};
            uint64_t call {0};
            uintptr_t matchmaking {0};
            uintptr_t search {0};
            uintptr_t lobby_array {0};
            int32_t api_lobby_count {0};
            int32_t lobby_count {0};
            int32_t lobby_max {0};
            bool ok {false};
        };

        static void atomic_max_i32(
            std::atomic<int32_t>& target,
            int32_t value) noexcept
        {
            int32_t observed = target.load(std::memory_order_acquire);
            while (value > observed &&
                   !target.compare_exchange_weak(
                       observed,
                       value,
                       std::memory_order_acq_rel,
                       std::memory_order_acquire))
            {
            }
        }

        static SteamPresenceSearchSnapshot
        read_steam_presence_search_snapshot(int64_t* context) noexcept
        {
            SteamPresenceSearchSnapshot out {};
            if (!context) return out;
            const auto* bytes =
                reinterpret_cast<const uint8_t*>(context);
            void* matchmaking = nullptr;
            void* search = nullptr;
            void* lobby_array = nullptr;
            out.ok =
                SafeReadUInt8(bytes + 0x40, &out.state)
                && SafeReadUInt8(bytes + 0x19, &out.success);
            (void)SafeReadUInt64(bytes + 0x20, &out.call);
            (void)SafeReadPtr(bytes + 0x28, &matchmaking);
            out.matchmaking = reinterpret_cast<uintptr_t>(matchmaking);
            (void)SafeReadPtr(bytes + 0x30, &search);
            out.search = reinterpret_cast<uintptr_t>(search);
            (void)SafeReadInt32(bytes + 0x44, &out.api_lobby_count);
            (void)SafeReadPtr(bytes + 0x48, &lobby_array);
            out.lobby_array = reinterpret_cast<uintptr_t>(lobby_array);
            (void)SafeReadInt32(bytes + 0x50, &out.lobby_count);
            (void)SafeReadInt32(bytes + 0x54, &out.lobby_max);
            return out;
        }

        static void count_steam_presence_state(uint8_t state) noexcept
        {
            switch (state)
            {
            case 0:
                s_steam_presence_search_state0_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 1:
                s_steam_presence_search_state1_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 2:
                s_steam_presence_search_state2_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 3:
                s_steam_presence_search_state3_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            case 4:
                s_steam_presence_search_state4_calls.fetch_add(
                    1, std::memory_order_acq_rel);
                break;
            default:
                break;
            }
        }

        static void steam_presence_search_tick_detour(
            int64_t* context) noexcept
        {
            const SteamPresenceSearchSnapshot before =
                read_steam_presence_search_snapshot(context);
            s_steam_presence_search_calls.fetch_add(
                1, std::memory_order_acq_rel);
            count_steam_presence_state(before.state);
            s_steam_presence_search_last_state_before.store(
                before.state, std::memory_order_release);
            s_steam_presence_search_last_success_before.store(
                before.success, std::memory_order_release);
            if (before.call)
                s_steam_presence_search_last_call.store(
                    before.call, std::memory_order_release);
            if (before.matchmaking)
                s_steam_presence_search_last_matchmaking.store(
                    before.matchmaking, std::memory_order_release);
            if (before.search)
                s_steam_presence_search_last_search.store(
                    before.search, std::memory_order_release);
            if (before.lobby_array)
                s_steam_presence_search_last_lobby_array.store(
                    before.lobby_array, std::memory_order_release);
            s_steam_presence_search_last_api_lobby_count.store(
                before.api_lobby_count, std::memory_order_release);
            atomic_max_i32(
                s_steam_presence_search_max_api_lobby_count,
                before.api_lobby_count);
            atomic_max_i32(
                s_steam_presence_search_max_collected_lobby_count,
                before.lobby_count);
            s_steam_presence_search_last_lobby_count.store(
                before.lobby_count, std::memory_order_release);
            s_steam_presence_search_last_lobby_max.store(
                before.lobby_max, std::memory_order_release);

            auto* original = reinterpret_cast<SteamPresenceSearchTickFn>(
                s_steam_presence_search_trampoline);
            if (original)
                original(context);

            const SteamPresenceSearchSnapshot after =
                read_steam_presence_search_snapshot(context);
            s_steam_presence_search_last_state_after.store(
                after.state, std::memory_order_release);
            s_steam_presence_search_last_success_after.store(
                after.success, std::memory_order_release);
            if (after.call)
                s_steam_presence_search_last_call.store(
                    after.call, std::memory_order_release);
            if (after.matchmaking)
                s_steam_presence_search_last_matchmaking.store(
                    after.matchmaking, std::memory_order_release);
            if (after.search)
                s_steam_presence_search_last_search.store(
                    after.search, std::memory_order_release);
            if (after.lobby_array)
                s_steam_presence_search_last_lobby_array.store(
                    after.lobby_array, std::memory_order_release);
            s_steam_presence_search_last_api_lobby_count.store(
                after.api_lobby_count, std::memory_order_release);
            atomic_max_i32(
                s_steam_presence_search_max_api_lobby_count,
                after.api_lobby_count);
            atomic_max_i32(
                s_steam_presence_search_max_collected_lobby_count,
                after.lobby_count);
            s_steam_presence_search_last_lobby_count.store(
                after.lobby_count, std::memory_order_release);
            s_steam_presence_search_last_lobby_max.store(
                after.lobby_max, std::memory_order_release);

            if (before.state == 2 && after.state == 3)
                s_steam_presence_search_state2_to3.fetch_add(
                    1, std::memory_order_acq_rel);
            else if (before.state == 2 && after.state == 4)
                s_steam_presence_search_state2_to4.fetch_add(
                    1, std::memory_order_acq_rel);
            else if (before.state == 3 && after.state == 4)
            {
                s_steam_presence_search_state3_to4.fetch_add(
                    1, std::memory_order_acq_rel);
                if (after.success == 0)
                    s_steam_presence_search_state3_timeout_fail.fetch_add(
                        1, std::memory_order_acq_rel);
            }
        }

