        bool start_standard_find_attempt(
            RC::Unreal::UObject* session_hub,
            int32_t main_user_id,
            uint64_t tick,
            const char* reason) noexcept
        {
            ++m_find_attempts;
            m_find_requested = true;
            m_find_callback_seen = false;
            m_find_callback_result = false;
            m_find_result_count = 0;
            m_find_result_max = 0;
            m_find_result_element_size = 0;
            m_find_result_polled = false;
            m_find_result_target_found = false;
            m_find_result_selected_index = -1;
            m_find_search_ptr = 0;
            m_find_result_ptr = 0;
            m_find_result_sample.clear();
            m_join_request_ok = false;
            m_join_complete_seen = false;
            m_join_complete_result = false;
            m_join_complete_result_type = -1;
            s_join_complete_seen.store(false, std::memory_order_release);
            s_join_complete_result.store(false, std::memory_order_release);
            s_join_complete_result_type.store(
                -1, std::memory_order_release);
            s_join_callback_requested.store(false, std::memory_order_release);
            s_join_callback_ok.store(false, std::memory_order_release);
            m_join_scene_result_staged = false;
            m_join_scene_result_bytes = 0;
            m_join_scene_result_element_bytes = 0;
            m_join_scene_result_write_bytes = 0;
            m_join_scene_result_array_dim = 0;
            m_join_scene_result_offset = 0;
            m_join_scene_result_struct_name.clear();
            m_join_scene_select_room_state = 0;
            m_join_scene_select_room_state_found = false;
            m_join_scene_select_room_state_result_staged = false;
            m_join_scene_select_room_state_result_write_bytes = 0;
            m_join_scene_pipeline_step = kJoinScenePipelineNone;
            m_join_scene_selected_result = 0;
            m_join_scene_selected_result_bytes = 0;
            m_join_scene_selected_result_storage.clear();
            m_join_scene_selected_tick = 0;
            m_join_scene_last_step_tick = 0;
            m_join_scene_mode = "not-run";
            m_join_scene_select_room_requested = false;
            m_join_scene_select_room_ok = false;
            m_join_scene_active_menu_widget = 0;
            m_join_scene_active_menu_name.clear();
            m_join_scene_ui_command_index = -1;
            m_join_scene_ui_command_tick = 0;
            m_join_scene_ui_command_requested = false;
            m_join_scene_ui_command_ok = false;
            m_join_scene_ui_command.clear();
            m_join_scene_ui_command_failure.clear();
            m_join_scene_decide_requested = false;
            m_join_scene_decide_ok = false;
            m_join_scene_search_connecting_requested = false;
            m_join_scene_search_connecting_ok = false;
            m_join_scene_poll_ok = false;
            m_join_scene_ping_wait_start_tick = 0;
            m_join_scene_ping_wait_started_at = {};
            m_join_scene_room_select_menu_wait_start_tick = 0;
            // OnPingSearchResults commonly arrives immediately after the
            // current FindPlayerSession callback, before the selected-result
            // handoff reaches SelectRoom. Define the edge at the start of the
            // find attempt and preserve every later callback through the join
            // pipeline.
            m_join_scene_ping_baseline_count =
                static_cast<uint64_t>(
                    s_ping_search_event_trace_count.load(
                        std::memory_order_acquire));
            m_join_scene_ping_seen = false;
            m_join_scene_ping_result = false;
            s_ping_search_callback_seen.store(
                false, std::memory_order_release);
            s_ping_search_callback_result.store(
                false, std::memory_order_release);
            m_join_scene_terminal_failure = false;
            m_join_scene_failure = "not-run";
            m_find_empty_callback_counted = false;
            m_find_retry_start_tick = tick;
            m_find_retry_reason = reason ? reason : "standard-find";

            prepare_join_callback_capture(
                session_hub,
                effective_join_session_name(),
                main_user_id);
            m_find_request_ok =
                call_find_player_session(session_hub, main_user_id);
            if (m_find_request_ok && m_cfg.debug_steam_filter_probe)
            {
                (void)debug_disable_find_presence_after_call(session_hub);
            }
            if (!m_find_request_ok)
            {
                stop_join_callback_capture(
                    "find-player-session-failed");
            }
            sync_join_callback_state();
            return m_find_request_ok;
        }

