        static RC::Unreal::UObject* resolve_match_setting_sync_from(
            RC::Unreal::UObject* obj) noexcept
        {
            if (!obj) return nullptr;
            static constexpr const wchar_t* kPropertyNames[] = {
                L"MatchSettingSync",
                L"MatchSync",
                L"SettingSync",
                L"BattleSync",
                L"OnlineBattleSync",
                L"LuxMatchSettingSync",
            };
            for (const wchar_t* name : kPropertyNames)
            {
                RC::Unreal::UObject* candidate = nullptr;
                if (safe_get_uobject_property(obj, name, candidate) &&
                    candidate)
                {
                    return candidate;
                }
            }
            return nullptr;
        }

        static RC::Unreal::UObject* resolve_match_setting_sync(
            const OnlineNavigatorObjects& nav,
            RC::Unreal::UObject* session_hub,
            RC::Unreal::UObject* match_data) noexcept
        {
            if (RC::Unreal::UObject* obj =
                    resolve_match_setting_sync_from(nav.current_scene))
                return obj;
            if (RC::Unreal::UObject* obj =
                    resolve_match_setting_sync_from(nav.next_scene))
                return obj;
            if (RC::Unreal::UObject* obj =
                    resolve_match_setting_sync_from(session_hub))
                return obj;
            if (RC::Unreal::UObject* obj =
                    resolve_match_setting_sync_from(match_data))
                return obj;

            static constexpr const wchar_t* kClassNames[] = {
                L"LuxMatchSettingSync",
                L"/Script/LuxorGame.LuxMatchSettingSync",
                L"Class /Script/LuxorGame.LuxMatchSettingSync",
            };
            for (const wchar_t* class_name : kClassNames)
            {
                RC::Unreal::UObject* first =
                    RC::Unreal::UObjectGlobals::FindFirstOf(class_name);
                if (first)
                    return first;
            }
            return nullptr;
        }

        static bool looks_like_match_setting_sync(
            const RollbackP2PUObjectIdentity& info) noexcept
        {
            return info.class_name.find("LuxMatchSettingSync") !=
                       std::string::npos
                || info.object_name.find("LuxMatchSettingSync") !=
                       std::string::npos
                || info.class_name.find("MatchSettingSync") !=
                       std::string::npos
                || info.object_name.find("MatchSettingSync") !=
                       std::string::npos
                || info.class_name.find("BattleSync") !=
                       std::string::npos
                || info.object_name.find("BattleSync") !=
                       std::string::npos;
        }

        void scan_match_setting_sync_candidates_once() noexcept
        {
            if (m_match_setting_sync_candidate_scanned)
                return;
            m_match_setting_sync_candidate_scanned = true;
            m_match_setting_sync_candidate_count = 0;
            m_match_setting_sync_candidate_sample.clear();
            try
            {
                RC::Unreal::UObjectGlobals::ForEachUObject(
                    [&](RC::Unreal::UObject* obj, int32_t, int32_t) {
                        if (!obj || !safe_is_real(obj))
                            return RC::LoopAction::Continue;
                        const RollbackP2PUObjectIdentity info =
                            describe_uobject(obj);
                        if (!looks_like_match_setting_sync(info))
                            return RC::LoopAction::Continue;
                        ++m_match_setting_sync_candidate_count;
                        if (m_match_setting_sync_candidate_sample.size()
                            < 768)
                        {
                            char ptr_text[32] {};
                            std::snprintf(
                                ptr_text, sizeof(ptr_text), "0x%llX",
                                static_cast<unsigned long long>(
                                    reinterpret_cast<uintptr_t>(obj)));
                            std::string item = ptr_text;
                            item.push_back('|');
                            item += info.class_name;
                            item.push_back('|');
                            item += info.object_name;
                            append_limited_name(
                                m_match_setting_sync_candidate_sample,
                                item,
                                768);
                        }
                        return RC::LoopAction::Continue;
                    });
            }
            catch (...)
            {
                m_match_setting_sync_candidate_sample =
                    "candidate-scan-threw";
            }
        }

        bool call_match_setting_sync_ready_to_connect(
            RC::Unreal::UObject* match_setting_sync) noexcept
        {
            m_match_setting_sync =
                reinterpret_cast<uintptr_t>(match_setting_sync);
            const RollbackP2PUObjectIdentity info =
                describe_uobject(match_setting_sync);
            m_match_setting_sync_name = info.object_name;
            m_match_setting_sync_class = info.class_name;

            if (!match_setting_sync)
            {
                m_match_setting_sync_failure =
                    "match-setting-sync-unavailable";
                return false;
            }
            if (m_match_setting_sync_name.find("Default__") == 0)
            {
                m_match_setting_sync_failure =
                    "match-setting-sync-default-object";
                return false;
            }

            m_match_setting_sync_initialize_ok =
                call_no_param_function(match_setting_sync, L"Initialize");
            m_match_setting_sync_is_connected_query_ok = call_bool_query(
                match_setting_sync, L"IsConnected",
                m_match_setting_sync_is_connected);

            m_match_setting_sync_ready_to_connect_ok =
                call_no_param_function(match_setting_sync, L"ReadyToConnect");

            m_match_setting_sync_is_completed_query_ok = call_bool_query(
                match_setting_sync, L"IsCompleted",
                m_match_setting_sync_is_completed);

            m_match_setting_sync_failure =
                m_match_setting_sync_ready_to_connect_ok
                    ? "ok"
                    : "ReadyToConnect failed";
            return m_match_setting_sync_ready_to_connect_ok;
        }

        void sample_match_setting_sync_raw(
            RC::Unreal::UObject* match_setting_sync) noexcept
        {
            m_match_setting_sync_raw_sampled = false;
            m_match_setting_sync_state_read_ok = false;
            m_match_setting_sync_character_complete_read_ok = false;
            m_match_setting_sync_stage_complete_read_ok = false;
            m_match_setting_sync_state = -1;
            m_match_setting_sync_character_complete = false;
            m_match_setting_sync_stage_complete = false;
            m_match_setting_sync_connected_raw = false;
            m_match_setting_sync_completed_raw = false;

            if (!match_setting_sync)
                return;

            m_match_setting_sync_raw_sampled = true;
            uint8_t state = 0;
            uint8_t character_complete = 0;
            uint8_t stage_complete = 0;
            auto* const bytes =
                reinterpret_cast<const uint8_t*>(match_setting_sync);
            m_match_setting_sync_state_read_ok =
                SafeReadUInt8(
                    bytes + kLuxMatchSettingSyncStateOff, &state);
            m_match_setting_sync_character_complete_read_ok =
                SafeReadUInt8(
                    bytes + kLuxMatchSettingSyncCharacterSetCompleteOff,
                    &character_complete);
            m_match_setting_sync_stage_complete_read_ok =
                SafeReadUInt8(
                    bytes + kLuxMatchSettingSyncStageOrAllCompleteOff,
                    &stage_complete);

            if (m_match_setting_sync_state_read_ok)
            {
                m_match_setting_sync_state =
                    static_cast<int32_t>(state);
                m_match_setting_sync_connected_raw = state > 1;
            }
            if (m_match_setting_sync_character_complete_read_ok)
            {
                m_match_setting_sync_character_complete =
                    character_complete != 0;
            }
            if (m_match_setting_sync_stage_complete_read_ok)
            {
                m_match_setting_sync_stage_complete =
                    stage_complete != 0;
            }
            m_match_setting_sync_completed_raw =
                m_match_setting_sync_character_complete_read_ok
                && m_match_setting_sync_stage_complete_read_ok
                && m_match_setting_sync_character_complete
                && m_match_setting_sync_stage_complete;
        }

