        void service_replay_input_script(uint64_t tick) noexcept
        {
            if (!m_replay_loaded)
                load_replay_input_file();

            if (!m_replay_decode_attempted)
            {
                m_replay_decode_attempted = true;
                const bool players_valid =
                    m_cfg.local_replay_player < 2
                    && m_cfg.remote_replay_player < 2
                    && m_cfg.local_replay_player !=
                        m_cfg.remote_replay_player;
                const bool decoded =
                    m_replay_input_frames_p0 > 0
                    && m_replay_input_frames_p1 > 0
                    && m_replay_input_frames_p0 ==
                        m_replay_input_frames_p1;
                if (!m_replay_file_exists)
                {
                    m_last_failure = "replay-input-file-missing";
                }
                else if (!decoded)
                {
                    m_last_failure =
                        m_replay_script.failure
                            ? m_replay_script.failure
                            : "replay-input-decode-failed";
                }
                else if (!players_valid)
                {
                    m_last_failure = "replay-player-mapping-invalid";
                }
                else
                {
                    m_replay_input_latched = true;
                    m_last_failure = "live-input-injection-not-wired";
                }
            }

            if (m_replay_input_latched)
            {
                arm_replay_input_injection();
                sync_replay_input_injection_report();
            }

            if (tick == 1 || !m_replay_input_script_emitted
                || (tick % 600) == 0)
            {
                emit_replay_input_script();
                if (m_cfg.direct_replay_input_requested
                    || m_cfg.direct_correction_requested)
                    emit_direct_replay_input();
                m_replay_input_script_emitted = true;
            }
            else if ((m_cfg.direct_replay_input_requested
                      || m_cfg.direct_correction_requested)
                     && (!m_direct_replay_input_emitted
                         || (m_replay_input_complete
                             && !m_direct_replay_input_ok_emitted)))
            {
                emit_direct_replay_input();
            }
        }

        void arm_replay_input_injection() noexcept
        {
            if (m_replay_injection_armed)
                return;
            if (!m_replay_script.ok)
                return;
            const uint32_t local_slot = m_cfg.local_replay_player;
            if (local_slot >= 2 ||
                local_slot >= m_replay_script.player_inputs.size())
            {
                m_last_failure = "replay-local-player-invalid";
                return;
            }
            const auto& local_inputs =
                m_replay_script.player_inputs[local_slot];
            if (local_inputs.empty())
            {
                m_last_failure = "replay-local-input-stream-empty";
                return;
            }
            const uint64_t local_hash =
                local_slot == 0 ? m_replay_input_hash_p0
                                : m_replay_input_hash_p1;
            if (!RollbackStockTransportObserveHook::instance().installed())
                (void)RollbackStockTransportObserveHook::instance().install();
            if (!RollbackLiveBoundaryHook::instance().installed())
                (void)RollbackLiveBoundaryHook::instance().install();
            RollbackStockTransportObserveHook::instance()
                .begin_replay_input_script(
                    local_slot, local_inputs, local_hash);
            RollbackLiveBoundaryHook::instance()
                .begin_replay_input_script(
                    local_slot, local_inputs, local_hash);
            m_replay_injection_armed = true;
            m_last_failure = "waiting-for-live-input-injection";
        }

        static uintptr_t direct_input_cache_entry_address(
            uintptr_t pInputLog,
            uint32_t dwPlayerIdx,
            uint32_t dwFrameIndex) noexcept
        {
            const uintptr_t entry_index =
                static_cast<uintptr_t>(dwPlayerIdx) * 0x200u
                + static_cast<uintptr_t>(dwFrameIndex & 0x1FFu);
            return pInputLog + kRollbackIL_InputCacheStart_Off
                + entry_index * sizeof(FLuxReplayInputCacheEntry_Model);
        }

        static bool write_direct_input_cache_entry(
            uintptr_t pInputLog,
            uint32_t dwPlayerIdx,
            int32_t nFrameID,
            uint32_t dwFrameIndex,
            uint32_t dwInputValue) noexcept
        {
            if (!pInputLog || dwPlayerIdx >= 2)
                return false;
            FLuxReplayInputCacheEntry_Model entry {};
            entry.nFrameID = nFrameID;
            entry.dwFrameIndex = dwFrameIndex;
            entry.dwInputValue = dwInputValue;
            entry.bFilled = 1;
            const uintptr_t entry_addr =
                direct_input_cache_entry_address(
                    pInputLog, dwPlayerIdx, dwFrameIndex);
            return SafeWriteBytes(
                reinterpret_cast<void*>(entry_addr),
                &entry,
                sizeof(entry));
        }

        uint64_t write_direct_replay_stream(
            uintptr_t pInputLog,
            uint32_t dwPlayerIdx,
            const std::vector<uint32_t>& inputs,
            uint32_t dwStartFrame,
            uint32_t dwFrameCount) noexcept
        {
            uint64_t writes = 0;
            if (!pInputLog || dwPlayerIdx >= 2 || inputs.empty())
                return 0;
            const uint32_t count =
                (std::min<uint32_t>)(
                    dwFrameCount,
                    static_cast<uint32_t>(
                        (std::min<uint64_t>)(
                            inputs.size(),
                            0xFFFFFFFFull)));
            for (uint32_t i = 0; i < count; ++i)
            {
                const uint32_t frame = dwStartFrame + i;
                if (write_direct_input_cache_entry(
                        pInputLog,
                        dwPlayerIdx,
                        static_cast<int32_t>(
                            (std::min<uint32_t>)(frame, 0x7FFFFFFFu)),
                        frame,
                        inputs[static_cast<size_t>(
                            frame % static_cast<uint32_t>(inputs.size()))]))
                {
                    ++writes;
                }
            }
            return writes;
        }

        void apply_direct_replay_input_injection() noexcept
        {
            if (!(m_cfg.direct_replay_input_requested
                  || m_cfg.direct_correction_requested))
                return;

            m_direct_replay_write_attempted = true;
            if (!m_direct_stage_ready)
            {
                m_last_failure = "direct-stage-not-ready";
                return;
            }
            if (!m_replay_script.ok)
            {
                m_last_failure =
                    m_replay_script.failure
                        ? m_replay_script.failure
                        : "replay-input-decode-failed";
                return;
            }
            const uint32_t local_slot = m_cfg.local_replay_player;
            const uint32_t remote_slot = m_cfg.remote_replay_player;
            if (local_slot >= 2 || remote_slot >= 2 ||
                local_slot == remote_slot ||
                local_slot >= m_replay_script.player_inputs.size() ||
                remote_slot >= m_replay_script.player_inputs.size())
            {
                m_last_failure = "direct-replay-player-mapping-invalid";
                return;
            }

            const auto& local_inputs =
                m_replay_script.player_inputs[local_slot];
            const auto& remote_inputs =
                m_replay_script.player_inputs[remote_slot];
            if (local_inputs.empty() || remote_inputs.empty())
            {
                m_last_failure = "direct-replay-input-stream-empty";
                return;
            }

            uintptr_t battle_manager = m_direct_stage_active_battle_manager;
            if (!battle_manager && resolve_direct_stage_natives())
            {
                battle_manager = reinterpret_cast<uintptr_t>(
                    safe_get_active_battle_manager(
                        m_get_active_battle_manager));
                m_direct_stage_active_battle_manager = battle_manager;
            }
            if (!battle_manager)
            {
                battle_manager = reinterpret_cast<uintptr_t>(
                    RC::Unreal::UObjectGlobals::FindFirstOf(
                        L"LuxBattleManager"));
                m_direct_stage_active_battle_manager = battle_manager;
            }
            if (!battle_manager)
            {
                m_last_failure = "direct-battle-manager-not-ready";
                return;
            }

            void* input_log_raw = nullptr;
            if (!SafeReadPtr(
                    reinterpret_cast<const void*>(
                        battle_manager + kRollbackBM_BattleFrameInputLog_Off),
                    &input_log_raw)
                || !input_log_raw)
            {
                m_last_failure = "direct-input-log-not-ready";
                return;
            }

            auto* il = static_cast<uint8_t*>(input_log_raw);
            uint32_t master_clock = 0;
            uint32_t last_frame_id = 0;
            (void)SafeReadUInt32(
                il + kRollbackIL_nMasterClock_Off,
                &master_clock);
            (void)SafeReadUInt32(
                il + kRollbackIL_nLastFrameID_Off,
                &last_frame_id);

            constexpr uint32_t kDirectReplayWriteWindow = 120;
            constexpr uint32_t kDirectReplayRefreshLead = 60;
            if (m_direct_replay_write_complete &&
                m_direct_replay_last_frame >=
                    master_clock + kDirectReplayRefreshLead)
            {
                m_last_failure = "ok";
                return;
            }

            const uint32_t local_count =
                static_cast<uint32_t>(
                    (std::min<uint64_t>)(
                        local_inputs.size(), kDirectReplayWriteWindow));
            const uint32_t remote_count =
                static_cast<uint32_t>(
                    (std::min<uint64_t>)(
                        remote_inputs.size(), kDirectReplayWriteWindow));
            const uint32_t count =
                (std::min<uint32_t>)(local_count, remote_count);
            if (count == 0)
            {
                m_last_failure = "direct-replay-input-window-empty";
                return;
            }

            uint32_t start_frame = master_clock;
            if (m_direct_replay_write_complete &&
                m_direct_replay_last_frame + 1 > start_frame)
            {
                start_frame = m_direct_replay_last_frame + 1;
            }
            const uint32_t max_end_frame =
                master_clock + kDirectReplayWriteWindow - 1;
            uint32_t write_count = count;
            if (start_frame > max_end_frame)
            {
                m_last_failure = "ok";
                return;
            }
            write_count =
                (std::min<uint32_t>)(write_count,
                                     max_end_frame - start_frame + 1);

            const uintptr_t input_log =
                reinterpret_cast<uintptr_t>(input_log_raw);
            const uint64_t local_writes =
                write_direct_replay_stream(
                    input_log, local_slot, local_inputs,
                    start_frame, write_count);
            const uint64_t remote_writes =
                write_direct_replay_stream(
                    input_log, remote_slot, remote_inputs,
                    start_frame, write_count);

            m_direct_replay_battle_manager = battle_manager;
            m_direct_replay_input_log = input_log;
            m_direct_replay_start_frame = start_frame;
            m_direct_replay_last_frame =
                write_count > 0 ? start_frame + write_count - 1 : start_frame;
            m_direct_replay_master_clock = master_clock;
            m_direct_replay_last_frame_id = last_frame_id;
            m_direct_replay_cache_writes_local = local_writes;
            m_direct_replay_cache_writes_remote = remote_writes;
            if (local_writes == 0 || remote_writes == 0)
            {
                m_last_failure = "direct-replay-cache-write-failed";
                return;
            }

            m_direct_replay_write_complete = true;
            ++m_direct_replay_cache_refreshes;
            m_replay_injected_first_frame = start_frame;
            m_replay_injected_last_frame =
                write_count > 0 ? start_frame + write_count - 1 : start_frame;
            m_replay_input_injected = true;
            m_replay_input_complete = true;
            m_last_failure = "ok";
        }

        void sync_replay_input_injection_report() noexcept
        {
            if (!m_replay_injection_armed)
                return;
            const RollbackReplayInputInjectionReport send =
                RollbackStockTransportObserveHook::instance()
                    .replay_input_script_report();
            const RollbackReplayInputInjectionReport consumer =
                RollbackLiveBoundaryHook::instance()
                    .replay_input_script_report();

            m_replay_send_cache_writes = send.send_cache_writes;
            m_replay_consumer_writes = consumer.consumer_writes;
            m_replay_consumed_input_hash =
                consumer.applied_input_hash;
            m_replay_consumed_input_count = consumer.applied_inputs;
            m_replay_send_failure = send.failure;
            m_replay_consumer_failure = consumer.failure;
            if (send.first_injected_frame != 0 &&
                (m_replay_injected_first_frame == 0 ||
                 send.first_injected_frame < m_replay_injected_first_frame))
            {
                m_replay_injected_first_frame =
                    send.first_injected_frame;
            }
            if (consumer.first_injected_frame != 0 &&
                (m_replay_injected_first_frame == 0 ||
                 consumer.first_injected_frame <
                    m_replay_injected_first_frame))
            {
                m_replay_injected_first_frame =
                    consumer.first_injected_frame;
            }
            m_replay_injected_last_frame =
                send.last_injected_frame > consumer.last_injected_frame
                    ? send.last_injected_frame
                    : consumer.last_injected_frame;

            apply_direct_replay_input_injection();
            if (m_direct_replay_write_complete)
                return;
            if (m_cfg.direct_replay_input_requested
                || m_cfg.direct_correction_requested)
                return;

            m_replay_input_injected =
                send.injected && consumer.injected;
            const bool diagnostic_epoch_match =
                send.script_epoch_set
                && consumer.script_epoch_set
                && send.script_epoch == consumer.script_epoch;
            m_replay_script_epoch_match = diagnostic_epoch_match;
            m_replay_script_epoch = diagnostic_epoch_match
                ? send.script_epoch : 0;
            m_replay_input_complete =
                m_replay_input_injected
                && m_replay_send_cache_writes > 0
                && m_replay_consumer_writes > 0
                && m_replay_consumed_input_count > 0
                && m_replay_consumed_input_hash != 0
                && diagnostic_epoch_match;
            if (m_replay_input_complete)
                m_last_failure = "ok";
            else if (!send.injected)
                m_last_failure = send.failure ? send.failure
                                               : "send-script-waiting";
            else if (!consumer.injected)
                m_last_failure = consumer.failure ? consumer.failure
                                                  : "consumer-script-waiting";
            else
                m_last_failure = "waiting-for-live-input-injection";
        }

        void load_replay_input_file() noexcept
        {
            m_replay_loaded = true;
            m_replay_file_exists = false;
            m_replay_file_bytes = 0;
            m_replay_file_hash = 0;
            m_replay_payload_hash = 0;
            m_replay_decompressed_bytes = 0;
            m_replay_decompressed_hash = 0;
            m_replay_input_blocks_detected = 0;
            m_replay_input_block_pairs = 0;
            m_replay_input_frames_p0 = 0;
            m_replay_input_frames_p1 = 0;
            m_replay_input_hash_p0 = 0;
            m_replay_input_hash_p1 = 0;
            m_replay_script = {};
            if (m_cfg.replay_input_file.empty())
            {
                m_last_failure = "replay-input-file-not-configured";
                return;
            }

            const std::wstring path = widen_utf8(m_cfg.replay_input_file);
            FILE* f = nullptr;
            if (_wfopen_s(&f, path.c_str(), L"rb") != 0 || !f)
            {
                m_last_failure = "replay-input-file-open-failed";
                return;
            }
            std::vector<uint8_t> bytes;
            uint8_t buf[4096];
            while (!std::feof(f) && bytes.size() < 16u * 1024u * 1024u)
            {
                const size_t n = std::fread(buf, 1, sizeof(buf), f);
                if (n == 0) break;
                bytes.insert(bytes.end(), buf, buf + n);
            }
            std::fclose(f);
            m_replay_file_exists = !bytes.empty();
            m_replay_file_bytes = static_cast<uint64_t>(bytes.size());
            if (!bytes.empty())
                m_replay_file_hash = fnv1a64_bytes(bytes);
            if (!m_replay_file_exists)
            {
                m_last_failure = "replay-input-file-empty";
                return;
            }

            RollbackReplayInputScript script {};
            (void)RollbackReplayInputScriptExtractor::extract(bytes, script);
            m_replay_script = std::move(script);
            m_replay_file_bytes = m_replay_script.file_bytes;
            m_replay_file_hash = m_replay_script.file_hash;
            m_replay_payload_hash = m_replay_script.payload_hash;
            m_replay_decompressed_bytes =
                m_replay_script.decompressed_bytes;
            m_replay_decompressed_hash =
                m_replay_script.decompressed_hash;
            m_replay_input_blocks_detected =
                m_replay_script.input_blocks_detected;
            m_replay_input_block_pairs =
                m_replay_script.input_block_pairs;
            m_replay_input_frames_p0 =
                m_replay_script.input_frames_p0;
            m_replay_input_frames_p1 =
                m_replay_script.input_frames_p1;
            m_replay_input_hash_p0 =
                m_replay_script.input_hash_p0;
            m_replay_input_hash_p1 =
                m_replay_script.input_hash_p1;
            m_direct_setup_stage_index =
                m_replay_script.setup_stage_index;
            m_direct_setup_stage_map_index =
                direct_stage_map_index(m_direct_setup_stage_index);
            m_direct_setup_left_chara_id =
                m_replay_script.setup_left_chara_id;
            m_direct_setup_right_chara_id =
                m_replay_script.setup_right_chara_id;
            m_direct_setup_metadata_valid = direct_stage_metadata_valid(
                m_direct_setup_stage_index,
                m_direct_setup_left_chara_id,
                m_direct_setup_right_chara_id);
            m_direct_setup_from_replay = m_direct_setup_metadata_valid;
            if (!m_direct_setup_metadata_valid && m_replay_script.ok)
            {
                m_direct_setup_stage_index = kDirectDefaultStageIndex;
                m_direct_setup_left_chara_id = kDirectDefaultLeftChara;
                m_direct_setup_right_chara_id = kDirectDefaultRightChara;
            }
            if (m_cfg.launch_left_character_override >= 0)
                m_direct_setup_left_chara_id =
                    m_cfg.launch_left_character_override;
            if (m_cfg.launch_right_character_override >= 0)
                m_direct_setup_right_chara_id =
                    m_cfg.launch_right_character_override;
            if (m_cfg.launch_stage_override >= 0)
            {
                m_direct_setup_stage_index = m_cfg.launch_stage_override;
            }
            m_direct_setup_stage_map_index =
                direct_stage_map_index(m_direct_setup_stage_index);
            m_direct_setup_metadata_valid =
                direct_stage_metadata_valid(
                    m_direct_setup_stage_index,
                    m_direct_setup_left_chara_id,
                    m_direct_setup_right_chara_id);
            m_direct_setup_source =
                m_direct_setup_metadata_valid
                    ? ((m_cfg.launch_left_character_override >= 0 ||
                        m_cfg.launch_right_character_override >= 0 ||
                        m_cfg.launch_stage_override >= 0)
                           ? (m_direct_setup_from_replay
                                  ? "replay-wrapper+operator-overrides"
                                  : "default-fallback+operator-overrides")
                           : (m_direct_setup_from_replay
                                  ? "replay-wrapper"
                                  : "default-fallback"))
                    : "missing";
            m_last_failure =
                m_replay_script.ok ? "ok" : m_replay_script.failure;
        }

        void emit_replay_input_script() noexcept
        {
            const bool players_valid =
                m_cfg.local_replay_player < 2
                && m_cfg.remote_replay_player < 2
                && m_cfg.local_replay_player != m_cfg.remote_replay_player;
            const bool decoded =
                m_replay_input_frames_p0 > 0 && m_replay_input_frames_p1 > 0;
            const uint64_t local_hash =
                m_cfg.local_replay_player == 0
                    ? m_replay_input_hash_p0
                    : (m_cfg.local_replay_player == 1
                           ? m_replay_input_hash_p1 : 0);
            const uint64_t remote_hash =
                m_cfg.remote_replay_player == 0
                    ? m_replay_input_hash_p0
                    : (m_cfg.remote_replay_player == 1
                           ? m_replay_input_hash_p1 : 0);
            const bool ok =
                m_replay_file_exists
                && players_valid
                && decoded
                && m_replay_input_latched
                && m_replay_input_injected;
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .boolean("live_replay_input_requested",
                      m_cfg.live_replay_input_requested)
             .string("replay_input_file", m_cfg.replay_input_file)
             .boolean("replay_file_exists", m_replay_file_exists)
             .uinteger("replay_file_bytes", m_replay_file_bytes)
             .hex("replay_file_hash", m_replay_file_hash)
             .hex("replay_payload_hash", m_replay_payload_hash)
             .uinteger("replay_decompressed_bytes",
                       m_replay_decompressed_bytes)
             .hex("replay_decompressed_hash",
                  m_replay_decompressed_hash)
             .uinteger("input_blocks_detected",
                       m_replay_input_blocks_detected)
             .uinteger("input_block_pairs", m_replay_input_block_pairs)
             .uinteger("local_replay_player", m_cfg.local_replay_player)
             .uinteger("remote_replay_player", m_cfg.remote_replay_player)
             .boolean("player_mapping_valid", players_valid)
             .boolean("inputs_decoded", decoded)
             .uinteger("input_frames_p0", m_replay_input_frames_p0)
             .uinteger("input_frames_p1", m_replay_input_frames_p1)
             .hex("input_hash_p0", m_replay_input_hash_p0)
             .hex("input_hash_p1", m_replay_input_hash_p1)
             .hex("local_input_hash", local_hash)
             .hex("expected_remote_input_hash", remote_hash)
             .boolean("input_latched", m_replay_input_latched)
              .boolean("input_injected", m_replay_input_injected)
              .boolean("input_complete", m_replay_input_complete)
              .boolean("input_injection_armed", m_replay_injection_armed)
              .boolean("direct_cache_write_attempted",
                       m_direct_replay_write_attempted)
              .boolean("direct_cache_write_complete",
                       m_direct_replay_write_complete)
              .uinteger("send_cache_writes", m_replay_send_cache_writes)
              .uinteger("consumer_writes", m_replay_consumer_writes)
              .hex("native_consumer_input_hash",
                   m_replay_consumed_input_hash)
              .uinteger("native_consumer_input_count",
                        m_replay_consumed_input_count)
              .boolean("script_epoch_match",
                       m_replay_script_epoch_match)
              .uinteger("script_epoch", m_replay_script_epoch)
              .uinteger("direct_cache_writes_local",
                        m_direct_replay_cache_writes_local)
              .uinteger("direct_cache_writes_remote",
                        m_direct_replay_cache_writes_remote)
              .hex("direct_battle_manager",
                   m_direct_replay_battle_manager)
              .hex("direct_input_log", m_direct_replay_input_log)
              .uinteger("direct_start_frame",
                        m_direct_replay_start_frame)
              .uinteger("direct_last_frame",
                        m_direct_replay_last_frame)
              .uinteger("direct_master_clock",
                        m_direct_replay_master_clock)
              .uinteger("direct_last_frame_id",
                        m_direct_replay_last_frame_id)
              .uinteger("direct_cache_refreshes",
                        m_direct_replay_cache_refreshes)
              .uinteger("injected_first_frame",
                        m_replay_injected_first_frame)
             .uinteger("injected_last_frame",
                       m_replay_injected_last_frame)
             .string("send_failure", m_replay_send_failure)
             .string("consumer_failure", m_replay_consumer_failure)
             .boolean("force_divergence",
                      m_cfg.force_live_prediction_divergence)
             .uinteger("divergence_frame", m_cfg.divergence_frame)
             .uinteger("divergence_window", m_cfg.divergence_window)
             .string("failure", ok ? "ok" : m_last_failure);
            ReplayDebugTrace::instance().event(
                "rollback_replay_input_script", f);
        }

        void emit_direct_replay_input() noexcept
        {
            const bool players_valid =
                m_cfg.local_replay_player < 2
                && m_cfg.remote_replay_player < 2
                && m_cfg.local_replay_player != m_cfg.remote_replay_player;
            const uint64_t local_hash = local_replay_input_hash();
            const uint64_t remote_hash =
                expected_remote_replay_input_hash();
            const uint32_t frames = replay_input_frame_count();
            const bool ok =
                m_replay_file_exists
                && players_valid
                && m_replay_input_latched
                && m_replay_input_injected
                && m_replay_input_complete
                && frames > 0
                && local_hash != 0
                && remote_hash != 0;
            ReplayTraceFields f;
            f.boolean("ok", ok)
             .string("request_id", m_cfg.request_id)
             .string("client_role", m_cfg.client_role)
             .boolean("direct_replay_input_requested",
                      m_cfg.direct_replay_input_requested)
             .boolean("direct_correction_requested",
                      m_cfg.direct_correction_requested)
             .boolean("steam_stage_bypassed", true)
             .string("replay_input_file", m_cfg.replay_input_file)
             .hex("replay_file_hash", m_replay_file_hash)
             .uinteger("local_replay_player", m_cfg.local_replay_player)
             .uinteger("remote_replay_player", m_cfg.remote_replay_player)
             .hex("local_input_hash", local_hash)
             .hex("expected_remote_input_hash", remote_hash)
             .uinteger("first_frame", 0)
             .uinteger("frame_count", frames)
              .boolean("input_latched", m_replay_input_latched)
              .boolean("input_injected", m_replay_input_injected)
              .boolean("input_complete", m_replay_input_complete)
              .boolean("direct_cache_write_attempted",
                       m_direct_replay_write_attempted)
              .boolean("direct_cache_write_complete",
                       m_direct_replay_write_complete)
              .uinteger("send_cache_writes", m_replay_send_cache_writes)
              .uinteger("consumer_writes", m_replay_consumer_writes)
              .hex("native_consumer_input_hash",
                   m_replay_consumed_input_hash)
              .uinteger("native_consumer_input_count",
                        m_replay_consumed_input_count)
              .boolean("script_epoch_match",
                       m_replay_script_epoch_match)
              .uinteger("script_epoch", m_replay_script_epoch)
              .uinteger("direct_cache_writes_local",
                        m_direct_replay_cache_writes_local)
              .uinteger("direct_cache_writes_remote",
                        m_direct_replay_cache_writes_remote)
              .hex("direct_battle_manager",
                   m_direct_replay_battle_manager)
              .hex("direct_input_log", m_direct_replay_input_log)
              .uinteger("direct_start_frame",
                        m_direct_replay_start_frame)
              .uinteger("direct_last_frame",
                        m_direct_replay_last_frame)
              .uinteger("direct_master_clock",
                        m_direct_replay_master_clock)
              .uinteger("direct_last_frame_id",
                        m_direct_replay_last_frame_id)
              .uinteger("direct_cache_refreshes",
                        m_direct_replay_cache_refreshes)
              .uinteger("injected_first_frame",
                        m_replay_injected_first_frame)
             .uinteger("injected_last_frame",
                       m_replay_injected_last_frame)
             .string("failure", ok ? "ok" : m_last_failure);
            ReplayDebugTrace::instance().event(
                "rollback_direct_replay_input", f);
            m_direct_replay_input_emitted = true;
            if (ok)
                m_direct_replay_input_ok_emitted = true;
        }

